"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[44],{1499:(e,t,n)=>{n.d(t,{H3:()=>r,SP:()=>l,s_:()=>o,y4:()=>s});let i="physics4all-progress";function a(){return{completedChapters:{}}}function s(){try{let e=localStorage.getItem(i);if(!e)return a();return JSON.parse(e)}catch(e){return a()}}function o(e,t){let n=s();n.completedChapters[e]||(n.completedChapters[e]=[]),n.completedChapters[e].includes(t)||n.completedChapters[e].push(t),localStorage.setItem(i,JSON.stringify(n))}function r(e,t){var n,i;return null!=(i=null==(n=s().completedChapters[e])?void 0:n.includes(t))&&i}function l(e,t){var n,i;let a=null!=(i=null==(n=s().completedChapters[e])?void 0:n.length)?i:0;return 0===t?0:Math.round(a/t*100)}},9826:(e,t,n)=>{n.d(t,{aq:()=>l,Z7:()=>c,Jv:()=>h,lb:()=>d,ZY:()=>r,Pq:()=>o,tW:()=>i,yo:()=>s});let i=[{number:1,title:"Foundations",description:"Seeing like a physicist — numbers, proportion, and every physics phenomenon qualitatively (classes 1–7, compressed for adults)",color:"phase-1",audienceLevel:"Complete Beginner"},{number:2,title:"The First Full Tour",description:"All of physics once, at one-formula depth, plus the algebra to power it (classes 8–10, the Russian/Chinese model)",color:"phase-2",audienceLevel:"Beginner"},{number:3,title:"Quantitative Physics",description:"The theory pass with vectors and trigonometry (classes 11–12; H2/A-level/NCERT/AP level)",color:"phase-3",audienceLevel:"Intermediate"},{number:4,title:"University General Physics",description:"Calculus-based mechanics, electromagnetism, waves and special relativity (BSc years 1–2, the MIT 8.01→8.033 spine)",color:"phase-4",audienceLevel:"Intermediate"},{number:5,title:"The Theoretical Core",description:"Lagrangian mechanics, electrodynamics, quantum mechanics, statistical mechanics — plus math methods and computation",color:"phase-5",audienceLevel:"Advanced"},{number:6,title:"Advanced & Frontier",description:"Solid state, nuclear & particle, astrophysics & cosmology, general relativity, and the QFT gateway",color:"phase-6",audienceLevel:"Advanced"}],a=[{icon:"\xbd",colorHex:"#6366f1",difficulty:"beginner",estimatedHours:25,shortName:"Numbers"},{icon:"⚛",colorHex:"#8b5cf6",difficulty:"beginner",estimatedHours:20,shortName:"Phenomena"},{icon:"\uD83D\uDD2C",colorHex:"#a855f7",difficulty:"beginner",estimatedHours:12,shortName:"Method"},{icon:"x\xb2",colorHex:"#3b82f6",difficulty:"beginner",estimatedHours:35,shortName:"Algebra"},{icon:"F",colorHex:"#2563eb",difficulty:"beginner",estimatedHours:25,shortName:"Motion"},{icon:"\uD83C\uDF21",colorHex:"#0ea5e9",difficulty:"beginner",estimatedHours:15,shortName:"Heat"},{icon:"\uD83D\uDCA1",colorHex:"#06b6d4",difficulty:"beginner",estimatedHours:18,shortName:"Light"},{icon:"⚡",colorHex:"#0891b2",difficulty:"beginner",estimatedHours:22,shortName:"Electricity"},{icon:"☢",colorHex:"#0e7490",difficulty:"beginner",estimatedHours:12,shortName:"Atoms"},{icon:"sin",colorHex:"#f59e0b",difficulty:"intermediate",estimatedHours:40,shortName:"Precalc"},{icon:"→",colorHex:"#d97706",difficulty:"intermediate",estimatedHours:35,shortName:"Mechanics"},{icon:"PV",colorHex:"#b45309",difficulty:"intermediate",estimatedHours:18,shortName:"Thermal"},{icon:"λ",colorHex:"#eab308",difficulty:"intermediate",estimatedHours:20,shortName:"Waves"},{icon:"E",colorHex:"#ca8a04",difficulty:"intermediate",estimatedHours:30,shortName:"Fields"},{icon:"hν",colorHex:"#a16207",difficulty:"intermediate",estimatedHours:20,shortName:"Modern"},{icon:"∫",colorHex:"#ef4444",difficulty:"intermediate",estimatedHours:50,shortName:"Calculus"},{icon:"ma",colorHex:"#dc2626",difficulty:"intermediate",estimatedHours:40,shortName:"Mechanics I"},{icon:"∇",colorHex:"#b91c1c",difficulty:"intermediate",estimatedHours:40,shortName:"Vector Calc"},{icon:"∮",colorHex:"#f97316",difficulty:"intermediate",estimatedHours:35,shortName:"E&M I"},{icon:"ω",colorHex:"#ea580c",difficulty:"intermediate",estimatedHours:30,shortName:"Waves II"},{icon:"c",colorHex:"#c2410c",difficulty:"intermediate",estimatedHours:18,shortName:"Relativity"},{icon:"Ax",colorHex:"#9a3412",difficulty:"intermediate",estimatedHours:45,shortName:"DE & LinAlg"},{icon:"ℂ",colorHex:"#10b981",difficulty:"advanced",estimatedHours:45,shortName:"Math Methods"},{icon:"ℒ",colorHex:"#059669",difficulty:"advanced",estimatedHours:35,shortName:"Lagrangian"},{icon:"∇\xd7",colorHex:"#047857",difficulty:"advanced",estimatedHours:40,shortName:"Electrodynamics"},{icon:"ψ",colorHex:"#14b8a6",difficulty:"advanced",estimatedHours:40,shortName:"Quantum I"},{icon:"⟨ ⟩",colorHex:"#0d9488",difficulty:"advanced",estimatedHours:35,shortName:"Quantum II"},{icon:"S",colorHex:"#0f766e",difficulty:"advanced",estimatedHours:35,shortName:"Stat Mech"},{icon:">_",colorHex:"#115e59",difficulty:"advanced",estimatedHours:25,shortName:"Computation"},{icon:"Si",colorHex:"#a855f7",difficulty:"advanced",estimatedHours:30,shortName:"Solid State"},{icon:"q",colorHex:"#9333ea",difficulty:"advanced",estimatedHours:28,shortName:"Particles"},{icon:"★",colorHex:"#7e22ce",difficulty:"advanced",estimatedHours:28,shortName:"Astro"},{icon:"g",colorHex:"#6b21a8",difficulty:"advanced",estimatedHours:35,shortName:"GR"},{icon:"φ",colorHex:"#581c87",difficulty:"advanced",estimatedHours:25,shortName:"QFT"}],s=[{id:"numbers-measurement-proportion",number:1,title:"Numbers, Measurement & Proportion",description:"Rebuild arithmetic to automaticity and conquer proportional reasoning — the grammar of every physics formula. Math track I.",phase:1,chapters:[{id:"numbers-rebuilt",title:"Numbers Rebuilt",subtitle:"Place value, mental arithmetic, negative numbers, and the estimation habits every physicist runs on",sections:[{id:"place-value-and-the-number-line",title:"Place Value & the Number Line",content:'\n<p>Every number you will ever meet in physics lives in one system: <strong>positional notation</strong>. The numeral 4,072 doesn\'t contain a four, a zero, a seven, and a two — it contains 4 thousands, 0 hundreds, 7 tens, and 2 ones. Each step to the left multiplies the value of a digit by ten; each step to the right divides it by ten. That single idea — <strong>each place is worth ten times its neighbor</strong> — is the engine behind decimals, scientific notation, metric units, and orders of magnitude. Master it here and four later chapters get easier.</p>\n<p>The second mental tool is the <strong>number line</strong>: an infinite ruler with zero in the middle, positives stretching right, negatives stretching left. It turns arithmetic into geometry:</p>\n<ul>\n  <li><strong>Addition</strong> is a move to the right: 3 + 5 means "start at 3, walk 5 right."</li>\n  <li><strong>Subtraction</strong> is a move to the left — or better, a <strong>distance</strong>: 9 − 4 asks "how far from 4 to 9?"</li>\n  <li><strong>Comparing</strong> numbers means asking which sits further right: −2 is greater than −7 because it is closer to zero on the right side.</li>\n</ul>\n<div class="key-concept">\n  <h3>Key Concept: Numbers Are Positions, Operations Are Movements</h3>\n  <p>A thermometer, a voltmeter, an altitude readout — every instrument in physics is a number line with a label. When a temperature "drops 12 degrees" or a charge "goes negative," you are watching a point slide along a line. If you can see arithmetic as motion, half of introductory physics becomes familiar territory.</p>\n</div>\n<p>Worked example: a weather station reads −3\xb0C at dawn. By noon the temperature has risen 11 degrees. Where are we? Start at −3, walk 11 to the right: three steps bring you to 0, and the remaining eight land you at <strong>8\xb0C</strong>. No rule was memorized — you just moved along the line.</p>\n<p>Physics will soon hand you quantities spread across this line at wild scales: the charge of an electron near zero, the mass of the Earth far to the right. The number line is where you will hang all of them.</p>'},{id:"arithmetic-and-mental-math",title:"Arithmetic That Runs Itself",content:"\n<p>You are not relearning arithmetic to pass a test — you are rebuilding it to <strong>automaticity</strong>, so that when a physics problem needs 25 \xd7 12, your working memory stays free for the physics. The trick adults were rarely taught: fast arithmetic isn't about speed, it's about <strong>restructuring numbers before you compute</strong>.</p>\n<p>Three moves cover most mental math:</p>\n<ol>\n  <li><strong>Break numbers apart (decomposition).</strong> 25 \xd7 12 = 25 \xd7 10 + 25 \xd7 2 = 250 + 50 = <strong>300</strong>. You never multiplied anything harder than 25 \xd7 2.</li>\n  <li><strong>Compensate.</strong> 47 + 38: add 40 (getting 87), then take back 2 → <strong>85</strong>. Or 6 \xd7 99 = 6 \xd7 100 − 6 = <strong>594</strong>.</li>\n  <li><strong>Use friendly pairs.</strong> Numbers that make 10, 100, or 1000 love each other: 4 \xd7 25 = 100, 8 \xd7 125 = 1000, 2 \xd7 50 = 100. Spot them and rearrange: 4 \xd7 7 \xd7 25 = (4 \xd7 25) \xd7 7 = 700.</li>\n</ol>\n<div class=\"analogy\">\n  <h3>Analogy: Touch Typing for Numbers</h3>\n  <p>A touch typist doesn't think about individual keys; their fingers handle the letters while their mind composes the sentence. That's the goal for arithmetic. In a physics problem about a falling ball, the thinking should go into \"what does gravity do here?\" — not into 4.9 \xd7 4. Fluency isn't a party trick; it's freed-up brainpower.</p>\n</div>\n<p>Worked example, physics-flavored: a car travels at 72 km per hour. How far does it go in 40 minutes? Restructure: 40 minutes is ⅔ of an hour. One third of 72 is 24, so two thirds is <strong>48 km</strong>. Notice what happened — the \"hard\" division became a friendly fraction because you reshaped the problem first.</p>\n<p>Practice deliberately for a week or two: double and halve numbers, multiply by 5 (multiply by 10, halve it), multiply by 25 (multiply by 100, quarter it). These aren't tricks to collect; they're the same idea — <strong>ten is the hub, and everything routes through it</strong>.</p>"},{id:"negative-numbers",title:"Below Zero: Negative Numbers",content:'\n<p>Negative numbers make many adults quietly nervous, and physics uses them <em>constantly</em>: negative charge, negative velocity, negative energy, temperatures below zero. Here\'s the reframe that makes them tame: a negative number is not a "weird number" — it\'s an ordinary size pointing the <strong>opposite direction</strong>. The minus sign is a direction flag.</p>\n<p>With that picture, the rules stop being arbitrary:</p>\n<ul>\n  <li><strong>Adding a negative = subtracting.</strong> Gaining a debt of 5 dollars is losing 5 dollars: 8 + (−5) = 3.</li>\n  <li><strong>Subtracting a negative = adding.</strong> Removing a debt makes you richer: 8 − (−5) = 13.</li>\n  <li><strong>Multiplying flips or keeps direction.</strong> Multiplying by −1 means "reverse." So (−3) \xd7 4 = −12 (a reversal), and (−3) \xd7 (−4) = +12 — reversing a reversal points you forward again. Two wrongs don\'t make a right, but two reversals do.</li>\n</ul>\n<div class="key-concept">\n  <h3>Key Concept: Sign = Direction, Size = Magnitude</h3>\n  <p>Physicists split every signed quantity into two pieces: its <strong>magnitude</strong> (how much) and its <strong>sign</strong> (which way). A velocity of −20 m/s isn\'t slower than +20 m/s — it\'s just as fast, headed the other way. When physics answers come out negative, the number is telling you a direction, not an error.</p>\n</div>\n<p>Worked example: a diver is 6 m below the surface (position −6 m) and descends another 9 m. New position: −6 + (−9) = <strong>−15 m</strong>. Now she rises 4 m: −15 + 4 = <strong>−11 m</strong>. The arithmetic is just walking the number line; the signs track "up versus down" for you automatically.</p>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>European mathematicians resisted negative numbers into the 1700s, calling them "absurd" and "fictitious." Meanwhile, Chinese mathematicians had computed with them for over 1,500 years, using red rods for positives and black rods for negatives. If negatives feel unnatural, you\'re in historically excellent company — and, like the holdouts, you\'ll get over it.</p>\n</div>\n<p>One warning worth its own sentence: −3\xb2 means −(3\xb2) = −9, while (−3)\xb2 = +9. The square binds tighter than the minus. That distinction will matter the first time you plug a negative velocity into an energy formula.</p>'},{id:"order-of-operations",title:"Order of Operations",content:"\n<p>Order of operations is not a schoolroom ritual — it's the <strong>grammar that makes formulas unambiguous</strong>. Physics is written in this grammar. The kinetic-energy formula E = \xbdmv\xb2 only means what it should because everyone agrees the square applies to v alone, before the multiplication. Misread the order, and every formula you meet will silently betray you.</p>\n<p>The hierarchy, from strongest binding to weakest:</p>\n<ol>\n  <li><strong>Parentheses</strong> — whatever is grouped happens first.</li>\n  <li><strong>Exponents and roots</strong> — squares, cubes, square roots.</li>\n  <li><strong>Multiplication and division</strong> — equal rank, left to right.</li>\n  <li><strong>Addition and subtraction</strong> — equal rank, left to right.</li>\n</ol>\n<p>Two clarifications that fix most adult confusion:</p>\n<ul>\n  <li>Multiplication does <strong>not</strong> beat division (nor addition beat subtraction). They're peers, processed left to right: 12 \xf7 3 \xd7 2 = 4 \xd7 2 = 8, not 12 \xf7 6 = 2.</li>\n  <li>A fraction bar is <strong>invisible parentheses</strong> around top and bottom. The expression (6 + 4) \xf7 (2 + 3) written as a tall fraction hides both sets of brackets in the bar — evaluate top and bottom fully before dividing.</li>\n</ul>\n<p>Worked example with a real formula. Kinetic energy: E = \xbd \xd7 m \xd7 v\xb2. For m = 2 kg and v = 10 m/s:</p>\n<ul>\n  <li>Exponent first: v\xb2 = 10\xb2 = 100</li>\n  <li>Then multiply left to right: \xbd \xd7 2 \xd7 100 = 1 \xd7 100 = <strong>100 joules</strong></li>\n</ul>\n<p>The classic wrong turn is squaring (\xbd \xd7 2 \xd7 10) = 10 into 100... which happens to give 100 here — a cruel coincidence. Try v = 4: correct is \xbd \xd7 2 \xd7 16 = 16 J; the wrong order gives (\xbd \xd7 2 \xd7 4)\xb2 = 16 too! Fine, this formula is forgiving with m = 2. Take m = 3, v = 4: correct is \xbd \xd7 3 \xd7 16 = 24 J; wrong order gives (\xbd \xd7 3 \xd7 4)\xb2 = 36 J. Different answers, real consequences.</p>\n<div class=\"key-concept\">\n  <h3>Key Concept: When in Doubt, Add Parentheses</h3>\n  <p>Parentheses are free. Writing (\xbd \xd7 m) \xd7 (v\xb2) costs nothing and removes all ambiguity — for you, for your calculator, and later for your code. Professional physicists over-parenthesize all the time; ambiguity is the only sin.</p>\n</div>"},{id:"estimation-and-rounding",title:"Estimation & Rounding",content:"\n<p>Here is a professional secret: physicists estimate <em>before</em> they calculate, every single time. An estimate is a cheap insurance policy — if your careful calculation says a bicycle travels 4,000 km in an hour, the rough estimate you made first is what catches the error. Estimation is not laziness; it is <strong>quality control for thinking</strong>.</p>\n<p>Rounding is the tool. The rule you remember (round the digit up if the next digit is 5 or more) is fine, but the skill is choosing <strong>what to round to</strong>:</p>\n<ul>\n  <li><strong>Round to one or two significant digits</strong> for a quick check: 387 \xd7 52 ≈ 400 \xd7 50 = 20,000. (True answer: 20,124. The estimate did its job.)</li>\n  <li><strong>Round in opposite directions when you can.</strong> Rounding 387 up and 52 down means the errors partly cancel — that's why 400 \xd7 50 landed so close.</li>\n  <li><strong>Track whether your estimate is high or low.</strong> 9.8 rounded to 10 makes gravity slightly \"too strong,\" so your estimated fall time will come out slightly short. Knowing the direction of the error is half of error analysis, which you'll meet formally later.</li>\n</ul>\n<div class=\"analogy\">\n  <h3>Analogy: The Restaurant Bill</h3>\n  <p>You don't add a dinner bill to the cent in your head — you round each dish to the nearest dollar and keep a running total. If the waiter's total is wildly off from yours, you check the itemized bill. Physicists treat every calculation like that bill: the rough total comes first, and the precise answer must agree with it or someone has made a mistake.</p>\n</div>\n<p>Worked example: roughly how many seconds are in a year? Estimate: 365 days ≈ 400 days is too crude; keep 365. Each day has 24 hours ≈ 25; each hour has 3,600 seconds ≈ 3,500. So 365 \xd7 25 ≈ 9,000 hours, and 9,000 \xd7 3,500 ≈ 31,500,000 — about <strong>3 \xd7 10⁷ seconds</strong>. The exact value is 31,536,000. Our two-minute estimate landed within 1%.</p>\n<p>That habit — <em>estimate, then compute, then compare</em> — will run underneath everything you do in this course, and it becomes a superpower in Chapter 4 when we scale it up to Fermi estimation.</p>"}],quiz:[{question:"The temperature is −7\xb0C and rises by 12 degrees. What is it now, and what mental model gets you there fastest?",options:["5\xb0C — start at −7 on the number line and move 12 to the right","−19\xb0C — negative numbers make additions negative","19\xb0C — drop the minus sign and add","−5\xb0C — move 12 to the left from −7"],correctIndex:0,explanation:"Addition is a rightward move on the number line: from −7, seven steps reach 0 and the remaining five land at +5\xb0C. Seeing signed arithmetic as motion along a line is exactly how physics treats temperature, position, and velocity changes."},{question:"What is 12 \xf7 3 \xd7 2?",options:["2, because multiplication is done before division","8, because multiplication and division have equal rank and are done left to right","18, because you always work right to left","2, because the 3 \xd7 2 is implicitly grouped"],correctIndex:1,explanation:"Multiplication and division are peers, evaluated left to right: 12 \xf7 3 = 4, then 4 \xd7 2 = 8. The belief that multiplication 'beats' division is one of the most common adult misconceptions — and formulas like v = d \xf7 t \xd7 conversion factors will punish it."},{question:"Using E = \xbdmv\xb2 with m = 3 kg and v = 4 m/s, what is the kinetic energy?",options:["36 J — compute \xbd \xd7 3 \xd7 4 first, then square","6 J — square applies to the whole right side","24 J — square v first (v\xb2 = 16), then multiply: \xbd \xd7 3 \xd7 16","48 J — ignore the \xbd since it is less than 1"],correctIndex:2,explanation:"Exponents bind before multiplication, and the square applies only to v. So v\xb2 = 16, then \xbd \xd7 3 \xd7 16 = 24 J. Squaring the whole product (36 J) is the classic order-of-operations error, and it produces confidently wrong physics."},{question:"You estimate 387 \xd7 52 by rounding to 400 \xd7 50 = 20,000. The exact answer is 20,124. Why did this estimate land so close?",options:["Rounding always produces errors under 1%","One number was rounded up and the other down, so the errors partly cancelled","Multiplication is immune to rounding errors","It was luck — estimates cannot be systematically accurate"],correctIndex:1,explanation:"Rounding 387 up (+3%) and 52 down (−4%) pushes the product in opposite directions, so the errors largely cancel. Deliberately rounding in opposite directions is a professional estimator's habit — and tracking the direction of errors is the seed of physics error analysis."},{question:"What is (−3) \xd7 (−4), and what does the sign rule mean?",options:["−12 — two negatives stay negative","−7 — multiply then subtract","+12, but only as an arbitrary convention","+12 — multiplying by a negative means reversing direction, and two reversals point forward again"],correctIndex:3,explanation:"Multiplying by −1 means 'reverse direction' on the number line. Reversing twice restores the original direction, so (−3) \xd7 (−4) = +12. This is not an arbitrary rule: physics uses it whenever a reversed velocity or force is reversed again."}]},{id:"fractions-decimals-percent",title:"Fractions, Decimals & Percent",subtitle:"Three costumes for the same idea — crossing the rational-number wall that stops most adult relearners",sections:[{id:"what-a-fraction-really-is",title:"What a Fraction Really Is",content:"\n<p>Research on adult numeracy keeps finding the same bottleneck: fractions. Educators call it the <strong>rational-number wall</strong>, and it's the single best-documented gap between people who find physics readable and people who find it hostile. So let's rebuild the concept from the floor.</p>\n<p>A fraction is <strong>one number, not two</strong>. The symbol \xbe is not \"a 3 and a 4 in a costume\" — it is a single point on the number line, sitting three quarters of the way from 0 to 1. The bar means division: \xbe literally equals 3 \xf7 4 = 0.75. Everything else follows from three readings, and fluency means switching between them freely:</p>\n<ul>\n  <li><strong>Part of a whole:</strong> \xbe of a pizza — 3 slices when the pizza is cut into 4.</li>\n  <li><strong>A division:</strong> 3 chocolate bars shared among 4 people — each gets \xbe of a bar.</li>\n  <li><strong>A ratio or rate:</strong> 3 parts salt to 4 parts water; 3 meters per 4 seconds. <em>This</em> reading is the one physics runs on.</li>\n</ul>\n<div class=\"key-concept\">\n  <h3>Key Concept: Equivalent Fractions Are the Same Point</h3>\n  <p>\xbd = 2⁄4 = 50⁄100 = 0.5. Different names, one point on the line. Multiplying top and bottom by the same number doesn't change the value, because you're multiplying by something equal to 1 (like 2⁄2). Hold onto that phrase — <strong>multiplying by a clever form of 1</strong> — because in Chapter 5 it becomes the entire method of unit conversion.</p>\n</div>\n<p>Worked example: which is larger, 5⁄8 or 2⁄3? Rewrite both over 24 (the least common multiple of 8 and 3): 5⁄8 = 15⁄24 and 2⁄3 = 16⁄24. So <strong>2⁄3 is larger</strong>, by exactly 1⁄24. No decimals needed — though converting works too: 0.625 versus 0.667.</p>\n<p>Why physics cares: nearly every formula you'll meet is a fraction in disguise. Speed is distance over time. Density is mass over volume. Pressure is force over area. If fractions feel like fog, those formulas feel like fog. Clear the fog here, and Chapter 3 will feel like revision instead of a wall.</p>"},{id:"operations-on-fractions",title:"Adding, Subtracting, Multiplying, Dividing",content:'\n<p>The four operations on fractions each have a <em>reason</em>, and knowing the reasons beats memorizing the recipes — recipes evaporate under exam pressure; reasons don\'t.</p>\n<p><strong>Addition and subtraction need matching pieces.</strong> You can\'t add 1⁄2 + 1⁄3 directly, for the same reason you can\'t add 2 meters + 3 feet: the units differ. Halves and thirds are different sizes of piece. Convert both to sixths — pieces that fit both: 1⁄2 = 3⁄6 and 1⁄3 = 2⁄6, so the sum is <strong>5⁄6</strong>. The "common denominator" is just a common unit.</p>\n<p><strong>Multiplication means "of."</strong> \xbd \xd7 \xbe asks: what is half <em>of</em> three quarters? Take \xbe, cut it in half: 3⁄8. The recipe (multiply tops, multiply bottoms) falls straight out. Notice the humbling consequence: multiplying by a fraction smaller than 1 makes things <em>smaller</em>. Adults who learned "multiplication makes bigger" in childhood trip on this for years.</p>\n<p><strong>Division asks "how many fit?"</strong> 3 \xf7 \xbd asks how many half-pizzas fit in 3 pizzas: 6. Hence dividing by a fraction multiplies by its reciprocal: 3 \xf7 \xbd = 3 \xd7 2 = 6. Likewise \xbe \xf7 \xbc = \xbe \xd7 4 = 3 — three quarter-pieces fit in three-quarters. Dividing by a small number gives a big answer, a fact with deep physics echoes (huge pressure from a small area; huge acceleration from a small mass).</p>\n<div class="analogy">\n  <h3>Analogy: Coins Before Adding</h3>\n  <p>You can\'t add 3 dimes and 2 quarters by writing "5 somethings" — you convert both to cents (30 + 50 = 80) first. Common denominators are exactly that conversion. Nobody finds the coin version hard; the fraction version is the same move with worse marketing.</p>\n</div>\n<p>Worked example: a rod of length ⅚ m has \xbc of it painted. How much rod is painted? "\xbc of ⅚" → \xbc \xd7 ⅚ = 5⁄24 m ≈ 0.21 m. And how much is unpainted? 1 − \xbc = \xbe of it: \xbe \xd7 ⅚ = 15⁄24 = ⅝ m. Check: 5⁄24 + 15⁄24 = 20⁄24 = ⅚ ✓. That closing check — do the parts rebuild the whole? — is a habit worth keeping for life.</p>'},{id:"decimals",title:"Decimals: Fractions in Base Ten",content:'\n<p>A decimal is not a new kind of number — it\'s a fraction whose denominator is a power of ten, written using the place-value system you rebuilt in Chapter 1. The places right of the decimal point continue the tenfold pattern: tenths, hundredths, thousandths. So 0.375 means 3⁄10 + 7⁄100 + 5⁄1000 = 375⁄1000 = ⅜.</p>\n<p>Why science runs on decimals rather than fractions: <strong>decimals compare instantly</strong>. Which is bigger, 7⁄16 or 4⁄9? Not obvious. Which is bigger, 0.4375 or 0.444...? Read left to right, done. Instruments agree — every digital meter, scale, and sensor speaks decimal.</p>\n<p>The three skills to make automatic:</p>\n<ul>\n  <li><strong>Multiplying and dividing by 10, 100, 1000 just slides the decimal point.</strong> 3.75 \xd7 100 = 375; 3.75 \xf7 10 = 0.375. Nothing is really moving but your bookkeeping — each slide is a place-value shift. This is the mechanical heart of metric conversions (2.5 km = 2,500 m) and scientific notation.</li>\n  <li><strong>Converting a fraction: just divide.</strong> ⅝ = 5 \xf7 8 = 0.625. Some fractions terminate (⅝ = 0.625), others repeat forever (⅓ = 0.333...). A fraction terminates exactly when its denominator\'s only prime factors are 2 and 5 — the primes of ten.</li>\n  <li><strong>Comparing: pad with zeros and read.</strong> Is 0.72 bigger than 0.598? Write 0.720 versus 0.598: yes. The common adult error is thinking "598 is longer than 72, so 0.598 wins" — length of digits means nothing; position means everything.</li>\n</ul>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>Decimal notation is startlingly recent. Simon Stevin only popularized decimal fractions in Europe in 1585, in a pamphlet promising to teach "all computations... by whole numbers without fractions." Newton had decimals for barely a century of mathematical tradition when he wrote the Principia; you have five.</p>\n</div>\n<p>Worked example: a lab balance reads 0.048 kg, and a second object reads 0.31 kg. Total mass? Line up the decimal points — 0.048 + 0.310 = <strong>0.358 kg</strong>. Lining up decimal points is lining up place values: tenths under tenths, hundredths under hundredths. Misalignment is the number-one decimal arithmetic error, and in a lab notebook it produces masses that are wrong by a factor of ten.</p>'},{id:"percent",title:"Percent: The Universal Comparison",content:'\n<p><strong>Percent</strong> means "per hundred" — that\'s the whole definition. 35% is 35⁄100 is 0.35. It exists because comparing raw fractions is awkward (is 17⁄40 better than 22⁄50?), while rescaling everything to a denominator of 100 makes comparison instant (42.5% versus 44%).</p>\n<p>The one move that unlocks every percent problem: <strong>translate the percent into a decimal multiplier, and the word "of" into \xd7</strong>.</p>\n<ul>\n  <li>30% of 250 → 0.30 \xd7 250 = <strong>75</strong></li>\n  <li>A 15% increase → multiply by 1.15 (the original 100% plus 15% more)</li>\n  <li>A 20% decrease → multiply by 0.80 (only 80% remains)</li>\n</ul>\n<p>That multiplier view solves the problems that ambush people. If a $200 jacket is marked up 25% and then discounted 25%, is it back to $200? No: 200 \xd7 1.25 \xd7 0.75 = $187.50. The second 25% acted on a <em>bigger</em> base than the first. <strong>Percent changes don\'t cancel, because percent is always relative to the current value.</strong></p>\n<div class="key-concept">\n  <h3>Key Concept: Always Ask "Percent of What?"</h3>\n  <p>A percent without a stated base is meaningless. "Efficiency rose 5%" — of the original efficiency, or 5 percentage points? Physics is fussy about this: when you later compute that a heat engine is 35% efficient or a measurement has 2% uncertainty, the base (energy input; measured value) is always explicit. Building that reflex now costs minutes and saves whole homework sets.</p>\n</div>\n<p>Worked examples:</p>\n<ol>\n  <li>A battery\'s charge drops from 80% to 60%. That\'s a fall of 20 <em>percentage points</em>, but a fall of 20⁄80 = <strong>25 percent</strong> of the charge it had. Both statements are true; they answer different questions.</li>\n  <li>Reverse percentage — a price after a 20% discount is $64. Original? The $64 is 80% of it, so original = 64 \xf7 0.80 = <strong>$80</strong>. Dividing by the multiplier undoes it — the same undo move you\'ll use to rearrange physics formulas.</li>\n</ol>\n<p>In physics, percent is the language of efficiency, uncertainty, and composition (the air is 21% oxygen). It\'s a small idea used daily forever.</p>'},{id:"three-faces-one-number",title:"Conversions: Three Faces, One Number",content:'\n<p>Here is the summit of the rational-number wall: seeing instantly that ⅗, 0.6, and 60% are <strong>one number wearing three costumes</strong>. Fluency means converting between all three without ceremony, and choosing the costume that makes the current problem easiest.</p>\n<table>\n  <thead>\n    <tr><th>Fraction</th><th>Decimal</th><th>Percent</th><th>Worth memorizing because...</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>\xbd</td><td>0.5</td><td>50%</td><td>the everywhere-benchmark</td></tr>\n    <tr><td>\xbc , \xbe</td><td>0.25, 0.75</td><td>25%, 75%</td><td>quarters rule money, angles, time</td></tr>\n    <tr><td>⅓ , ⅔</td><td>0.333..., 0.667</td><td>33⅓%, 66⅔%</td><td>the repeating pair everyone rounds</td></tr>\n    <tr><td>⅕ , ⅖ , ⅗ , ⅘</td><td>0.2, 0.4, 0.6, 0.8</td><td>20–80%</td><td>fifths are the metric-friendly family</td></tr>\n    <tr><td>⅛</td><td>0.125</td><td>12.5%</td><td>halving \xbc; appears in energy problems</td></tr>\n    <tr><td>1⁄10</td><td>0.1</td><td>10%</td><td>the decimal system itself</td></tr>\n  </tbody>\n</table>\n<p>The conversion rules are two arrows: <strong>fraction → decimal</strong> is a division (⅗ = 3 \xf7 5 = 0.6); <strong>decimal → percent</strong> slides the point two places right (0.6 = 60%). Reverse the arrows to go back. That\'s the entire machinery.</p>\n<p>Which costume when?</p>\n<ul>\n  <li><strong>Fractions</strong> for exact reasoning and cancellation: ⅓ \xd7 3 = 1 exactly, while 0.333 \xd7 3 = 0.999.</li>\n  <li><strong>Decimals</strong> for comparing, measuring, and calculators.</li>\n  <li><strong>Percents</strong> for communicating to humans.</li>\n</ul>\n<div class="analogy">\n  <h3>Analogy: One Person, Three Outfits</h3>\n  <p>The same person wears gym clothes, work clothes, and a wedding suit — different contexts, one identity. Your job is to recognize the person regardless of outfit. When a physics solution flips from "the ball loses \xbc of its energy" to "0.75 of the energy remains" to "75% efficiency," it\'s one fact changing clothes mid-sentence. Textbooks do this without warning; from now on, so can you.</p>\n</div>\n<p>Worked example: light passes through two filters. The first transmits ⅔ of the light, the second 75%. Total transmission? Same costume first: ⅔ \xd7 \xbe = \xbd = 0.5 = <strong>50%</strong>. Pick fractions, and the cancellation is effortless.</p>'}],quiz:[{question:"Which of these is NOT equal to the others?",options:["⅗","0.6","60%","6⁄100"],correctIndex:3,explanation:"⅗ = 3 \xf7 5 = 0.6 = 60% — one number in three costumes. But 6⁄100 = 0.06 = 6%, ten times smaller. Reading 0.6 as 6⁄100 (instead of 6⁄10) is a classic place-value slip: the first digit after the point counts tenths, not hundredths."},{question:"Why does 1⁄2 + 1⁄3 require a common denominator?",options:["It's a convention with no deeper reason","Halves and thirds are different-sized pieces — like meters and feet, they must be converted to a common unit (sixths) before adding","Because addition of fractions is only defined for even denominators","To make the answer smaller than 1"],correctIndex:1,explanation:"Adding requires matching units. 1⁄2 = 3⁄6 and 1⁄3 = 2⁄6, so the sum is 5⁄6. Adding tops and bottoms directly (giving 2⁄5) is like adding 3 dimes and 2 quarters and calling it '5 coins worth' — the pieces were never the same size."},{question:"A $200 item is marked up 25%, then discounted 25%. What is the final price?",options:["$200 — the changes cancel","$187.50 — the discount acts on the larger, marked-up price","$150 — subtract 50% total","$212.50 — percents always compound upward"],correctIndex:1,explanation:"200 \xd7 1.25 = 250, then 250 \xd7 0.75 = 187.50. Percent changes never cancel because each acts on the current value, not the original. The multiplier view (\xd71.25, \xd70.75) makes this visible at a glance — and it is exactly how compounding works in radioactive decay and interest alike."},{question:"What is 3 \xf7 \xbd, and what question does it answer?",options:["1.5 — dividing always makes numbers smaller","6 — it asks how many half-sized pieces fit into 3 wholes","⅙ — flip the first fraction and multiply","5 — subtract the denominator"],correctIndex:1,explanation:"Division asks 'how many fit?' Six halves fit into 3, so 3 \xf7 \xbd = 3 \xd7 2 = 6. Dividing by a number smaller than 1 gives a larger answer — the same logic that later explains why a small area under a force produces enormous pressure (P = F \xf7 A)."},{question:"Two filters transmit ⅔ and 75% of light respectively. What fraction of light passes through both?",options:["\xbd — convert to one form and multiply: ⅔ \xd7 \xbe = \xbd","About 1.42 — add the two transmissions","⅔ — the weaker filter decides alone","5⁄7 — average the two fractions"],correctIndex:0,explanation:"Successive 'of' operations multiply: \xbe of ⅔ of the light survives, and ⅔ \xd7 \xbe = 6⁄12 = \xbd = 50%. Converting 75% into the fraction costume first makes the cancellation trivial — choosing the convenient representation is the real skill being tested."}]},{id:"ratio-rate-proportion",title:"Ratio, Rate & Proportion",subtitle:"The single most important chapter in the math track — the reasoning pattern behind speed, density, and nearly every physics formula",sections:[{id:"ratios-and-rates",title:"Ratios & Rates: Comparing by Division",content:'\n<p>If this course has one chapter you must not skim, it\'s this one. Research on physics learning is blunt: students who can reason proportionally can learn physics, and students who can\'t, struggle everywhere — because <strong>most physics formulas are ratio statements</strong>. Speed, density, pressure, resistance, concentration: all of them are "this per that."</p>\n<p>There are two ways to compare quantities. <strong>Comparison by subtraction</strong> asks "how much more?" — a 6 kg dog outweighs a 2 kg cat by 4 kg. <strong>Comparison by division</strong> asks "how many times as much?" — the dog is 3 times the cat\'s mass. That second kind is a <strong>ratio</strong>, and it has a superpower: it survives rescaling. Photograph the dog and cat at half size and the 4 kg difference becomes meaningless, but the 3-to-1 ratio still holds. Ratios capture <em>structure</em>; differences capture only amounts.</p>\n<p>A <strong>rate</strong> is a ratio between different kinds of quantity: 150 km per 2 hours, 30 grams per 3 cm\xb3, $12 per kg. The most useful form is the <strong>unit rate</strong> — how much per <em>one</em>: 75 km per hour, 10 g per cm\xb3. Finding the unit rate first, then scaling to whatever you need, is called the <strong>unitary method</strong>, and it is quietly the most reliable problem-solving algorithm in elementary math:</p>\n<ol>\n  <li>5 identical books cost $60. Cost per book: 60 \xf7 5 = $12.</li>\n  <li>Cost of 8 books: 8 \xd7 12 = <strong>$96</strong>.</li>\n</ol>\n<p>Down to one, up to many. It never fails, and it works unchanged in physics: if a pump moves 240 liters in 8 minutes, it moves 30 L per minute, so 11 minutes moves 330 L.</p>\n<div class="key-concept">\n  <h3>Key Concept: A Rate Is a Ratio With a Physical Meaning</h3>\n  <p>"Per" is the most important small word in science. Speed is kilometers <em>per</em> hour. Density is grams <em>per</em> cubic centimeter. Power is joules <em>per</em> second. Whenever you see "per," you are looking at a division — and the number tells you how much of the first thing rides along with one unit of the second. Learn to hear "per" as \xf7 and half the formulas in this course become sentences you can read.</p>\n</div>'},{id:"bar-models",title:"Bar Models: Seeing Ratio Problems",content:"\n<p>Singapore's math curriculum — a perennial world number one — teaches ratio with a deceptively simple drawing tool: the <strong>bar model</strong>. Instead of jumping to equations, you draw rectangles whose lengths represent quantities. The picture does the algebra for you, and for adults it's a genuinely faster way to crack word problems.</p>\n<p><strong>Worked example 1.</strong> Alex and Ben share $120 in the ratio 3 : 2. How much does each get?</p>\n<p>Draw Alex as 3 equal boxes and Ben as 2 equal boxes — 5 boxes total sharing $120. Each box is 120 \xf7 5 = $24. So Alex gets 3 \xd7 24 = <strong>$72</strong> and Ben gets 2 \xd7 24 = <strong>$48</strong>. The bar model turned an algebra problem into counting boxes.</p>\n<p><strong>Worked example 2 (harder).</strong> After spending ⅖ of her money, Maya has $36 left. How much did she start with?</p>\n<p>Draw her money as 5 boxes; she spent 2, so 3 boxes remain and equal $36. One box = 12; five boxes = <strong>$60</strong>. Notice how the model dissolves the usual panic of \"reverse\" problems — the leftover is <em>visibly</em> 3 boxes, so you never mistakenly compute ⅖ of 36.</p>\n<div class=\"analogy\">\n  <h3>Analogy: Scaffolding, Not a Crutch</h3>\n  <p>The bar model is scaffolding for the equation x + \xb2⁄₃x = 120 you'll write comfortably after the algebra course (Subject 4). Scaffolding isn't cheating — it's how the building goes up. Even physicists sketch before they calculate; a force diagram is nothing but a grown-up bar model for vectors.</p>\n</div>\n<p><strong>Worked example 3, physics-flavored.</strong> Bronze is 7 parts copper to 1 part tin by mass. How much copper is in 4 kg of bronze? Eight boxes total; each box is 4 \xf7 8 = 0.5 kg; copper is 7 boxes = <strong>3.5 kg</strong>. Mixture and alloy problems — and later, mole-ratio chemistry and circuit current-splitting — are exactly this picture.</p>\n<p>Draw bars until you don't need to. The day the boxes appear in your head unbidden, you have acquired what teachers call proportional reasoning — and you'll spend the rest of this curriculum cashing it in.</p>"},{id:"direct-and-inverse-proportion",title:"Direct & Inverse Proportion",content:"\n<p>Two quantities are <strong>directly proportional</strong> when doubling one doubles the other — their <em>ratio</em> stays fixed. Distance at constant speed is the classic case: twice the time, twice the distance; d \xf7 t never changes. Writing it generally: y = kx for some constant k. The graph is a straight line <strong>through the origin</strong> — zero time, zero distance.</p>\n<p>Two quantities are <strong>inversely proportional</strong> when doubling one <em>halves</em> the other — their <em>product</em> stays fixed. Sharing a fixed job is the classic case: twice the workers, half the time; workers \xd7 time is constant. Generally: y = k \xf7 x, or equivalently x\xb7y = k.</p>\n<table>\n  <thead>\n    <tr><th></th><th>Direct (y = kx)</th><th>Inverse (x\xb7y = k)</th></tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>Double x...</strong></td><td>y doubles</td><td>y halves</td></tr>\n    <tr><td><strong>What's constant</strong></td><td>the ratio y \xf7 x</td><td>the product x\xb7y</td></tr>\n    <tr><td><strong>Physics examples</strong></td><td>distance & time (fixed speed); mass & volume (fixed density); voltage & current (fixed resistance — Ohm's law)</td><td>pressure & volume of a gas (Boyle's law); speed & travel time (fixed distance); current & resistance (fixed voltage)</td></tr>\n  </tbody>\n</table>\n<p><strong>Worked example (direct):</strong> 3 m of wire has mass 45 g. Mass of 8 m? Unit rate: 15 g per meter, so 8 \xd7 15 = <strong>120 g</strong>.</p>\n<p><strong>Worked example (inverse):</strong> a journey takes 6 hours at 40 km/h. How long at 60 km/h? The product speed \xd7 time is the fixed distance: 40 \xd7 6 = 240 km. Then 240 \xf7 60 = <strong>4 hours</strong>. Speeding up by half (\xd71.5) cut the time by the same factor (\xf71.5).</p>\n<div class=\"key-concept\">\n  <h3>Key Concept: Ask \"What Stays Constant?\"</h3>\n  <p>This question is the master key. Every proportion problem — and a shocking fraction of physics problems — is solved by identifying the invariant. Fixed ratio → direct. Fixed product → inverse. Later, whole subjects hang on invariants: energy conservation, momentum conservation, Boyle's law. Chapter 3 of a math course is where physicists are actually made.</p>\n</div>\n<p>One caution: not every increasing relationship is proportional. A taxi fare with a $5 flag-fall rises with distance but isn't proportional to it — its graph misses the origin, and doubling the distance doesn't double the fare. Always test with the doubling question before you deploy proportion machinery.</p>"},{id:"speed-distance-time",title:"Speed, Distance & Time",content:'\n<p>Your first real physics formula, arriving a full phase ahead of the physics course: <strong>speed = distance \xf7 time</strong>, or v = d \xf7 t. It\'s nothing but a unit rate — kilometers per one hour — which is why it belongs in this chapter. Every technique you\'ve built (unitary method, ratios, proportion) now gets a test drive on the most-used relationship in mechanics.</p>\n<p>One relationship, three rearrangements:</p>\n<ul>\n  <li>v = d \xf7 t — how fast? (unit rate)</li>\n  <li>d = v \xd7 t — how far? (rate \xd7 how long)</li>\n  <li>t = d \xf7 v — how long? (distance shared out at v per hour)</li>\n</ul>\n<p>Don\'t memorize a triangle diagram; instead <em>hear the sentence</em>: "at 60 km per hour, each hour delivers 60 km." From that sentence all three forms are obvious.</p>\n<p><strong>Worked example 1.</strong> A train covers 210 km in 2 h 30 min. Average speed? Convert time to hours: 2.5 h. Then v = 210 \xf7 2.5 = <strong>84 km/h</strong>. (Mixed units — kilometers with minutes — are the number-one source of wrong answers; convert first, always.)</p>\n<p><strong>Worked example 2 (the classic trap).</strong> A cyclist rides 30 km out at 15 km/h and returns at 10 km/h. Average speed for the round trip? <em>Not</em> 12.5. Average speed is total distance \xf7 total time. Out: 30 \xf7 15 = 2 h. Back: 30 \xf7 10 = 3 h. Total: 60 km in 5 h → <strong>12 km/h</strong>. You can\'t average rates directly, because the slower leg eats more time and drags the average toward itself.</p>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>"Speed" hides an assumption: that it was constant. Real trips speed up and slow down, so v = d \xf7 t gives the <em>average</em> speed. The instant-by-instant speed — what the speedometer shows — needs the idea of a limit, and chasing that idea rigorously is precisely what forced Newton to invent calculus. You are, right now, one honest question away from calculus.</p>\n</div>\n<p>Sanity-check habit: before computing, estimate. A 210 km trip in "about two and a half hours" should be "a bit over 80 km/h" — brisk highway driving, plausible. If your calculation had produced 840, the estimate would have flagged the slipped decimal instantly. Numbers in physics always mean something; check them against the world.</p>'},{id:"density-as-a-ratio",title:"Density: Your Second Physics Formula",content:'\n<p>Why do density problems feel hard for so many students? Not because density is deep — because density is a <em>ratio</em>, and ratio reasoning is exactly the skill schools under-built. You\'ve now built it, so let\'s collect the reward.</p>\n<p><strong>Density is mass per unit volume:</strong> ρ = m \xf7 V (physicists write density with the Greek letter ρ, "rho"). It answers: how much stuff is packed into each cubic centimeter? Water: 1 g/cm\xb3. Iron: 7.9 g/cm\xb3. Air: about 0.0012 g/cm\xb3. Same-size boxes of different materials have very different masses — density is the number that captures that.</p>\n<p>The crucial mental step: <strong>density belongs to the material, not the object</strong>. Cut an iron bar in half and each half has half the mass and half the volume — but the ratio, 7.9 g/cm\xb3, is untouched. A ratio that stays fixed while amounts change is exactly the "what stays constant?" invariant from the proportion section: for a given material, m and V are directly proportional, and density is the constant of proportionality. Speed is to distance-and-time what density is to mass-and-volume. One reasoning pattern, two costumes.</p>\n<p><strong>Worked example 1.</strong> A block measures 4 cm \xd7 5 cm \xd7 2 cm and has mass 316 g. Density? Volume = 40 cm\xb3, so ρ = 316 \xf7 40 = <strong>7.9 g/cm\xb3</strong> — matching iron. Congratulations: you\'ve just identified a metal with arithmetic, which is precisely how Archimedes audited the king\'s crown.</p>\n<p><strong>Worked example 2.</strong> What is the mass of 250 cm\xb3 of water? m = ρ \xd7 V = 1 \xd7 250 = <strong>250 g</strong>. And of 250 cm\xb3 of air? 0.0012 \xd7 250 = 0.3 g. Same volume, mass differing by a factor of ≈800 — which is why a "full" balloon still feels empty.</p>\n<div class="analogy">\n  <h3>Analogy: Crowdedness</h3>\n  <p>Density is crowdedness. A packed elevator and a packed stadium have wildly different numbers of people, but can have the same people-per-square-meter. Asking "which is denser?" is never asking "which is bigger or heavier?" — it\'s asking "which is more crowded?" Floating hangs on this: wood floats not because it\'s light (a log outweighs a nail) but because it\'s less crowded than water.</p>\n</div>\n<p>When density problems appear in Subject 5, they will offer you three quantities and ask for one. That\'s not a physics puzzle — it\'s the unitary method wearing a lab coat. You already know the move.</p>'}],quiz:[{question:"Alex and Ben share $150 in the ratio 2 : 3. Using a bar model, how much does Ben receive?",options:["$60 — Ben has 2 of the 5 boxes","$90 — five equal boxes of $30 each, and Ben has three of them","$100 — Ben gets two thirds","$75 — they split it evenly"],correctIndex:1,explanation:"Draw 2 boxes for Alex and 3 for Ben: 5 equal boxes share $150, so each box is $30. Ben's three boxes make $90 (Alex gets $60). The bar model reduces ratio-sharing to counting boxes — no algebra required."},{question:"A journey takes 6 hours at 40 km/h. How long does it take at 80 km/h, and why?",options:["12 hours — time is directly proportional to speed","4 hours — subtract the speed increase from the time","3 hours — speed and time are inversely proportional when distance is fixed: doubling speed halves the time","6 hours — travel time depends only on the route"],correctIndex:2,explanation:"The invariant is the distance: speed \xd7 time = 40 \xd7 6 = 240 km stays fixed. At 80 km/h, time = 240 \xf7 80 = 3 h. Recognizing 'fixed product → inverse proportion' is the master move; the same logic later runs Boyle's law for gases."},{question:"A cyclist travels 30 km at 15 km/h and returns at 10 km/h. What is the average speed for the whole trip?",options:["12.5 km/h — the average of 15 and 10","12 km/h — total distance (60 km) divided by total time (5 h)","13 km/h — weighted toward the faster leg","25 km/h — add the speeds"],correctIndex:1,explanation:"Average speed is always total distance \xf7 total time, never the average of the speeds. The slow leg takes 3 hours against the fast leg's 2, so the slow speed dominates: 60 \xf7 5 = 12 km/h. Rates can't be averaged directly because they carry unequal time weights."},{question:"A metal block has volume 40 cm\xb3 and mass 316 g. Its density is 7.9 g/cm\xb3. If the block is cut exactly in half, the density of each piece is...",options:["7.9 g/cm\xb3 — density is a ratio belonging to the material, unchanged by the amount","3.95 g/cm\xb3 — half the block, half the density","15.8 g/cm\xb3 — the same mass packs into less volume","Impossible to say without weighing the pieces"],correctIndex:0,explanation:"Halving the block halves both mass (158 g) and volume (20 cm\xb3), so the ratio 158 \xf7 20 = 7.9 g/cm\xb3 is untouched. This is what makes density an identifier of materials — and it's the same 'fixed ratio' structure as constant speed. Students who miss this are missing the ratio concept, not the physics."},{question:"A taxi charges a $5 flag-fall plus $2 per km. Why is the fare NOT directly proportional to distance?",options:["Because the fare involves money rather than physical quantities","Because doubling the distance doesn't double the fare, and the graph doesn't pass through the origin","It is directly proportional — the fare rises when distance rises","Because proportionality only applies to decreasing quantities"],correctIndex:1,explanation:"Direct proportion demands a fixed ratio: y = kx, a straight line through the origin. A 1 km ride costs $7 ($7/km) but a 10 km ride costs $25 ($2.50/km) — the ratio isn't constant, and at zero distance the fare is $5, not $0. 'It increases' is not enough; always apply the doubling test."}]},{id:"powers-roots-scientific-notation",title:"Powers, Roots & Scientific Notation",subtitle:"From repeated multiplication to the size of the universe — the notation that makes physics' huge and tiny numbers manageable",sections:[{id:"exponents-and-roots",title:"Exponents & Roots",content:'\n<p>An exponent is compressed multiplication: 2⁵ means 2 \xd7 2 \xd7 2 \xd7 2 \xd7 2 = 32. Say it as "2 to the 5th power." The notation earns its keep because physics quantities multiply <em>relentlessly</em> — areas are lengths squared, volumes are lengths cubed, energies go as speeds squared — and because exponents obey beautifully simple rules:</p>\n<ul>\n  <li><strong>Multiplying powers adds exponents:</strong> 10\xb3 \xd7 10⁴ = 10⁷. (Three tens times four tens is seven tens multiplied together.)</li>\n  <li><strong>Dividing subtracts:</strong> 10⁷ \xf7 10\xb3 = 10⁴.</li>\n  <li><strong>A power of a power multiplies:</strong> (10\xb3)\xb2 = 10⁶.</li>\n</ul>\n<p>Push the subtraction rule to its edges and two famous results fall out, no decree required. 10\xb3 \xf7 10\xb3 = 10⁰, but anything divided by itself is 1 — so <strong>10⁰ = 1</strong>. And 10\xb2 \xf7 10\xb3 = 10⁻\xb9, but 100 \xf7 1000 = 1⁄10 — so <strong>a negative exponent means a reciprocal</strong>: 10⁻\xb3 = 1⁄1000 = 0.001. Negative exponents aren\'t negative numbers; they\'re small positive ones. That distinction will matter every day of this course.</p>\n<p><strong>Roots undo powers.</strong> The square root of 49 asks: what number, squared, gives 49? Answer 7, written √49 = 7. Cube roots undo cubes: ∛64 = 4, since 4\xb3 = 64. Physics reaches for roots whenever it reasons backwards from an area, a volume, or an energy: if a square field has area 200 m\xb2, its side is √200 ≈ 14.1 m. If kinetic energy quadruples, speed only doubled — because energy carries a v\xb2, undone by a square root.</p>\n<div class="key-concept">\n  <h3>Key Concept: Squares Grow Fast, and Physics Feels It</h3>\n  <p>Doubling a speed quadruples the kinetic energy (2\xb2 = 4) — which is why a crash at 100 km/h is four times as destructive as at 50, not twice. Tripling the distance from a planet cuts gravity to a ninth (3\xb2 = 9). The nonlinear world of physics is largely the arithmetic of squares.</p>\n</div>\n<p>Worked example: fold a paper 0.1 mm thick 42 times (in imagination — physical folding gives out near 7). Thickness: 0.1 mm \xd7 2⁴\xb2 ≈ 0.1 \xd7 4.4 \xd7 10\xb9\xb2 mm ≈ 440,000 km — past the Moon. Exponential growth is not intuition-friendly; that\'s precisely why we need the notation.</p>'},{id:"scientific-notation",title:"Scientific Notation",content:'\n<p>Physics traffics in absurd numbers. The mass of the Earth: 5,972,000,000,000,000,000,000,000 kg. The mass of an electron: 0.000 000 000 000 000 000 000 000 000 000 911 kg. Written that way, they\'re unusable — uncountable zeros, invisible errors. <strong>Scientific notation</strong> fixes this by splitting every number into two jobs:</p>\n<p style="text-align:center"><strong>(a number between 1 and 10) \xd7 (a power of ten)</strong></p>\n<p>Earth\'s mass: 5.972 \xd7 10\xb2⁴ kg. Electron: 9.11 \xd7 10⁻\xb3\xb9 kg. The first factor carries the <em>digits</em> (the precision); the exponent carries the <em>size</em>. Two jobs, cleanly separated.</p>\n<p>Converting is place-value gymnastics from Chapter 1: count how many places the decimal point must slide to leave one nonzero digit in front. 34,500 → 3.45 \xd7 10⁴ (four slides left). 0.0072 → 7.2 \xd7 10⁻\xb3 (three slides right; small numbers get negative exponents).</p>\n<p>The real payoff is arithmetic — the exponent rules take over the heavy lifting:</p>\n<ul>\n  <li><strong>Multiply:</strong> multiply the fronts, add the exponents. (3 \xd7 10⁸) \xd7 (2 \xd7 10⁻⁵) = 6 \xd7 10\xb3.</li>\n  <li><strong>Divide:</strong> divide the fronts, subtract the exponents. (8 \xd7 10⁶) \xf7 (4 \xd7 10\xb2) = 2 \xd7 10⁴.</li>\n  <li><strong>Tidy up:</strong> if the front leaves the 1–10 range, slide once more: 60 \xd7 10\xb3 → 6 \xd7 10⁴.</li>\n</ul>\n<p><strong>Worked example.</strong> How long does sunlight take to reach Earth? Distance ≈ 1.5 \xd7 10\xb9\xb9 m; light speed ≈ 3 \xd7 10⁸ m/s. Time = distance \xf7 speed = (1.5 \xf7 3) \xd7 10\xb9\xb9⁻⁸ = 0.5 \xd7 10\xb3 = 5 \xd7 10\xb2 s = <strong>500 seconds ≈ 8⅓ minutes</strong>. A calculation spanning eleven orders of magnitude, done in one line, in your head.</p>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>Your calculator\'s "E notation" — 5.972E24 — is scientific notation wearing a keyboard-friendly disguise: E24 means \xd7 10\xb2⁴. Knowing this saves you from the classic blunder of typing 5.972 \xd7 10 ^ 24 with stray parentheses and getting an answer that is off by a factor of ten — an error scientific notation was invented to prevent.</p>\n</div>'},{id:"orders-of-magnitude",title:"Orders of Magnitude",content:'\n<p>An <strong>order of magnitude</strong> is a factor of ten. Two numbers are "an order of magnitude apart" when one is about ten times the other; "three orders" means a factor of about a thousand. It sounds like jargon, but it\'s really a decision to care about the <em>exponent</em> and treat the front number as a detail — physics\' favorite level of precision for a first look at anything.</p>\n<p>Why coarse-grain like this? Because at first contact with a problem, the exponent carries almost all the information. Whether a bacterium is 1 or 3 micrometers long barely matters; that it\'s 10⁻⁶ m rather than 10⁻\xb3 m is everything. A ladder to keep in your head:</p>\n<table>\n  <thead>\n    <tr><th>Scale (m)</th><th>Roughly...</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>10⁻\xb9⁵</td><td>a proton</td></tr>\n    <tr><td>10⁻\xb9⁰</td><td>an atom</td></tr>\n    <tr><td>10⁻⁶</td><td>a bacterium</td></tr>\n    <tr><td>10⁰</td><td>you (≈1–2 m)</td></tr>\n    <tr><td>10⁷</td><td>Earth\'s diameter (1.3 \xd7 10⁷ m)</td></tr>\n    <tr><td>10\xb9\xb9</td><td>Earth–Sun distance</td></tr>\n    <tr><td>10\xb9⁶</td><td>one light-year</td></tr>\n    <tr><td>10\xb2\xb9</td><td>the Milky Way\'s diameter</td></tr>\n    <tr><td>10\xb2⁶</td><td>the observable universe</td></tr>\n  </tbody>\n</table>\n<p>Notice the symmetry worth savoring: you stand roughly halfway (in factors of ten) between a proton and the observable universe — about 41 orders of magnitude in each direction? Not quite: 15 below, 26 above. Closer to atoms than to galaxies, but a middle creature either way.</p>\n<div class="analogy">\n  <h3>Analogy: The Zoom Slider</h3>\n  <p>Think of reality as a map app with a zoom slider, where each notch is \xd710. Nine notches out from your street: the whole planet. Nine notches in: a virus. The famous 1977 film <em>Powers of Ten</em> is exactly this ride, and the mental slider it installs is a permanent piece of physics equipment.</p>\n</div>\n<p><strong>Worked example.</strong> How many times more massive is the Sun (2 \xd7 10\xb3⁰ kg) than the Earth (6 \xd7 10\xb2⁴ kg)? Exponents first: 10\xb3⁰ \xf7 10\xb2⁴ = 10⁶ — about a million. Fronts: 2 \xf7 6 ≈ 0.33. Answer: ≈ 3.3 \xd7 10⁵, a third of a million. For most purposes, "the Sun is five to six orders of magnitude heavier" is the memorable, useful fact — and you computed it without a calculator.</p>'},{id:"fermi-estimation",title:"Fermi Estimation",content:"\n<p>The physicist Enrico Fermi was famous for producing good rough answers to seemingly impossible questions — how many piano tuners work in Chicago? — using nothing but everyday knowledge and powers of ten. A <strong>Fermi estimate</strong> aims not for the right answer but for the right <em>order of magnitude</em>: within a factor of ten. That sounds unambitious until you see how much it buys.</p>\n<p>The method:</p>\n<ol>\n  <li><strong>Break the question into factors you can roughly guess.</strong></li>\n  <li><strong>Round each factor to one digit times a power of ten.</strong></li>\n  <li><strong>Multiply, adding exponents as you go.</strong></li>\n</ol>\n<p>The magic is error cancellation: with several independently guessed factors, some guesses run high and others low, and the product usually lands within a factor of 2–3 of truth — the same opposite-direction cancellation you met while rounding in Chapter 1, now industrialized.</p>\n<p><strong>Worked example: how many breaths do you take in a lifetime?</strong></p>\n<ul>\n  <li>Breathing rate: ≈ 15 per minute ≈ 1.5 \xd7 10\xb9</li>\n  <li>Minutes per day: 60 \xd7 24 = 1,440 ≈ 1.5 \xd7 10\xb3</li>\n  <li>Days per year: ≈ 4 \xd7 10\xb2</li>\n  <li>Years: ≈ 8 \xd7 10\xb9</li>\n</ul>\n<p>Multiply fronts: 1.5 \xd7 1.5 \xd7 4 \xd7 8 ≈ 72. Add exponents: 10\xb9⁺\xb3⁺\xb2⁺\xb9 = 10⁷. Total ≈ 72 \xd7 10⁷ ≈ <strong>7 \xd7 10⁸ breaths</strong> — roughly a billion, give or take. No reference book on Earth has this number; you just manufactured it from things you already knew.</p>\n<p><strong>Worked example 2: could all of humanity fit in Lake Superior?</strong> A person's volume ≈ 0.07 m\xb3 (they mostly float, like water, and weigh ≈ 70 kg — density reasoning from Chapter 3!). Humanity: 8 \xd7 10⁹ people \xd7 7 \xd7 10⁻\xb2 m\xb3 ≈ 5.6 \xd7 10⁸ m\xb3. Lake Superior holds ≈ 1.2 \xd7 10\xb9\xb3 m\xb3. Verdict: humanity would fill about 0.005% of the lake. All of us, one lake, a rounding error.</p>\n<div class=\"key-concept\">\n  <h3>Key Concept: Estimation Is a Physicist's License</h3>\n  <p>Fermi problems train the exact reflexes real physics demands: decompose, approximate, track powers of ten, and sanity-check the result. Interviewers at national labs and tech firms still pose them, because the skill they reveal — reasoning confidently under uncertainty — is the job. From now on, estimate one absurd thing per week. It's the most enjoyable homework in this course.</p>\n</div>"}],quiz:[{question:"What is 10⁻\xb3 as an ordinary number?",options:["−1000 — the minus makes it negative","0.001 — a negative exponent means a reciprocal: 1⁄10\xb3","−0.001 — negative and small","0.003 — the 3 moves after the decimal point"],correctIndex:1,explanation:"A negative exponent is a reciprocal, not a negative number: 10⁻\xb3 = 1⁄10\xb3 = 1⁄1000 = 0.001, a small positive value. This follows from the division rule (10\xb2 \xf7 10\xb3 = 10⁻\xb9 = 1⁄10). Physics is full of 10⁻\xb9⁹s and 10⁻\xb3\xb9s — all tiny, none negative."},{question:"Light travels at 3 \xd7 10⁸ m/s and the Sun is 1.5 \xd7 10\xb9\xb9 m away. How long does sunlight take to reach Earth?",options:["500 s (about 8 minutes) — divide fronts (1.5 \xf7 3 = 0.5) and subtract exponents (11 − 8 = 3)","0.002 s — light is essentially instantaneous","4.5 \xd7 10\xb9⁹ s — multiply the numbers","50 s — subtract exponents to get 10\xb3 but ignore the fronts"],correctIndex:0,explanation:"Time = distance \xf7 speed = (1.5 \xf7 3) \xd7 10\xb9\xb9⁻⁸ = 0.5 \xd7 10\xb3 = 500 s ≈ 8⅓ min. Scientific notation turns an 11-orders-of-magnitude calculation into one-digit arithmetic plus exponent subtraction — the entire point of the notation."},{question:"Kinetic energy grows as the square of speed. A car doubles its speed from 50 to 100 km/h. Its kinetic energy...",options:["doubles — energy tracks speed","triples — one factor for speed, one for mass, one extra","quadruples — 2\xb2 = 4, which is why high-speed crashes are so disproportionately destructive","increases by 50 km/h worth"],correctIndex:2,explanation:"Squares turn a doubling into a quadrupling: (2v)\xb2 = 4v\xb2. This is the single most practical fact about exponents — stopping distances, crash energies, and wind loads all carry squares, so modest speed increases buy severe consequences."},{question:"In a Fermi estimate with several guessed factors, why does the final answer usually land within a factor of 2–3 of the truth?",options:["Because each individual guess is highly accurate","Because independent guesses err in both directions, and their errors partly cancel in the product","Because powers of ten cannot compound errors","It doesn't — Fermi estimates are typically off by factors of 100 or more"],correctIndex:1,explanation:"Each factor might be off by 2\xd7 either way, but overestimates and underestimates multiply against each other and largely cancel. This statistical mercy is why order-of-magnitude reasoning works at all — and why breaking a question into more independent factors often makes the estimate better, not worse."},{question:"Which is the correct scientific-notation form of 0.00042?",options:["42 \xd7 10⁻⁵ — front number can be anything","4.2 \xd7 10⁴ — count the four decimal places","0.42 \xd7 10⁻\xb3 — slide three places","4.2 \xd7 10⁻⁴ — one nonzero digit before the point, decimal slid four places right"],correctIndex:3,explanation:"Standard form requires the front number to sit between 1 and 10: 4.2. The decimal point slides four places right to get there, so the exponent is −4 (small number, negative exponent). The forms 42 \xd7 10⁻⁵ and 0.42 \xd7 10⁻\xb3 equal the same value but break the convention that makes numbers instantly comparable."}]},{id:"units-and-measurement",title:"Units & Measurement",subtitle:"SI units, conversion as multiplication by 1, dimensional thinking, and honest numbers — where math becomes measurement",sections:[{id:"the-si-system",title:"The SI System: One Language for Measurement",content:"\n<p>A measurement without a unit is a rumor. \"The rope is 12\" — twelve what? Physics enforces the rule absolutely: <strong>every measured quantity is a number times a unit</strong>, and the unit is not decoration — it's half the information. In 1999, NASA's $327-million Mars Climate Orbiter burned up because one team supplied thrust data in pound-force units while another read them as newtons. Units are not pedantry. Units are survival.</p>\n<p>The <strong>SI system</strong> (Syst\xe8me International) is science's shared measurement language. Everything you'll meet in this course is built from a handful of base units:</p>\n<table>\n  <thead>\n    <tr><th>Quantity</th><th>Unit</th><th>Symbol</th><th>Everyday anchor</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Length</td><td>meter</td><td>m</td><td>a long stride</td></tr>\n    <tr><td>Mass</td><td>kilogram</td><td>kg</td><td>a liter of water</td></tr>\n    <tr><td>Time</td><td>second</td><td>s</td><td>one \"one-Mississippi\"</td></tr>\n    <tr><td>Temperature</td><td>kelvin</td><td>K</td><td>Celsius shifted so 0 K is absolute zero (0\xb0C = 273.15 K)</td></tr>\n    <tr><td>Electric current</td><td>ampere</td><td>A</td><td>a bright LED bulb draws ≈ 0.05 A</td></tr>\n  </tbody>\n</table>\n<p>Everything else is <strong>derived</strong> by combining these: speed in m/s, volume in m\xb3, density in kg/m\xb3, and later force in kg\xb7m/s\xb2 (honored with its own name, the newton). Recognizing derived units as combinations is a preview of dimensional thinking, two sections from now.</p>\n<p>SI's masterstroke is its <strong>prefixes</strong> — the place-value system from Chapter 1, bolted onto units. Each prefix is a power of ten: kilo (10\xb3), mega (10⁶), giga (10⁹); going down, centi (10⁻\xb2), milli (10⁻\xb3), micro (10⁻⁶), nano (10⁻⁹). One set of prefixes, every unit: a kilometer, a kilogram, a kilowatt; a millimeter, a milliliter, a millisecond. Learn nine prefixes and you can read every instrument in a laboratory.</p>\n<div class=\"did-you-know\">\n  <h4>Did You Know?</h4>\n  <p>Since 2019, every SI base unit is defined by fixing a constant of nature — the second by a cesium atom's vibration, the meter by the speed of light, the kilogram via Planck's constant. The platinum-iridium kilogram cylinder in a Paris vault, humanity's last physical unit standard, is now a museum piece. Measurement no longer rests on any object anyone could scratch, steal, or lose.</p>\n</div>"},{id:"unit-conversion-as-multiplication-by-one",title:"Unit Conversion: Multiplying by 1",content:'\n<p>Most people convert units by half-remembered folklore: "multiply by 1000... or was it divide?" Physics has a method with no folklore in it, and it will carry you from this chapter through relativity: <strong>every unit conversion is a multiplication by 1</strong>.</p>\n<p>The trick: since 1 km = 1000 m, the fraction (1000 m ⁄ 1 km) equals exactly 1 — top and bottom are the same length in different costumes. Multiplying by it changes nothing real; it only changes the label. Then you let the units <strong>cancel like fractions</strong>:</p>\n<p style="text-align:center">3.5 km \xd7 (1000 m ⁄ 1 km) = 3,500 m — the km upstairs cancels the km downstairs.</p>\n<p>Which way up does the factor go? Let the cancellation decide: put the unit you\'re <em>leaving</em> where it will cancel. If nothing cancels, the factor is upside down — flip it. The method is self-correcting, which folklore never is.</p>\n<p><strong>Worked example (chained factors).</strong> Convert 90 km/h to m/s:</p>\n<p style="text-align:center">90 km⁄h \xd7 (1000 m ⁄ 1 km) \xd7 (1 h ⁄ 3600 s) = 90 \xd7 1000 \xf7 3600 = <strong>25 m/s</strong></p>\n<p>Each factor equals 1; km cancels km, h cancels h; only m/s survives. (The shortcut worth memorizing after you trust it: km/h \xf7 3.6 = m/s.)</p>\n<p><strong>Worked example (squared units — where folklore dies).</strong> Convert 2.5 m\xb2 to cm\xb2. Not 250! A square meter is a 100 cm \xd7 100 cm square: 10,000 cm\xb2. So 2.5 m\xb2 \xd7 (100 cm ⁄ 1 m) \xd7 (100 cm ⁄ 1 m) = <strong>25,000 cm\xb2</strong>. The conversion factor gets applied once per dimension — automatic with this method, invisible without it.</p>\n<div class="key-concept">\n  <h3>Key Concept: The Same "Clever 1" You Already Know</h3>\n  <p>In Chapter 2 you made equivalent fractions by multiplying by 2⁄2. This is the identical move with units in the costume: (1000 m ⁄ 1 km) is just a clever form of 1. One idea — multiplying by 1 never changes a value, only its appearance — now runs your fraction work AND your unit work. Physics is full of such economies.</p>\n</div>\n<p>From here on, treat units as algebraic objects that multiply, divide, and cancel. That single habit prevents the most common wrong answers in all of introductory physics — and it\'s the warm-up for the next section, where units stop being bookkeeping and start doing physics for you.</p>'},{id:"dimensional-thinking",title:"Dimensional Thinking",content:"\n<p>Here's a superpower disguised as bookkeeping. Every physical quantity has a <strong>dimension</strong> — its recipe in terms of length (L), mass (M), and time (T), regardless of which units dress it up. Speed has dimension L⁄T whether measured in m/s or furlongs per fortnight. Area is L\xb2. Density is M⁄L\xb3. Acceleration — speed's rate of change — is L⁄T\xb2.</p>\n<p>The power comes from one iron rule: <strong>an equation must have the same dimensions on both sides</strong>. You cannot equate meters to seconds, any more than you can owe someone 5 kilograms of money. Consequences:</p>\n<ul>\n  <li><strong>Error detection.</strong> Suppose you misremember distance fallen as d = \xbdgt (should it be t\xb2?). Check: g is L⁄T\xb2, times t gives L⁄T — a speed, not a distance. Wrong, caught in five seconds, no experiment needed. With t\xb2: L⁄T\xb2 \xd7 T\xb2 = L ✓.</li>\n  <li><strong>Formula reconstruction.</strong> Forgot the pendulum period formula? It should involve length ℓ and gravity g (L⁄T\xb2). To build a time from L and L⁄T\xb2: divide ℓ by g to get T\xb2, then square-root. So the period ≈ √(ℓ⁄g) — correct up to the dimensionless 2π that dimensions can never see. You just recovered physics from bookkeeping.</li>\n  <li><strong>Sanity in every answer.</strong> If a problem asks for a mass and your result carries m\xb3, no further review is required: it's wrong.</li>\n</ul>\n<div class=\"analogy\">\n  <h3>Analogy: Grammar Check for Equations</h3>\n  <p>\"The purple seven slept furiously\" is grammatical nonsense even before you ask if it's true. Dimensional analysis is grammar-checking for physics: it can't confirm an equation is <em>right</em>, but it instantly exposes whole categories of wrongness — and physicists run this check reflexively on every formula they write or recall.</p>\n</div>\n<p><strong>Worked example.</strong> A student derives that a dropped object's landing speed is v = √(2gh). Check it: inside the root, g \xd7 h has dimensions (L⁄T\xb2) \xd7 L = L\xb2⁄T\xb2. The square root gives L⁄T — a speed ✓. Note what the check costs: nothing. Note what it catches over a career: everything from sign-of-exhaustion slips to deep misunderstandings.</p>\n<p>When formulas multiply in Phase 2 — and they will — dimensional thinking is what separates students who memorize twenty formulas nervously from students who carry three ideas confidently and rebuild the rest on demand. Build the reflex now: <em>every</em> equation you meet, ask it to show its dimensions at the door.</p>"},{id:"significant-figures",title:"Significant Figures: Honest Numbers",content:"\n<p>Measure a table with a ruler marked in millimeters and report the length as 1.274063 m, and you have told a lie — not about the table, but about your ruler. No instrument justifies those last four digits. <strong>Significant figures</strong> are the discipline of reporting exactly as much precision as you actually have: every digit you write is a claim, and honest numbers make only defensible claims.</p>\n<p>Reading significance:</p>\n<ul>\n  <li><strong>Nonzero digits always count:</strong> 47.3 has three sig figs.</li>\n  <li><strong>Zeros between digits count:</strong> 4,003 has four.</li>\n  <li><strong>Leading zeros never count:</strong> 0.0052 has two — the zeros just locate the decimal point. (Scientific notation says it cleanly: 5.2 \xd7 10⁻\xb3.)</li>\n  <li><strong>Trailing zeros after a decimal point count:</strong> 2.500 has four — writing them is a deliberate claim of precision. A bare 2,500 is ambiguous, which is precisely why scientists prefer 2.5 \xd7 10\xb3 (two sig figs) or 2.500 \xd7 10\xb3 (four).</li>\n</ul>\n<p>Calculating without inflating precision:</p>\n<ul>\n  <li><strong>Multiplying/dividing:</strong> the answer keeps as many sig figs as the <em>least</em> precise input. 12.3 (three) \xd7 4.6 (two) = 56.58 → report <strong>57</strong>.</li>\n  <li><strong>Adding/subtracting:</strong> the answer keeps the least precise <em>decimal place</em>. 12.11 + 0.043 = 12.153 → report <strong>12.15</strong>.</li>\n  <li><strong>Round only at the end.</strong> Carry full digits through intermediate steps; premature rounding compounds.</li>\n</ul>\n<div class=\"key-concept\">\n  <h3>Key Concept: A Chain Is as Precise as Its Weakest Measurement</h3>\n  <p>Multiplying a superbly measured 3.14159 by a crudely measured 2.1 yields a crude product. No arithmetic can add information that a measurement failed to capture. Calculators are the enemy here — they will happily hand you ten digits of fiction; sig figs are how you decline.</p>\n</div>\n<p><strong>Worked example.</strong> A block's sides measure 2.1 cm, 3.45 cm, 1.2 cm. Volume: 2.1 \xd7 3.45 \xd7 1.2 = 8.694 cm\xb3. The stingiest inputs have two sig figs, so report <strong>8.7 cm\xb3</strong>. If its mass is 68.5 g, density = 68.5 \xf7 8.694 ≈ 7.879... → <strong>7.9 g/cm\xb3</strong> (two sig figs) — iron again, and now stated with exactly the confidence the ruler deserves.</p>\n<p>This is your first taste of measurement uncertainty, which Subject 3 develops properly and lab work lives by. The theme deserves its banner: <strong>physics is not about exact numbers; it's about known precision</strong>.</p>"}],quiz:[{question:"Convert 90 km/h to m/s using conversion factors. Which is the correct setup and result?",options:["90 \xd7 (1000 m ⁄ 1 km) \xd7 (1 h ⁄ 3600 s) = 25 m/s — each factor equals 1, and km and h cancel","90 \xd7 3600 \xf7 1000 = 324 m/s — hours convert first","90 \xf7 1000 \xd7 3600 = 324 m/s — the factors flip","90 \xf7 60 = 1.5 m/s — divide by minutes"],correctIndex:0,explanation:"Each factor is a 'clever form of 1' (top equals bottom), so the value is unchanged while km cancels km and h cancels h: 90 \xd7 1000 \xf7 3600 = 25 m/s. If units don't cancel, a factor is upside down — the method is self-correcting, which is why physicists trust it over memorized rules."},{question:"How many cm\xb2 are in 2.5 m\xb2?",options:["250 — multiply by 100","2,500 — multiply by 1000","25,000 — the factor of 100 applies once per dimension: 2.5 \xd7 100 \xd7 100","250,000 — apply 100 three times"],correctIndex:2,explanation:"A square meter is a 100 cm \xd7 100 cm square = 10,000 cm\xb2. Squared units need the conversion factor squared: 2.5 \xd7 10⁴ = 25,000 cm\xb2. Writing the factor (100 cm ⁄ 1 m) twice makes this automatic — forgetting it is the single most common conversion error in physics homework."},{question:"A student recalls the distance-fallen formula as d = \xbdgt (g in m/s\xb2, t in seconds). What does a dimensional check reveal?",options:["The formula is fine — the \xbd fixes the dimensions","The right side has dimensions L⁄T (a speed), not L, so a factor of t is missing: it must be t\xb2","Dimensions can't test formulas containing constants","The formula fails only for large values of t"],correctIndex:1,explanation:"g \xd7 t has dimensions (L⁄T\xb2) \xd7 T = L⁄T — a speed, not a distance, so the equation is grammatically impossible; with t\xb2 it gives L ✓. Pure numbers like \xbd carry no dimensions, so they can't rescue a mismatch. This five-second check catches misremembered formulas before they cost you a problem set."},{question:"How many significant figures does 0.00520 have?",options:["six — count every digit","five — count all zeros after the decimal point","two — trailing zeros never count","three — the leading zeros only place the decimal point, but the trailing zero is a deliberate claim of precision"],correctIndex:3,explanation:"Leading zeros are placeholders (not significant); the 5, the 2, and the final 0 are significant — that trailing zero asserts the measurement resolved that digit. Scientific notation removes all doubt: 5.20 \xd7 10⁻\xb3 displays exactly its three significant figures, which is one reason scientists prefer it."},{question:"Sides of a block measure 2.1 cm, 3.45 cm, and 1.2 cm. A calculator gives the volume as 8.694 cm\xb3. What should you report, and why?",options:["8.694 cm\xb3 — never discard computed digits","8.7 cm\xb3 — the least precise measurements have two significant figures, and no calculation can exceed its weakest input","8.69 cm\xb3 — match the most precise measurement","9 cm\xb3 — always round to whole numbers in a lab"],correctIndex:1,explanation:"For multiplication, the result inherits the sig-fig count of the least precise factor — here two (2.1 and 1.2). The extra calculator digits are fiction: they claim a precision the ruler never delivered. Report 8.7 cm\xb3. Honest precision is the foundation of the uncertainty analysis you'll meet in real lab work."}]}]},{id:"phenomena-of-physics",number:2,title:"The Phenomena of Physics",description:"The entire primary-science 'starter set' of the world's best school systems — every physics phenomenon, qualitatively, with at-home experiments.",phase:1,chapters:[{id:"matter-and-materials",title:"Matter & Materials",subtitle:"Solids, liquids, gases, and the particle picture that explains them all",sections:[{id:"three-states",title:"The Three States of Matter",content:'\n<p>Look around you right now. Everything you can see or touch — the chair beneath you, the water in your glass, the air filling the room — is <strong>matter</strong>, and almost all of it comes in one of three familiar states: <strong>solid</strong>, <strong>liquid</strong>, or <strong>gas</strong>.</p>\n<p>Each state behaves in its own recognizable way:</p>\n<ul>\n  <li><strong>Solids</strong> keep their shape and their size. A spoon stays spoon-shaped whether it sits on the table or in a drawer. You cannot squash it smaller by squeezing.</li>\n  <li><strong>Liquids</strong> keep their size but not their shape. Pour the same cup of water into a tall glass, a wide bowl, or a zig-zag straw and it takes the shape of whatever holds it — yet the amount never changes. Liquids also find their own level: the surface of still water is always flat and horizontal.</li>\n  <li><strong>Gases</strong> keep neither shape nor size. Open a bottle of perfume in one corner of a room and within minutes someone at the far side smells it. A gas spreads out to fill every bit of available space.</li>\n</ul>\n<p>The same substance can appear in all three states. Water is the everyday example: ice in the freezer, liquid water from the tap, and invisible water vapour in the air. It is still water throughout — nothing is added or removed, only the state changes.</p>\n<div class="analogy">\n  <h3>Analogy: A Crowd in Three Moods</h3>\n  <p>Picture people in a stadium. A solid is the seated crowd — everyone in a fixed place, jiggling slightly but not swapping seats. A liquid is the crowd on the concourse at half-time — packed shoulder to shoulder but sliding past one another. A gas is the crowd after the game, scattered across the whole city, each person moving freely with lots of empty space between them.</p>\n</div>\n<div class="key-concept">\n  <h3>Key Concept: State Is Behaviour, Not Identity</h3>\n  <p>Freezing water does not turn it into a new substance — it just makes the same substance behave differently. State describes how matter behaves, not what it is.</p>\n</div>'},{id:"properties-of-materials",title:"Properties of Materials",content:'\n<p>Why are windows made of glass, saucepans of metal, and raincoats of plastic-coated fabric? Because every material has a personality — a set of <strong>properties</strong> — and we choose materials whose properties match the job.</p>\n<p>Some properties you can test with your hands and eyes:</p>\n<ul>\n  <li><strong>Hardness</strong> — does it resist scratching and denting? Steel is hard; wax is soft.</li>\n  <li><strong>Flexibility</strong> — does it bend without breaking? A rubber band bends; a ceramic tile snaps.</li>\n  <li><strong>Strength</strong> — how much pulling or squashing can it take before it fails? A steel cable can hold up a bridge; a cotton thread cannot.</li>\n  <li><strong>Transparency</strong> — does light pass through? Glass yes, brick no.</li>\n  <li><strong>Waterproofness</strong> — does water soak in or run off? Compare a sponge with a plastic bag.</li>\n  <li><strong>Conduction</strong> — does heat (or electricity) travel through it easily? Metals feel cold to the touch because they carry heat away from your skin quickly; wood feels warmer because it does not.</li>\n</ul>\n<p>Notice that a property belongs to the <strong>material</strong>, not the object. A steel spoon and a steel bridge share the properties of steel. That is why engineers talk about "choosing a material" before they design anything.</p>\n<table>\n  <thead>\n    <tr><th>Job</th><th>Property needed</th><th>Good material</th><th>Bad material</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Window</td><td>Transparent, rigid</td><td>Glass</td><td>Wood</td></tr>\n    <tr><td>Saucepan</td><td>Conducts heat, high melting point</td><td>Metal</td><td>Plastic</td></tr>\n    <tr><td>Saucepan handle</td><td>Does <em>not</em> conduct heat</td><td>Plastic, wood</td><td>Metal</td></tr>\n    <tr><td>Raincoat</td><td>Waterproof, flexible</td><td>Coated fabric</td><td>Paper</td></tr>\n  </tbody>\n</table>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>Modern smartphone screens use a special glass that has been chemically treated to be far harder than ordinary window glass — a reminder that we can engineer a material\'s properties, not just accept them.</p>\n</div>'},{id:"changing-state",title:"Melting, Freezing & Evaporation",content:'\n<p>Matter changes state when it is heated or cooled, and every change has a name:</p>\n<ul>\n  <li><strong>Melting:</strong> solid → liquid (ice cube → puddle). Happens when a solid is warmed enough.</li>\n  <li><strong>Freezing:</strong> liquid → solid (water → ice). Happens when a liquid is cooled enough.</li>\n  <li><strong>Evaporation:</strong> liquid → gas, happening quietly from the surface at any temperature. This is why puddles vanish on a dry day even though the water never boils.</li>\n  <li><strong>Boiling:</strong> liquid → gas throughout the whole liquid at once — the rolling bubbles in a kettle.</li>\n  <li><strong>Condensation:</strong> gas → liquid (the mist on a cold mirror after a shower, the droplets on a cold drink can).</li>\n</ul>\n<p>Two everyday observations are worth savouring. First, each pure substance changes state at its own fixed temperature: water freezes at 0 \xb0C and boils at 100 \xb0C at sea level, while chocolate melts at roughly body temperature — which is precisely why it melts in your mouth. Second, these changes are <strong>reversible</strong>: melt ice, refreeze the water, and you are back where you started. Contrast that with toasting bread or frying an egg, which can never be undone — those are changes of substance, not just of state.</p>\n<p>Evaporation speeds up when the liquid is warmer, when it is spread out, and when air moves across it. Laundry knows all three rules: it dries fastest on a warm, breezy day with the clothes spread wide on the line.</p>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Pour equal small amounts of water into two saucers. Leave one flat and open; cover the other with an upturned bowl. Put both in the same warm spot and check after a day. The open saucer will be nearly dry while the covered one is still wet — the escaping water needed open air to evaporate into. Now breathe gently onto a cold mirror or window: the fog that appears is the reverse trip, water vapour from your breath condensing back into liquid.</p>\n</div>'},{id:"particle-picture",title:"The Particle Picture",content:'\n<p>Here is the single most powerful idea in this whole subject: <strong>all matter is made of tiny particles, far too small to see, and the particles are always moving</strong>. Accept that one sentence, and everything in the previous sections stops being a list of facts and becomes obvious.</p>\n<ul>\n  <li>In a <strong>solid</strong>, the particles are packed tightly in a regular arrangement, each one vibrating on the spot but held by its neighbours. That is why solids keep their shape and cannot be squashed.</li>\n  <li>In a <strong>liquid</strong>, the particles are still touching but can slide past one another. The substance holds together — fixed volume — yet flows into any shape.</li>\n  <li>In a <strong>gas</strong>, the particles are far apart and flying freely in all directions, colliding and rebounding. That is why gases spread to fill any space and can be squeezed into a smaller volume (there is mostly emptiness between the particles).</li>\n</ul>\n<p>Heating matter is simply making its particles move faster. Warm a solid and the vibrations grow until the particles shake loose from their positions — that is melting. Warm a liquid and the fastest particles at the surface break free entirely — that is evaporation. Cool a gas and slow-moving particles begin to stick when they collide — that is condensation. Temperature, state changes, why smells drift across a room, why a sealed balloon slowly deflates: one tiny-particle picture explains them all.</p>\n<div class="key-concept">\n  <h3>Key Concept: Nothing Appears, Nothing Vanishes</h3>\n  <p>When a puddle "disappears", every single particle of water still exists — the particles have merely escaped into the air one by one. Changes of state rearrange particles; they never create or destroy them.</p>\n</div>\n<div class="analogy">\n  <h3>Analogy: The Dance Floor</h3>\n  <p>Slow music: dancers sway in place, holding hands — a solid. Faster music: they let go and weave among each other, still close — a liquid. Turn the music all the way up: they leap apart and bounce around the whole hall — a gas. The dancers never change; only their energy does.</p>\n</div>'}],quiz:[{question:"Which state of matter keeps its volume but takes the shape of its container?",options:["Solid","Liquid","Gas","All three do"],correctIndex:1,explanation:"A liquid's particles stay in contact (so the volume is fixed) but can slide past one another (so the shape adapts to the container). Solids keep both shape and volume; gases keep neither."},{question:"A puddle dries up on a warm day even though the water never gets close to boiling. What is happening?",options:["The water soaks entirely into the ground","The water is destroyed by sunlight","The fastest particles at the surface escape into the air — evaporation","The water freezes and then disappears"],correctIndex:2,explanation:"Evaporation happens from the surface of a liquid at any temperature: the most energetic particles break free one by one and mix into the air. No particle is destroyed — they all still exist as invisible water vapour."},{question:"Why does a metal spoon feel colder than a wooden spoon at the same room temperature?",options:["Metal is genuinely at a lower temperature than wood","Wood generates its own heat","Metal contains frozen particles","Metal conducts heat away from your hand quickly; wood does not"],correctIndex:3,explanation:"Both spoons are at room temperature. The metal merely carries heat away from your warm skin much faster, and that rapid heat loss is what your nerves report as 'cold'. Feel is a measure of heat flow, not of temperature."},{question:"According to the particle picture, what changes when a solid melts?",options:["The particles gain enough energy to break loose from fixed positions and slide past each other","The particles themselves turn into liquid particles","New particles are created between the old ones","The particles shrink so they can flow"],correctIndex:0,explanation:"The particles are identical before and after melting. Heating makes them vibrate harder until they shake free of their fixed arrangement and can slide around — the same particles, just with more energy and more freedom."}]},{id:"forces-all-around",title:"Forces All Around",subtitle:"Pushes, pulls, gravity, friction, magnets, levers, and why things float or sink",sections:[{id:"pushes-pulls-gravity",title:"Pushes, Pulls & Gravity",content:'\n<p>A <strong>force</strong> is simply a push or a pull. That modest definition covers everything: kicking a ball (push), opening a drawer (pull), squeezing a sponge (a pair of pushes), stretching a rubber band (a pair of pulls). Forces are invisible, but their effects are not — a force can <strong>start</strong> something moving, <strong>stop</strong> it, <strong>speed it up</strong>, <strong>slow it down</strong>, <strong>change its direction</strong>, or <strong>change its shape</strong>.</p>\n<p>One pull acts on you every second of your life: <strong>gravity</strong>. The Earth pulls everything toward its centre, which is why dropped keys fall down and never sideways, why rivers flow downhill, and why "down" in Australia points in the opposite direction to "down" in Europe — both point toward the middle of the planet.</p>\n<p>This lets us untangle two words that everyday speech muddles together:</p>\n<ul>\n  <li><strong>Mass</strong> is how much matter something contains — how much "stuff" it is made of. Your mass would be the same on the Moon as on Earth.</li>\n  <li><strong>Weight</strong> is the pull of gravity on that mass. On the Moon, where gravity\'s pull is about one-sixth as strong, you would weigh about one-sixth as much — while being exactly the same person, made of exactly the same amount of stuff.</li>\n</ul>\n<div class="key-concept">\n  <h3>Key Concept: Forces Come in Interactions</h3>\n  <p>A force is never something an object "has"; it is something one object <em>does to another</em>. The Earth pulls the apple; your foot pushes the ball; the magnet pulls the pin. Every force sentence needs two characters.</p>\n</div>\n<div class="analogy">\n  <h3>Analogy: The Invisible Hands</h3>\n  <p>Imagine every force as an invisible hand. Watch a leaf settle to the ground and you can narrate the hands at work: gravity\'s hand pulling it steadily down, the air\'s hand brushing upward against it. Physicists never see forces either — they read them from what the motion does.</p>\n</div>'},{id:"friction-and-springs",title:"Friction & Elastic Forces",content:'\n<p>Slide a book across a table and it always stops. Nothing visible grabs it — what stops it is <strong>friction</strong>, the force that appears whenever two surfaces rub. Zoom in on even a polished tabletop and you would find a mountain range of microscopic bumps; sliding means dragging one mountain range across another, and that resistance is friction.</p>\n<p>Friction is a two-faced friend:</p>\n<ul>\n  <li><strong>We fight it</strong> when it wastes effort: oil in engines, ball bearings in wheels, wax on skis, the smooth ice of a rink — all are tricks for reducing friction.</li>\n  <li><strong>We depend on it</strong> constantly: without friction you could not walk (your shoes would slip as on perfect ice), cars could not grip the road, knots would untie themselves, and a nail would slide straight out of the wall. Tyre treads and shoe soles are designed to <em>increase</em> friction.</li>\n</ul>\n<p>A second everyday force lives in stretched and squashed things. Pull a rubber band and you feel it pull back; the further you stretch, the harder it resists. Squash a sponge and it pushes outward, springing back the moment you let go. This is the <strong>elastic force</strong>: certain materials fight to return to their natural shape. Springs in mattresses, trampolines, bows, pens, and bathroom scales all exploit it. (Bathroom scales literally measure how much your weight squashes a spring.)</p>\n<p>Stretch anything too far, though, and it stops springing back — a rubber band snaps, a spring stays bent. Every elastic material has its limit.</p>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Make a friction ramp: tilt a large book or tray and place a coin, an eraser, and an ice cube (or a wet bottle cap) at the top. Slowly increase the tilt. The ice slides first, the coin next, the rubbery eraser last — the grippier the surface pair, the steeper the slope needed before the pull of gravity beats friction. Now tape a strip of sandpaper or a rough cloth to the ramp and watch the order change.</p>\n</div>'},{id:"magnets-and-poles",title:"Magnets & Their Poles",content:'\n<p>Most forces need contact — you cannot push a door without touching it. Magnets break that rule: a magnet pulls a steel paper clip <strong>across empty space</strong>, through air, through a sheet of paper, even through water. This "action at a distance" is what makes magnets feel like magic, and it is your first meeting with the idea that a force can reach out through a region of space.</p>\n<p>The essential facts, all checkable at your kitchen table:</p>\n<ul>\n  <li>Every magnet has two ends called <strong>poles</strong> — north and south. Cut a magnet in half and you do not get a lone north and a lone south; you get two smaller magnets, each with both poles.</li>\n  <li><strong>Opposite poles attract; like poles repel.</strong> Bring two north poles together and you can feel a springy, invisible cushion pushing them apart. Repulsion is the sure test for a magnet — attraction alone might just mean unmagnetized steel.</li>\n  <li>Magnets attract only a few materials — iron and steel above all (plus nickel and cobalt). Aluminium foil, copper coins, plastic, glass, and wood are ignored completely. "Metal" and "magnetic" are not the same thing.</li>\n  <li>The pull weakens rapidly with distance: a paper clip leaps to a magnet a centimetre away but feels nothing from across the table.</li>\n</ul>\n<p>The Earth itself behaves like a colossal, weak magnet — which is why a freely swinging magnetized needle settles pointing north-south. That is all a compass is, and sailors trusted their lives to this piece of physics for a thousand years.</p>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>Migrating birds, sea turtles, and even some bacteria can sense the Earth\'s magnetism and use it to navigate — a built-in compass, refined by evolution long before humans discovered lodestones.</p>\n</div>'},{id:"balance-levers-floating",title:"Balance, Levers & Floating",content:'\n<p>When two forces on an object pull with equal strength in opposite directions, they cancel: the forces are <strong>balanced</strong> and the object stays put. A book resting on a table is not force-free — gravity pulls it down while the table pushes it up, in a perfect standoff. A tug-of-war with neither side moving is the same standoff made visible.</p>\n<p>The <strong>lever</strong> is the oldest force-multiplying trick humans know. A rigid bar tipping about a fixed point (the <strong>pivot</strong>) lets a small push win against a big load — provided the small push acts far from the pivot and the load sits close to it. A see-saw says it plainly: a small child far from the middle balances a heavy adult sitting near it. <strong>Distance from the pivot trades against force.</strong> Crowbars, wheelbarrows, scissors, bottle openers, and door handles are all levers in disguise; that is why a longer wrench loosens a stubborn bolt more easily.</p>\n<p>Floating is a force standoff too. Push an inflated ball underwater and you feel the water pushing it firmly back up. Every liquid pushes upward on anything placed in it — the <strong>upthrust</strong>. Whether an object floats or sinks is a duel: gravity pulling down versus upthrust pushing up. A stone loses the duel and sinks; a cork wins and floats.</p>\n<p>What decides the winner is not weight alone but weight <em>for its size</em>. A massive steel ship floats because its hull encloses so much air that, taken as a whole, it is light for its enormous size; a small dense pebble sinks. Squeeze a lump of foil into a tight ball and it sinks; shape the same foil into a boat and it floats.</p>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Fill a bowl with water. Shape a piece of kitchen foil into a little boat — it floats, and will even carry a cargo of coins. Now crumple the identical piece of foil into a tight ball and it sinks. Same material, same weight; only the shape, and therefore the size for that weight, has changed.</p>\n</div>'}],quiz:[{question:"An astronaut travels from Earth to the Moon. What happens to her mass and weight?",options:["Both mass and weight stay the same","Mass stays the same; weight becomes about one-sixth","Weight stays the same; mass becomes about one-sixth","Both become about one-sixth"],correctIndex:1,explanation:"Mass is the amount of matter in her body, and no journey changes that. Weight is the pull of gravity on that mass — and since the Moon's gravity is about one-sixth as strong as Earth's, her weight drops to about one-sixth while her mass is untouched."},{question:"Which situation shows friction being helpful rather than a nuisance?",options:["A car's brakes gripping the wheels to stop at a red light","An engine part wearing out from rubbing","A drawer that sticks and is hard to open","A cyclist slowed down by a rusty, unoiled chain"],correctIndex:0,explanation:"Brakes work entirely by friction: pads rub against the wheel and the grip slows the car. Walking, driving, and holding objects all depend on friction — it is only a nuisance when it resists motion we want, as in the other three cases."},{question:"What is the one sure test that an object is itself a magnet?",options:["It is attracted to a magnet","It is made of metal","It repels one pole of a known magnet","It feels heavy for its size"],correctIndex:2,explanation:"Plain iron or steel is attracted to either pole of a magnet, so attraction proves nothing. Only a magnet can repel — like poles push apart — so repulsion is the definitive test."},{question:"A huge steel ship floats while a small steel bolt sinks. Why?",options:["The ship's engines constantly push it upward","Salt water only holds up large objects","The ship is made of a special floating steel","The ship's hull encloses so much air that it is light for its overall size, so the water's upthrust can win"],correctIndex:3,explanation:"Floating is a duel between gravity (down) and the water's upthrust (up). What matters is weight for its size: the hollow hull makes the ship-as-a-whole light for the huge space it occupies, so upthrust wins. The solid bolt is heavy for its small size, so gravity wins."}]},{id:"light-and-shadow",title:"Light & Shadow",subtitle:"Where light comes from, how it travels, and what happens when something blocks it",sections:[{id:"light-sources-and-seeing",title:"Light Sources & How We See",content:'\n<p>Some things make their own light: the Sun, a candle flame, a light bulb, a firefly, a phone screen. These are <strong>light sources</strong>. Everything else — the Moon, this page, your own face in a mirror — is visible only because it <strong>bounces light from a source</strong> into your eyes. The Moon is the classic surprise: it produces no light of its own and shines purely by reflecting sunlight, like a dusty grey mirror hanging in space.</p>\n<p>That leads to the central rule of seeing: <strong>you see an object when light from it enters your eye</strong>. For a lamp, the light comes directly. For a book, light from the lamp bounces off the page and then enters your eye. Two steps, but the last step is always the same — no light into the eye, no seeing.</p>\n<p>The proof is <strong>darkness</strong>. In a room with truly no light — a windowless cellar at night — you see nothing at all, no matter how long you wait. Your eyes never "adjust to total darkness" because there is nothing to adjust to; the adjusting we experience at night is our eyes becoming more sensitive to the small amounts of light that are still present (moonlight, starlight, a distant streetlamp under the door).</p>\n<p>The ancient Greeks had it backwards: several believed the eye sent out invisible rays that felt objects, like a torch beam in reverse. The cellar test defeats that idea in one move — if eyes emitted their own rays, we could see in a coal mine.</p>\n<div class="key-concept">\n  <h3>Key Concept: Source → Object → Eye</h3>\n  <p>Every act of seeing is a delivery of light along a path: from a source, possibly bouncing off objects, and finally into your eye. Trace that path and you can explain every shadow, mirror, and reflection in this chapter.</p>\n</div>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>Light is the fastest thing in the universe — about 300,000 km every second. Sunlight still needs over 8 minutes to reach Earth, so you always see the Sun as it was 8 minutes ago.</p>\n</div>'},{id:"straight-lines-and-shadows",title:"Straight Lines & Shadows",content:"\n<p>Light travels in <strong>straight lines</strong>. You have seen the evidence often: sunbeams slicing through gaps in clouds, a torch beam cutting through mist, laser pointers, the crisp edge of the light patch a window throws on the floor. Light never bends around a corner on its own — which is why you cannot see around corners without a mirror.</p>\n<p>Straight-line travel explains <strong>shadows</strong> completely. Put an object in light's path and the light cannot swerve around it; behind the object lies a region the light simply cannot reach. That region of blocked light is the shadow. Three consequences follow, each one checkable:</p>\n<ul>\n  <li><strong>A shadow takes the outline of the object that casts it</strong> — the straight rays project the object's silhouette onto whatever is behind.</li>\n  <li><strong>Shadows fall on the opposite side from the source.</strong> Walk away from a low evening sun and your shadow stretches ahead of you.</li>\n  <li><strong>The geometry sets the size.</strong> Move an object close to a lamp and its shadow on the wall grows huge; move it near the wall and the shadow shrinks toward the object's true size. Shadow puppetry is nothing but this rule performed with skill.</li>\n</ul>\n<p>The same logic runs on the grandest scale. Your shadow at noon is short because the Sun stands high; in the evening it stretches long because the Sun sits low. And a solar eclipse is simply the Moon's shadow falling on the Earth — the everyday physics of a hand blocking a lamp, enlarged to the size of worlds.</p>\n<div class=\"did-you-know\">\n  <h4>Try it yourself</h4>\n  <p>In a dark room, shine a phone torch at a wall and hold your hand halfway between. Now move your hand slowly toward the torch: the shadow grows enormous and its edges soften. Move your hand toward the wall: the shadow shrinks and sharpens. You are watching straight-line rays being blocked, and you can predict every change before it happens.</p>\n</div>"},{id:"reflection-and-mirrors",title:"Reflection & Mirrors",content:'\n<p>When light strikes a surface, some of it bounces off — that is <strong>reflection</strong>. Every surface you can see is reflecting light; the difference between a page and a mirror is <em>how</em> they reflect it.</p>\n<ul>\n  <li>A rough surface, like paper — microscopically full of bumps — scatters incoming light in all directions. That scattered light is what lets everyone in the room see the page from wherever they sit.</li>\n  <li>A mirror is so smooth that light bounces off cleanly and in an orderly way, like a ball rebounding from a flat wall. The ordered bounce preserves the pattern of the incoming light — and a preserved pattern is exactly what an <strong>image</strong> is.</li>\n</ul>\n<p>The bounce itself follows one tidy rule: light leaves a mirror at the same angle it arrived, just as a snooker ball rebounds off the cushion at the angle it came in. From this one rule comes everything mirrors do — including letting you see around corners: light from a hidden object strikes the angled mirror and rebounds toward your eye. Periscopes, car wing mirrors, and shop security mirrors are all corner-seeing machines.</p>\n<p>Your reflection holds two famous puzzles. First, the person in the mirror appears to stand <em>behind</em> the glass, exactly as far behind as you stand in front — step back and your image steps back too. Second, mirrors appear to swap left and right (your raised right hand looks like the image\'s left) yet never swap up and down. Wave and watch; being puzzled by this is a centuries-old tradition.</p>\n<div class="analogy">\n  <h3>Analogy: The Bouncing Ball</h3>\n  <p>Throw a ball straight down at a smooth floor and it returns straight up; throw it at a slant and it bounces away at the matching slant. Light off a mirror behaves exactly like that ball. Now imagine throwing the ball at a cobblestone street — it could rebound anywhere. That is paper: same bounce, messy surface.</p>\n</div>'},{id:"transparency",title:"Transparent, Translucent, Opaque",content:'\n<p>Hold different materials up to a window and they sort themselves into three families by what they do to light:</p>\n<table>\n  <thead>\n    <tr><th>Family</th><th>What light does</th><th>What you see through it</th><th>Examples</th></tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>Transparent</strong></td><td>Passes almost straight through</td><td>A clear view</td><td>Window glass, still water, cling film</td></tr>\n    <tr><td><strong>Translucent</strong></td><td>Gets through, but scrambled and scattered</td><td>Light and blurry shapes, no detail</td><td>Frosted glass, baking paper, a thin curtain</td></tr>\n    <tr><td><strong>Opaque</strong></td><td>Blocked — absorbed or reflected</td><td>Nothing</td><td>Wood, brick, metal, your hand</td></tr>\n  </tbody>\n</table>\n<p>The shadow test tells the families apart instantly: opaque objects cast dark, crisp shadows; translucent ones cast pale, fuzzy shadows; transparent ones cast almost none. And notice the design decisions all around you — bathroom windows are frosted (translucent) precisely because they should deliver light but not images, while windscreens must be flawlessly transparent because a driver needs the detail, not just the brightness.</p>\n<p>Transparency has one more surprise. Light passing from air into water or glass gets slightly <strong>bent</strong> at the boundary — which is why a straw in a glass of water appears broken at the waterline and why a swimming pool always looks shallower than it really is. The bending of light by shaped transparent material is the whole working principle of lenses: spectacles, magnifying glasses, cameras, telescopes, and the living lens inside your own eye.</p>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Place a coin in the bottom of an empty mug and step back until the rim just hides the coin from view. Hold your head still while you (or a helper) slowly pour in water: the coin comes back into view, apparently lifted into sight. Light from the coin is being bent at the water\'s surface on its way to your eye — bending you can summon on demand at the kitchen sink.</p>\n</div>'}],quiz:[{question:"Why can we see the Moon at night?",options:["The Moon produces its own light like a star","The Moon reflects light from the Sun toward our eyes","Moonlight is starlight collected by the Moon","Our eyes emit rays that reach the Moon"],correctIndex:1,explanation:"The Moon is not a light source — it shines only by bouncing sunlight toward us. We see any non-source object the same way: light from a source reflects off it and enters our eyes. And eyes emit nothing, which is why total darkness means total blindness."},{question:"You hold your hand between a torch and a wall, then move the hand closer to the torch. What happens to its shadow on the wall?",options:["It gets bigger","It gets smaller","It stays the same size","It disappears"],correctIndex:0,explanation:"Light spreads out from the torch in straight lines. The closer the hand is to the torch, the larger the cone of light it blocks by the time those straight rays reach the wall — so the shadow grows. This straight-line geometry is the whole physics of shadow puppets."},{question:"Both a sheet of paper and a mirror reflect light. Why does only the mirror show your image?",options:["Paper absorbs all the light that hits it","Mirrors add their own light to the reflection","Paper only reflects white light","The mirror is smooth, so light bounces off in an orderly way that preserves the pattern; rough paper scatters it"],correctIndex:3,explanation:"Both surfaces reflect. Paper's microscopic roughness scatters light in all directions, destroying any pattern — which is why you can read a page from any angle but see no reflection in it. A mirror's smoothness keeps the reflected rays organized, and an organized pattern of light is exactly what an image is."},{question:"Which material would cast the palest, fuzziest shadow?",options:["A brick (opaque)","A pane of clear glass (transparent)","A sheet of baking paper (translucent)","A steel plate (opaque)"],correctIndex:2,explanation:"Translucent materials let light through but scatter it on the way, so they cast weak, blurred shadows. Opaque materials block light fully (dark, sharp shadows), and transparent ones let it pass almost undisturbed (almost no shadow)."}]},{id:"sound-and-vibration",title:"Sound & Vibration",subtitle:"Every sound is something shaking — pitch, loudness, travel, and hearing",sections:[{id:"sound-from-vibration",title:"Sound Comes from Vibration",content:'\n<p>Every sound you have ever heard — a guitar chord, a slammed door, your own name — began with something <strong>vibrating</strong>: moving back and forth very fast. This is the one law of sound, and it has no exceptions.</p>\n<p>Sometimes the vibration is visible. Pluck a guitar string hard and you can see it as a blur; strike a cymbal and watch its edge shimmer. A struck drum skin visibly trembles, and grains of rice placed on it will dance. Sometimes the vibration is too small or too fast to see — a struck wine glass looks perfectly still while it rings — but it is always there, and there is a lovely way to prove it: touch the ringing glass and the sound stops instantly. Your finger killed the vibration, and the sound died with it. Silencing-by-touching is exactly how cymbal players end a crash.</p>\n<p>You can also <em>feel</em> vibrations you cannot see. Rest your fingertips lightly on your throat and hum: the buzzing you feel is your <strong>vocal cords</strong> vibrating — that buzz is your voice. Place a hand on a speaker playing music and the cabinet trembles against your palm, strongest during the bass notes.</p>\n<p>What reaches your ear is the vibration passed along by the air. The shaking object pushes on the air next to it, that air pushes on the air beyond, and the disturbance races outward in all directions — like ripples spreading from a pebble dropped in a pond, but in three dimensions and invisible. When those ripples of trembling air arrive at your ear, you hear.</p>\n<div class="key-concept">\n  <h3>Key Concept: No Vibration, No Sound</h3>\n  <p>Stop the vibration and the sound stops with it — instantly, every time. Sound is not a thing objects contain; it is the motion they perform.</p>\n</div>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Hold a ruler flat on a table with half sticking over the edge. Twang the free end: you can simultaneously <em>see</em> the blur of vibration and <em>hear</em> the note. Now slide the ruler inward and twang again — a shorter free end vibrates visibly faster and the note jumps higher. In ten seconds you have discovered the next section\'s law for yourself.</p>\n</div>'},{id:"pitch-and-loudness",title:"Pitch & Loudness",content:"\n<p>Sounds differ from each other in two independent ways, and each traces back to a property of the vibration.</p>\n<p><strong>Pitch</strong> is how high or low a note sounds — a flute versus a tuba, a child's voice versus a bass singer. Pitch is set by how <strong>fast</strong> the vibration is: fast vibrations make high notes, slow vibrations make low ones. Watch it on any string instrument. The thick, long, heavy strings vibrate lazily and give the low notes; the thin, short strings whip back and forth quickly and give the high notes. A guitarist's fingers are pitch engineers: pressing a fret shortens the vibrating length, the vibration speeds up, the note rises. Small things generally vibrate faster than big ones — which is why the piccolo is tiny, the double bass is huge, and a mosquito's whine is higher than a bumblebee's drone (its little wings beat faster).</p>\n<p><strong>Loudness</strong> is how strong a sound is, and it is set by how <strong>big</strong> the vibration is — how far the object swings on each back-and-forth. Pluck a string gently and it barely trembles: a quiet note. Pluck the same string hard and it swings in a wide blur: a loud note at exactly the same pitch. Gentle tap, wide whack — same drum, same pitch, different loudness.</p>\n<p>The two are fully independent: a sound can be high and quiet (a distant whistle), high and loud (a smoke alarm), low and quiet (distant thunder), low and loud (that same thunder overhead).</p>\n<table>\n  <thead>\n    <tr><th>You change…</th><th>By changing…</th><th>Example</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Pitch</td><td>Speed of vibration</td><td>Shorter string → faster → higher note</td></tr>\n    <tr><td>Loudness</td><td>Size of vibration</td><td>Harder pluck → wider swing → louder note</td></tr>\n  </tbody>\n</table>\n<div class=\"did-you-know\">\n  <h4>Did You Know?</h4>\n  <p>Dogs hear vibrations far too fast for human ears — that is the trick of the \"silent\" dog whistle. Bats go further still, navigating in darkness by shouting ultra-high squeaks and listening for the echoes bouncing off obstacles and insects.</p>\n</div>"},{id:"how-sound-travels",title:"How Sound Travels",content:'\n<p>Sound needs a medium — some stuff to travel <em>through</em>. Air is the usual carrier, but it is far from the only one, and not even the best one.</p>\n<p>Sound travels through <strong>solids</strong>, and superbly. Put your ear flat on a wooden table and gently scratch the far end: the scratch arrives loud and crisp through the wood, though it is almost inaudible through the air. Children whispering through a taut string telephone, a wall transmitting the neighbour\'s bass, train robbers in old westerns listening to the rail for a distant train — all solid-borne sound. It travels through <strong>liquids</strong> too: swimmers hear pool sounds with their heads underwater, and whale song carries for hundreds of kilometres through the ocean.</p>\n<p>The particle picture explains the ranking. Sound is a shove passed from particle to particle. In a solid the particles are packed tightly against each other, so the shove passes on instantly, like a push travelling down a line of people standing shoulder to shoulder. In a gas the particles are far apart, so the relay is slower and weaker. Hence the rule of thumb: <strong>solids carry sound best, liquids next, gases last</strong> — the reverse of what most people guess.</p>\n<p>And where there are no particles at all, there is no sound. In the vacuum of space, an explosion is perfectly silent — there is nothing to pass the vibration along. (Films get this wrong for drama.) Light crosses empty space happily; sound cannot take one step into it.</p>\n<p>Sound is fast, but nowhere near light-fast: roughly 340 metres per second in air, about a kilometre every three seconds. That gap between light speed and sound speed is something you have already noticed — it is the pause between lightning and thunder.</p>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Count the storm. When you see a lightning flash, count the seconds until the thunder: the flash arrives essentially instantly, the rumble at about 1 km every 3 seconds. Nine seconds means the strike was about 3 km away. Count again for the next flash and you can tell whether the storm is approaching or leaving.</p>\n</div>'},{id:"hearing",title:"Hearing — and Protecting It",content:'\n<p>Your ear is a vibration detector of astonishing sensitivity, and its working principle is exactly the drum-skin physics of this chapter, miniaturized.</p>\n<p>The visible outer ear is a funnel. It gathers the ripples of trembling air and channels them down a short canal to the <strong>eardrum</strong> — a taut membrane, much like the skin of a tiny drum. Arriving vibrations make the eardrum tremble in sympathy: fast for high notes, slow for low, hard for loud, gently for soft. On the far side, a chain of the three tiniest bones in your body passes the trembling inward, where it becomes signals travelling along a nerve to the brain. Everything you have ever heard — every voice and every song — entered your life as the shaking of that little membrane.</p>\n<p>Why two ears? Direction. A sound from your left reaches the left ear a fraction sooner, and slightly louder, than the right. Your brain reads that tiny difference and instantly points your attention the right way. Close your eyes and you can still tell where a snap of the fingers came from.</p>\n<p>A detector this delicate can be damaged by what it detects. Violent vibrations — one explosive bang, or loud music poured in through earphones for hours — can overload the sensitive parts of the inner ear, and unlike a scraped knee, <strong>that damage does not heal</strong>. Hearing loss from noise is permanent, which is why workers on runways and building sites wear ear defenders by law. A useful personal warning sign: if your ears ring after a loud event, they were overdriven. The advice is simple and worth taking seriously: keep the volume moderate, give your ears quiet breaks, and treat ringing as the alarm bell it is.</p>\n<div class="analogy">\n  <h3>Analogy: The Drum in Your Head</h3>\n  <p>A drummer strikes a drum skin and it vibrates to make sound. Your eardrum runs the same event in reverse: arriving sound strikes the skin and makes it vibrate. One membrane turns motion into sound; the other turns sound back into motion.</p>\n</div>'}],quiz:[{question:"A wine glass rings after being struck. You touch it lightly and the sound stops immediately. Why?",options:["Your finger absorbs the sound that was stored in the glass","Touching it stops the vibration, and without vibration there is no sound","Your skin blocks sound from leaving the glass","The glass cools down when touched"],correctIndex:1,explanation:"Sound is not stored in objects — it is produced continuously by their vibration. The glass was still trembling (too finely to see), your finger damped that trembling, and the sound died with it. No vibration, no sound: the one law of sound."},{question:"What must change about a vibration to make its note higher in pitch?",options:["It must vibrate faster","It must swing through a bigger distance","It must vibrate more slowly","It must come from a bigger object"],correctIndex:0,explanation:"Pitch is set by vibration speed: faster back-and-forth means a higher note. That is why shortening a guitar string (making it vibrate faster) raises its pitch. The size of the swing controls loudness instead — the two properties are independent."},{question:"Why does a distant train become audible through the rail before it can be heard through the air?",options:["Metal amplifies all sounds","Sound cannot really travel through air at all","The train pushes sound down into the ground","The rail's tightly packed particles pass the vibration along faster and better than the spread-out particles of air"],correctIndex:3,explanation:"Sound is a shove relayed from particle to particle. In a solid like steel the particles press right against each other, so the relay is fast and efficient; in a gas they are far apart, so it is slower and weaker. Solids carry sound best, liquids next, gases last — and a vacuum, with no particles, carries none."},{question:"You see lightning and hear the thunder 6 seconds later. Roughly how far away was the strike?",options:["About 6 km","About 20 km","About 2 km","Right overhead — the delay means nothing"],correctIndex:2,explanation:"Light arrives essentially instantly, while sound crawls along at roughly 1 km every 3 seconds. Six seconds of delay therefore means about 2 km. The flash-to-rumble count is a genuine distance measurement you can make with no instrument but patience."}]},{id:"heat-and-cold",title:"Heat & Cold",subtitle:"Temperature, heat flow, expansion, and the three ways warmth gets around",sections:[{id:"temperature-vs-heat",title:"Temperature vs Heat",content:'\n<p>Everyday speech uses "hot" and "heat" loosely, but physics keeps two ideas carefully apart — and once you feel the difference, a lot of kitchen mysteries dissolve.</p>\n<p><strong>Temperature</strong> is how hot something is — a level, measured in degrees. In the particle picture, temperature tells you how vigorously the particles of a substance are jiggling: fast jiggling means high temperature, sluggish jiggling means low. A thermometer reads that level: 37 \xb0C for your body, 0 \xb0C for freezing water, 100 \xb0C for boiling water, around 20 \xb0C for a comfortable room.</p>\n<p><strong>Heat</strong> is warmth <em>on the move</em> — energy flowing from a hotter thing to a colder one. And it flows in only that direction, always. Put a warm hand on a cold window: heat flows from hand to glass, never the reverse. Leave hot tea on the table and heat leaks from tea to room until both match. Everything left alone drifts toward the temperature of its surroundings — the fate of every forgotten cup of tea and every softening tub of ice cream.</p>\n<p>The two ideas really are different, and here is the classic pair to prove it: a burning matchhead has a far <strong>higher temperature</strong> than a bathtub of warm water, yet the bathtub holds vastly <strong>more heat to give</strong> — the match could not warm a cold bathroom, but the tubful of water can. Level and amount are different things.</p>\n<p>One more correction from the particle picture: <strong>there is no such substance as "cold"</strong>. Cold is not a thing that flows into you; it is merely the absence of heat, as darkness is the absence of light. A draught from the fridge does not deliver coldness to your skin — your skin loses its heat to the cool air.</p>\n<div class="analogy">\n  <h3>Analogy: Water Level and Water Amount</h3>\n  <p>Temperature is like water <em>level</em>; heat flow is like water <em>current</em>. Connect a full high tank to a low one and water flows downhill until the levels equalize — regardless of which tank holds more water. Heat likewise flows from higher temperature to lower until the temperatures level out, no matter which object is bigger.</p>\n</div>'},{id:"expansion-and-contraction",title:"Expansion & Contraction",content:'\n<p>Here is a quiet fact with loud consequences: <strong>almost everything swells slightly when heated and shrinks slightly when cooled</strong>. The particle picture says why — hotter particles jiggle more vigorously and elbow themselves a little more room; cooled particles calm down and settle closer together. The substance itself doesn\'t change, and nothing is added or removed: the same particles simply take up a bit more or less space.</p>\n<p>The changes are small, but the world is full of their fingerprints:</p>\n<ul>\n  <li><strong>Railways and bridges</strong> are built with small expansion gaps so summer heat can lengthen the metal without buckling it. Long bridges sit on rollers; the roadway includes comb-toothed joints that clack under your car wheels — that clack is expansion engineering.</li>\n  <li><strong>Power lines</strong> sag noticeably more on hot days: kilometres of warmed metal add up to real extra length.</li>\n  <li><strong>The stuck jam-jar lid</strong> surrenders under hot water because the heated metal lid expands faster than the glass beneath it, loosening its grip — grandmother\'s trick, particle physics underneath.</li>\n  <li><strong>Creaking houses</strong> at night are the sounds of roofs and pipes contracting as they cool after a warm day.</li>\n</ul>\n<p>Liquids expand too, and one instrument depends on it: the classic <strong>thermometer</strong> is just a bulb of liquid and a hair-thin tube. Warmth makes the liquid expand, and the only place the extra volume can go is up the tube. The scale printed alongside converts "how far it crept up" into degrees. Gases expand most eagerly of all — a sealed balloon swells in a warm room, and a dented ping-pong ball can be re-rounded in hot water as the air inside it pushes outward.</p>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Stretch a balloon over the neck of an empty glass bottle. Stand the bottle in a bowl of hot tap water: the balloon slowly inflates as the air inside warms and expands. Move the bottle to a bowl of iced water and the balloon deflates and may even get sucked inward as the cooling air contracts. Same air throughout — only its temperature, and therefore its spread, has changed.</p>\n</div>'},{id:"how-heat-travels",title:"Conduction, Convection & Radiation",content:"\n<p>Heat gets from hot places to cold places in exactly three ways. Every warming and cooling you have ever experienced is one of the three, or a combination.</p>\n<p><strong>Conduction</strong> is heat passed through a material by touch, particle to jiggling particle. Heat the tip of a metal spoon and soon the handle burns your fingers: each vigorously jiggling particle jostles its neighbour, and the agitation travels along like a rumour down a packed row of seats. Metals are superb conductors; wood, plastic, wool, and air are poor ones — which is why the pan is metal but its handle is plastic.</p>\n<p><strong>Convection</strong> is heat carried by a moving liquid or gas. Air warmed by a radiator expands, becomes lighter for its size, and floats upward; cooler air slides in beneath, gets warmed, and follows. The result is a slow merry-go-round of air that carries warmth around the whole room. Convection is why the air near the ceiling is warmest, why a radiator heats a whole room rather than just the air touching it, and — in the pan — why soup heated only from below ends up hot throughout.</p>\n<p><strong>Radiation</strong> is heat that travels as invisible rays, needing no material at all. It is how the Sun's warmth crosses 150 million kilometres of empty space, how a bonfire toasts your face from metres away (the air between you stays cool — step behind a person and their body blocks the rays like a shadow), and why a parked car's dashboard bakes behind closed windows.</p>\n<table>\n  <thead>\n    <tr><th>Route</th><th>Carrier</th><th>Everyday example</th></tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>Conduction</strong></td><td>Particles jostling neighbours in place</td><td>Spoon handle heating up in soup</td></tr>\n    <tr><td><strong>Convection</strong></td><td>Warm liquid or gas physically rising and circulating</td><td>Radiator warming a whole room</td></tr>\n    <tr><td><strong>Radiation</strong></td><td>Invisible rays, no material needed</td><td>Sunshine; a bonfire's glow on your face</td></tr>\n  </tbody>\n</table>\n<div class=\"key-concept\">\n  <h3>Key Concept: One Campfire, All Three Routes</h3>\n  <p>Sit by a campfire holding a metal marshmallow skewer. Your face is toasted by <strong>radiation</strong>, the smoke and hot air rise by <strong>convection</strong>, and the skewer's handle slowly heats by <strong>conduction</strong>. Any real heating situation is usually all three at once.</p>\n</div>"},{id:"insulation",title:"Insulation: The Art of Slowing Heat",content:'\n<p>Heat cannot be stopped, but it can be magnificently <strong>delayed</strong> — and that delay is a technology as old as clothing. A material that conducts heat poorly is an <strong>insulator</strong>, and the champion insulator is one you cannot even see: <strong>trapped, still air</strong>.</p>\n<p>Air conducts heat very badly, provided it cannot move (moving air would carry heat away by convection). So the great insulators are all, secretly, devices for holding air still: wool traps air among its fibres, duvets and puffer jackets trap it in fluffy filling, double-glazed windows trap a layer between glass panes, foam is riddled with air bubbles. When a bird fluffs up on a cold day, it is thickening its own trapped-air jacket.</p>\n<p>Two corrections to everyday intuition follow:</p>\n<ul>\n  <li><strong>A jumper does not produce warmth.</strong> Your body is the heater; the wool merely slows the escape of the heat you constantly generate. That is why a sweater on a snowman does not melt him — with no heat inside to keep in, the wool has nothing to do (in fact it slows the day\'s warmth from reaching him).</li>\n  <li><strong>Insulation works both ways.</strong> The same cool-box that keeps soup hot keeps ice cream frozen; the same duvet that warms you in winter can keep a cold drink cold. An insulator does not choose a direction — it simply slows heat flow across itself, whichever way heat is trying to go.</li>\n</ul>\n<p>The vacuum flask is the masterpiece of the art: its double wall encloses not even air but a near-vacuum, which conduction and convection simply cannot cross (no particles!), plus a silvered lining to reflect radiation back. All three heat routes blocked at once — hot coffee at noon or iced tea, the flask neither knows nor cares.</p>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Take three ice cubes. Leave one on a plate, wrap one loosely in a tea towel, and wrap one snugly in a woolly hat or scarf. Guess which survives longest — most people pick the naked one, expecting wool to "warm" the ice. Check every 20 minutes: the wrapped cubes outlast the bare one by far, because the wool\'s trapped air slows the room\'s heat from getting <em>in</em>. Insulation slows heat flow in both directions.</p>\n</div>'}],quiz:[{question:"A lit match has a much higher temperature than a bathtub of warm water. Which statement is correct?",options:["The bathtub holds far more heat to give, despite its lower temperature","The match also holds more heat to give than the bathtub","Temperature and heat are two words for the same thing","The bathtub must be hotter, because it is bigger"],correctIndex:0,explanation:"Temperature is a level (how vigorously particles jiggle); heat is an amount of energy that can flow. The tiny match sits at a high level but has little to give; the huge tubful sits at a modest level but can warm a whole cold room. Level and amount are different ideas — that is the heart of this chapter."},{question:"Why does running hot water over a stuck metal jam-jar lid loosen it?",options:["The heat melts the jam sealing the lid","Hot water lubricates the thread","The metal lid expands more and faster than the glass jar, loosening its grip","The glass jar expands and pushes the lid off"],correctIndex:2,explanation:"Nearly all materials expand when heated, but not equally: the thin metal lid warms quickly and expands more than the glass beneath it, so its grip slackens. Grandmother's kitchen trick is applied expansion physics."},{question:"Standing two metres from a bonfire, your face feels hot even though the air between you and the fire is cool. How is the heat reaching you?",options:["Conduction through the air's particles","Convection currents blowing toward you","Radiation — invisible rays that need no material to travel","Sound waves carrying the heat"],correctIndex:2,explanation:"Conduction through air is feeble, and convection carries the fire's hot air upward, not sideways at your face. What toasts you is radiation — heat travelling as invisible rays, the same route by which the Sun's warmth crosses the empty space to Earth. Step behind someone and their body blocks the rays like a shadow."},{question:"What does wrapping a woolly scarf around an ice cube do?",options:["Melts it faster, because wool is warm","Has no effect either way","Freezes it harder","Makes it last longer, because the wool's trapped air slows the room's heat from reaching the ice"],correctIndex:3,explanation:"Wool produces no warmth of its own — it is an insulator, full of trapped still air, and it simply slows heat flow across itself in either direction. On you, it keeps body heat in; on the ice cube, it keeps room heat out. The wrapped cube outlasts a bare one by a wide margin — try it."}]},{id:"electricity-and-circuits",title:"Electricity & Circuits",subtitle:"Batteries, bulbs, switches, and the loop that must never be broken",sections:[{id:"battery-and-bulb",title:"The Battery, the Bulb & the Loop",content:'\n<p>The foundation of all electrical understanding fits on a kitchen table: one battery, one small bulb, two wires. Connect them so that a path runs from one end of the battery, through the bulb, and back to the other end of the battery — and the bulb lights. Break the path anywhere, and it goes dark. That closed path is a <strong>circuit</strong>, from the same root as "circle", and the circle is the whole secret.</p>\n<p>What is happening? The battery acts as a pump, pushing a flow of electricity — a <strong>current</strong> — around the loop. The current is not used up on its journey: it flows <em>through</em> the bulb (working as it passes, which is what makes the thin wire inside glow) and returns to the battery. What the battery slowly uses up is its own stored push; when that runs out, the battery is "dead".</p>\n<p>Everything follows from the loop rule:</p>\n<ul>\n  <li><strong>Both battery ends must be used.</strong> A wire from just one end can never light a bulb — there is no circle.</li>\n  <li><strong>One break anywhere kills the whole circuit.</strong> A loose wire, a blown bulb, a gap: the current stops everywhere at once, not just at the break.</li>\n  <li><strong>The loop explains the plug.</strong> Every appliance cable hides at least two wires — electricity needs a way in <em>and</em> a way back. There are no one-way trips in a circuit.</li>\n</ul>\n<div class="analogy">\n  <h3>Analogy: The Bicycle Chain</h3>\n  <p>A bicycle chain is a loop that transmits work from pedals to wheel. The chain itself is not consumed — links are not eaten as you ride — yet it delivers effort continuously. Snap the chain at any single point and everything stops instantly, everywhere. A circuit\'s current behaves exactly like the chain: an unbroken loop that carries the push, not a fuel that gets used up.</p>\n</div>\n<div class="key-concept">\n  <h3>Key Concept: No Loop, No Light</h3>\n  <p>Every electrical fault you will ever diagnose — dead torch, silent doorbell, dark fairy-light string — comes down to one question: where is the loop broken?</p>\n</div>'},{id:"conductors-insulators-switches",title:"Conductors, Insulators & Switches",content:"\n<p>Build the battery-and-bulb loop but leave a small gap, and you have made a materials tester: bridge the gap with an object, and the bulb reports whether current can flow through it.</p>\n<ul>\n  <li>Bridge it with a <strong>metal</strong> — a paper clip, a coin, kitchen foil, a key — and the bulb lights. Metals let current flow: they are <strong>conductors</strong>.</li>\n  <li>Bridge it with <strong>plastic, rubber, glass, dry wood, paper, or fabric</strong> — and the bulb stays dark. These block current: they are <strong>insulators</strong>.</li>\n</ul>\n<p>Every electrical device is built from this pairing, and you can see it in any cable: a copper core to carry the current, wrapped in plastic so the current stays on its path and off your fingers. The wall socket's holes are metal inside, plastic outside; the electrician's screwdriver has a steel shaft and an insulating handle. Conductor for the current's path, insulator everywhere the current must not go.</p>\n<p>A <strong>switch</strong> is the loop rule turned into a convenience: a deliberate, reopenable break in the circuit. Flip it one way and a metal bridge closes the gap — current flows, light on. Flip it back and the bridge lifts — gap, no loop, light off. Nothing is \"sent\" from the switch to the lamp; the switch simply completes or breaks the one shared loop, which is why it acts instantly and why a switch can sit far away from the bulb it controls, anywhere along the loop.</p>\n<p>This on/off simplicity scales astonishingly far: a fridge-door light is switched by a button the door presses; a keyboard is a hundred switches; and at the very bottom, a computer chip is billions of microscopic switches flicking on and off billions of times each second.</p>\n<div class=\"did-you-know\">\n  <h4>Try it yourself</h4>\n  <p>With a 4.5 V flat battery or an AA holder, a torch bulb (or an LED with a battery pack from a broken toy), and kitchen-foil strips as wires, build the loop and leave a gap. Test what bridges it: spoon, coin, eraser, pencil case, key, dry paper. Metals light the bulb; plastics never do. Then try a sharpened pencil's graphite core — a famous in-between surprise. This is exactly the experiment every Japanese and Singaporean primary schooler performs, and it is worth an adult's ten minutes.</p>\n</div>"},{id:"series-vs-parallel",title:"Series vs Parallel",content:"\n<p>Add a second bulb to your circuit and you face a genuine design decision — the same decision electricians face wiring a house. There are two ways to connect it, and they behave completely differently.</p>\n<p><strong>In series</strong>, the bulbs sit one after another on a single loop, like beads on one necklace. The consequences:</p>\n<ul>\n  <li>Both bulbs glow <strong>dimmer</strong> than one alone — one battery's push now drives current through two obstacles in a row.</li>\n  <li>If either bulb fails or is removed, the single loop is broken and <strong>both go dark</strong>. Old-fashioned fairy-light strings were wired this way, and one blown bulb blacked out the whole tree — the source of a classic family Christmas ordeal, hunting the dead bulb.</li>\n</ul>\n<p><strong>In parallel</strong>, each bulb gets its <strong>own loop</strong> to the battery — two side-by-side circles sharing one pump. The consequences flip:</p>\n<ul>\n  <li>Each bulb glows at <strong>full, normal brightness</strong>, exactly as if it were alone.</li>\n  <li>If one bulb fails, the other's private loop is untouched: <strong>it keeps shining</strong>.</li>\n  <li>The price: the battery feeds two full loops at once and drains faster.</li>\n</ul>\n<p>Your home is wired in parallel, and now you can say why: every lamp and socket gets full strength, each has its own switch, and a bulb blowing in the bathroom does not darken the kitchen. Series wiring survives where its all-or-nothing behaviour is exactly the point — a fridge-door switch in series with the fridge light, a safety interlock that cuts a microwave the instant the door opens.</p>\n<table>\n  <thead>\n    <tr><th></th><th>Series (one shared loop)</th><th>Parallel (own loop each)</th></tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>Brightness</strong></td><td>Dimmer with each added bulb</td><td>Full brightness each</td></tr>\n    <tr><td><strong>One bulb fails</strong></td><td>All go out</td><td>Others unaffected</td></tr>\n    <tr><td><strong>Used for</strong></td><td>Switches, safety interlocks</td><td>House wiring, car lights</td></tr>\n  </tbody>\n</table>"},{id:"electromagnets-and-safety",title:"Electromagnets & Electrical Safety",content:'\n<p>Here is one of the loveliest surprises in physics, discovered by accident in 1820 when a Danish lecturer noticed a compass needle twitch beside a current-carrying wire: <strong>an electric current creates magnetism</strong>. Coil a wire many times around an iron nail, connect the coil to a battery, and the nail becomes a magnet — it picks up paper clips exactly as a bar magnet does. Disconnect the battery and the paper clips drop instantly.</p>\n<p>That is an <strong>electromagnet</strong>, and its two superpowers put it far beyond any bar magnet. It can be <strong>switched</strong> — magnetism on demand, obedient to an ordinary switch. And it can be made <strong>stronger at will</strong>: more turns of wire, or a stronger current, give a stronger pull. Scrapyard cranes use room-sized electromagnets to lift whole cars and — the part no permanent magnet could do — release them on command. Electric doorbells, door latches that buzz open, loudspeakers, and electric motors all have an electromagnet at their heart. Whenever electricity makes something <em>move</em>, an electromagnet is usually the muscle.</p>\n<p>Respect must accompany the wonder. Battery experiments like those in this chapter are safe — a small battery\'s push is gentle. <strong>Mains electricity is a different animal entirely</strong>: its push is powerful enough to drive a dangerous current through a human body, and it must never be experimented with. The household rules all follow from physics you now understand:</p>\n<ul>\n  <li><strong>Water and mains do not mix</strong> — water on skin makes your body a much better conductor. Never touch switches or appliances with wet hands; keep hairdryers away from baths.</li>\n  <li><strong>Never poke anything into a socket</strong> — the metal contacts inside are live, and a metal object bridges them to you.</li>\n  <li><strong>Damaged insulation is an alarm</strong> — a frayed cable is a conductor with its safety jacket torn off. Stop using it.</li>\n  <li>Outdoors, kites and fishing rods stay far from overhead power lines.</li>\n</ul>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Wind about a metre of thin insulated wire in tight turns around a large iron nail or screw, leaving two free ends. Connect the ends to a single 1.5 V battery (briefly — the wire warms) and try picking up paper clips or pins. Then test the two superpowers: disconnect and watch the clips drop, reconnect with extra turns of wire and feel the stronger grip. You have built the working heart of every doorbell and scrapyard crane.</p>\n</div>'}],quiz:[{question:"A torch stops working. In circuit language, what has almost certainly happened?",options:["The current inside has all been eaten by the bulb","The loop is broken somewhere — dead battery, blown bulb, or a bad contact","The metal parts have become insulators","The torch has run out of stored light"],correctIndex:1,explanation:"Electricity flows only around a complete loop, and current is not consumed on the way — the battery's push is what runs down. Every dead torch is a loop question: either the pump has no push left (flat battery) or the circle is physically broken (blown bulb filament, loose contact). Find the break, fix the loop."},{question:"Which set of objects would all light the bulb when used to bridge a gap in a circuit?",options:["Coin, key, paper clip","Eraser, coin, glass marble","Plastic ruler, dry paper, spoon","Rubber band, key, cork"],correctIndex:0,explanation:"Metals conduct electricity, so the all-metal set — coin, key, paper clip — completes the circuit every time. Each other set hides at least one insulator (rubber, glass, plastic, paper, cork), and a single insulator in the path breaks the loop."},{question:"In an old-fashioned string of fairy lights, one bulb blows and the entire string goes dark. How were the bulbs wired?",options:["In parallel — each bulb on its own loop","Half in series, half in parallel","Without a battery or power source","In series — all bulbs on one shared loop"],correctIndex:3,explanation:"In a series circuit all bulbs share one single loop, so one failure breaks the path for everyone — hence the whole dark string, and the family ritual of hunting the dead bulb. House wiring is parallel for exactly this reason: every device has its own loop, so one failure strands no one else."},{question:"What can an electromagnet do that a permanent bar magnet cannot?",options:["Attract iron and steel","Have a north and a south pole","Be switched off on command, releasing whatever it holds","Work under water"],correctIndex:2,explanation:"Both magnets attract iron and both have two poles. The electromagnet's unique power is control: its magnetism exists only while current flows, so a switch turns it on and off — which is why a scrapyard crane can lift a car and then drop it on command, and why doorbells and motors are built around electromagnets rather than bar magnets."}]},{id:"energy-everywhere",title:"Energy Everywhere",subtitle:"Forms, conversions, storage, generation — and the one great rule of the universe",sections:[{id:"forms-of-energy",title:"The Many Costumes of Energy",content:'\n<p><strong>Energy</strong> is one of those words physics borrowed from everyday speech and sharpened. The working idea is simple: energy is <strong>the ability to make things happen</strong> — to move something, heat something, light something, change something. Nothing happens anywhere, ever, without energy being involved.</p>\n<p>Energy shows up wearing different costumes. Learning to spot them by name is the skill of this chapter:</p>\n<ul>\n  <li><strong>Movement energy</strong> — anything moving carries it: a rolling ball, wind (moving air), a river, a runner. The faster and heavier, the more it carries.</li>\n  <li><strong>Height energy</strong> — a stored form held by anything lifted up: water behind a high dam, a raised hammer, you at the top of a slide. Lower the object and the stored energy is released as motion.</li>\n  <li><strong>Elastic energy</strong> — stored in stretched or squashed things: a drawn bow, a wound clockwork spring, a stretched catapult band.</li>\n  <li><strong>Chemical energy</strong> — stored in substances, released when they react: food, petrol, wood, candle wax, and batteries. Your breakfast is literally your body\'s fuel tank.</li>\n  <li><strong>Heat</strong> — hot things can make other things happen (steam drives turbines); in the particle picture, heat is the jiggling of particles.</li>\n  <li><strong>Light</strong> — energy on the move as rays; sunlight powers essentially everything alive.</li>\n  <li><strong>Sound</strong> — vibration energy travelling outward.</li>\n  <li><strong>Electrical energy</strong> — energy delivered by current around a circuit; the most convenient form of all, because wires can carry it anywhere and it converts so easily into everything else.</li>\n</ul>\n<div class="key-concept">\n  <h3>Key Concept: Stored vs On-the-Move</h3>\n  <p>Notice the two families. Some forms are energy <em>in action</em> — movement, light, sound, heat flowing. Others are energy <em>waiting</em> — height, elastic, chemical. A stretched bowstring and a chocolate bar are both loaded springs, patient until called upon.</p>\n</div>\n<div class="analogy">\n  <h3>Analogy: Money in Many Currencies</h3>\n  <p>Energy is like money that exists in many currencies — cash, bank balance, gift cards. Different in form, exchangeable at every turn, and always countable as one total. Physics is the accounting.</p>\n</div>'},{id:"conversions-and-storage",title:"Conversions & Storage",content:"\n<p>Energy's forms would be mere vocabulary but for the crucial fact: <strong>energy constantly changes from one form into another</strong>, and every event — from a heartbeat to a thunderstorm — is an energy conversion. Once you see conversions, you cannot stop seeing them:</p>\n<ul>\n  <li><strong>A falling apple:</strong> height energy → movement energy.</li>\n  <li><strong>A toaster:</strong> electrical energy → heat (and a little light from the glowing elements).</li>\n  <li><strong>A candle:</strong> chemical energy in wax → light + heat.</li>\n  <li><strong>You climbing stairs:</strong> chemical energy from food → movement + height energy (plus body heat — you warm up).</li>\n  <li><strong>An archer:</strong> muscle chemistry → elastic energy in the bent bow → movement energy of the arrow.</li>\n  <li><strong>A phone:</strong> chemical energy in the battery → light (screen) + sound (speaker) + a little heat.</li>\n</ul>\n<p>Longer chains are everywhere. Follow a swing ride: food-chemistry in your legs pumps you upward (→ height), you sweep down (→ movement), up the far side (→ height again), back and forth — and friction with the air skims a little into heat on every pass, which is why an unpumped swing gradually settles to rest.</p>\n<p><strong>Storage</strong> is the art of parking energy in a patient form until needed. Humanity's storehouses: batteries (chemical), fuel tanks and woodpiles (chemical), reservoirs behind dams (height), wound springs in clockwork (elastic), and your own body fat (chemical — the tank that keeps you alive between meals). A hydroelectric country like Norway effectively banks its wealth as water held high in the mountains.</p>\n<div class=\"did-you-know\">\n  <h4>Try it yourself</h4>\n  <p>Rub your palms together hard for ten seconds — movement becomes heat you can feel immediately. Then repeatedly bend a metal paper clip back and forth about twenty times and touch the bend point to your lip (lips sense temperature finely): distinctly warm. In both cases you can feel exactly where the energy of motion went. Nothing vanished — it changed costume.</p>\n</div>"},{id:"generating-electricity",title:"Where Electricity Comes From",content:'\n<p>Electricity is the most convenient energy form — but wall sockets are not sources, only delivery points. Somewhere, right now, a machine is <strong>converting</strong> some other form of energy into the electrical energy in your walls. Nearly always, the machine is a <strong>generator</strong>: a device that produces current when spun. (It is the electromagnet story of the last chapter run backwards — there, current made magnetism and motion; here, motion and magnetism make current. A bicycle dynamo pressed against a spinning wheel is a generator you may have pedalled yourself: your legs literally light the lamp.)</p>\n<p>So the entire question of powering civilization reduces to: <strong>what shall we use to spin the generators?</strong></p>\n<ul>\n  <li><strong>Fuel-burning power stations</strong> (coal, gas): burn fuel → heat → boil water into high-pressure steam → steam blasts through a turbine, spinning it → generator. Chemical → heat → movement → electrical.</li>\n  <li><strong>Hydroelectric dams:</strong> water stored high falls through turbines. Height → movement → electrical.</li>\n  <li><strong>Wind turbines:</strong> moving air spins the blades directly. Movement → electrical.</li>\n  <li><strong>Nuclear stations:</strong> the same steam-and-turbine chain, with the water boiled by heat from atomic nuclei instead of flames.</li>\n  <li><strong>Solar panels</strong> — the one great exception: no spinning at all. The panel converts light to electrical energy directly, silently, with no moving parts.</li>\n</ul>\n<p>Trace any of these chains backwards and almost every one ends at the <strong>Sun</strong>. Sunlight lifts the water that fills the dams (evaporation → rain), drives the winds by heating the Earth unevenly, and grew the ancient plants that became coal. Flip a light switch and you are, at several removes, spending sunshine — much of it banked millions of years ago.</p>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>A hand-cranked torch or wind-up radio contains a small generator: your arm\'s movement energy becomes electrical energy on the spot. Crank one for a minute and your arm will report, accurately, that electricity is work.</p>\n</div>'},{id:"conservation-idea",title:"The Great Rule: Energy Is Conserved",content:'\n<p>Everything in this chapter now gathers into a single law — the deepest and most reliable rule in all of physics: <strong>energy is never created and never destroyed; it only changes form</strong>. Total up the energy before any event and after it, in all its costumes, and the totals match. Always. No exception to this law has ever been observed, anywhere, in centuries of looking.</p>\n<p>The law faces an obvious everyday objection, and answering it is the true capstone. Objection: energy certainly <em>seems</em> to disappear. The swing settles to rest. The rolling ball stops. Your phone battery empties. Where did it all go?</p>\n<p><strong>Answer: into heat — gently, invisibly, and every single time.</strong> Friction with the air and the pivot skimmed the swing\'s energy into slight warmth of the surroundings. The rolling ball warmed the floor along its path, a trace too small to feel but real. The phone\'s stored chemistry left as light from the screen, sound from the speaker, and warmth you can feel on its back. Energy that "disappears" has merely converted into its most easily overlooked and hardest-to-reuse costume and spread thinly into the surroundings. The accounting always closes; you just have to remember to count the heat.</p>\n<p>The law also explains a famous impossibility. For centuries, inventors sought the <strong>perpetual-motion machine</strong> — a device that would run forever, giving out more energy than it takes in. Patent offices eventually refused to examine such applications without a working model. None ever ran, and now you know the reason: a machine cannot pay out energy it never received. Conservation is the universe\'s unbreakable bookkeeping.</p>\n<div class="key-concept">\n  <h3>Key Concept: Nothing Comes from Nowhere</h3>\n  <p>Every bit of energy that makes anything happen came from somewhere, and goes somewhere. "Where did this energy come from, and where is it going?" — carry that one question with you and you can interrogate any machine, meal, storm, or star.</p>\n</div>\n<div class="analogy">\n  <h3>Analogy: The Unbreakable Bank</h3>\n  <p>Energy is money in a bank that permits transfers but never printing or shredding. Balances move between accounts — height, motion, chemistry, heat — and the "lost" energy of a stopped swing is simply the account labelled <em>warmth of the surroundings</em>: real money, but scattered as pennies too widely to gather back up.</p>\n</div>'}],quiz:[{question:"You climb a flight of stairs. What is the main energy conversion?",options:["Electrical energy → movement energy","Chemical energy from food → height energy (plus body heat)","Height energy → chemical energy","Heat from the room → movement energy"],correctIndex:1,explanation:"Your muscles run on chemical energy stored from food. Climbing converts some of it into height energy (which you could reclaim as motion by sliding back down) — and, as always, some becomes heat, which is why exercise warms you. Food is fuel in a precise, physical sense."},{question:"In a coal-fired power station, what is the correct order of the energy chain?",options:["Chemical → heat → movement → electrical","Heat → chemical → electrical → movement","Electrical → heat → movement → chemical","Chemical → electrical → heat → movement"],correctIndex:0,explanation:"Burning coal releases stored chemical energy as heat; the heat boils water into steam; the steam spins a turbine (movement); the turbine drives the generator (electrical). Gas and nuclear stations share the same chain — only the source of the heat differs. Solar panels are the notable exception: light to electricity directly, nothing spinning."},{question:"A child stops pumping a swing and it gradually comes to rest. What happened to the swing's energy?",options:["It was destroyed — motion simply runs out","It flowed back into the child's muscles","It converted into heat, warming the air and the pivot slightly, and spread into the surroundings","It is stored in the swing, ready to restart it"],correctIndex:2,explanation:"Energy is never destroyed. Friction — against the air and in the pivot — skimmed the swing's energy into slight, unnoticeable warmth on every pass. Apparent disappearances of energy are always conversions into thinly spread heat; the conservation accounting closes once you remember to count it."},{question:"Why is a perpetual-motion machine — one that runs forever while giving out extra energy — impossible?",options:["No one has yet found a frictionless bearing","Such machines would overheat and melt","They are only impossible on Earth, not in space","Energy cannot be created, so a machine cannot pay out more than it receives"],correctIndex:3,explanation:"The obstacle is not engineering but bookkeeping: conservation of energy means output can never exceed input, because the extra would have to come from nowhere. Better bearings reduce losses but can never create a surplus — which is why patent offices stopped examining such designs, and why none has ever run."}]},{id:"earth-and-sky",title:"Earth & Sky",subtitle:"Day, night, seasons, the Moon's changing face, and our address in the universe",sections:[{id:"day-and-night",title:"Day & Night: A Spinning Earth",content:'\n<p>The Sun "rises" in the east, "crosses" the sky, and "sets" in the west — the oldest observation in human experience, and one of the most misleading. The Sun is not going anywhere. <strong>It is the Earth that moves: our planet spins on its axis, one full turn every 24 hours</strong>, and day and night are nothing more than being carried around into the sunshine and out of it.</p>\n<p>The Sun lights half the globe at any moment — the half facing it. As the Earth turns, your home town is carried across the lit half (your daytime), around into the shadowed half (your night), and back into the light (sunrise). Nothing switches on or off; you are on a slowly rotating ball beside a steady lamp.</p>\n<p>The spin explains the everyday details, too. The Earth turns from west to east, so the Sun first appears in the east and slips away in the west — and the Moon and stars appear to make exactly the same east-to-west journey each night, because the same spin sweeps your viewpoint past them all. It also makes sense of time zones: "noon" means the Sun at its highest, and the spinning Earth serves noon to Tokyo, then Delhi, then Paris, then New York in turn. When it is breakfast time in London it is already evening in Sydney — different positions on the turning ball, facing different ways relative to the Sun.</p>\n<p>Why do we feel none of this motion? For the same reason you feel nothing in a smoothly cruising aeroplane: steady motion is imperceptible — only <em>changes</em> in motion (jolts, swerves) can be felt. The ride is perfectly smooth, so people believed for millennia that the Earth stood still. It was an entirely reasonable mistake.</p>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>In a dark room, walk slowly around a single lamp while spinning yourself gently counter-clockwise. The lamp repeatedly "rises" past your left shoulder, crosses your view, and "sets" past your right — a complete sunrise and sunset with every turn you make, while the lamp never moves at all. You have just replaced two thousand years of Sun-goes-round-the-Earth intuition with thirty seconds of physics.</p>\n</div>'},{id:"seasons",title:"The Seasons: A Tilted Planet",content:'\n<p>While spinning daily, the Earth also travels a huge, nearly circular path around the Sun, completing one lap per <strong>year</strong>. But the lap alone does not cause the seasons — the real cause is a beautiful accident: <strong>the Earth\'s spin axis is tilted</strong> (by about 23\xb0) and holds that tilt, pointing the same way in space, all the way around the orbit.</p>\n<p>So for half of each lap, the northern half of the planet leans <em>toward</em> the Sun; half a lap later it leans <em>away</em>. Leaning toward the Sun means: the Sun climbs higher in your sky, its light strikes your ground more directly (concentrated rather than spread at a slant), and your days are long. That is <strong>summer</strong>. Leaning away brings a low Sun, slanting spread-out light, and short days: <strong>winter</strong>. Spring and autumn are the in-between positions. This also explains a fact every traveller knows: the hemispheres are opposite — Australians celebrate Christmas on the beach precisely because when the north leans away, the south leans toward.</p>\n<p>First, a myth to bury: the seasons are <strong>not</strong> caused by distance from the Sun. The Earth\'s orbit is so nearly circular that distance barely varies — and in fact the Earth is slightly <em>closest</em> to the Sun in early January, deep in the northern winter. It is angle and day-length, not distance.</p>\n<p>You can feel the angle effect with a torch: shine it straight down at a table and it makes a small, intense pool of light; tilt the beam and the same light smears across a wide, weak oval. Winter sunlight is the tilted beam — the same delivery, spread thin.</p>\n<div class="key-concept">\n  <h3>Key Concept: Height of the Sun = Strength of the Season</h3>\n  <p>Summer is when your part of the world leans sunward: high Sun, direct concentrated light, long days. Winter is the lean away: low Sun, slanted diluted light, short days. One steady tilt, carried around one yearly lap, produces the whole calendar of seasons — opposite in the two hemispheres.</p>\n</div>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>At midsummer, places north of the Arctic Circle lean so far sunward that the Sun never sets — the midnight Sun. At midwinter it never rises. Norway sells this physics to tourists twice a year, in opposite forms.</p>\n</div>'},{id:"moon-phases",title:"The Moon & Its Phases",content:"\n<p>The Moon is our companion in space — a ball of grey rock about a quarter of the Earth's width, circling us roughly once a month. It makes no light of its own; we see it purely by reflected sunlight. And in that sentence hides the explanation of its famous changing shape.</p>\n<p><strong>At every moment, half the Moon is sunlit</strong> — the half facing the Sun, just as half the Earth is. The Moon does not change; what changes, as it circles us, is <strong>how much of that lit half faces the Earth</strong>:</p>\n<ul>\n  <li>When the Moon lies roughly between Earth and Sun, its lit side faces away from us: we see nothing — <strong>new moon</strong>.</li>\n  <li>A week later, we view it side-on: half its lit face visible — a <strong>half moon</strong>.</li>\n  <li>Another week and the Moon is on the far side of Earth from the Sun, its lit face fully toward us: <strong>full moon</strong>.</li>\n  <li>The following weeks replay the show in reverse — waning half, thinning crescent, and back to new. The whole cycle takes about 29 and a half days, and gave humanity its <strong>month</strong>.</li>\n</ul>\n<p>Two clarifications complete the picture. The phases are <strong>not the Earth's shadow</strong> on the Moon — the geometry above needs no shadow at all. (The Earth's shadow does occasionally sweep across the full Moon, and that rarer, redder event is a <strong>lunar eclipse</strong>.) And the Moon is no night-only object: it is often visible in broad daylight, pale in the blue sky — a surprise to most adults, hiding in plain sight.</p>\n<div class=\"did-you-know\">\n  <h4>Try it yourself</h4>\n  <p>Become the Earth. In a dark room, hold a ball (the Moon) at arm's length and stand a lamp (the Sun) across the room. Turn slowly on the spot, carrying the ball around you, and watch its lit shape run through new → crescent → half → full → and back, exactly matching the sky's calendar. Every phase of the Moon, generated on demand with a lamp and an orange.</p>\n</div>"},{id:"solar-system-and-stars",title:"The Solar System, the Stars & the Scale of Everything",content:"\n<p>Step back for the widest view. Our <strong>Solar System</strong> is one star — the Sun — holding a family in its gravitational grip: eight planets on nested near-circular orbits, plus moons, and countless leftovers (asteroids, and the comets whose tails occasionally grace our sky). Nearest the Sun come the four small rocky worlds — Mercury, Venus, <strong>Earth</strong>, Mars — then the four giants: vast Jupiter, ringed Saturn, and the ice giants Uranus and Neptune.</p>\n<p>The Sun itself is no lamp but a <strong>star</strong> — a ball of glowing gas so large that a million Earths could fit inside, holding the whole family in orbit and supplying, as the energy chapter showed, nearly every joule that moves our world.</p>\n<p>Now the idea that separates a list of names from real understanding: <strong>scale</strong>. Shrink the Sun to a football sitting on the centre spot of a stadium, and the Earth becomes a peppercorn about 25 metres away; Neptune, another peppercorn, sits some 800 metres distant. Space is almost entirely empty space.</p>\n<p>And the stars? <strong>Every star in the night sky is another sun</strong> — many larger and brighter than ours — reduced to a dot by unimaginable distance. On the football model, the football's nearest neighbouring star-football lies thousands of kilometres away: from a stadium in London, roughly in Beijing. Light itself, the universe's fastest traveller, needs over four years to make that crossing — so we see every star as it <em>was</em>, years or centuries ago. The night sky is a photograph album of the past. Our Sun and its neighbours are a few of the hundreds of billions of stars swirling in our galaxy, the <strong>Milky Way</strong> — visible on truly dark nights as a misty band arching overhead, our own city of stars seen from inside — and the observable universe holds more galaxies than there are stars in ours.</p>\n<div class=\"analogy\">\n  <h3>Analogy: The Cosmic Address</h3>\n  <p>Written in full, your address reads: your street, your town, planet Earth, third orbit of the Sun, Solar System, Milky Way galaxy, the universe. This chapter's achievement is that every line of that address now means something to you.</p>\n</div>"}],quiz:[{question:"What actually causes day and night?",options:["The Sun orbits the Earth once every 24 hours","The Earth spins on its axis, carrying each place into and out of the Sun's light","The Sun switches from bright to dim on a daily cycle","Clouds cover the Sun at night"],correctIndex:1,explanation:"The Sun holds still while the Earth turns, one rotation per 24 hours. The half facing the Sun has day; the half facing away has night; the spin carries you from one to the other. The Sun's apparent journey across the sky is your own motion, felt as smooth stillness — like scenery sliding past a cruising aeroplane."},{question:"Why is it summer in Australia when it is winter in Europe?",options:["Australia is much closer to the Sun in December","The Sun burns hotter over the southern hemisphere","Australia's deserts store extra summer heat","The Earth's axis is tilted: when the northern hemisphere leans away from the Sun, the southern hemisphere leans toward it"],correctIndex:3,explanation:"Seasons come from the Earth's steady 23\xb0 tilt carried around its yearly orbit — not from distance (Earth is actually slightly closest to the Sun in January). Whichever hemisphere leans sunward gets a high Sun, direct concentrated light, and long days; the other hemisphere simultaneously gets the opposite. The two hemispheres' seasons are therefore always reversed."},{question:"What causes the phases of the Moon?",options:["The Earth's shadow covering different amounts of the Moon","Clouds on the Moon hiding parts of its surface","As the Moon orbits us, we see different amounts of its permanently sunlit half","The Moon's own light slowly brightening and dimming each month"],correctIndex:2,explanation:"Half the Moon is always sunlit — the half facing the Sun. As the Moon circles the Earth each month, our viewpoint changes: lit side away from us (new), side-on (half), lit side toward us (full). No shadow is involved — the Earth's shadow touching the Moon is the much rarer event called a lunar eclipse."},{question:"What is a star, such as those we see at night?",options:["A distant sun, reduced to a point of light by enormous distance","Sunlight reflecting off small rocky bodies","A hole in the darkness letting light through","A nearby object about the size of the Moon"],correctIndex:0,explanation:"Every star is another sun — a vast ball of glowing gas, many bigger than ours — shrunk to a dot by distances so great that its light takes years or centuries to reach us. We therefore see each star as it was when the light left it: the night sky is a view into the past, and our Sun is simply the star we happen to orbit."}]}]},{id:"thinking-like-a-physicist",number:3,title:"Thinking Like a Physicist",description:"The scientific method, fair tests, graphs, and estimation — the experimental-skill progression every top school system builds, compressed for adults.",phase:1,chapters:[{id:"scientific-method",title:"The Scientific Method",subtitle:"Observation → hypothesis → experiment — and what models, theories, and physics itself really are",sections:[{id:"from-noticing-to-asking",title:"From Noticing to Asking",content:'\n<p>Every piece of physics you will ever learn began with someone <strong>noticing something and refusing to shrug it off</strong>. Ice floats, but almost every other solid sinks in its own liquid. A spinning top stays up; a stationary one falls over. Your phone loses charge faster in the cold. These are all invitations to ask a question — and the quality of the question determines everything that follows.</p>\n<p>Scientists sharpen vague curiosity into questions with three properties:</p>\n<ul>\n  <li><strong>Specific:</strong> not "why is the sky weird at sunset?" but "why does the sky turn red near the horizon when the Sun is low?"</li>\n  <li><strong>About measurable things:</strong> the question points at something you could observe, count, or measure — angle, colour, time, temperature.</li>\n  <li><strong>Answerable by evidence:</strong> some possible observation could settle it, at least partially.</li>\n</ul>\n<p>From a good question comes a <strong>hypothesis</strong>: a proposed answer stated clearly enough to be tested. "Cold weather affects batteries" is too mushy. "My phone battery drains at least twice as fast at 0 \xb0C as at 20 \xb0C" is a real hypothesis — it sticks its neck out.</p>\n<div class="key-concept">\n  <h3>Key Concept: Falsifiability</h3>\n  <p>A scientific hypothesis must be <strong>falsifiable</strong> — there must be some conceivable observation that would prove it wrong. "Invisible undetectable gremlins drain my battery" can never be refuted by any measurement, so it is not a scientific claim. Sticking your neck out is the price of admission.</p>\n</div>\n<p>Notice what a hypothesis is <em>not</em>: it is not a guess you are emotionally attached to. Physicists deliberately hold hypotheses loosely. The point of the next step — the experiment — is to give nature every opportunity to say "no." A hypothesis that survives serious attempts to kill it earns your confidence; one that is merely defended earns nothing. That mental posture, more than any lab equipment, is what this whole subject is about.</p>'},{id:"predictions-experiments-evidence",title:"Predictions, Experiments & Evidence",content:'\n<p>A hypothesis becomes useful the moment you squeeze a <strong>prediction</strong> out of it: a concrete "if… then…" statement about something you have not yet observed. If cold really drains batteries faster, <em>then</em> a phone left in the fridge should lose more charge in an hour than an identical phone on the table. Now you have something to check.</p>\n<p>The experiment is simply the check. The classic loop looks like this:</p>\n<ol>\n  <li><strong>Observe</strong> something interesting.</li>\n  <li><strong>Hypothesize</strong> an explanation.</li>\n  <li><strong>Predict</strong> what should happen in a situation you can arrange.</li>\n  <li><strong>Test</strong> — run the experiment and record what actually happens.</li>\n  <li><strong>Compare</strong> prediction with outcome, then revise or retest.</li>\n</ol>\n<p>Two subtleties separate real science from wishful thinking. First, <strong>evidence never "proves" a hypothesis</strong> — it supports it or contradicts it. A thousand successful predictions can be undone by one clean failure; that is exactly what happened to Newtonian gravity when Mercury\'s orbit misbehaved. Second, the loop is a <em>loop</em>: a failed prediction is not a defeat but the most informative result you can get, because it tells you your picture of the world needs repair.</p>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Hypothesis: a lid dramatically slows how fast a hot drink cools. Prediction: of two identical mugs of hot water filled at the same time, the covered one will still be noticeably hotter after 15 minutes. Fill both mugs from the same kettle, cover one with a saucer, wait 15 minutes, then compare with a kitchen thermometer (or carefully by sip). You have just run the full loop: observation → hypothesis → prediction → test → conclusion. Bonus: was your test <em>fair</em>? Same mug shape? Same starting temperature? Chapter 2 is about exactly that.</p>\n</div>\n<p>Keep a written record of predictions <em>before</em> testing. Human memory happily rewrites "I expected that" after the fact — paper does not.</p>'},{id:"models-and-theories",title:"Models & Theories",content:'\n<p>Between a single hypothesis and the grand laws of physics sit two workhorses of scientific thinking: <strong>models</strong> and <strong>theories</strong>.</p>\n<p>A <strong>model</strong> is a deliberately simplified stand-in for reality — simple enough to reason with, faithful enough to be useful. The "particle model" pictures matter as tiny balls in motion; it ignores almost everything about atoms, yet it beautifully explains melting, evaporation, and gas pressure. Physicists treat "all models are wrong, but some are useful" not as a confession but as a strategy: you <em>choose</em> what to ignore.</p>\n<div class="analogy">\n  <h3>Analogy: The Subway Map</h3>\n  <p>A subway map is geographically false — distances are distorted, curves straightened, streets erased. Yet it is far more useful for riding the subway than a satellite photo, precisely <em>because</em> of what it leaves out. A physics model is a subway map of nature: judged not by completeness but by whether it gets you where you need to go.</p>\n</div>\n<p>A <strong>theory</strong>, in scientific usage, is the opposite of "just a guess." It is a broad, coherent explanatory framework that has survived extensive testing and ties many observations together: the particle theory of matter, the theory of electromagnetism, the theory of relativity. In everyday English "theory" means speculation; in science it is the highest status an explanation can earn.</p>\n<table>\n  <thead>\n    <tr><th>Term</th><th>What it is</th><th>Example</th></tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>Hypothesis</strong></td><td>A testable proposed answer to one question</td><td>"Period of a pendulum depends only on its length"</td></tr>\n    <tr><td><strong>Model</strong></td><td>A simplified, workable picture of a system</td><td>Matter as tiny moving particles</td></tr>\n    <tr><td><strong>Theory</strong></td><td>A well-tested framework explaining many phenomena</td><td>Newton\'s theory of gravitation</td></tr>\n    <tr><td><strong>Law</strong></td><td>A compact rule (often a formula) describing a pattern</td><td>Ohm\'s law, V = IR</td></tr>\n  </tbody>\n</table>\n<p>Note that a law <em>describes</em> a pattern while a theory <em>explains</em> it — and laws do not "graduate" into theories or vice versa. They are different kinds of tools.</p>'},{id:"what-physics-is-and-isnt",title:"What Physics Is (and Isn't)",content:'\n<p>Physics is the search for the <strong>simplest, most general rules</strong> that describe how the universe behaves — rules that apply equally to a falling apple, a falling raindrop, and a falling satellite. Where biology and chemistry study particular systems, physics hunts for the patterns underneath all of them: motion, energy, forces, fields, matter, and how they interconnect.</p>\n<p>Three habits define the physicist\'s approach:</p>\n<ul>\n  <li><strong>Quantify:</strong> turn "heavy," "fast," and "hot" into numbers with units, because numbers can be compared, predicted, and checked.</li>\n  <li><strong>Idealize:</strong> strip a problem to its essentials first (frictionless slope, spherical cow), then add complications one at a time.</li>\n  <li><strong>Universalize:</strong> distrust any rule that works only here, only today, or only for you.</li>\n</ul>\n<p>Just as important is what physics is <em>not</em>. Physics does not answer questions of value ("what should I do?"), taste, or ultimate purpose — not because those questions are unimportant, but because no measurement can settle them. And a field is not scientific just because it uses scientific-sounding language. The test is behavioural: does it make risky, falsifiable predictions, and does it change its mind when they fail?</p>\n<div class="did-you-know">\n  <h3>Did You Know: Horoscopes Under Test</h3>\n  <p>Astrology makes an excellent contrast case. When astrologers\' specific predictions have been tested — matching birth charts to personality profiles under controlled conditions, as in Shawn Carlson\'s famous 1985 double-blind test published in <em>Nature</em> — they perform at chance level. The revealing part is what happened next: nothing. The claims did not change. A field that never updates in response to failed predictions is not doing science, whatever vocabulary it borrows.</p>\n</div>\n<p>None of this makes physics cold. It is, at heart, an act of optimism: the wager that the universe is comprehensible, that honest questions get honest answers, and that anyone — including an adult restarting from scratch — can check the answers for themselves. That last part is the point of this whole course: you are not asked to believe anything you cannot, in principle, test.</p>'}],quiz:[{question:"What makes a hypothesis scientific rather than just an opinion?",options:["It is stated by a qualified expert","It is falsifiable — some possible observation could prove it wrong","It has already been proven true","It uses mathematical language"],correctIndex:1,explanation:"A scientific hypothesis must stick its neck out: there must be some conceivable measurement or observation that would refute it. Claims that no evidence could ever contradict are not scientific, whoever states them."},{question:"In everyday speech, 'theory' means a guess. What does it mean in science?",options:["A broad explanatory framework that has survived extensive testing","An idea that has not yet been tested","A hypothesis proposed by a famous scientist","A mathematical formula describing one experiment"],correctIndex:0,explanation:"In science, 'theory' is the highest status an explanation can earn — a coherent framework (like electromagnetism or relativity) that ties many observations together and has withstood serious attempts to refute it."},{question:"Why do physicists say experiments can support a hypothesis but never prove it?",options:["Because experiments always contain errors","Because proof is only possible in biology and chemistry","Because a single future failed prediction could still overturn it, however many past tests it passed","Because hypotheses are opinions and opinions cannot be proven"],correctIndex:2,explanation:"Evidence accumulates support but can never guarantee future success. Newtonian gravity passed tests for two centuries before Mercury's orbit exposed its limits — one clean, well-verified failure outweighs a thousand successes."},{question:"The particle model treats atoms as tiny featureless balls, which is known to be false in detail. Why do physicists still use it?",options:["Out of respect for tradition","Because no better model of the atom exists","Because using a false model is acceptable if the conclusions are checked twice","Because a deliberately simplified model can capture exactly the behaviour that matters, like a subway map"],correctIndex:3,explanation:"Models are judged by usefulness, not completeness. Like a subway map that distorts geography to make routes clear, the particle model ignores atomic detail yet correctly explains melting, evaporation, and gas pressure."},{question:"Which of these is a genuinely testable prediction, in the 'if… then…' sense?",options:["Cold weather is bad for electronics","If I leave one of two identical charged phones at 0 \xb0C and one at 20 \xb0C for an hour, the cold one will have lost more charge","Batteries contain energy that can be affected by many factors","Everyone knows phones die faster in winter"],correctIndex:1,explanation:"A useful prediction specifies a concrete arrangement and a measurable outcome that could fail to occur. The other statements are too vague for any observation to contradict them cleanly."}]},{id:"fair-tests-and-variables",title:"Fair Tests & Variables",subtitle:"Comparing, relating, and controlling variables — mastered through the classic pendulum investigation",sections:[{id:"from-comparing-to-relating",title:"From Comparing to Relating",content:'\n<p>The world\'s strongest school science systems teach experimental skill as a ladder, one rung per year, and it is worth climbing the same ladder deliberately as an adult — it takes minutes, not years, but skipping rungs leaves gaps.</p>\n<p><strong>Rung 1 — Comparing.</strong> The simplest experiment answers "which one?" Which paper towel absorbs more water? Which pan heats up faster? A comparison needs only two things: a common task and an honest judge. Even here, fairness sneaks in — comparing towels is meaningless if one towel is twice the size of the other.</p>\n<p><strong>Rung 2 — Relating.</strong> The next question is "how does one thing change with another?" Not "which ball bounces higher?" but "how does bounce height change as I drop the ball from higher up?" You are now relating two quantities — drop height and bounce height — and the answer is not a winner but a <em>pattern</em>: more of this gives more of that, or less, or no change at all.</p>\n<p><strong>Rung 3 — Controlling.</strong> The hardest and most important rung: when many things <em>could</em> matter, how do you find out which ones actually do? The answer — change one thing at a time while holding everything else fixed — is the subject of the rest of this chapter.</p>\n<div class="analogy">\n  <h3>Analogy: Debugging a Recipe</h3>\n  <p>Your bread came out dense. Was it the new flour, the colder kitchen, or the shorter kneading time? If you change all three next bake and it improves, you have learned almost nothing. Any cook who changes one thing per bake is already doing controlled experimentation — physicists just do it on purpose, every time.</p>\n</div>\n<p>Notice that each rung asks a sharper question of nature than the last. "Which?" becomes "how much?" becomes "what actually causes what?" That final question — causation, untangled from coincidence — is the one the fair test is built to answer, and it is the single most transferable skill in this entire course: it works on bread, medicine, marketing claims, and pendulums alike.</p>'},{id:"naming-the-variables",title:"Naming the Variables",content:'\n<p>A <strong>variable</strong> is anything in an experiment that can change or be changed. Fair-test design starts by listing them and assigning each one a role:</p>\n<ul>\n  <li><strong>Independent variable</strong> — the one thing <em>you deliberately change</em>. (Also called the input.)</li>\n  <li><strong>Dependent variable</strong> — the thing <em>you measure</em> to see the effect. (The output.)</li>\n  <li><strong>Controlled variables</strong> — everything else that could plausibly matter, which you <em>hold fixed</em>.</li>\n</ul>\n<p>A test is "fair" precisely when only the independent variable differs between trials. Then, and only then, can a change in the outcome be pinned on the thing you changed.</p>\n<table>\n  <thead>\n    <tr><th>Question</th><th>Independent</th><th>Dependent</th><th>Must control</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Does sugar dissolve faster in hotter water?</td><td>Water temperature</td><td>Time to dissolve</td><td>Amount of water, amount of sugar, stirring, sugar grain size</td></tr>\n    <tr><td>Does a heavier car roll further down a ramp?</td><td>Mass of toy car</td><td>Distance rolled</td><td>Ramp angle, release height, same car body, same floor</td></tr>\n    <tr><td>Does bounce height depend on drop height?</td><td>Drop height</td><td>Bounce height</td><td>Same ball, same surface, no throw (just release)</td></tr>\n  </tbody>\n</table>\n<div class="key-concept">\n  <h3>Key Concept: One Variable at a Time</h3>\n  <p>If two things change between trials and the result differs, you cannot tell which one was responsible — the experiment is <strong>confounded</strong>, and no amount of clever analysis afterwards can fully rescue it. Change one variable; measure one variable; freeze the rest.</p>\n</div>\n<p>Two practical habits complete the setup. First, <strong>decide in advance</strong> what you will change, what you will measure, and what you will hold fixed — writing it down keeps you honest. Second, <strong>repeat each trial</strong> at least three times. No two runs ever come out identical; repeats reveal how much natural scatter your setup has, so you can tell a real effect from ordinary wobble. We will quantify that wobble in Chapter 3.</p>'},{id:"the-pendulum-investigation",title:"The Pendulum Investigation",content:"\n<p>Here is the most celebrated fair-test exercise in the world. In Japan, every grade-5 student spends weeks on it; it appears in curricula from Singapore to Finland because it is the perfect controlled-variables workout. The question: a pendulum swings back and forth with some <strong>period</strong> (the time for one complete swing). What does the period depend on?</p>\n<p>Three candidates suggest themselves, and intuition argues loudly for all of them:</p>\n<ul>\n  <li><strong>Length</strong> of the string — surely a longer pendulum swings more slowly?</li>\n  <li><strong>Mass</strong> of the bob — surely a heavier bob is harder to move, so slower?</li>\n  <li><strong>Amplitude</strong> — surely a wider swing takes longer, since the bob travels further?</li>\n</ul>\n<p>The investigation is three fair tests, one per candidate. To test mass, you swing pendulums of the same length and same amplitude with different bobs. To test amplitude, same length and same bob, different release angles. To test length, same bob and same amplitude, different string lengths. One independent variable per test; everything else frozen.</p>\n<p>The result surprises almost everyone: <strong>only length matters</strong>. Double the mass — no change. Swing wider (within modest angles) — no change. But lengthen the string and the period grows: four times the length gives twice the period. Intuition loses two out of three, which is exactly why we run experiments. (The full law, coming in later subjects, is T = 2π√(L/g) — notice mass and amplitude simply do not appear.)</p>\n<div class=\"did-you-know\">\n  <h4>Try it yourself</h4>\n  <p>Tie a small weight (a few metal washers, or keys) to a string and hang it from a door frame or table edge. Time <strong>10 complete swings</strong> with your phone's stopwatch and divide by 10 — timing one swing is too error-prone. Now run the three fair tests: double the washers (same length, small swing); double the release angle (same length, same washers); then quadruple the length, say 25 cm → 1 m (same washers, small swing). You should find the first two periods unchanged and the third roughly doubled, from about 1.0 s to about 2.0 s.</p>\n</div>\n<p>Galileo reportedly began this line of thought watching a lamp swing in Pisa's cathedral, timing it against his own pulse. Your phone is a better stopwatch; the reasoning is identical.</p>"},{id:"designing-good-experiments",title:"Designing Good Experiments",content:'\n<p>You now have all the pieces. Here is the checklist a physicist runs through — consciously at first, automatically forever after — before trusting any experiment, their own included:</p>\n<ol>\n  <li><strong>One question, stated up front.</strong> What exactly are you asking, and what would each possible answer look like in the data?</li>\n  <li><strong>One independent variable.</strong> Everything else that could plausibly matter is listed and pinned down.</li>\n  <li><strong>A measurable dependent variable.</strong> "Better," "faster-ish," and "seems stronger" are not measurements. Choose a number and a unit.</li>\n  <li><strong>Repeats.</strong> At least three trials per setting, so scatter is visible.</li>\n  <li><strong>A range, not two points.</strong> Test five lengths, not two — patterns (and surprises) live in the range.</li>\n  <li><strong>Records made in the moment.</strong> Data written down as it happens, including the runs that "went wrong."</li>\n</ol>\n<p>Equally valuable is knowing the classic failure modes, because you will see them everywhere once named:</p>\n<ul>\n  <li><strong>Confounding:</strong> two variables changed at once — the bread-recipe mistake. The fix is structural, not statistical: redesign the test.</li>\n  <li><strong>Cherry-picking:</strong> keeping the trials that fit your hunch and quietly discarding the rest. Anomalies may be excluded, but only for a documented physical reason ("bumped the table"), never for disagreeing with you.</li>\n  <li><strong>Tiny samples:</strong> one lucky trial proves nothing. Coincidence is astonishingly good at impersonating causation over small numbers.</li>\n  <li><strong>Moving goalposts:</strong> deciding what counts as success <em>after</em> seeing the results.</li>\n</ul>\n<div class="key-concept">\n  <h3>Key Concept: Fair Testing Is a Life Skill</h3>\n  <p>"This supplement worked for my cousin," "sales rose after the redesign," "it rained right after they seeded the clouds" — each is an uncontrolled, unrepeated, one-variable-among-many observation. You do not need a laboratory to ask the physicist\'s question: <em>compared to what, with what else held fixed, how many times?</em></p>\n</div>\n<p>Design is nine-tenths of experimental skill. A fair test with kitchen equipment beats a sloppy test with precision instruments, every single time.</p>'}],quiz:[{question:"In an experiment to see whether water temperature affects how fast sugar dissolves, what is the dependent variable?",options:["The water temperature","The amount of sugar","The time the sugar takes to dissolve","The size of the cup"],correctIndex:2,explanation:"The dependent variable is the outcome you measure — here, dissolving time. Temperature is the independent variable (deliberately changed), while sugar amount, water amount, and stirring must be controlled."},{question:"In the classic pendulum investigation, which factor actually changes the pendulum's period?",options:["The length of the string only","The mass of the bob only","Both the mass and the amplitude","Length, mass, and amplitude all matter equally"],correctIndex:0,explanation:"Fair tests show that (for modest swing angles) neither mass nor amplitude changes the period — only length does. Quadrupling the length doubles the period, reflected in the law T = 2π√(L/g), where mass and amplitude never appear."},{question:"To test fairly whether the mass of the bob affects a pendulum's period, you should change the mass while keeping…",options:["the mass constant and varying the length","the string length and release amplitude the same in every trial","everything different, to explore more possibilities at once","the period the same in every trial"],correctIndex:1,explanation:"A fair test changes only the variable under investigation. Testing mass means every trial uses the same length and same amplitude; only the bob changes. Otherwise you cannot attribute any difference to mass alone."},{question:"You changed both the ramp angle and the car's mass, and the car rolled further. What can you conclude?",options:["Mass makes cars roll further","Ramp angle makes cars roll further","Both factors contributed equally","Nothing definite — the experiment is confounded because two variables changed at once"],correctIndex:3,explanation:"When two variables change together, the effect cannot be attributed to either one — the experiment is confounded. The fix is to redesign: vary the angle with mass fixed, then vary the mass with angle fixed."},{question:"Why time 10 pendulum swings and divide by 10, rather than timing a single swing?",options:["The pendulum needs 10 swings to reach full speed","Your reaction-time error gets spread across 10 swings, shrinking its effect on the result tenfold","The period only stabilizes after several swings","Stopwatches cannot measure times shorter than 10 seconds"],correctIndex:1,explanation:"Your start/stop reaction error (a few tenths of a second) is roughly the same whether you time 1 swing or 10. Dividing a 10-swing measurement by 10 also divides that error by 10 — a classic trick for improving precision with no new equipment."}]},{id:"data-and-graphs",title:"Data & Graphs",subtitle:"Tables, bar and line graphs, patterns and averages — and a first honest look at uncertainty",sections:[{id:"tables-that-work",title:"Tables That Work",content:'\n<p>Raw experience is fleeting; <strong>data is experience written down in a form you can reason about later</strong>. The humble table is where that starts, and a few conventions — the same ones used in every professional lab — make the difference between a table you can trust and a pile of numbers.</p>\n<ul>\n  <li><strong>Units live in the header, once.</strong> Write "Length (cm)" at the top, then plain numbers below. A column mixing "25 cm" and "0.3 m" is an accident waiting to happen.</li>\n  <li><strong>Independent variable in the left column</strong>, in a sensible order (usually increasing). Dependent variable(s) to the right.</li>\n  <li><strong>One column per repeat, plus a mean.</strong> Three trials means three columns and an average — never just the average, because the spread of the repeats is information you will want later.</li>\n  <li><strong>Record immediately, and record everything.</strong> Data written from memory an hour later is fiction with confidence. Failed runs get recorded too, with a note.</li>\n</ul>\n<p>Here is what pendulum data looks like done properly:</p>\n<table>\n  <thead>\n    <tr><th>Length (cm)</th><th>Trial 1 — time for 10 swings (s)</th><th>Trial 2 (s)</th><th>Trial 3 (s)</th><th>Mean (s)</th><th>Period (s)</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>25</td><td>10.1</td><td>9.9</td><td>10.2</td><td>10.1</td><td>1.01</td></tr>\n    <tr><td>50</td><td>14.3</td><td>14.1</td><td>14.4</td><td>14.3</td><td>1.43</td></tr>\n    <tr><td>100</td><td>20.0</td><td>20.3</td><td>19.9</td><td>20.1</td><td>2.01</td></tr>\n  </tbody>\n</table>\n<div class="key-concept">\n  <h3>Key Concept: The Mean Tames the Wobble</h3>\n  <p>Repeated measurements never agree exactly — hand timing, air currents, and release wobble all inject scatter. The <strong>mean</strong> (add the trials, divide by how many) smooths out this random scatter, and the trials\' spread tells you how much to trust it. One reading is an anecdote; three readings and a mean are a measurement.</p>\n</div>\n<p>Notice something satisfying in that table: quadrupling the length from 25 cm to 100 cm did double the period, 1.01 s → 2.01 s. The pattern was in the data — but it takes a graph to make patterns leap out, which is where we go next.</p>'},{id:"bar-or-line",title:"Bar or Line? Choosing and Building Graphs",content:'\n<p>A graph is a machine for turning columns of numbers into a shape your visual system can read instantly. Choosing the right kind is the first decision, and it hinges on the independent variable:</p>\n<ul>\n  <li><strong>Bar graph — for categories.</strong> When the things compared are separate kinds with no in-between (materials, brands, days of the week), draw bars. There is no such thing as "halfway between wood and steel," so connecting them with a line would be nonsense.</li>\n  <li><strong>Line graph (or scatter plot) — for continuous quantities.</strong> When the independent variable can take any value in a range (length, temperature, time), plot points and look for the trend. In-between values exist, so the trend between points is meaningful.</li>\n</ul>\n<p>Quick test: could the x-axis value be 37.4? If yes, it is continuous — points and a trend line. If the question is absurd, bars.</p>\n<p>A graph worth drawing is worth drawing properly. The professional checklist:</p>\n<ol>\n  <li><strong>Independent variable on the horizontal axis</strong>, dependent on the vertical — "y against x" means y is measured, x is chosen.</li>\n  <li><strong>Both axes labelled with quantity and unit:</strong> "Length (cm)", "Period (s)".</li>\n  <li><strong>Scales chosen so the data fills the plot</strong>, with evenly spaced, round-numbered gridlines. A graph squashed into one corner hides its own story.</li>\n  <li><strong>Points marked clearly</strong>, and for continuous data, a single <strong>smooth trend</strong> — a straight line or gentle curve capturing the overall pattern, not a jittery connect-the-dots through every point.</li>\n</ol>\n<div class="analogy">\n  <h3>Analogy: The Trend Line as a Voting Booth</h3>\n  <p>Each data point casts a vote about where the true relationship lies, but every voter is slightly unreliable — scatter is guaranteed. Drawing a smooth best-fit line through the middle of the points is letting the votes average out. Zigzagging through every single point treats each unreliable voter as infallible, faithfully reproducing the noise instead of the signal.</p>\n</div>\n<p>That last habit — trusting the trend over the individual point — marks the biggest single step from school plotting to scientific plotting.</p>'},{id:"reading-stories-from-graphs",title:"Reading Stories from Graphs",content:'\n<p>Making graphs is half the skill; <strong>reading</strong> them is the half that pays off daily, since the world communicates in graphs — news charts, fitness apps, energy bills. A line graph tells its story through shape, and physicists read shape with three questions.</p>\n<p><strong>1. Which way does it go?</strong> Rising: the quantities increase together. Falling: one grows as the other shrinks. Flat: the dependent variable simply does not care — remember pendulum period against mass: a perfectly flat line is a strong, useful result, not a failed experiment.</p>\n<p><strong>2. How steep, and is the steepness changing?</strong> The <strong>slope</strong> is the rate of change — how much the y-quantity changes per unit of x. On a distance–time graph, slope literally <em>is</em> speed: steeper means faster, flat means stopped, and a slope that steepens over time means acceleration. Learning to see slope as "how fast y responds to x" is one of the highest-value reading skills in all of physics.</p>\n<p><strong>3. Is it a straight line through the origin?</strong> That special shape means <strong>direct proportionality</strong>: double x, and y doubles. Straight but missing the origin means "linear but with a head start" — related, but not proportional. Curves tell subtler stories: period versus length curves like a square root (flattening as it rises), which is a genuine clue about the underlying law.</p>\n<div class="key-concept">\n  <h3>Key Concept: Interpolate Freely, Extrapolate Carefully</h3>\n  <p><strong>Interpolation</strong> — reading between your measured points — is usually safe: you have data on both sides. <strong>Extrapolation</strong> — extending the trend beyond your data — is a bet that the pattern continues where you never looked. Sometimes it must be done, but every extrapolation deserves suspicion: a spring stretches proportionally right up until it doesn\'t.</p>\n</div>\n<p>Finally, read graphs defensively. A vertical axis that starts at 90 instead of 0 makes a 2% difference look like a cliff; a cherry-picked time window can turn any wiggle into a trend. The same conventions that make graphs powerful make them easy to abuse — and now you know exactly where to look.</p>'},{id:"first-look-at-uncertainty",title:"A First Look at Uncertainty",content:'\n<p>Here is a truth that separates physics from arithmetic: <strong>no measurement is exact</strong>. Every number you will ever measure comes with a fuzz of doubt, and mature science does not hide the fuzz — it measures it, reports it, and reasons with it.</p>\n<p>Where does the fuzz come from? Your ruler has finite markings; your reaction time varies; the room\'s drafts nudge the pendulum. These effects come in two flavours:</p>\n<ul>\n  <li><strong>Random scatter</strong> — trial-to-trial wobble in both directions. Repeats and averaging beat it down.</li>\n  <li><strong>Systematic error</strong> — a consistent push one way: a stopwatch that runs slow, a ruler measured from its worn end, a scale that reads 0.2 kg with nothing on it. Averaging is helpless here; only checking the instrument catches it.</li>\n</ul>\n<p>The simplest honest report of a repeated measurement is <strong>mean \xb1 half the spread</strong>. Timing swings gave 10.1, 9.9, and 10.2 s: the mean is 10.1 s and the spread is 0.3 s, so report 10.1 \xb1 0.15 s — "our best value is 10.1, and we would not be shocked by anything within about 0.15 of it." That little \xb1 converts a bare claim into a testable one: two results agree when their \xb1 ranges overlap.</p>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Measure your own reaction time with a ruler and a friend. They hold a 30 cm ruler vertically by the top; you position your open finger and thumb at the 0 cm mark, and catch it the instant they drop it (no warning). Record the catch distance, repeat 10 times, and tabulate. Convert with t = √(2d \xf7 980) (d in cm, t in seconds): catching at 20 cm means about 0.20 s. Now look at your table like a scientist: how big is your scatter? Is your mean improving over the 10 trials (a practice effect — a systematic drift!)? You have just done a complete uncertainty analysis with a ruler.</p>\n</div>\n<p>An <strong>anomaly</strong> — one reading far outside the pack — deserves investigation, not silent deletion: find the cause ("I flinched early"), note it, and repeat the trial. Uncertainty handled this honestly is not weakness. It is precisely what makes measurements comparable, claims checkable, and science self-correcting.</p>'}],quiz:[{question:"You measured how far a toy car rolls on four different floor surfaces: tile, carpet, wood, and rug. Which graph suits this data?",options:["A line graph, because distance is continuous","A pie chart, to show each surface's share","A bar graph, because the surfaces are separate categories with no in-between values","No graph is possible with only four data points"],correctIndex:2,explanation:"The independent variable (surface type) is categorical — there is no value 'between tile and carpet' — so bars are correct. Line graphs are reserved for continuous independent variables like length, time, or temperature."},{question:"On a distance–time graph, what does the slope of the line represent?",options:["The total distance travelled","The speed of motion","The time elapsed","The mass of the moving object"],correctIndex:1,explanation:"Slope is the rate of change of the vertical quantity per unit of the horizontal one — here, distance per time, which is speed. Steeper means faster; a flat section means stationary."},{question:"Three timing trials give 14.3 s, 14.1 s, and 14.4 s. What is the best value to report?",options:["14.4 s, since the largest reading is the most complete","14.1 s, since the smallest reading has the least error","42.8 s, the total of all three","About 14.3 s — the mean of the trials, with roughly \xb1 0.15 s of uncertainty"],correctIndex:3,explanation:"The mean (14.27 ≈ 14.3 s) is the best single estimate because random scatter partially cancels when you average. The spread of 0.3 s suggests an uncertainty of about \xb1 0.15 s — the honest way to report the result."},{question:"A kitchen scale reads 0.2 kg with nothing on it, so every measurement comes out 0.2 kg too high. This is an example of…",options:["a systematic error, which averaging repeated readings cannot remove","random scatter, which averaging removes","an anomaly that should be deleted from the data","acceptable uncertainty that needs no correction"],correctIndex:0,explanation:"A consistent push in one direction is a systematic error. Unlike random scatter, it never averages away — every reading is shifted the same way. The cure is checking and correcting the instrument (here, taring the scale)."},{question:"Your data on spring stretch versus load is beautifully linear from 0 to 500 g. A friend uses your trend line to predict the stretch at 5 kg. Why should you both be cautious?",options:["Trend lines can only be used at the exact points measured","Predictions require at least 100 data points","This is extrapolation far beyond the measured range — the linear pattern may break down (springs eventually deform)","The prediction is invalid because grams must first be converted to newtons"],correctIndex:2,explanation:"Reading within your measured range (interpolation) is well-supported; extending the pattern to ten times the maximum load (extrapolation) assumes the spring stays linear where you have no evidence — and real springs stop obeying Hooke's law and permanently deform."}]},{id:"estimation-and-sanity-checks",title:"Estimation & Sanity Checks",subtitle:"Order-of-magnitude reasoning, Fermi problems, and letting units catch your mistakes",sections:[{id:"the-power-of-ten",title:"Thinking in Powers of Ten",content:'\n<p>Ask a physicist how many people live in your city and you may get the answer "about 10⁶." Not evasion — a different, deliberately chosen precision called an <strong>order of magnitude</strong>: the nearest power of ten. It sounds crude, but thinking in powers of ten is one of the sharpest tools in physics, for two reasons.</p>\n<p>First, <strong>most real questions only need the exponent</strong>. Will the file fit on the drive? Can this battery run that heater? Is this news statistic even possible? For all of these, knowing whether the answer is closer to 10\xb3 or 10⁶ settles the matter; the third significant figure never gets consulted.</p>\n<p>Second, <strong>orders of magnitude are hard to get wrong by much</strong>. Your guess for a city\'s population might be off by a factor of two, but rarely by a factor of a hundred. Working in powers of ten deliberately plays to the strength of rough knowledge.</p>\n<p>To find an order of magnitude, write the number in scientific notation and round: 3,200 = 3.2 \xd7 10\xb3 ≈ 10\xb3, while 82,000 = 8.2 \xd7 10⁴ rounds up to 10⁵. A feel for the scale of things is worth building deliberately:</p>\n<table>\n  <thead>\n    <tr><th>Length</th><th>Order of magnitude</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Thickness of paper</td><td>10⁻⁴ m</td></tr>\n    <tr><td>An ant</td><td>10⁻\xb3 m</td></tr>\n    <tr><td>A human</td><td>10⁰ m (≈ 2 m)</td></tr>\n    <tr><td>Height of Everest</td><td>10⁴ m</td></tr>\n    <tr><td>Diameter of Earth</td><td>10⁷ m</td></tr>\n    <tr><td>Earth to Sun</td><td>10\xb9\xb9 m</td></tr>\n  </tbody>\n</table>\n<div class="key-concept">\n  <h3>Key Concept: Each Step Is a Factor of Ten</h3>\n  <p>The gap between 10⁴ and 10⁶ is not "2 more" — it is <strong>100 times</strong>. Order-of-magnitude thinking is multiplicative: a billion (10⁹) is not "a bit past" a million (10⁶), it is a thousand millions. A million seconds is 12 days; a billion seconds is 32 <em>years</em>. Most bad intuitions about big numbers are failures to feel this difference.</p>\n</div>\n<p>From here on, before computing anything precisely, we will ask: <em>roughly what size should the answer be?</em> That one habit catches more errors than any calculator.</p>'},{id:"fermi-problems",title:"Fermi Problems",content:'\n<p>Enrico Fermi, one of the great physicists of the twentieth century, was famous for estimating seemingly unknowable quantities — legend says he estimated the strength of the first atomic-bomb test by dropping scraps of paper and watching how far the blast wave carried them, landing within a factor of two of the instrumented value. A <strong>Fermi problem</strong> honours that spirit: estimate something outrageous using only common knowledge and courage.</p>\n<p>The classic: <em>how many piano tuners work in Chicago?</em> The method is always the same — <strong>break the impossible number into a chain of guessable ones</strong>:</p>\n<ol>\n  <li>Chicago has roughly 3 \xd7 10⁶ people — about 10⁶ households.</li>\n  <li>Maybe 1 household in 20 has a piano → ~5 \xd7 10⁴ pianos.</li>\n  <li>A piano gets tuned about once a year → 5 \xd7 10⁴ tunings/year.</li>\n  <li>A tuner does ~4 tunings a day, ~250 days a year → ~10\xb3 tunings per tuner per year.</li>\n  <li>So Chicago supports about 5 \xd7 10⁴ \xf7 10\xb3 ≈ <strong>50 tuners</strong>.</li>\n</ol>\n<p>Directory listings historically said: a few dozen. The magic is that individual errors tend to <strong>cancel</strong>: guess pianos too high and tunings-per-year too low, and the product barely moves. A chain of five guesses, each within a factor of 2–3, usually lands the final answer within a factor of 10 — which is exactly what you need to call nonsense on a claim, size a plan, or decide whether a precise calculation is worth doing.</p>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Estimate how many litres of water your household uses per day. Chain it: showers (minutes \xd7 ~10 L/min) + toilet flushes (count \xd7 ~6 L) + dishes, laundry, cooking, drinking. Write down your total — then check yourself against your water bill or meter, which reports actual usage (often in m\xb3: 1 m\xb3 = 1,000 L). Landing within a factor of 2 on your first try is genuinely good Fermi form. Where was your worst single guess?</p>\n</div>\n<p>Estimate first, look up later. The estimate builds the intuition; the lookup then calibrates it — and every future estimate gets sharper.</p>'},{id:"let-the-units-do-the-work",title:"Let the Units Do the Work",content:'\n<p>Units are not decorations after a number — they are <strong>algebra that checks your reasoning for free</strong>. Treat every unit as a symbol that multiplies, divides, and cancels exactly like x and y, and two superpowers follow.</p>\n<p><strong>Superpower 1: conversions become unmissable.</strong> To convert, multiply by fractions equal to 1. Converting 90 km/h to m/s:</p>\n<p style="text-align:center">90 km/h \xd7 (1,000 m / 1 km) \xd7 (1 h / 3,600 s) = 25 m/s</p>\n<p>The km cancels, the h cancels, and only m/s survives. If you had flipped a fraction, the units would refuse to cancel — the mistake announces itself before the arithmetic even happens.</p>\n<p><strong>Superpower 2: formulas can be sanity-checked without knowing physics.</strong> An equation is only meaningful if both sides carry the same units — you cannot equate metres to seconds any more than you can pay a bill in kilograms. Suppose you half-remember distance fallen as d = \xbdgt, with g ≈ 9.8 m/s\xb2 and t in seconds. Check: (m/s\xb2) \xd7 s = m/s. That is a <em>speed</em>, not a distance — the formula must be wrong. The correct d = \xbdgt\xb2 gives (m/s\xb2) \xd7 s\xb2 = m. ✓ You just debugged a physics formula with no physics at all, only unit bookkeeping. This habit, called <strong>dimensional analysis</strong>, scales all the way to research: professionals run it on every result, reflexively.</p>\n<div class="did-you-know">\n  <h3>Did You Know: The $327 Million Unit Error</h3>\n  <p>In 1999 NASA\'s Mars Climate Orbiter burned up in the Martian atmosphere because one team\'s software output thruster impulse in pound-force seconds while another\'s expected newton-seconds — a factor of 4.45 slipped through every review. The spacecraft arrived 170 km lower than planned. The most expensive unit-conversion mistake in history is now the standard cautionary tale: <em>always carry the units</em>.</p>\n</div>\n<p>Make it mechanical: write units beside every number, cancel them like fractions, and refuse to box any answer whose units are wrong. Wrong units mean a wrong answer, with certainty; right units do not guarantee a right answer, but they eliminate the entire family of errors that carelessness produces most often.</p>'},{id:"the-sanity-check-toolkit",title:"The Sanity-Check Toolkit",content:'\n<p>A calculator will happily tell you that a bathtub holds 4,000,000 litres or that a cyclist rides at 900 km/h. The final skill of this subject — the one that quietly guards all the others — is the reflex of interrogating every answer before accepting it. Four checks, run in seconds:</p>\n<ol>\n  <li><strong>The size check.</strong> Compare against benchmarks you carry in your head. Build this shelf deliberately: a human is ~70 kg; brisk walking is ~1.5 m/s and highway driving ~30 m/s; a car is ~1,500 kg; a flight of stairs is ~3 m; a bathtub is ~150 L; a phone battery stores ~10 Wh; room temperature is ~20 \xb0C. Any result wildly off-shelf is guilty until proven innocent.</li>\n  <li><strong>The unit check.</strong> From the previous section — wrong units, wrong answer, no appeal.</li>\n  <li><strong>The direction check.</strong> Should the answer grow or shrink as inputs change? More friction should mean stopping sooner; if your formula says otherwise, the formula (or your algebra) is broken.</li>\n  <li><strong>The extreme-case check.</strong> Push inputs to limits where the answer is obvious. A formula for pendulum period should give a huge period for an absurdly long string and zero for zero length. Extreme cases are where wrong formulas fail most loudly.</li>\n</ol>\n<div class="analogy">\n  <h3>Analogy: The Restaurant Bill</h3>\n  <p>Six people dine, and the bill says $4,700. You do not re-add every line — you instantly know it is wrong, because six dinners is a few hundred dollars, and you demand a recount. Sanity-checking physics answers is the same reflex pointed at nature: rough expected size first, precision second. The goal of this chapter is that a 900 km/h cyclist feels exactly as absurd to you as that bill.</p>\n</div>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Estimate the total mass of air in your bedroom — most people are shocked. Pace out the room\'s dimensions (say 4 m \xd7 3 m \xd7 2.5 m = 30 m\xb3) and use the benchmark that air\'s density is about 1.2 kg/m\xb3: roughly <strong>36 kg of air</strong> — about the mass of a ten-year-old child, floating invisibly around you. Then run the toolkit on it: units (m\xb3 \xd7 kg/m\xb3 = kg ✓), direction (bigger room → more air ✓), extreme case (an empty room of zero volume → zero air ✓). It survives every check — which is exactly why physicists believe surprising numbers when they earn it.</p>\n</div>\n<p>Estimation, units, and sanity checks form one habit: <strong>never let a number pass unexamined</strong>. Carry that habit forward and every formula in the phases ahead becomes something you can verify — not something you must take on faith.</p>'}],quiz:[{question:"What is the order of magnitude of 82,000?",options:["10⁴, because 82,000 starts with an 8","10⁵, because 8.2 \xd7 10⁴ rounds to 10⁵","10⁸, because there are 8 in the number","10\xb3, the nearest round unit"],correctIndex:1,explanation:"82,000 = 8.2 \xd7 10⁴. Since 8.2 is closer to 10 than to 1, it rounds up, giving an order of magnitude of 10⁵. (A common convention: mantissas above about 3.16, i.e. √10, round up.)"},{question:"Why do Fermi estimates built from a chain of rough guesses often land surprisingly close to the truth?",options:["Because each individual guess is usually exact","Because the method only works for questions about pianos","Because overestimates and underestimates in the chain tend to cancel each other out","Because multiplying numbers always reduces error"],correctIndex:2,explanation:"Each factor is only good to within perhaps 2–3\xd7, but errors are as likely high as low, so in a product they partially cancel. A five-step chain typically lands within a factor of 10 — exactly the precision an order-of-magnitude question needs."},{question:"You half-remember a formula for distance fallen: d = \xbdgt, with g in m/s\xb2 and t in seconds. What does a unit check reveal?",options:["The right side gives m/s — a speed, not a distance — so the formula must be wrong","The units work out, so the formula is correct","Units cannot be used to check formulas, only conversions","The formula is wrong because g should be in kilograms"],correctIndex:0,explanation:"(m/s\xb2) \xd7 s = m/s, a speed. Since a distance must come out in metres, the formula fails the dimensional check. The correct d = \xbdgt\xb2 gives (m/s\xb2) \xd7 s\xb2 = m. Units debug formulas even when you have forgotten the physics."},{question:"What destroyed NASA's Mars Climate Orbiter in 1999?",options:["A collision with space debris","A software team supplied thruster data in pound-force seconds while another expected newton-seconds","An error in Newton's law of gravitation","A failure of the launch rocket"],correctIndex:1,explanation:"One team's software reported impulse in imperial units (pound-force seconds) while the trajectory software expected metric (newton-seconds). The unnoticed factor of 4.45 sent the $327 million spacecraft 170 km too deep into Mars's atmosphere — history's most expensive unit error."},{question:"A calculation tells you a cyclist's speed is 900 km/h. Which sanity check most immediately flags the problem?",options:["The unit check — km/h is not a valid unit of speed","The extreme-case check — cyclists cannot ride uphill","No check flags it; the calculation should simply be redone from scratch","The size check — benchmark speeds (brisk walk ≈ 5 km/h, highway car ≈ 100 km/h, airliner ≈ 900 km/h) show a cyclist cannot plausibly match an airliner"],correctIndex:3,explanation:"The units (km/h) are fine — it is the size that is absurd. Comparing against mental benchmarks instantly shows 900 km/h is airliner speed, roughly 30 times a strong cyclist's pace, so an error (likely a unit slip or misplaced power of ten) must be hiding in the calculation."}]}]},{id:"algebra-geometry-for-physics",number:4,title:"Algebra & Geometry for Physics",description:"The math toolkit that powers the entire Phase 2 tour of physics: rearrange any formula on demand, read physics straight off a graph, and solve triangles with confidence.",phase:2,chapters:[{id:"the-language-of-algebra",title:"The Language of Algebra",subtitle:"Variables, expressions, and the symbol-manipulation moves behind every physics formula",sections:[{id:"letters-that-stand-for-numbers",title:"Letters That Stand for Numbers",content:'\n<p>A variable is nothing more mysterious than a <strong>labeled box that holds a number</strong>. When physics writes v = d/t, it is saying: "take whatever number is in the box labeled d, divide it by whatever number is in the box labeled t, and the result belongs in the box labeled v." The letters aren\'t the point — the <em>relationship</em> between the boxes is.</p>\n<p>An <strong>expression</strong> is a recipe built from variables and numbers: 3x + 5, or d/t, or 2(a + b). It has no equals sign — it\'s just a quantity waiting to be computed. An <strong>equation</strong> makes a claim: it says two expressions are equal, like v = d/t or 3x + 5 = 20. Expressions you <em>evaluate</em>; equations you <em>solve</em>.</p>\n<h3>Substitution: the number-in-the-box move</h3>\n<p>Evaluating an expression means replacing each letter with its number and doing the arithmetic. Watch it work:</p>\n<ul>\n  <li>Evaluate 3x + 5 when x = 4: &nbsp; 3 \xd7 4 + 5 = 12 + 5 = <strong>17</strong></li>\n  <li>Evaluate d/t when d = 150 and t = 3: &nbsp; 150 \xf7 3 = <strong>50</strong></li>\n  <li>Evaluate 2(a + b) when a = 7, b = 3: &nbsp; 2 \xd7 (7 + 3) = 2 \xd7 10 = <strong>20</strong></li>\n  <li>Evaluate \xbdat\xb2 when a = 10, t = 3: &nbsp; \xbd \xd7 10 \xd7 3\xb2 = \xbd \xd7 10 \xd7 9 = <strong>45</strong></li>\n</ul>\n<p>Notice the last one: the \xb2 applies only to t, and you square <em>before</em> multiplying — order of operations (brackets, powers, \xd7 and \xf7, then + and −) is the grammar of this language.</p>\n<div class="analogy">\n  <h3>Analogy: A Spreadsheet Cell</h3>\n  <p>If you\'ve ever typed =A1/B1 into a spreadsheet, you\'ve already done algebra. A1 and B1 are variables; the formula is an expression; changing the inputs updates the output automatically. Physics formulas are exactly this — v = d/t is =A1/B1 with better labels.</p>\n</div>\n<div class="key-concept">\n  <h3>Key Concept: One Formula, Infinite Problems</h3>\n  <p>The power of a variable is generality. "150 km in 3 hours means 50 km/h" solves one trip. v = d/t solves <em>every</em> trip ever taken. That compression — infinitely many facts in five symbols — is why physics is written in algebra.</p>\n</div>'},{id:"simplifying-expressions",title:"Simplifying: Collecting Like Terms",content:'\n<p>Algebraic expressions often arrive messy, and simplifying is just tidying up: combining everything that can be combined so the expression says the same thing in fewer symbols. The one rule that governs it all: <strong>you can only add or subtract like terms</strong> — terms with exactly the same letter part.</p>\n<p>Think of terms as objects. 3x means "three x-things." So 3x + 2x = 5x for the same reason 3 apples + 2 apples = 5 apples. But 3x + 2y stays 3x + 2y — apples and oranges don\'t merge. And 3x + 2x\xb2 also stays put: an x-thing and an x\xb2-thing are different objects, just as a meter and a square meter are different quantities.</p>\n<h3>Worked examples</h3>\n<ol>\n  <li>4x + 7 + 2x − 3 &nbsp;→&nbsp; (4x + 2x) + (7 − 3) &nbsp;→&nbsp; <strong>6x + 4</strong></li>\n  <li>5a + 3b − 2a + b &nbsp;→&nbsp; (5a − 2a) + (3b + b) &nbsp;→&nbsp; <strong>3a + 4b</strong></li>\n  <li>x\xb2 + 4x + 3x\xb2 − x &nbsp;→&nbsp; (x\xb2 + 3x\xb2) + (4x − x) &nbsp;→&nbsp; <strong>4x\xb2 + 3x</strong></li>\n  <li>2t + 6t − t &nbsp;→&nbsp; <strong>7t</strong> &nbsp;(the invisible coefficient of −t is −1)</li>\n</ol>\n<p>Multiplication is friendlier: any terms can multiply. 3 \xd7 2x = 6x. And x \xd7 x = x\xb2, so 2x \xd7 4x = 8x\xb2. Multiply the numbers, then combine the letters.</p>\n<div class="key-concept">\n  <h3>Key Concept: The Sign Travels With the Term</h3>\n  <p>In 5a − 2a + 3b, the "−" belongs to the 2a. The most common simplifying error is dropping a minus sign while shuffling terms. Read expressions as a list of signed terms: +5a, −2a, +3b — then collecting is foolproof.</p>\n</div>\n<div class="did-you-know">\n  <h3>Why Physics Cares</h3>\n  <p>When several forces act on one object, physics adds them into a single <em>net force</em> — which is literally collecting like terms: 30 N forward − 12 N backward = 18 N forward. Later, when you combine energy terms or add resistances in a circuit, you\'ll be doing this exact move with physical quantities attached.</p>\n</div>'},{id:"expanding-brackets",title:"Expanding Brackets: The Distributive Law",content:'\n<p>Brackets say "treat this as one package." Expanding unwraps the package by the <strong>distributive law</strong>: whatever multiplies a bracket multiplies <em>every</em> term inside it.</p>\n<p>a(b + c) = ab + ac. With numbers you already believe this: 4 \xd7 (10 + 2) is 4 \xd7 10 + 4 \xd7 2 = 48 — it\'s how you multiply 4 \xd7 12 in your head.</p>\n<h3>Worked examples</h3>\n<ol>\n  <li>3(x + 5) = 3x + 15</li>\n  <li>4(2x + 3) = 8x + 12</li>\n  <li>−2(x − 4) = −2x + 8 &nbsp;<em>(a negative outside flips every sign inside)</em></li>\n  <li>x(x + 7) = x\xb2 + 7x</li>\n  <li>5(2a + 3b − 1) = 10a + 15b − 5 &nbsp;<em>(every term, including the lonely −1)</em></li>\n</ol>\n<h3>Two brackets: everything meets everything</h3>\n<p>To expand (x + 2)(x + 3), each term in the first bracket multiplies each term in the second — four little products in total:</p>\n<ul>\n  <li>x \xd7 x = x\xb2</li>\n  <li>x \xd7 3 = 3x</li>\n  <li>2 \xd7 x = 2x</li>\n  <li>2 \xd7 3 = 6</li>\n</ul>\n<p>Collect like terms: x\xb2 + 3x + 2x + 6 = <strong>x\xb2 + 5x + 6</strong>. One more: (x − 4)(x + 1) = x\xb2 + x − 4x − 4 = <strong>x\xb2 − 3x − 4</strong>. Watch the signs travel.</p>\n<div class="analogy">\n  <h3>Analogy: The Handshake Rule</h3>\n  <p>Two people from team one, two from team two: everyone shakes hands with everyone on the other team — 2 \xd7 2 = 4 handshakes. Expanding double brackets is exactly this: four products, no term left out, then tidy up.</p>\n</div>\n<div class="key-concept">\n  <h3>Key Concept: One Pattern to Memorize</h3>\n  <p>(a + b)\xb2 = a\xb2 + 2ab + b\xb2 — <em>not</em> a\xb2 + b\xb2. Check with numbers: (3 + 4)\xb2 = 49, while 3\xb2 + 4\xb2 = 25. That middle term 2ab is real, and forgetting it is the single most famous algebra mistake. This identity returns in Pythagoras proofs, energy formulas, and error estimates all through physics.</p>\n</div>'},{id:"factoring-basics",title:"Factoring: Running the Film Backwards",content:'\n<p>Factoring is expanding in reverse: you take a spread-out expression and repackage it as a product. 8x + 12 becomes 4(2x + 3). Nothing changed in value — you can always check by expanding again — but the <em>form</em> changed, and form is power.</p>\n<h3>Step one: hunt the common factor</h3>\n<p>Look at every term and ask: what do they all share? Pull it out front.</p>\n<ol>\n  <li>6x + 9 &nbsp;→&nbsp; both share 3 &nbsp;→&nbsp; <strong>3(2x + 3)</strong></li>\n  <li>10a − 15b &nbsp;→&nbsp; both share 5 &nbsp;→&nbsp; <strong>5(2a − 3b)</strong></li>\n  <li>x\xb2 + 7x &nbsp;→&nbsp; both share x &nbsp;→&nbsp; <strong>x(x + 7)</strong></li>\n  <li>4t\xb2 + 8t &nbsp;→&nbsp; both share 4t &nbsp;→&nbsp; <strong>4t(t + 2)</strong></li>\n</ol>\n<p>Always check by expanding: 4t(t + 2) = 4t\xb2 + 8t. ✓ If it doesn\'t expand back, the factoring is wrong — this self-check makes factoring one of the safest skills in algebra.</p>\n<h3>Why bother?</h3>\n<p>Because a product equals zero only when one of its factors is zero — the key that unlocks quadratic equations in the chapter ahead. And because factored form reveals structure: in physics, mgh₁ − mgh₂ = mg(h₁ − h₂) shows at a glance that only the <em>height difference</em> matters for gravitational energy, not the individual heights. The factored form is the insight.</p>\n<div class="analogy">\n  <h3>Analogy: Zipping a File</h3>\n  <p>Expanding and factoring are unzip and zip. The information is identical either way; you choose the form that suits the job. Need to combine with other terms? Expand. Need to solve, cancel, or see what\'s shared? Factor.</p>\n</div>\n<div class="did-you-know">\n  <h3>Mental Arithmetic Bonus</h3>\n  <p>Factoring is why 17 \xd7 6 + 3 \xd7 6 is easy: it\'s (17 + 3) \xd7 6 = 120. Physicists and engineers factor constantly in their heads — pulling out common factors before computing is often the difference between a 10-second calculation and a calculator hunt.</p>\n</div>'}],quiz:[{question:"Using v = d/t, what is v when d = 150 km and t = 3 hours?",options:["45 km/h","153 km/h","50 km/h","0.02 km/h"],correctIndex:2,explanation:"Substitute the numbers into their boxes: v = 150 \xf7 3 = 50 km/h. Substitution — replace each letter with its value, then do the arithmetic — is the move you'll use in every physics chapter that follows."},{question:"Simplify: 3x + 5 + 2x − 1",options:["5x + 4","6x + 4","5x − 4","10x"],correctIndex:0,explanation:"Collect like terms with their signs: 3x + 2x = 5x, and 5 − 1 = 4, giving 5x + 4. The x-terms and the plain numbers are different kinds of object, so they never merge into one term like 10x."},{question:"Expand: 4(2x + 3)",options:["8x + 3","6x + 7","24x","8x + 12"],correctIndex:3,explanation:"The 4 multiplies every term inside the bracket: 4 \xd7 2x = 8x and 4 \xd7 3 = 12, so the answer is 8x + 12. The classic error is multiplying only the first term (8x + 3)."},{question:"Factor completely: 6x + 9",options:["6(x + 3)","3(2x + 3)","2(3x + 6)","3(2x + 6)"],correctIndex:1,explanation:"Both terms share a factor of 3: 6x + 9 = 3(2x + 3). Verify by expanding: 3 \xd7 2x = 6x and 3 \xd7 3 = 9. ✓ Always run the film forward again to check a factoring."},{question:"Which of these is an equation, rather than just an expression?",options:["3x + 2","5ab","v = d/t","2(x − 1)"],correctIndex:2,explanation:"An equation makes a claim that two things are equal — it needs an equals sign. v = d/t claims that speed equals distance over time. The others are expressions: recipes for a quantity, with nothing asserted."}]},{id:"equations-and-formula-fluency",title:"Equations & Formula Fluency",subtitle:"Solve linear equations and rearrange any formula to automaticity — the single most-used skill in physics",sections:[{id:"the-balance-model",title:"Solving Equations: The Balance Model",content:'\n<p>An equation is a <strong>balanced scale</strong>: the left pan and the right pan hold equal weight. The golden rule of solving is simply this — <strong>whatever you do to one side, do to the other</strong> — and the scale stays balanced. Your goal is to peel everything away from the unknown until it stands alone.</p>\n<h3>Worked example, narrated</h3>\n<p>Solve 3x − 7 = 14.</p>\n<ol>\n  <li>The x is wrapped in two operations: multiplied by 3, then 7 subtracted. Undo them in reverse order.</li>\n  <li>Add 7 to both sides: &nbsp; 3x = 21</li>\n  <li>Divide both sides by 3: &nbsp; x = <strong>7</strong></li>\n  <li>Check by substituting back: 3 \xd7 7 − 7 = 14. ✓</li>\n</ol>\n<h3>More reps</h3>\n<ul>\n  <li>x + 12 = 30 &nbsp;→&nbsp; subtract 12 &nbsp;→&nbsp; x = 18</li>\n  <li>x/4 = 9 &nbsp;→&nbsp; multiply by 4 &nbsp;→&nbsp; x = 36</li>\n  <li>5x + 3 = 2x + 18 &nbsp;→&nbsp; subtract 2x: 3x + 3 = 18 &nbsp;→&nbsp; subtract 3: 3x = 15 &nbsp;→&nbsp; x = 5</li>\n  <li>2(x − 4) = 10 &nbsp;→&nbsp; expand: 2x − 8 = 10 &nbsp;→&nbsp; 2x = 18 &nbsp;→&nbsp; x = 9 &nbsp;<em>(or divide both sides by 2 first: x − 4 = 5 — often faster)</em></li>\n</ul>\n<div class="key-concept">\n  <h3>Key Concept: Undo in Reverse Order</h3>\n  <p>Getting dressed: socks then shoes. Getting undressed: shoes then socks. An equation wraps x in layers of operations, and you unwrap from the outside in — undo the +7 or −7 first, then the \xd73. This "inverse operations, reverse order" habit is what makes solving mechanical instead of magical.</p>\n</div>\n<div class="did-you-know">\n  <h3>The Check Is Free</h3>\n  <p>Substituting your answer back takes five seconds and catches nearly every error. Physicists check habitually — not because they doubt algebra, but because they know fingers slip. Make the check part of the move, not an afterthought.</p>\n</div>'},{id:"rearranging-formulas",title:"Rearranging Formulas: Make Any Letter the Subject",content:'\n<p>Here is the single most-used math skill in all of physics. Formulas arrive solved for one variable — v = d/t gives you speed — but real problems constantly ask for a different one: how much <em>time</em> will the trip take? You must be able to make <strong>any</strong> letter the subject, quickly and without anxiety. It\'s the balance model again, applied to letters instead of numbers.</p>\n<h3>The full workout on v = d/t</h3>\n<ul>\n  <li><strong>Solve for d:</strong> multiply both sides by t &nbsp;→&nbsp; vt = d, so <strong>d = vt</strong>. (Distance = speed \xd7 time.)</li>\n  <li><strong>Solve for t:</strong> start from d = vt, divide both sides by v &nbsp;→&nbsp; <strong>t = d/v</strong>. (Time = distance \xf7 speed.)</li>\n</ul>\n<p>Check with numbers: 150 km at 50 km/h → t = 150/50 = 3 h. Sensible. ✓</p>\n<h3>The same three moves, everywhere</h3>\n<table>\n  <thead>\n    <tr><th>Formula</th><th>Solve for…</th><th>Result</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>ρ = m/V (density)</td><td>m</td><td>m = ρV</td></tr>\n    <tr><td>ρ = m/V</td><td>V</td><td>V = m/ρ</td></tr>\n    <tr><td>P = F/A (pressure)</td><td>F</td><td>F = PA</td></tr>\n    <tr><td>W = Fd (work)</td><td>F</td><td>F = W/d</td></tr>\n    <tr><td>V = IR (Ohm\'s law)</td><td>R</td><td>R = V/I</td></tr>\n    <tr><td>y = mx + c</td><td>x</td><td>x = (y − c)/m</td></tr>\n  </tbody>\n</table>\n<p>That last one has two steps: subtract c from both sides first, <em>then</em> divide by m. Undo addition before undoing multiplication — same reverse-order rule as before.</p>\n<div class="key-concept">\n  <h3>Key Concept: Rearrange First, Substitute Last</h3>\n  <p>Do the algebra with letters, and only plug in numbers at the end. Letters are easier to move than messy decimals, you can reuse the rearranged formula forever, and errors are far easier to spot in vt = d than in a soup of digits.</p>\n</div>\n<div class="analogy">\n  <h3>Analogy: The Formula Triangle, Retired</h3>\n  <p>You may remember the d–v–t "magic triangle" from school. It works — but only for three-letter formulas, and it hides the reasoning. The balance method handles v = d/t today and \xbdmv\xb2 = mgh next month. Learn the general tool; automaticity comes from reps, and this chapter\'s reps are the investment.</p>\n</div>'},{id:"inequalities",title:"Inequalities: Ranges Instead of Answers",content:'\n<p>Sometimes the answer isn\'t a number but a <strong>range</strong>. "The elevator carries at most 600 kg." "The fuse blows above 13 A." Inequalities express these: x &lt; 5 (less than), x ≤ 5 (at most), x &gt; 5 (greater than), x ≥ 5 (at least).</p>\n<p>The good news: you solve inequalities with the same balance moves as equations. Add, subtract, multiply, divide both sides — the inequality survives. With <strong>one famous exception</strong>.</p>\n<h3>The flip rule</h3>\n<p>Multiplying or dividing both sides by a <strong>negative</strong> number reverses the inequality sign. Why? Watch the number line: 2 &lt; 5 is true, but multiply both by −1 and you get −2 and −5, and −2 &gt; −5. Negation mirrors the number line, so "left of" becomes "right of."</p>\n<h3>Worked examples</h3>\n<ol>\n  <li>x + 3 &lt; 10 &nbsp;→&nbsp; x &lt; 7</li>\n  <li>4x ≥ 20 &nbsp;→&nbsp; x ≥ 5 &nbsp;<em>(divided by positive 4: no flip)</em></li>\n  <li>−2x &lt; 10 &nbsp;→&nbsp; divide by −2 and flip &nbsp;→&nbsp; <strong>x &gt; −5</strong></li>\n  <li>3x + 2 ≤ 17 &nbsp;→&nbsp; 3x ≤ 15 &nbsp;→&nbsp; x ≤ 5</li>\n</ol>\n<p>Check example 3 with a test number: x = 0 satisfies x &gt; −5, and indeed −2 \xd7 0 = 0 &lt; 10. ✓ Testing one easy value catches flip mistakes instantly.</p>\n<div class="key-concept">\n  <h3>Key Concept: Safety Margins Are Inequalities</h3>\n  <p>An elevator rated for 600 kg with passengers averaging 75 kg: 75n ≤ 600 gives n ≤ 8 people. A 13 A fuse on 230 V mains limits appliance power to P ≤ 230 \xd7 13 ≈ 3000 W. Engineering rarely asks "what exactly" — it asks "what at most," and that question is an inequality.</p>\n</div>\n<div class="did-you-know">\n  <h3>Reading the Symbols</h3>\n  <p>The small end of the symbol points at the small quantity — 3 &lt; 8 reads "3 is less than 8." If you ever blank on which is which, that visual saves you.</p>\n</div>'},{id:"systems-of-two-equations",title:"Two Equations, Two Unknowns",content:'\n<p>One equation with two unknowns has infinitely many solutions — x + y = 10 is satisfied by (1, 9), (4, 6), (200, −190)… But add a <strong>second</strong> equation and usually only one pair survives both. Finding it is called solving a <em>system</em>, and there are two standard tools.</p>\n<h3>Method 1: Substitution</h3>\n<p>Solve one equation for one letter, then substitute into the other.</p>\n<p>y = x + 2 and x + y = 10: replace y in the second equation → x + (x + 2) = 10 → 2x + 2 = 10 → x = 4, then y = 6. Check in both: 6 = 4 + 2 ✓ and 4 + 6 = 10 ✓.</p>\n<h3>Method 2: Elimination</h3>\n<p>Add or subtract whole equations so one letter cancels.</p>\n<ol>\n  <li>x + y = 10</li>\n  <li>x − y = 4</li>\n</ol>\n<p>Add them: the +y and −y annihilate → 2x = 14 → <strong>x = 7</strong>, and then y = 3. Elimination shines when the coefficients already match; substitution shines when one equation is already solved for a letter. Both always work — pick the one with less mess.</p>\n<h3>A word-problem classic</h3>\n<p>Two numbers sum to 25; one is 4 times the other. Equations: a + b = 25 and a = 4b. Substitute: 4b + b = 25 → 5b = 25 → b = 5, a = 20.</p>\n<div class="analogy">\n  <h3>Analogy: Two Clues, One Culprit</h3>\n  <p>Each equation is a clue narrowing the suspects. "Sum is 10" leaves a whole line of suspects; "difference is 4" leaves another line. The solution is where the clues intersect — literally: graph both equations and the answer is the crossing point of two lines.</p>\n</div>\n<div class="did-you-know">\n  <h3>Where Physics Uses This</h3>\n  <p>Two-equation systems appear whenever two conditions hold at once: two forces balancing in two directions, a mixture problem (total mass <em>and</em> total value), or finding where two moving objects meet — their two distance equations share one time and one place.</p>\n</div>'},{id:"word-problems-to-equations",title:"Turning Words into Equations",content:'\n<p>The hardest part of a word problem is not the algebra — it\'s the <strong>translation</strong>. Physics is one long word problem ("a train leaves the station at 60 km/h…"), so this craft is worth deliberate practice. The procedure:</p>\n<ol>\n  <li><strong>Name the unknown.</strong> Write it down: "let k = number of kilometers."</li>\n  <li><strong>Translate phrases into symbols</strong> using the dictionary below.</li>\n  <li><strong>Write the equation, solve, then check against the story</strong> — does the answer make real-world sense?</li>\n</ol>\n<table>\n  <thead>\n    <tr><th>English</th><th>Algebra</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>"5 more than x"</td><td>x + 5</td></tr>\n    <tr><td>"5 less than x"</td><td>x − 5 &nbsp;<em>(not 5 − x!)</em></td></tr>\n    <tr><td>"triple x" / "3 times x"</td><td>3x</td></tr>\n    <tr><td>"half of x"</td><td>x/2</td></tr>\n    <tr><td>"is", "gives", "totals"</td><td>=</td></tr>\n    <tr><td>"per" (km per hour)</td><td>\xf7 (a rate: km/h)</td></tr>\n  </tbody>\n</table>\n<h3>Worked examples</h3>\n<p><strong>The taxi.</strong> A taxi charges a 3 € flat fee plus 2 € per km. A ride costs 15 €. How far did it go? Let k = kilometers. Equation: 3 + 2k = 15 → 2k = 12 → <strong>k = 6 km</strong>. Check: 3 + 12 = 15 ✓.</p>\n<p><strong>The head start.</strong> You walk at 5 km/h; a friend leaves the same point 1 hour later cycling at 15 km/h. When does she catch you? After she rides t hours, you\'ve walked (t + 1) hours. Same distance when caught: 15t = 5(t + 1) → 15t = 5t + 5 → 10t = 5 → <strong>t = \xbd hour</strong>, at 7.5 km from the start.</p>\n<div class="key-concept">\n  <h3>Key Concept: The Equation Is a Sentence</h3>\n  <p>Every equation you write should read aloud as a true statement about the story: "flat fee plus per-km charge equals the total." If you can\'t say the sentence, the equation isn\'t ready. This habit — words → sentence → symbols — is exactly how physicists set up F = ma problems.</p>\n</div>\n<div class="did-you-know">\n  <h3>The Answer Audits Itself</h3>\n  <p>A negative number of kilometers, a speed of 4000 km/h for a cyclist, a time of −2 s: nonsense answers are gifts. They tell you the translation went wrong before anyone else has to.</p>\n</div>'}],quiz:[{question:"Solve for x: 3x − 7 = 14",options:["x = 3","x = 7","x = 21","x = 7/3"],correctIndex:1,explanation:"Undo in reverse order: add 7 to both sides (3x = 21), then divide by 3 (x = 7). Check: 3 \xd7 7 − 7 = 14 ✓. The wrong answers come from skipping a step or undoing in the wrong order."},{question:"Rearrange v = d/t to make t the subject. Which is correct?",options:["t = v/d","t = vd","t = d/v","t = d − v"],correctIndex:2,explanation:"Multiply both sides by t to get vt = d, then divide both sides by v: t = d/v. Sanity-check with numbers: 150 km at 50 km/h gives t = 150/50 = 3 hours — time is distance divided by speed."},{question:"Solve the inequality: −2x < 10",options:["x > −5","x < −5","x < 5","x > 5"],correctIndex:0,explanation:"Divide both sides by −2, and because you divided by a negative, flip the inequality: x > −5. Test x = 0: −2 \xd7 0 = 0, and 0 < 10 ✓, confirming that 0 (which is > −5) belongs to the solution."},{question:"Solve the system: x + y = 10 and x − y = 4",options:["x = 4, y = 6","x = 5, y = 5","x = 6, y = 4","x = 7, y = 3"],correctIndex:3,explanation:"Add the two equations so y cancels: 2x = 14, so x = 7, and then y = 10 − 7 = 3. Check the second equation: 7 − 3 = 4 ✓. Elimination is fastest when the coefficients already match like this."},{question:"A taxi charges a 3 € flat fee plus 2 € per kilometer, and a ride costs 15 €. Which equation finds the distance k?",options:["2k − 3 = 15","3k + 2 = 15","3 + 2k = 15","2(k + 3) = 15"],correctIndex:2,explanation:"Read the story as a sentence: flat fee (3) plus per-km charge (2k) equals the total (15), so 3 + 2k = 15, giving k = 6 km. Option B swaps the roles of the flat fee and the rate — the classic translation slip."}]},{id:"graphs-and-linear-models",title:"Graphs & Linear Models",subtitle:"The coordinate plane, y = mx + c, and reading physics directly from slopes and areas",sections:[{id:"the-coordinate-plane",title:"A Map for Numbers",content:'\n<p>The coordinate plane is a machine for turning number pairs into pictures. Two number lines cross at the <strong>origin</strong> (0, 0): the horizontal <strong>x-axis</strong> and the vertical <strong>y-axis</strong>. Any point in the plane gets an address (x, y): how far right, then how far up. The point (3, 2) sits 3 to the right and 2 up; (−2, 4) sits 2 to the <em>left</em> and 4 up; (0, −3) sits on the y-axis, 3 below the origin.</p>\n<p><strong>Order matters</strong>: (3, 2) and (2, 3) are different points, just as "3rd Avenue, 2nd Street" and "2nd Avenue, 3rd Street" are different corners. The axes divide the plane into four quadrants, but in physics you\'ll usually live in the first one (both positive) — time and distance are rarely negative.</p>\n<h3>Plotting a relationship</h3>\n<p>The real power move: plot an <em>equation</em>. Take y = 2x + 1 and build a table:</p>\n<table>\n  <thead><tr><th>x</th><th>0</th><th>1</th><th>2</th><th>3</th></tr></thead>\n  <tbody><tr><td><strong>y</strong></td><td>1</td><td>3</td><td>5</td><td>7</td></tr></tbody>\n</table>\n<p>Plot (0, 1), (1, 3), (2, 5), (3, 7) — they line up perfectly. Every equation draws a picture, and every picture encodes an equation. This two-way translation is the heart of the chapter.</p>\n<div class="analogy">\n  <h3>Analogy: The Chessboard and the GPS</h3>\n  <p>A chess move like "e4" and a GPS reading like "48.85\xb0 N, 2.35\xb0 E" both use Descartes\' idea: two numbers pin down one location. In physics, the axes usually aren\'t places at all — the x-axis might be <em>time</em> and the y-axis <em>distance</em>, so a point means "at 3 seconds, the cart was 7 meters along." A moving object becomes a curve you can look at.</p>\n</div>\n<div class="did-you-know">\n  <h3>Legend Has It…</h3>\n  <p>Ren\xe9 Descartes supposedly dreamed up coordinates while watching a fly on his bedroom ceiling, realizing he could describe its position with two numbers: distance from each wall. True or not, the idea fused algebra and geometry — and made all of graphical physics possible.</p>\n</div>'},{id:"slope",title:"Slope: The Rate of Climb",content:'\n<p>Slope measures how steeply a line climbs. The definition is a ratio: <strong>slope = rise \xf7 run</strong> — how much the line goes <em>up</em> for each step it goes <em>across</em>. Between two points (x₁, y₁) and (x₂, y₂):</p>\n<p style="text-align:center"><strong>m = (y₂ − y₁) \xf7 (x₂ − x₁)</strong></p>\n<h3>Worked examples</h3>\n<ol>\n  <li>Through (2, 3) and (6, 11): rise = 11 − 3 = 8, run = 6 − 2 = 4, so m = 8 \xf7 4 = <strong>2</strong>. The line climbs 2 units for every 1 across.</li>\n  <li>Through (0, 5) and (10, 5): rise = 0, so m = <strong>0</strong>. A flat line — no climb at all.</li>\n  <li>Through (1, 8) and (3, 2): rise = 2 − 8 = −6, run = 2, so m = <strong>−3</strong>. Negative slope means the line falls as you move right.</li>\n</ol>\n<p>Subtract in the same order top and bottom — if you start from the second point in the numerator, start from it in the denominator too, and the sign comes out right automatically.</p>\n<h3>Slope is a rate</h3>\n<p>Here\'s the physics payoff hiding in plain sight. If the x-axis is time in hours and the y-axis is distance in km, then rise \xf7 run is <strong>km \xf7 hours</strong> — a speed. Slope always inherits the units "y-units per x-unit": euros per km on a taxi-fare graph, liters per minute on a filling-tank graph, meters per second on a motion graph. Steep line, fast change; shallow line, slow change.</p>\n<div class="key-concept">\n  <h3>Key Concept: A Straight Line Means a Constant Rate</h3>\n  <p>The defining feature of a line is that its slope is the same everywhere — every step across gains the same rise. Constant slope = constant rate. The moment a graph curves, the rate is changing — which, on a distance–time graph, is the visual signature of acceleration.</p>\n</div>\n<div class="did-you-know">\n  <h3>Slope on the Road</h3>\n  <p>A road sign reading "8% grade" is a slope: 8 m of rise per 100 m of run, m = 0.08. Ski runs, wheelchair-ramp regulations (typically at most 1:12 ≈ 8.3%), and roof pitches are all slopes hiding in everyday clothes.</p>\n</div>'},{id:"y-equals-mx-plus-c",title:"y = mx + c: Every Line in One Formula",content:'\n<p>Every non-vertical straight line can be written as <strong>y = mx + c</strong>, and the two constants each have a job:</p>\n<ul>\n  <li><strong>m is the slope</strong> — the rate of climb you just mastered.</li>\n  <li><strong>c is the y-intercept</strong> — the value of y when x = 0, where the line crosses the y-axis. (Check: set x = 0 and y = m \xd7 0 + c = c.)</li>\n</ul>\n<p>So y = 2x + 1 is a line of slope 2 crossing the y-axis at 1. And y = −\xbdx + 4 falls gently (half a unit down per unit across) from a starting height of 4.</p>\n<h3>From data to equation</h3>\n<p>The taxi from last chapter charges 3 € flat plus 2 € per km. Fare F for k kilometers: <strong>F = 2k + 3</strong> — it\'s y = mx + c with m = 2 (rate per km) and c = 3 (the cost of just sitting down). A phone plan of 10 € plus 0.05 € per minute: C = 0.05t + 10. Any "starting amount plus steady rate" story is a straight line, and you can now write its equation on sight.</p>\n<h3>From equation to line, in seconds</h3>\n<ol>\n  <li>Put a dot at c on the y-axis.</li>\n  <li>From there use the slope: for m = 2, go right 1, up 2; repeat.</li>\n  <li>Join the dots with a ruler. Done.</li>\n</ol>\n<p>Going the other way — from a plotted line to its equation — read c where it crosses the axis, then measure rise over run between two clean grid points to get m.</p>\n<div class="key-concept">\n  <h3>Key Concept: Two Numbers Tell the Whole Story</h3>\n  <p>Once you know a relationship is linear, m and c say everything: c is where you start, m is how fast things change. In physics experiments this is the standard trick — plot the data, fit a line, and the slope and intercept <em>are</em> the measurement. The equation v = u + at is literally y = mx + c: start at velocity u, gain a m/s each second; slope = acceleration, intercept = initial velocity.</p>\n</div>'},{id:"proportionality",title:"Proportionality: Straight Through the Origin",content:"\n<p>The simplest relationship in science: <strong>y is directly proportional to x</strong>, written y ∝ x. It means doubling x doubles y, tripling x triples y — the ratio y/x never changes. As an equation, <strong>y = kx</strong>, where k is the <em>constant of proportionality</em>. That's y = mx + c with c = 0, so the graph is a straight line <strong>through the origin</strong>: zero in, zero out.</p>\n<h3>Spotting proportionality</h3>\n<table>\n  <thead>\n    <tr><th>Relationship</th><th>Proportional?</th><th>Why</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Distance at steady speed: d = 60t</td><td>Yes</td><td>Twice the time, twice the distance; d/t is always 60</td></tr>\n    <tr><td>Taxi fare: F = 2k + 3</td><td>No</td><td>Flat fee means doubling km does not double the fare</td></tr>\n    <tr><td>Mass of water: m = 1000 V</td><td>Yes</td><td>Twice the volume, twice the mass; k is the density</td></tr>\n  </tbody>\n</table>\n<p>Numerical test: (2, 5) and (4, 10) and (6, 15) — each y/x = 2.5, so proportional with k = 2.5. But (1, 4) and (2, 6)? Ratios 4 and 3 — a line perhaps, but not through the origin, so not proportional.</p>\n<h3>Why physicists worship this line</h3>\n<p>An enormous amount of physics says \"this ∝ that\": stretch of a spring ∝ force (Hooke's law), current ∝ voltage (Ohm's law), weight ∝ mass, mass ∝ volume for one material. In each case the constant k <em>is the physics</em> — spring stiffness, 1/resistance, gravitational field strength g ≈ 9.8 N/kg, density. Plot data, get a line through the origin, measure its slope: you've measured a property of nature.</p>\n<div class=\"key-concept\">\n  <h3>Key Concept: The Origin Is the Test</h3>\n  <p>Both features are required: straight <em>and</em> through (0, 0). A straight line missing the origin is linear but not proportional — doubling x won't double y. When a lab result \"should\" be proportional but the fitted line misses the origin, the intercept often reveals a systematic error, like a scale that wasn't zeroed.</p>\n</div>"},{id:"reading-physics-from-graphs",title:"Reading Physics from Graphs: Slope = Speed, Area = Distance",content:'\n<p>This is the signature skill the motion chapters ahead depend on. A graph of an object\'s motion isn\'t decoration — it\'s an instrument you read, and the two dials are <strong>slope</strong> and <strong>area</strong>.</p>\n<h3>Distance–time graphs: slope is speed</h3>\n<p>Plot distance (m) against time (s). Slope = rise/run = meters per second = <strong>speed</strong>.</p>\n<ul>\n  <li>Steep straight line: fast, steady motion.</li>\n  <li>Shallow line: slow motion. A line rising 30 m over 5 s means 30 \xf7 5 = <strong>6 m/s</strong>.</li>\n  <li>Horizontal line: slope 0 — <strong>stopped</strong> (time passes, distance doesn\'t).</li>\n  <li>Curving ever steeper: speeding up — the slope, hence the speed, is growing.</li>\n</ul>\n<h3>Velocity–time graphs: area is distance</h3>\n<p>Now plot velocity (m/s) against time (s). Travel at 4 m/s for 10 s and you cover 4 \xd7 10 = 40 m — but look: on the graph that product is a rectangle, height 4 and width 10. <strong>The area under a velocity–time graph is the distance traveled.</strong> It works for any shape:</p>\n<ul>\n  <li>Constant 4 m/s for 10 s: rectangle, area 4 \xd7 10 = <strong>40 m</strong>.</li>\n  <li>Speeding up steadily from 0 to 10 m/s over 6 s: triangle, area \xbd \xd7 6 \xd7 10 = <strong>30 m</strong>.</li>\n  <li>Complicated trip: cut the region into rectangles and triangles, add the pieces.</li>\n</ul>\n<p>And the slope of a velocity–time graph? Rise/run = (m/s)/s = m/s\xb2 — that\'s <strong>acceleration</strong>. Same graph, two readings.</p>\n<div class="key-concept">\n  <h3>Key Concept: One Picture, Whole Story</h3>\n  <p>A single v–t graph tells you the velocity at every instant (read the height), the acceleration (read the slope), and the total distance (read the area). Three physical quantities from one picture — this is why physicists sketch a graph before touching a formula.</p>\n</div>\n<div class="did-you-know">\n  <h3>You\'re Previewing Calculus</h3>\n  <p>"Slope of the graph" and "area under the graph" are the two central ideas of calculus — derivatives and integrals — wearing everyday clothes. Master them here on straight lines and you\'ve already understood, in pictures, what Newton and Leibniz formalized.</p>\n</div>'}],quiz:[{question:"What is the slope of the line through (2, 3) and (6, 11)?",options:["8","4","2","\xbd"],correctIndex:2,explanation:"Slope = rise \xf7 run = (11 − 3) \xf7 (6 − 2) = 8 \xf7 4 = 2: the line climbs 2 units for every 1 unit across. Answer \xbd comes from dividing run by rise — always put the change in y on top."},{question:"In y = mx + c, what does c tell you?",options:["Where the line crosses the y-axis","How steep the line is","Where the line crosses the x-axis","The area under the line"],correctIndex:0,explanation:"Set x = 0 and y = c: the line passes through (0, c), its crossing point on the y-axis. In a real-world model, c is the starting value — like a taxi's flat fee before any kilometers tick by. Steepness is m's job."},{question:"A distance–time graph is a straight line that rises 30 m over 5 s. What is the object's speed?",options:["150 m/s","35 m/s","25 m/s","6 m/s"],correctIndex:3,explanation:"Speed is the slope of a distance–time graph: rise \xf7 run = 30 m \xf7 5 s = 6 m/s. Multiplying (150) or adding (35) mixes up the operations — slope is always a division, giving y-units per x-unit."},{question:"Which equation graphs as a straight line through the origin — a direct proportionality?",options:["y = 3x + 2","y = 3x","y = x\xb2","y = 3 \xf7 x"],correctIndex:1,explanation:"y = 3x is y = kx: zero in, zero out, and doubling x doubles y. Adding +2 lifts the line off the origin, x\xb2 curves into a parabola, and 3 \xf7 x is an inverse relationship that never touches either axis."},{question:"A velocity–time graph shows a constant 4 m/s for 10 s. What distance was covered?",options:["14 m","4 m","40 m","400 m"],correctIndex:2,explanation:"Distance is the area under a velocity–time graph: a rectangle of height 4 m/s and width 10 s, area 4 \xd7 10 = 40 m. This area rule works for any shape — slice curvy regions into rectangles and triangles and add."}]},{id:"quadratics",title:"Quadratics",subtitle:"Factoring, completing the square, the quadratic formula, and the parabola",sections:[{id:"solving-by-factoring",title:"Factoring and the Zero-Product Rule",content:"\n<p>A <strong>quadratic</strong> equation contains an x\xb2 and nothing higher: ax\xb2 + bx + c = 0. The square changes the game — quadratics typically have <strong>two</strong> solutions, not one. That's not a nuisance; it's physics being honest. Throw a ball up to a height of 15 m and it's at that height <em>twice</em>: once rising, once falling. The algebra knows.</p>\n<h3>The zero-product rule</h3>\n<p>The key that unlocks everything: <strong>if two things multiply to zero, at least one of them is zero</strong>. Nothing else has this property — a product of 12 could be 3 \xd7 4 or 2 \xd7 6, but a product of 0 forces a factor to be 0. So if we can write a quadratic as (something)(something) = 0, each factor gives a solution.</p>\n<h3>Worked example</h3>\n<p>Solve x\xb2 − 5x + 6 = 0.</p>\n<ol>\n  <li>Hunt two numbers that <strong>multiply to +6</strong> and <strong>add to −5</strong>: they're −2 and −3.</li>\n  <li>Factor: (x − 2)(x − 3) = 0.</li>\n  <li>Zero-product rule: x − 2 = 0 or x − 3 = 0, so <strong>x = 2 or x = 3</strong>.</li>\n  <li>Check x = 2: 4 − 10 + 6 = 0 ✓.</li>\n</ol>\n<h3>More reps</h3>\n<ul>\n  <li>x\xb2 + 7x + 10 = 0 → numbers: +2, +5 → (x + 2)(x + 5) = 0 → x = −2 or x = −5</li>\n  <li>x\xb2 − x − 12 = 0 → numbers: −4, +3 → (x − 4)(x + 3) = 0 → x = 4 or x = −3</li>\n  <li>x\xb2 − 9 = 0 → (x − 3)(x + 3) = 0 → x = \xb13 &nbsp;<em>(difference of squares)</em></li>\n  <li>x\xb2 + 4x = 0 → x(x + 4) = 0 → x = 0 or x = −4 &nbsp;<em>(don't divide by x — you'd throw away the x = 0 solution!)</em></li>\n</ul>\n<div class=\"key-concept\">\n  <h3>Key Concept: Get Zero on One Side First</h3>\n  <p>The zero-product rule only works against zero. To solve x\xb2 = 5x − 6, first move everything left: x\xb2 − 5x + 6 = 0, <em>then</em> factor. Factoring against \"= 12\" tells you nothing.</p>\n</div>"},{id:"completing-the-square",title:"Completing the Square",content:"\n<p>Plenty of quadratics refuse to factor nicely — try finding whole numbers that multiply to 3 and add to 6 for x\xb2 + 6x + 3 = 0. <strong>Completing the square</strong> handles every case, by rebuilding the quadratic around a perfect square.</p>\n<h3>The core observation</h3>\n<p>(x + 3)\xb2 = x\xb2 + 6x + 9. So x\xb2 + 6x is <em>almost</em> a perfect square — it's just missing the 9. The recipe: take half the x-coefficient (half of 6 is 3), square it (9), and that's the missing piece. In general, x\xb2 + bx needs (b/2)\xb2 to complete the square.</p>\n<h3>Worked example</h3>\n<p>Solve x\xb2 + 6x + 3 = 0.</p>\n<ol>\n  <li>Move the lone number over: x\xb2 + 6x = −3</li>\n  <li>Add (6/2)\xb2 = 9 to <strong>both</strong> sides: x\xb2 + 6x + 9 = 6</li>\n  <li>The left side is now a perfect square: (x + 3)\xb2 = 6</li>\n  <li>Square root both sides — remembering both signs: x + 3 = \xb1√6</li>\n  <li>So <strong>x = −3 + √6 ≈ −0.55</strong> or <strong>x = −3 − √6 ≈ −5.45</strong></li>\n</ol>\n<p>One more: x\xb2 − 4x − 1 = 0 → x\xb2 − 4x = 1 → add (−4/2)\xb2 = 4 → (x − 2)\xb2 = 5 → x = 2 \xb1 √5.</p>\n<div class=\"key-concept\">\n  <h3>Key Concept: Why \xb1 Appears</h3>\n  <p>Squaring destroys sign information: both 2\xb2 and (−2)\xb2 equal 4. So when you undo a square, both candidates must come back — (x + 3)\xb2 = 6 means x + 3 could be √6 <em>or</em> −√6. That \xb1 is exactly where a quadratic's two solutions come from.</p>\n</div>\n<div class=\"did-you-know\">\n  <h3>The Vertex for Free</h3>\n  <p>Completing the square rewrites y = x\xb2 + 6x + 3 as y = (x + 3)\xb2 − 6, and that form is a treasure map: since (x + 3)\xb2 is never negative, y bottoms out when x = −3, at y = −6. Maximum heights, minimum costs, peak ranges — completing the square finds the extremes of any quadratic, which is why physics keeps it in the toolbox. It's also, step for step, how the quadratic formula is derived.</p>\n</div>"},{id:"the-quadratic-formula",title:"The Quadratic Formula",content:'\n<p>Run completing-the-square on the fully general quadratic ax\xb2 + bx + c = 0 and out comes a formula that solves <strong>every quadratic that will ever exist</strong>:</p>\n<p style="text-align:center"><strong>x = (−b \xb1 √(b\xb2 − 4ac)) \xf7 (2a)</strong></p>\n<p>Identify a, b, c (with their signs!), substitute, simplify. No cleverness required — this is the power tool you reach for when factoring doesn\'t leap out.</p>\n<h3>Worked example</h3>\n<p>Solve x\xb2 + 2x − 8 = 0. Here a = 1, b = 2, c = −8.</p>\n<ol>\n  <li>Discriminant first: b\xb2 − 4ac = 2\xb2 − 4 \xd7 1 \xd7 (−8) = 4 + 32 = 36</li>\n  <li>√36 = 6</li>\n  <li>x = (−2 \xb1 6) \xf7 2</li>\n  <li>Two answers: x = 4/2 = <strong>2</strong> and x = −8/2 = <strong>−4</strong></li>\n  <li>Check x = 2: 4 + 4 − 8 = 0 ✓</li>\n</ol>\n<p>One with a ≠ 1: solve 2x\xb2 − 5x + 2 = 0. Discriminant: 25 − 16 = 9, √9 = 3, x = (5 \xb1 3)/4 → x = 2 or x = \xbd.</p>\n<h3>The discriminant: a solution forecast</h3>\n<p>The quantity under the root, <strong>b\xb2 − 4ac</strong>, predicts what you\'ll get before you finish:</p>\n<table>\n  <thead><tr><th>b\xb2 − 4ac</th><th>Solutions</th><th>Picture</th></tr></thead>\n  <tbody>\n    <tr><td>Positive</td><td>Two real solutions</td><td>Parabola crosses the x-axis twice</td></tr>\n    <tr><td>Zero</td><td>Exactly one solution</td><td>Parabola just touches the axis</td></tr>\n    <tr><td>Negative</td><td>No real solutions</td><td>Parabola never reaches the axis</td></tr>\n  </tbody>\n</table>\n<div class="key-concept">\n  <h3>Key Concept: "No Real Solutions" Is an Answer</h3>\n  <p>Ask when a ball thrown at 10 m/s reaches 20 m of height and the discriminant goes negative: the algebra is telling you <em>it never gets that high</em>. A negative discriminant in a physics problem isn\'t failure — it\'s the math reporting that the event doesn\'t happen.</p>\n</div>\n<div class="did-you-know">\n  <h3>An Old Friend</h3>\n  <p>Versions of this formula were known to Babylonian scribes solving land-area problems 4000 years ago — a thousand years before algebra had symbols. You are memorizing one of humanity\'s oldest power tools.</p>\n</div>'},{id:"parabolas",title:"The Parabola: Nature's Favorite Curve",content:'\n<p>Graph any quadratic y = ax\xb2 + bx + c and you get a <strong>parabola</strong> — a symmetric U-shaped curve. Everything about its shape is readable from the equation:</p>\n<ul>\n  <li><strong>a positive:</strong> opens upward (a smile); <strong>a negative:</strong> opens downward (a frown).</li>\n  <li><strong>Bigger |a|:</strong> narrower curve; smaller |a|: wider.</li>\n  <li><strong>The vertex</strong> is the turning point — the minimum (smile) or maximum (frown).</li>\n  <li><strong>The axis of symmetry</strong> is the vertical mirror line x = −b/(2a) through the vertex.</li>\n</ul>\n<p>Vertex form makes the geometry explicit: y = (x − 3)\xb2 + 2 is a parabola whose vertex sits at <strong>(3, 2)</strong> — the square term is zero at x = 3 and positive everywhere else, so that\'s the low point. This is completing the square, now read as geometry.</p>\n<h3>The physics: why thrown things trace parabolas</h3>\n<p>Launch a ball and its height obeys h = v₀t − \xbdgt\xb2 — a quadratic in time, with the −\xbdgt\xb2 (g ≈ 9.8 m/s\xb2) supplying the frown. Concretely, h = 20t − 5t\xb2:</p>\n<ul>\n  <li><strong>When does it land?</strong> Set h = 0: 5t(4 − t) = 0 → t = 0 (launch) or <strong>t = 4 s</strong> (landing). Factoring!</li>\n  <li><strong>How high does it get?</strong> By symmetry the peak is midway, at t = 2 s: h = 40 − 20 = <strong>20 m</strong>.</li>\n  <li><strong>When is it at 15 m?</strong> 20t − 5t\xb2 = 15 → t\xb2 − 4t + 3 = 0 → (t − 1)(t − 3) = 0 → at t = 1 s going up and t = 3 s coming down. Two solutions, both real.</li>\n</ul>\n<div class="key-concept">\n  <h3>Key Concept: Symmetry Is Free Information</h3>\n  <p>A parabola\'s two x-crossings sit symmetrically around the vertex, so the peak is always at their midpoint. Up-time equals down-time; launch speed equals landing speed. Before computing anything, symmetry hands you half the answers.</p>\n</div>\n<div class="did-you-know">\n  <h3>Parabolas That Focus</h3>\n  <p>A parabolic mirror reflects all incoming parallel rays to a single focus — which is why satellite dishes, telescope mirrors, and car headlights are parabolic. Same curve, entirely different physics: geometry this useful gets reused everywhere.</p>\n</div>'}],quiz:[{question:"What are the solutions of x\xb2 − 5x + 6 = 0?",options:["x = −2 and x = −3","x = 2 and x = 3","x = 1 and x = 6","x = −1 and x = −6"],correctIndex:1,explanation:"Find two numbers multiplying to +6 and adding to −5: they are −2 and −3, so (x − 2)(x − 3) = 0, giving x = 2 or x = 3. Note the sign flip: factors (x − 2)(x − 3) give positive solutions. Check: 4 − 10 + 6 = 0 ✓."},{question:"If (x − 4)(x + 2) = 0, what does the zero-product rule tell you?",options:["x must equal −4 or 2","x must equal 8","x must equal 4 and −2 at the same time","x = 4 or x = −2"],correctIndex:3,explanation:'A product is zero only when a factor is zero: either x − 4 = 0 (so x = 4) or x + 2 = 0 (so x = −2). Each factor yields one solution, and "or" is the right word — the equation is satisfied by either value separately.'},{question:"For a quadratic ax\xb2 + bx + c = 0, the discriminant b\xb2 − 4ac comes out negative. What does that mean?",options:["The parabola never crosses the x-axis — no real solutions","There are two real solutions","The parabola opens downward","The equation was copied wrong — discriminants can't be negative"],correctIndex:0,explanation:'A negative discriminant means the square root has no real value: the parabola never reaches the x-axis, so there are no real solutions. In physics this is a meaningful answer — ask when a ball reaches a height it can\'t attain, and this is how the math says "never."'},{question:"What is the vertex of the parabola y = (x − 3)\xb2 + 2?",options:["(−3, 2)","(3, −2)","(3, 2)","(2, 3)"],correctIndex:2,explanation:"The squared term (x − 3)\xb2 is zero at x = 3 and positive everywhere else, so y bottoms out at y = 2 when x = 3: vertex (3, 2). Watch the sign: (x − 3)\xb2 puts the vertex at +3, not −3 — that flip trips everyone once."},{question:"A ball's height follows h = 20t − 5t\xb2 (meters, seconds). When does it return to the ground?",options:["t = 2 s","t = 4 s","t = 5 s","t = 20 s"],correctIndex:1,explanation:"Set h = 0 and factor: 5t(4 − t) = 0, so t = 0 (the launch) or t = 4 s (the landing). By symmetry the peak is midway at t = 2 s — that's when it's highest, not when it lands."}]},{id:"geometry-essentials",title:"Geometry Essentials",subtitle:"Triangles, Pythagoras, circles, areas and volumes — spatial fluency without proof drills",sections:[{id:"angles-and-triangles",title:"Angle Facts You Actually Use",content:'\n<p>Physics lives in space, and space is described with angles. You don\'t need two years of proof drills — you need a small kit of facts, held firmly enough to use without thinking.</p>\n<h3>The kit</h3>\n<ul>\n  <li><strong>Full turn:</strong> 360\xb0. <strong>Straight line:</strong> 180\xb0. <strong>Right angle:</strong> 90\xb0.</li>\n  <li><strong>Angles on a straight line add to 180\xb0:</strong> if one is 110\xb0, its neighbor is 70\xb0.</li>\n  <li><strong>Vertically opposite angles are equal:</strong> two crossing lines make an X — opposite angles match.</li>\n  <li><strong>Parallel lines cut by a slanted line:</strong> the slanted line makes the same angle with both parallels (those matching "F-pattern" angles, and the equal "Z-pattern" angles between the lines). This is why a light ray keeps its angle when crossing between parallel surfaces.</li>\n  <li><strong>The angles of any triangle add to 180\xb0.</strong> The workhorse of the whole chapter.</li>\n</ul>\n<h3>Worked examples</h3>\n<ol>\n  <li>A triangle has angles 90\xb0 and 35\xb0. Third angle: 180 − 90 − 35 = <strong>55\xb0</strong>.</li>\n  <li>An isosceles triangle (two equal sides, hence two equal base angles) has a top angle of 40\xb0. Each base angle: (180 − 40) \xf7 2 = <strong>70\xb0</strong>.</li>\n  <li>A ramp meets the ground at 15\xb0. The angle between ramp and a vertical wall at its top: the triangle has 90\xb0 and 15\xb0, so 180 − 90 − 15 = <strong>75\xb0</strong>.</li>\n</ol>\n<h3>Naming triangles</h3>\n<p><strong>Equilateral:</strong> all sides equal, all angles 60\xb0. <strong>Isosceles:</strong> two sides equal, base angles equal. <strong>Scalene:</strong> all different. <strong>Right triangle:</strong> one 90\xb0 angle — the star of physics, because perpendicular directions (horizontal/vertical, east/north) appear everywhere, and the side opposite the right angle, the <strong>hypotenuse</strong>, gets its own theorem next section.</p>\n<div class="key-concept">\n  <h3>Key Concept: Two Angles Are Really Three</h3>\n  <p>Because the sum is locked at 180\xb0, knowing two angles of a triangle means you know all three — no measuring required. Physics uses this constantly: find one angle in a force diagram or a light-ray sketch and the rest cascade out for free.</p>\n</div>\n<div class="did-you-know">\n  <h3>Why 360?</h3>\n  <p>The 360\xb0 circle is a Babylonian inheritance — they counted in base 60, and 360 divides beautifully (by 2, 3, 4, 5, 6, 8, 9, 10, 12…). Later you\'ll meet the radian, the "natural" angle unit physics prefers for waves and rotation.</p>\n</div>'},{id:"similar-triangles",title:"Congruence & Similarity: Same Shape, Different Size",content:"\n<p>Two triangles are <strong>congruent</strong> if they're identical — same angles <em>and</em> same sides, one traceable onto the other. They're <strong>similar</strong> if they have the same angles but different sizes: one is a photo-enlargement of the other. Similarity is the one you'll use constantly, because it comes with a superpower: <strong>in similar triangles, corresponding sides are all scaled by the same factor</strong>.</p>\n<h3>The shadow trick</h3>\n<p>Classic problem, beloved since ancient Greece: find a tree's height without climbing it. A 1.8 m person casts a 1.2 m shadow; at the same moment the tree casts an 8 m shadow. The sun's rays arrive at the same angle for both, and both stand at 90\xb0 to the ground — same angles, so the two triangles (object, shadow, sun-ray) are similar.</p>\n<ol>\n  <li>Scale factor from person's shadow to tree's shadow: 8 \xf7 1.2 = 6.67</li>\n  <li>Tree height = 1.8 \xd7 6.67 = <strong>12 m</strong></li>\n  <li>Equivalent ratio form: height \xf7 shadow is equal for both: 1.8/1.2 = h/8 → h = 8 \xd7 1.5 = 12 m ✓</li>\n</ol>\n<p>Legend says Thales measured the Great Pyramid exactly this way around 600 BCE — waiting for the moment his own shadow equaled his height, so the pyramid's shadow equaled <em>its</em> height.</p>\n<h3>More scaling reps</h3>\n<ul>\n  <li>A 4 cm \xd7 6 cm photo enlarged so the short side is 10 cm: scale factor 2.5, long side 15 cm.</li>\n  <li>On a 1 : 50 000 map, 3 cm of trail = 3 \xd7 50 000 cm = <strong>1.5 km</strong> of real trail.</li>\n  <li>Triangles with sides 3, 4, 5 and 6, 8, 10: each side doubled — similar, same angles.</li>\n</ul>\n<div class=\"key-concept\">\n  <h3>Key Concept: Equal Angles → Proportional Sides</h3>\n  <p>That one implication does all the work. Spot two triangles sharing angles, and you may immediately write side ratios as equations. This is the geometry behind map scales, camera pinhole images, and — crucially for the optics chapters ahead — how lenses form magnified or shrunken images: image size \xf7 object size is a ratio of similar triangles.</p>\n</div>\n<div class=\"did-you-know\">\n  <h3>Similarity Runs Physics Labs</h3>\n  <p>Wind-tunnel models work because a 1:20 model airplane in suitably chosen airflow is \"similar\" to the real thing — the shape of the flow scales like the shape of the craft. Scaling arguments are a professional physicist's daily bread.</p>\n</div>"},{id:"pythagoras",title:"Pythagoras: The Most Useful Theorem in Physics",content:'\n<p>In any right triangle with legs a and b and hypotenuse c (the side facing the right angle):</p>\n<p style="text-align:center"><strong>a\xb2 + b\xb2 = c\xb2</strong></p>\n<p>That\'s it — and it may be the single most-used piece of geometry in all of physics.</p>\n<h3>Worked examples</h3>\n<ol>\n  <li><strong>Find the hypotenuse.</strong> Legs 3 and 4: c\xb2 = 9 + 16 = 25 → c = √25 = <strong>5</strong>. (The famous 3–4–5 triangle; builders still use it to check corners are square.)</li>\n  <li><strong>Walk east, then north.</strong> 6 km east then 8 km north: displacement\xb2 = 36 + 64 = 100 → <strong>10 km</strong> from the start, even though your legs logged 14 km.</li>\n  <li><strong>Find a leg.</strong> Ladder 5 m long, foot 1.4 m from the wall: height\xb2 = 25 − 1.96 = 23.04 → height = √23.04 = <strong>4.8 m</strong>. Rearranged form: a\xb2 = c\xb2 − b\xb2 — the hypotenuse is always the biggest, so subtract to find a leg.</li>\n  <li><strong>Diagonal of a screen.</strong> A 16 \xd7 9 panel scaled to 111 cm \xd7 62 cm: diagonal ≈ √(111\xb2 + 62\xb2) ≈ √16 165 ≈ <strong>127 cm</strong> — a "50-inch" TV.</li>\n</ol>\n<h3>Why physics can\'t live without it</h3>\n<p>Physics constantly splits quantities into <strong>perpendicular components</strong> — horizontal and vertical, east and north — and then needs the combined size back. A plane flying 200 km/h east in a 50 km/h north crosswind moves at √(200\xb2 + 50\xb2) ≈ 206 km/h. Two perpendicular forces of 30 N and 40 N combine into a 50 N resultant. Every "combine perpendicular pieces" problem <em>is</em> Pythagoras.</p>\n<div class="key-concept">\n  <h3>Key Concept: Hypotenuse = Combined Effect</h3>\n  <p>Whenever two contributions act at right angles — displacements, velocities, forces, even AC voltages later on — the total is the hypotenuse: total = √(a\xb2 + b\xb2). File this as one move; you will use it hundreds of times in Phase 2 and beyond.</p>\n</div>\n<div class="did-you-know">\n  <h3>Older Than Pythagoras</h3>\n  <p>Babylonian clay tablet Plimpton 322, a thousand years before Pythagoras, lists whole-number triples like 3–4–5 and 5–12–13. He (or his school) likely earned naming rights with a general proof — of which over 350 now exist, including one by U.S. President James Garfield.</p>\n</div>'},{id:"circles",title:"Circles: π and the Two Formulas",content:"\n<p>A circle is all points at one fixed distance — the <strong>radius r</strong> — from a center. The <strong>diameter</strong> d = 2r spans the circle through the center. And hiding inside every circle, from coins to planetary orbits, is the same number: divide any circle's circumference by its diameter and you get <strong>π ≈ 3.14159…</strong>, the most famous constant in mathematics.</p>\n<h3>The two formulas</h3>\n<ul>\n  <li><strong>Circumference</strong> (distance around): C = πd = 2πr</li>\n  <li><strong>Area</strong> (space inside): A = πr\xb2</li>\n</ul>\n<p>Keep them straight by units: circumference is a length (one factor of r); area is a length squared (r\xb2).</p>\n<h3>Worked examples</h3>\n<ol>\n  <li>Bike wheel, radius 34 cm. One revolution rolls the bike forward one circumference: C = 2π \xd7 34 ≈ <strong>214 cm ≈ 2.1 m</strong>. Over 1 km, that's 1000 \xf7 2.14 ≈ 468 wheel turns — exactly how a bike computer measures distance.</li>\n  <li>Circle of radius 5 cm: C = 2π \xd7 5 ≈ 31.4 cm; A = π \xd7 25 ≈ <strong>78.5 cm\xb2</strong>.</li>\n  <li>Pizza logic: a 30 cm pizza vs two 20 cm pizzas. Areas: π \xd7 15\xb2 ≈ 707 cm\xb2 vs 2 \xd7 π \xd7 10\xb2 ≈ 628 cm\xb2. The single large pizza wins — area grows with the <em>square</em> of the radius.</li>\n</ol>\n<p>That last example is a scaling law worth internalizing: double a circle's radius and its circumference doubles, but its <strong>area quadruples</strong>.</p>\n<div class=\"key-concept\">\n  <h3>Key Concept: r\xb2 Scaling Shows Up Everywhere</h3>\n  <p>A pipe twice as wide carries about four times the flow (cross-section area is πr\xb2). A dish antenna twice as wide gathers four times the signal. And light spreading from a bulb dilutes over spheres of area 4πr\xb2 — the origin of the inverse-square laws you'll meet for light and gravity.</p>\n</div>\n<div class=\"did-you-know\">\n  <h3>π Is Everywhere, Suspiciously</h3>\n  <p>π escapes circles entirely: it appears in the swing time of a pendulum, T = 2π√(L/g), in the statistics bell curve, and in Euler's identity e<sup>iπ</sup> + 1 = 0. When circles and rotations underlie a phenomenon — as with waves and oscillations — π tags along. For calculations, π ≈ 3.14 or the ratio 22/7 is nearly always accurate enough.</p>\n</div>"},{id:"areas-and-volumes",title:"Areas & Volumes: The Formulas Physics Uses Daily",content:'\n<p>Area measures surface (m\xb2, cm\xb2); volume measures space (m\xb3, cm\xb3, liters). Physics needs both constantly — pressure divides by an area, density divides by a volume — so this toolkit must be at your fingertips.</p>\n<h3>The reference card</h3>\n<table>\n  <thead><tr><th>Shape</th><th>Area</th></tr></thead>\n  <tbody>\n    <tr><td>Rectangle</td><td>length \xd7 width</td></tr>\n    <tr><td>Triangle</td><td>\xbd \xd7 base \xd7 height</td></tr>\n    <tr><td>Parallelogram</td><td>base \xd7 height</td></tr>\n    <tr><td>Circle</td><td>πr\xb2</td></tr>\n  </tbody>\n</table>\n<table>\n  <thead><tr><th>Solid</th><th>Volume</th></tr></thead>\n  <tbody>\n    <tr><td>Box</td><td>length \xd7 width \xd7 height</td></tr>\n    <tr><td>Cylinder</td><td>πr\xb2 \xd7 height</td></tr>\n    <tr><td>Sphere</td><td>(4/3)πr\xb3</td></tr>\n    <tr><td>Cone or pyramid</td><td>⅓ \xd7 base area \xd7 height</td></tr>\n  </tbody>\n</table>\n<p>Notice the pattern: box and cylinder are both "base area \xd7 height" — a stack of identical slices. The triangle\'s \xbd (half a rectangle) and the cone\'s ⅓ (a third of its cylinder) are the only fractions to memorize.</p>\n<h3>Worked examples</h3>\n<ol>\n  <li>Box 2 cm \xd7 3 cm \xd7 4 cm: V = <strong>24 cm\xb3</strong>. If it has mass 48 g, its density is ρ = m/V = 48 \xf7 24 = <strong>2 g/cm\xb3</strong> — it will sink in water (density 1 g/cm\xb3). Volume feeds straight into the physics.</li>\n  <li>Cylindrical glass, r = 4 cm, height 12 cm: V = π \xd7 16 \xd7 12 ≈ <strong>603 cm\xb3 ≈ 0.6 liters</strong> (1 liter = 1000 cm\xb3; 1 cm\xb3 = 1 mL).</li>\n  <li>Triangular sail, base 3 m, height 5 m: A = \xbd \xd7 3 \xd7 5 = <strong>7.5 m\xb2</strong> — the area the wind pushes on.</li>\n</ol>\n<div class="key-concept">\n  <h3>Key Concept: Units Are the Answer Key</h3>\n  <p>Area formulas multiply two lengths (m\xb2); volume formulas multiply three (m\xb3). If your "volume" came out in cm\xb2, a length went missing. Checking units catches errors instantly — and in physics, unit-checking graduates into a full-blown professional technique.</p>\n</div>\n<div class="did-you-know">\n  <h3>Why an Elephant Can\'t Jump</h3>\n  <p>Scale an animal up 10\xd7: its volume — and weight — grows 1000\xd7 (length cubed), but its bone cross-section grows only 100\xd7 (length squared). Strength-to-weight collapses as size grows. This square–cube law is why ants hoist multiples of their body weight, why cells stay microscopic, and why giant movie monsters are physically impossible.</p>\n</div>'}],quiz:[{question:"A triangle has angles of 90\xb0 and 35\xb0. What is the third angle?",options:["55\xb0","65\xb0","45\xb0","125\xb0"],correctIndex:0,explanation:"The angles of any triangle sum to 180\xb0: third angle = 180 − 90 − 35 = 55\xb0. Because the sum is fixed, two known angles always determine the third — a fact you'll use constantly in force diagrams and ray sketches."},{question:"A 1.8 m person casts a 1.2 m shadow while a tree casts an 8 m shadow. How tall is the tree?",options:["8 m","9.6 m","12 m","14.4 m"],correctIndex:2,explanation:"The sun's rays hit both at the same angle, so the triangles are similar and height \xf7 shadow is the same ratio for both: 1.8/1.2 = 1.5, so the tree is 8 \xd7 1.5 = 12 m. Equal angles → proportional sides is the whole trick."},{question:"You walk 6 km east, then 8 km north. How far are you from your starting point?",options:["14 km","10 km","48 km","100 km"],correctIndex:1,explanation:"The two legs are perpendicular, so Pythagoras gives the direct distance: √(6\xb2 + 8\xb2) = √100 = 10 km. You walked 14 km of path, but displacement — straight-line distance — is the hypotenuse. Don't forget the final square root (100 is c\xb2, not c)."},{question:"What is the circumference of a circle with radius 5 cm? (π ≈ 3.14)",options:["15.7 cm","78.5 cm","25 cm","31.4 cm"],correctIndex:3,explanation:"Circumference C = 2πr = 2 \xd7 3.14 \xd7 5 ≈ 31.4 cm. The value 78.5 is the area (πr\xb2 = π \xd7 25) and 15.7 forgets the factor of 2 — remember circumference uses the full diameter: C = πd."},{question:"A box measures 2 cm \xd7 3 cm \xd7 4 cm and has a mass of 48 g. What is its density?",options:["2 g/cm\xb3","24 g/cm\xb3","0.5 g/cm\xb3","1152 g/cm\xb3"],correctIndex:0,explanation:"Volume first: 2 \xd7 3 \xd7 4 = 24 cm\xb3. Then density ρ = m/V = 48 \xf7 24 = 2 g/cm\xb3 — denser than water (1 g/cm\xb3), so it sinks. This geometry-to-physics pipeline (dimensions → volume → density) is exactly how Subject 5 will use these formulas."}]},{id:"first-trigonometry",title:"First Trigonometry",subtitle:"SOH-CAH-TOA and solving right triangles — the first step toward vectors and projectiles",sections:[{id:"soh-cah-toa",title:"Three Ratios That Unlock Triangles",content:"\n<p>Here's the observation trigonometry is built on: in a right triangle, once you fix one of the other angles, the <strong>shape</strong> is fixed — every such triangle is similar to every other. So the <em>ratios</em> between the sides depend only on the angle. Those ratios get names: sine, cosine, and tangent.</p>\n<h3>Labeling the sides</h3>\n<p>Relative to your chosen angle θ (never the right angle):</p>\n<ul>\n  <li><strong>Hypotenuse</strong> — the longest side, facing the 90\xb0 angle.</li>\n  <li><strong>Opposite</strong> — the side facing θ, across the triangle from it.</li>\n  <li><strong>Adjacent</strong> — the side touching θ (that isn't the hypotenuse).</li>\n</ul>\n<p>Relabeling happens if you switch angles: one angle's opposite is the other's adjacent. Always label <em>from the angle you're using</em>.</p>\n<h3>The three ratios — SOH-CAH-TOA</h3>\n<table>\n  <thead><tr><th>Ratio</th><th>Definition</th><th>Mnemonic</th></tr></thead>\n  <tbody>\n    <tr><td>sin θ</td><td>Opposite \xf7 Hypotenuse</td><td><strong>S</strong>OH</td></tr>\n    <tr><td>cos θ</td><td>Adjacent \xf7 Hypotenuse</td><td><strong>C</strong>AH</td></tr>\n    <tr><td>tan θ</td><td>Opposite \xf7 Adjacent</td><td><strong>T</strong>OA</td></tr>\n  </tbody>\n</table>\n<p>A few values worth recognizing: sin 30\xb0 = 0.5 (at 30\xb0, the opposite side is exactly half the hypotenuse), cos 60\xb0 = 0.5, tan 45\xb0 = 1 (a 45\xb0 triangle has equal legs), sin 0\xb0 = 0, and sin 90\xb0 = 1. Your calculator holds every other value — make sure it's in <strong>degree mode</strong>.</p>\n<div class=\"analogy\">\n  <h3>Analogy: A Ramp's Personality</h3>\n  <p>Think of a ramp at angle θ. Walk 1 m along the ramp surface: you gain sin θ meters of height and cover cos θ meters of ground; tan θ is the steepness — rise over run, the slope from the graphs chapter wearing new clothes. Steeper ramp: sin grows, cos shrinks, tan soars.</p>\n</div>\n<div class=\"key-concept\">\n  <h3>Key Concept: Why Physics Cares</h3>\n  <p>Physics constantly splits a slanted quantity into horizontal and vertical parts. A ball kicked at 20 m/s at 30\xb0 starts with horizontal speed 20 cos 30\xb0 ≈ 17.3 m/s and vertical speed 20 sin 30\xb0 = 10 m/s. That move — multiply by cos for adjacent, sin for opposite — is the doorway to vectors and projectiles.</p>\n</div>"},{id:"solving-right-triangles",title:"Solving Right Triangles",content:'\n<p>"Solving" a triangle means finding all its sides and angles from partial information. With SOH-CAH-TOA plus Pythagoras, a right triangle surrenders completely if you know just <strong>two facts</strong> (beyond the right angle). The routine:</p>\n<ol>\n  <li>Sketch and label hypotenuse, opposite, adjacent from the angle you know (or want).</li>\n  <li>Pick the ratio linking your two knowns to the unknown.</li>\n  <li>Rearrange (formula fluency!) and compute.</li>\n</ol>\n<h3>Finding a side</h3>\n<p><strong>Example 1.</strong> Hypotenuse 10, angle 30\xb0; find the side opposite the angle. Ratio linking opposite and hypotenuse: sine. sin 30\xb0 = x/10 → x = 10 \xd7 sin 30\xb0 = 10 \xd7 0.5 = <strong>5</strong>.</p>\n<p><strong>Example 2.</strong> Same triangle, find the adjacent side: cos 30\xb0 = y/10 → y = 10 \xd7 0.866 ≈ <strong>8.66</strong>. Check with Pythagoras: 5\xb2 + 8.66\xb2 = 25 + 75 ≈ 100 = 10\xb2 ✓.</p>\n<p><strong>Example 3 — unknown in the bottom.</strong> A wire anchored at 55\xb0 must reach the top of a 12 m mast: sin 55\xb0 = 12/L → L = 12 \xf7 sin 55\xb0 = 12 \xf7 0.819 ≈ <strong>14.6 m</strong>. When the unknown is downstairs, you <em>divide</em> — rearrange first, then compute.</p>\n<h3>Finding an angle: the inverse functions</h3>\n<p>Know the sides but not the angle? Run the ratio backwards with sin⁻\xb9, cos⁻\xb9, tan⁻\xb9 (calculator: SHIFT/2nd + sin etc.). These answer the question "which angle has this ratio?"</p>\n<p><strong>Example 4.</strong> Opposite 3, adjacent 4: tan θ = 3/4 = 0.75 → θ = tan⁻\xb9(0.75) ≈ <strong>36.9\xb0</strong>. (The 3–4–5 triangle\'s angles: 36.9\xb0, 53.1\xb0, 90\xb0.)</p>\n<p><strong>Example 5.</strong> A 6 m ladder reaching 5.5 m up a wall: sin θ = 5.5/6 = 0.917 → θ = sin⁻\xb9(0.917) ≈ <strong>66.5\xb0</strong> — close to the 75\xb0 maximum safe-lean angle used in some safety codes.</p>\n<div class="key-concept">\n  <h3>Key Concept: Choose the Ratio by What You Have</h3>\n  <p>Don\'t memorize problem types; just ask which two sides are in play. Opposite &amp; hypotenuse → sine. Adjacent &amp; hypotenuse → cosine. Opposite &amp; adjacent → tangent. Two knowns, one unknown, one equation — the rest is the rearranging you drilled in Chapter 2.</p>\n</div>'},{id:"angles-of-elevation",title:"Angles of Elevation and Depression",content:"\n<p>Point a finger horizontally, then tilt it up to sight the top of a building: the tilt is the <strong>angle of elevation</strong>. Sight downward from a cliff to a boat and the tilt below horizontal is the <strong>angle of depression</strong>. These angles turn a clinometer (or a phone app and a tape measure) into a rangefinder for heights you could never climb.</p>\n<h3>Worked examples</h3>\n<p><strong>The building.</strong> Standing 50 m from a building's base, you sight the top at 45\xb0 elevation. Height above eye level: tan 45\xb0 = h/50 → h = 50 \xd7 1 = <strong>50 m</strong>. (At 45\xb0, height equals distance — a handy field fact.) Add your eye height, ≈ 1.6 m, for the full 51.6 m.</p>\n<p><strong>The steeper sight.</strong> From 30 m away, a tower's top sits at 60\xb0 elevation: h = 30 \xd7 tan 60\xb0 = 30 \xd7 1.732 ≈ <strong>52 m</strong>.</p>\n<p><strong>The kite.</strong> 80 m of taut string at 50\xb0 elevation. Height uses sine (opposite over the string, which is the hypotenuse): h = 80 \xd7 sin 50\xb0 ≈ 80 \xd7 0.766 ≈ <strong>61 m</strong>. Horizontal distance downrange: 80 \xd7 cos 50\xb0 ≈ 51 m.</p>\n<p><strong>The cliff, in reverse.</strong> From a 40 m cliff top, a boat appears at 25\xb0 depression. The depression angle from your horizontal equals the elevation angle from the boat's (Z-pattern angles between parallels). tan 25\xb0 = 40/d → d = 40 \xf7 0.466 ≈ <strong>86 m</strong> offshore.</p>\n<div class=\"key-concept\">\n  <h3>Key Concept: Draw the Triangle First</h3>\n  <p>Every elevation problem is the same right triangle: horizontal ground, vertical height, line of sight as hypotenuse. Sketch it, mark the angle at your eye, label the sides — the correct ratio then picks itself. The sketch-first habit is precisely how you'll set up force and projectile diagrams later.</p>\n</div>\n<div class=\"did-you-know\">\n  <h3>Measuring the Unreachable</h3>\n  <p>With angles alone, ancient and modern surveyors measured the absurdly distant: Eratosthenes got Earth's circumference from shadow angles in two cities; 19th-century surveyors of the Great Trigonometrical Survey computed Mount Everest's height — 8850 m — from theodolite angles sighted over 150 km away, without setting foot on it.</p>\n</div>"},{id:"sine-cosine-rules",title:"Beyond Right Angles: The Sine and Cosine Rules",content:'\n<p>SOH-CAH-TOA demands a right angle. But triangles in the wild — two roads meeting at 50\xb0, two forces at 120\xb0 — often have none. Two upgraded tools handle <em>any</em> triangle. Label the angles A, B, C and let a, b, c be the sides <strong>opposite</strong> them.</p>\n<h3>The sine rule: pairs of opposites</h3>\n<p style="text-align:center"><strong>a \xf7 sin A = b \xf7 sin B = c \xf7 sin C</strong></p>\n<p>Each side divided by the sine of its opposite angle gives the same number. Use it when you have a matched side–angle pair plus one more piece.</p>\n<p><strong>Example.</strong> Angle A = 40\xb0, angle B = 60\xb0, and side a = 8 cm. Then b = 8 \xd7 sin 60\xb0 \xf7 sin 40\xb0 = 8 \xd7 0.866 \xf7 0.643 ≈ <strong>10.8 cm</strong>. Bigger angle, bigger opposite side — the rule quantifies that instinct.</p>\n<h3>The cosine rule: Pythagoras with a correction</h3>\n<p style="text-align:center"><strong>c\xb2 = a\xb2 + b\xb2 − 2ab cos C</strong></p>\n<p>Use it with two sides and the angle <em>between</em> them, or with all three sides (solve for the angle). Look closely: it\'s Pythagoras plus a correction term. When C = 90\xb0, cos C = 0, the correction vanishes, and c\xb2 = a\xb2 + b\xb2 reappears — Pythagoras is just the right-angle special case.</p>\n<p><strong>Example.</strong> Two straight paths of 5 km and 7 km diverge from camp at 60\xb0. Distance between their endpoints: c\xb2 = 25 + 49 − 2 \xd7 5 \xd7 7 \xd7 cos 60\xb0 = 74 − 70 \xd7 0.5 = 39 → c = √39 ≈ <strong>6.2 km</strong>.</p>\n<div class="key-concept">\n  <h3>Key Concept: Which Rule When?</h3>\n  <p>Have a side–angle opposite pair? <strong>Sine rule.</strong> Have two sides hugging a known angle, or all three sides? <strong>Cosine rule.</strong> Right triangle? Plain SOH-CAH-TOA is faster. That\'s the entire decision tree.</p>\n</div>\n<div class="did-you-know">\n  <h3>Where You\'ll Meet Them Again</h3>\n  <p>Combining two forces that pull at 120\xb0? The resultant comes from the cosine rule. Navigation fixes, GPS geometry, and the vector additions of Phase 3 all quietly run on these two rules. This section is a preview — Subject 10 builds full trigonometric fluency, including the unit circle and the sinusoidal waves at the heart of sound and light.</p>\n</div>'}],quiz:[{question:"In a right triangle, sin θ equals which ratio?",options:["adjacent \xf7 hypotenuse","opposite \xf7 hypotenuse","opposite \xf7 adjacent","hypotenuse \xf7 opposite"],correctIndex:1,explanation:"SOH: Sine = Opposite \xf7 Hypotenuse. Adjacent \xf7 hypotenuse is cosine (CAH) and opposite \xf7 adjacent is tangent (TOA). Always label opposite and adjacent from the angle in question — they swap if you switch angles."},{question:"A right triangle has hypotenuse 10 and an angle of 30\xb0. How long is the side opposite that angle? (sin 30\xb0 = 0.5)",options:["5","8.7","10","20"],correctIndex:0,explanation:"sin 30\xb0 = opposite \xf7 10, so opposite = 10 \xd7 sin 30\xb0 = 10 \xd7 0.5 = 5. The value 8.7 is the adjacent side (10 \xd7 cos 30\xb0), and 20 comes from dividing instead of multiplying — rearrange before you compute."},{question:"A right triangle has opposite side 3 and adjacent side 4. What is the angle? (tan⁻\xb9 finds it)",options:["30\xb0","45\xb0","53.1\xb0","36.9\xb0"],correctIndex:3,explanation:"tan θ = opposite \xf7 adjacent = 3 \xf7 4 = 0.75, so θ = tan⁻\xb9(0.75) ≈ 36.9\xb0. The other acute angle of this 3–4–5 triangle is 53.1\xb0 — you'd get it by taking tan⁻\xb9(4/3), i.e. by labeling from the other corner."},{question:"Standing 50 m from a building, you sight its top at a 45\xb0 angle of elevation. How high is the top above eye level?",options:["25 m","70.7 m","50 m","100 m"],correctIndex:2,explanation:"tan 45\xb0 = height \xf7 50, and tan 45\xb0 = 1, so height = 50 m. At 45\xb0 elevation, height above eye level always equals your horizontal distance — a triangle with a 45\xb0 angle has equal legs. Handy for quick field estimates."},{question:"A triangle has no right angle, but you know angle A, angle B, and side a (opposite A). What's the right tool to find side b?",options:["Pythagoras: a\xb2 + b\xb2 = c\xb2","The sine rule: a \xf7 sin A = b \xf7 sin B","SOH-CAH-TOA directly","The cosine rule: c\xb2 = a\xb2 + b\xb2 − 2ab cos C"],correctIndex:1,explanation:"You hold a matched side–angle pair (a and A) plus another angle — exactly the sine rule's setup: b = a \xd7 sin B \xf7 sin A. Pythagoras and SOH-CAH-TOA need a right angle, and the cosine rule wants two sides with the angle between them."}]}]},{id:"motion-and-forces",number:5,title:"Motion & Forces",description:"Your first complete, quantitative tour of mechanics at one-formula depth — motion, forces, pressure, buoyancy, and energy, in the classic Russian/Chinese grade 8–9 tradition.",phase:2,chapters:[{id:"describing-motion",title:"Describing Motion",subtitle:"Speed, acceleration, and the motion graphs that turn movement into mathematics",sections:[{id:"distance-and-displacement",title:"Position, Distance & Displacement",content:'\n<p>Before physics can explain motion, it has to describe it — and the first surprise is that "how far did you go?" has two different answers. <strong>Distance</strong> is the total length of the path you actually traveled, counted step by step. <strong>Displacement</strong> is the straight-line change from where you started to where you ended, together with a direction.</p>\n<p>Try it with a real trip. You walk 400 m from home to the bakery, then 400 m straight back:</p>\n<ul>\n  <li><strong>Distance traveled:</strong> 400 m + 400 m = 800 m. Your legs did all of it.</li>\n  <li><strong>Displacement:</strong> 0 m. You ended exactly where you began.</li>\n</ul>\n<p>Both numbers are honest — they just answer different questions. Distance tells you how much walking happened; displacement tells you the net result of the motion. A marathon run on a loop course covers 42,195 m of distance with a displacement of almost zero.</p>\n<p>Describing motion also requires saying <strong>motion relative to what</strong>. A passenger asleep on a train is motionless relative to her seat, yet moving at 90 km/h relative to the ground. Neither description is "the true one" — physics always measures motion against a chosen reference object, usually the ground, and you should quietly note which one you are using.</p>\n<div class="key-concept">\n  <h4>Key Concept: Direction Is Part of the Answer</h4>\n  <p>Displacement always comes with a direction: "600 m north," not just "600 m." Later subjects will grow this idea into full vectors; for now, an arrow drawn from start point to end point is all the machinery you need.</p>\n</div>\n<div class="analogy">\n  <h3>Analogy: The Taxi Meter and the Crow</h3>\n  <p>A taxi meter charges you for distance — every turn and detour adds to the fare. A crow flying from your origin to your destination measures displacement. In a city grid the taxi might drive 5 km while the crow flies just 3 km, and both numbers are correct measurements of the same trip.</p>\n</div>'},{id:"speed",title:"Speed: v = d/t, the First Formula of Physics",content:'\n<p>Speed answers the question "how fast?" by comparing distance to the time it took: <strong>v = d/t</strong> — speed equals distance divided by time. It is the first of the great ratio formulas of physics, and every one that follows (density, pressure, power) works the same way: one quantity spread out over another.</p>\n<p><strong>Worked example.</strong> A cyclist covers 36 km in 2 hours. Her speed is v = 36 km \xf7 2 h = <strong>18 km/h</strong>. In the scientific unit, metres per second: 36,000 m \xf7 7,200 s = <strong>5 m/s</strong>. The handy conversion is worth memorizing: 1 m/s = 3.6 km/h, so 5 m/s \xd7 3.6 = 18 km/h. It checks out.</p>\n<p>Some reference points to calibrate your intuition:</p>\n<table>\n  <thead>\n    <tr><th>Mover</th><th>Typical speed</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Brisk walk</td><td>1.5 m/s (≈ 5 km/h)</td></tr>\n    <tr><td>Sprinting human</td><td>10 m/s (≈ 36 km/h)</td></tr>\n    <tr><td>Highway car</td><td>28 m/s (≈ 100 km/h)</td></tr>\n    <tr><td>Passenger jet</td><td>250 m/s (≈ 900 km/h)</td></tr>\n    <tr><td>Sound in air</td><td>340 m/s</td></tr>\n  </tbody>\n</table>\n<p>Most real motion is uneven — a bus speeds up, crawls in traffic, stops at lights. Dividing total distance by total time gives the <strong>average speed</strong>. What the speedometer shows at one instant is the <strong>instantaneous speed</strong>. A 60 km trip that takes 1.5 hours has an average speed of 40 km/h even if the speedometer touched 90 somewhere along the way.</p>\n<p>When speed comes packaged with a direction — 15 m/s <em>east</em> — physicists call it <strong>velocity</strong>. A car rounding a bend at a steady 50 km/h keeps the same speed but changes its velocity, because its direction changes.</p>\n<div class="did-you-know">\n  <h4>Did You Know? Thunder Is a Speedometer</h4>\n  <p>Light reaches you almost instantly, but thunder travels at only 340 m/s. Count the seconds between flash and rumble and divide by 3 to get the storm\'s distance in kilometres: d = v \xd7 t = 340 m/s \xd7 6 s ≈ 2 km. That is v = d/t rearranged and put to work.</p>\n</div>'},{id:"acceleration",title:"Acceleration: When Speed Changes",content:'\n<p>Steady speed is the exception; the interesting moments of motion are when speed <em>changes</em>. <strong>Acceleration</strong> measures how quickly velocity changes: the change in speed divided by the time it took, a = Δv/t. Its unit, the metre per second per second (<strong>m/s\xb2</strong>), sounds odd until you read it literally: how many m/s of speed are gained (or lost) each second.</p>\n<p><strong>Worked example.</strong> A metro train pulls away from the platform and reaches 24 m/s in 8 s. Its acceleration is a = 24 m/s \xf7 8 s = <strong>3 m/s\xb2</strong>. Every second, the train is moving 3 m/s faster than the second before: 3, 6, 9, 12 … you can feel each of those steps pressing you gently into your seat.</p>\n<p>Slowing down is also acceleration — just directed against the motion. A car braking from 20 m/s to rest in 4 s changes speed by 20 m/s in 4 s, a deceleration of <strong>5 m/s\xb2</strong>. Everyday language says "deceleration"; physics happily calls both cases acceleration and keeps track with a sign or an arrow.</p>\n<p>The most famous acceleration of all belongs to falling objects. Near Earth\'s surface, anything dropped (when air resistance is small) gains speed at about <strong>10 m/s every second</strong> — after 1 s it falls at 10 m/s, after 2 s at 20 m/s, after 3 s at 30 m/s. Galileo established this by rolling balls down ramps to slow the action enough to time it, one of the founding experiments of physics.</p>\n<div class="key-concept">\n  <h4>Key Concept: Speed Tells You Nothing About Acceleration</h4>\n  <p>A jet cruising at 900 km/h has zero acceleration; a skateboard rolling off from rest has plenty. Acceleration is about <em>change</em>. This distinction — between how fast something moves and how fast that changes — is the single most common source of confusion in mechanics, and mastering it now pays off for the rest of the curriculum.</p>\n</div>\n<div class="analogy">\n  <h3>Analogy: Salary vs. Raise</h3>\n  <p>Speed is like your salary: how much distance you earn per second. Acceleration is like your annual raise: how quickly the salary itself is changing. A high salary with no raise (cruising jet) and a small salary growing fast (sprinter off the blocks) are completely different situations.</p>\n</div>'},{id:"motion-graphs",title:"Motion Graphs: Distance–Time and Velocity–Time",interactive:"motion-graphs",content:"\n<p>A motion graph compresses an entire journey into a single picture — and once you can read the two classic types, you can decode any trip at a glance.</p>\n<p><strong>Distance–time graphs</strong> put time on the horizontal axis and distance on the vertical. The rule is: <strong>the slope of the line is the speed</strong>.</p>\n<ul>\n  <li>A horizontal line means the object is standing still — time passes, distance doesn't grow.</li>\n  <li>A straight rising line means steady speed; steeper means faster.</li>\n  <li>A curve that gets steeper shows speeding up.</li>\n</ul>\n<p><strong>Worked example.</strong> A jogger's graph rises from 0 m to 1,200 m between the 0 s and 600 s marks, then goes flat for 120 s (water break), then rises again. First leg speed: v = d/t = 1,200 m \xf7 600 s = <strong>2 m/s</strong>. The flat stretch is v = 0. The whole story is right there in the shape.</p>\n<p><strong>Velocity–time graphs</strong> put velocity on the vertical axis, and they carry two treasures:</p>\n<ul>\n  <li><strong>The slope is the acceleration.</strong> A rising line means speeding up; a horizontal line means constant velocity; a falling line means braking.</li>\n  <li><strong>The area under the line is the distance traveled.</strong> A bus holding 10 m/s for 30 s sweeps out a rectangle: 10 m/s \xd7 30 s = <strong>300 m</strong>. A train accelerating steadily from 0 to 20 m/s over 10 s sweeps out a triangle: half of 20 m/s \xd7 10 s = <strong>100 m</strong>.</li>\n</ul>\n<div class=\"key-concept\">\n  <h4>Key Concept: Same Shape, Different Meaning</h4>\n  <p>A horizontal line on a distance–time graph means <em>stopped</em>. A horizontal line on a velocity–time graph means <em>moving at constant speed</em>. Always check the vertical axis label before reading a motion graph — it is the most common trap in every physics exam ever written.</p>\n</div>\n<p>Use the simulator below to drive an object back and forth and watch both graphs draw themselves in real time. Try to produce a flat line, a steep line, and a triangle — matching motion to graph is a skill your hands learn faster than your eyes.</p>"}],quiz:[{question:"You walk 300 m east to a shop, then 300 m west back home. What are your distance and displacement?",options:["Distance 0 m, displacement 600 m","Distance 600 m, displacement 600 m","Distance 600 m, displacement 0 m","Distance 300 m, displacement 300 m"],correctIndex:2,explanation:"Distance counts the whole path (300 + 300 = 600 m), while displacement is the straight-line change from start to finish — and you ended where you started, so it is 0 m."},{question:"A train covers 150 km in 2.5 hours. What is its average speed?",options:["60 km/h","75 km/h","50 km/h","375 km/h"],correctIndex:0,explanation:"v = d/t = 150 km \xf7 2.5 h = 60 km/h. Average speed is always total distance over total time, no matter how uneven the trip was in between."},{question:"On a distance–time graph, what does the slope of the line represent?",options:["Acceleration","Speed","Distance","Time elapsed"],correctIndex:1,explanation:"Slope is rise over run — distance gained per unit time — which is exactly the definition of speed, v = d/t. A steeper line means a faster mover; a flat line means standing still."},{question:"A car speeds up from rest to 24 m/s in 8 seconds. What is its acceleration?",options:["24 m/s\xb2","8 m/s\xb2","192 m/s\xb2","3 m/s\xb2"],correctIndex:3,explanation:"Acceleration is the change in speed divided by the time: 24 m/s \xf7 8 s = 3 m/s\xb2. Every second, the car moves 3 m/s faster than the second before."},{question:"A bus holds a steady 10 m/s for 30 s. On its velocity–time graph, what does the area under the line tell you?",options:["Its acceleration: 3 m/s\xb2","Its average speed: 40 m/s","The distance traveled: 300 m","Nothing — area has no meaning on motion graphs"],correctIndex:2,explanation:"On a velocity–time graph, area under the line equals distance: 10 m/s \xd7 30 s = 300 m. This area rule is the graph version of d = v \xd7 t and works even when the speed changes."}]},{id:"mass-density-and-measurement",title:"Mass, Density & Measurement",subtitle:"Mass vs weight, ρ = m/V, and the measuring instruments of the physics lab",sections:[{id:"measuring-instruments",title:"The Instruments of the Physics Lab",content:'\n<p>Physics became a real science the day it started measuring instead of just arguing, and every measurement follows the same recipe: an instrument, a scale, and an honest statement of how precise the reading is. The classic starter kit:</p>\n<ul>\n  <li><strong>Ruler or tape measure</strong> — length, usually marked in millimetres.</li>\n  <li><strong>Measuring cylinder</strong> — volume of liquids, marked in millilitres (1 mL = 1 cm\xb3).</li>\n  <li><strong>Balance</strong> — mass, in grams or kilograms.</li>\n  <li><strong>Stopwatch</strong> — time, in seconds.</li>\n  <li><strong>Thermometer</strong> — temperature, in \xb0C.</li>\n</ul>\n<p>Before trusting any instrument, find its <strong>scale division</strong>: the gap between neighbouring marks. A ruler marked every 1 mm can honestly report "12.4 cm, give or take half a millimetre" — but never "12.4132 cm." Writing more digits than your instrument can justify is the physics equivalent of making things up.</p>\n<p><strong>Worked example.</strong> A measuring cylinder has marks every 10 mL, and the water level sits between 70 and 80, slightly closer to 80. The honest reading is 78 mL \xb1 5 mL. When you read it, put your eye level with the liquid surface and read the bottom of the curved meniscus — reading from above or below shifts the answer by several millilitres.</p>\n<p>What about the volume of an irregular solid — a stone, a key, a chess knight? Use <strong>displacement</strong>: submerge it and see how much liquid it shoves aside. If the cylinder reads 60 mL before and 85 mL after the stone goes in, the stone\'s volume is 85 − 60 = <strong>25 cm\xb3</strong>. This trick, over two thousand years old, is exactly what you will need for density in the next section.</p>\n<div class="did-you-know">\n  <h4>Try It Yourself: Calibrate Your Own Hands</h4>\n  <p>Measure your hand span (thumb tip to pinky tip, fingers spread) with a ruler — for many adults it is close to 20 cm. Now pace out a room, measure one pace, and multiply. With a calibrated span and a calibrated pace you carry two measuring instruments everywhere you go, accurate to a few percent. Estimate first, then check with a tape measure: good physicists always guess before they measure.</p>\n</div>'},{id:"mass-vs-weight",title:"Mass Is Not Weight",content:'\n<p>In everyday speech "mass" and "weight" blur together; in physics they are different quantities with different units, and keeping them straight is a rite of passage.</p>\n<p><strong>Mass</strong> measures how much matter an object contains — equivalently, how hard it is to change the object\'s motion. It is measured in <strong>kilograms (kg)</strong> with a balance, and it does not change when you travel: a 70 kg astronaut is 70 kg on Earth, on the Moon, and floating in orbit.</p>\n<p><strong>Weight</strong> is the <em>force</em> with which gravity pulls on that mass. Like every force it is measured in <strong>newtons (N)</strong>, and it very much depends on where you are. Near Earth\'s surface, gravity pulls with about <strong>10 N on every kilogram</strong>, so:</p>\n<p style="text-align:center"><strong>weight ≈ 10 N/kg \xd7 mass</strong></p>\n<p><strong>Worked example.</strong> A 2 kg bag of flour has a weight of about 2 kg \xd7 10 N/kg = <strong>20 N</strong> on Earth. On the Moon, where gravity pulls with only 1.6 N per kilogram, the same bag weighs 2 \xd7 1.6 = 3.2 N — yet it is still exactly 2 kg of flour, and would make exactly as much bread.</p>\n<table>\n  <thead>\n    <tr><th></th><th>Mass</th><th>Weight</th></tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>What it is</strong></td><td>Amount of matter</td><td>Force of gravity on it</td></tr>\n    <tr><td><strong>Unit</strong></td><td>kilogram (kg)</td><td>newton (N)</td></tr>\n    <tr><td><strong>Instrument</strong></td><td>Balance</td><td>Spring scale</td></tr>\n    <tr><td><strong>On the Moon</strong></td><td>Unchanged</td><td>About 1/6 of Earth value</td></tr>\n  </tbody>\n</table>\n<div class="key-concept">\n  <h4>Key Concept: Why the Bathroom Scale Lies (Slightly)</h4>\n  <p>A bathroom scale actually measures the force you press on it — a weight — and then divides by 10 N/kg to display kilograms. On the Moon it would read about 12 kg for a 70 kg person: same mass, weaker pull. A two-pan balance, which compares your mass against standard masses, would still read correctly, because gravity pulls equally on both pans.</p>\n</div>'},{id:"density",title:"Density: ρ = m/V",content:'\n<p>Which is heavier, iron or wood? The honest answer is "it depends on how much of each" — a log outweighs a nail. The fair comparison asks how much mass is packed into each unit of volume, and that ratio is <strong>density</strong>:</p>\n<p style="text-align:center"><strong>ρ = m/V</strong> (density = mass \xf7 volume)</p>\n<p>Density is measured in g/cm\xb3 or kg/m\xb3 (1 g/cm\xb3 = 1000 kg/m\xb3), and it is a fingerprint of the material itself, not of the object\'s size. Every scrap of pure aluminium — filing or engine block — has density 2.7 g/cm\xb3.</p>\n<table>\n  <thead>\n    <tr><th>Material</th><th>Density (g/cm\xb3)</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Cork</td><td>0.24</td></tr>\n    <tr><td>Ice</td><td>0.92</td></tr>\n    <tr><td>Water</td><td>1.00</td></tr>\n    <tr><td>Aluminium</td><td>2.7</td></tr>\n    <tr><td>Iron</td><td>7.9</td></tr>\n    <tr><td>Gold</td><td>19.3</td></tr>\n  </tbody>\n</table>\n<p><strong>Worked example.</strong> A metal part has mass 540 g. You lower it into a measuring cylinder and the water level rises by 200 cm\xb3. Its density: ρ = m/V = 540 g \xf7 200 cm\xb3 = <strong>2.7 g/cm\xb3</strong> — the table says aluminium. You have just identified a material with a balance and a jug of water.</p>\n<p>The formula runs in every direction. Need the mass of water in a 40-litre aquarium? m = ρ \xd7 V = 1 g/cm\xb3 \xd7 40,000 cm\xb3 = 40,000 g = <strong>40 kg</strong> — which is why you empty an aquarium before moving it.</p>\n<div class="did-you-know">\n  <h4>Did You Know? Ice Is the Odd One Out</h4>\n  <p>Almost every substance is denser as a solid than as a liquid — but water expands about 9% when it freezes, dropping to 0.92 g/cm\xb3. That is why ice floats, why frozen pipes burst, and why ponds freeze from the top down, letting fish winter safely underneath. Life on Earth quietly depends on this one anomaly in the density table.</p>\n</div>'},{id:"density-and-floating",title:"Why Density Decides Who Floats",content:"\n<p>Drop a coin in water: it sinks. Drop a cork: it floats. Drop an ice cube: it floats, but just barely, riding low. One number predicts all three outcomes — density compared to the liquid's density.</p>\n<ul>\n  <li><strong>Denser than the liquid → sinks.</strong> Iron (7.9 g/cm\xb3) in water (1.0 g/cm\xb3): straight down.</li>\n  <li><strong>Less dense → floats,</strong> with only part of it submerged. Cork (0.24) floats high; ice (0.92) floats with about 9/10 of its volume hidden underwater — the \"tip of the iceberg\" is a real density calculation.</li>\n  <li><strong>Equal density → hovers,</strong> drifting at whatever depth you leave it, like a fish with a tuned swim bladder.</li>\n</ul>\n<p><strong>Worked example.</strong> An ice cube of volume 30 cm\xb3 has mass m = ρ \xd7 V = 0.92 g/cm\xb3 \xd7 30 cm\xb3 ≈ 27.6 g. Floating, it displaces 27.6 g of water — which occupies 27.6 cm\xb3. So 27.6 of its 30 cm\xb3 sit below the surface: 92% submerged, matching the ratio of the densities.</p>\n<p>Then what about a steel ship? Steel is eight times denser than water, yet a 100,000-tonne ship floats. The resolution: the ship is not solid steel. Its hull encloses vast air-filled spaces, so the <em>average</em> density of the whole ship — steel plus air — is less than 1 g/cm\xb3. Puncture the hull, let water replace the air, and the average density climbs past water's; the ship sinks. Submarines do this on purpose, pumping water in and out of ballast tanks to tune their average density above or below the water's.</p>\n<div class=\"did-you-know\">\n  <h4>Try It Yourself: The Floating Egg</h4>\n  <p>Place a fresh egg in a glass of tap water — it sinks, because an egg is slightly denser than fresh water. Now stir in salt, a spoonful at a time. Salt water is denser than fresh, and after 3–4 spoonfuls the egg lifts off the bottom and floats. You changed nothing about the egg; you changed the liquid's density. The same physics makes swimmers float noticeably better in the sea than in a pool.</p>\n</div>"}],quiz:[{question:"An astronaut travels from Earth to the Moon. What happens to her mass and weight?",options:["Both mass and weight decrease","Mass stays the same; weight decreases","Weight stays the same; mass decreases","Both stay the same"],correctIndex:1,explanation:"Mass measures the amount of matter and travels unchanged. Weight is gravity's pull on that mass — the Moon pulls with about 1.6 N/kg instead of Earth's 10 N/kg, so weight drops to roughly one sixth."},{question:"A metal block has mass 540 g and volume 200 cm\xb3. What is its density, and what metal is it likely to be?",options:["2.7 g/cm\xb3 — aluminium","0.37 g/cm\xb3 — cork","7.9 g/cm\xb3 — iron","108 g/cm\xb3 — no known metal"],correctIndex:0,explanation:"ρ = m/V = 540 g \xf7 200 cm\xb3 = 2.7 g/cm\xb3, the density of aluminium. Density is a fingerprint of the material — measuring m and V is enough to identify what something is made of."},{question:"What is the best way to measure the volume of an irregular stone?",options:["Weigh it on a balance and divide by 10","Measure its length, width, and height with a ruler","It cannot be measured without cutting it into cubes","Submerge it in a measuring cylinder and read how much the water level rises"],correctIndex:3,explanation:"A submerged object displaces exactly its own volume of liquid, so the rise in the water level equals the stone's volume. Rulers only work for regular shapes, and a balance gives mass, not volume."},{question:"An object floats in a liquid when…",options:["it is lighter than the container","it contains no metal","its density is less than the liquid's density","its volume is smaller than the liquid's volume"],correctIndex:2,explanation:"Floating is a density contest: less dense than the liquid floats, denser sinks, equal density hovers. This is why cork (0.24 g/cm\xb3) floats on water while iron (7.9 g/cm\xb3) sinks — and why a hollow steel ship, whose average density includes lots of air, floats too."},{question:"Taking gravity's pull as 10 N per kilogram, what is the weight of a 5 kg sack of potatoes on Earth?",options:["5 N","50 N","0.5 N","500 N"],correctIndex:1,explanation:"Weight = 10 N/kg \xd7 5 kg = 50 N. Mass (5 kg) is the amount of matter; weight (50 N) is the gravitational force on it — different quantities, different units."}]},{id:"forces-and-inertia",title:"Forces & Inertia",subtitle:"Newton's first law, friction, Hooke's law, and the art of the force diagram",sections:[{id:"force-as-interaction",title:"Force: An Interaction, Not a Possession",content:'\n<p>Kick a ball, stretch a rubber band, hold up a bag of groceries — in each case something pushes or pulls on something else. A <strong>force</strong> is exactly that: a push or a pull that one object exerts on another. The wording matters: force is not something an object <em>has</em>, like mass; it is an <em>interaction between two objects</em>. No partner, no force. The ball is kicked by a foot; the band is stretched by fingers; the bag is held by a hand while Earth pulls it down.</p>\n<p>What can a force do? Only two kinds of things:</p>\n<ul>\n  <li><strong>Change motion</strong> — start it, stop it, speed it up, slow it down, or bend its path.</li>\n  <li><strong>Change shape</strong> — stretch, squash, bend, or twist the object.</li>\n</ul>\n<p>Force is measured in <strong>newtons (N)</strong>. One newton is roughly the weight of a small apple (100 g) — a pleasantly Newtonian coincidence. To measure a force, physicists use a <strong>dynamometer</strong> (spring scale): a spring stretches in proportion to the pull, and a pointer reads the force off a scale. Some everyday magnitudes: lifting a 1-litre water bottle takes about 10 N, a firm handshake squeezes with 50–100 N, and a car engine can push with several thousand newtons.</p>\n<p>Because a force has a size <em>and</em> a direction, we draw it as an <strong>arrow</strong>: the arrow points the way the force pushes or pulls, and its length shows how strong it is. If 10 N is drawn as a 1 cm arrow, a 30 N force gets 3 cm.</p>\n<p><strong>Worked example.</strong> A shopping bag with 3 kg of groceries hangs from your hand. Earth pulls it down with about 3 kg \xd7 10 N/kg = 30 N; your hand pulls it up with 30 N. Two arrows, equal length, opposite directions — the bag hangs still.</p>\n<div class="key-concept">\n  <h4>Key Concept: Forces Come in Pairs</h4>\n  <p>Every force is one side of a two-way interaction. Push a wall and you feel the wall push back on your hand; the Earth pulls you down, and you pull the Earth up (very slightly). You never find a lone force with no partner object — a preview of Newton\'s third law, treated fully in a later subject.</p>\n</div>'},{id:"inertia-and-first-law",title:"Inertia & Newton's First Law",content:'\n<p>Common sense says motion needs a motor: stop pedalling and the bicycle coasts to a halt, so surely "no force means no motion." For two thousand years, following Aristotle, nearly everyone believed exactly that. Galileo and Newton showed it is backwards.</p>\n<p>The bicycle stops not because its motion "runs out," but because friction and air resistance actively slow it. Reduce those forces and the coasting stretches out: farther on smooth asphalt than gravel, farther still on ice. Imagine the limit — a perfectly smooth, endless surface with no air — and the conclusion is inescapable: the bicycle would coast <strong>forever</strong>.</p>\n<div class="key-concept">\n  <h4>Newton\'s First Law</h4>\n  <p>An object keeps doing what it is doing — staying at rest, or moving in a straight line at constant speed — unless a force acts to change it. Motion needs no force to <em>continue</em>; it needs a force only to <em>change</em>.</p>\n</div>\n<p>This built-in stubbornness of matter is called <strong>inertia</strong>, and the more mass, the more of it. You feel inertia constantly:</p>\n<ul>\n  <li>A bus brakes and passengers lurch <em>forward</em> — their bodies keep moving at the old speed while the bus slows under them.</li>\n  <li>The bus turns right and everyone leans left — their bodies try to continue straight ahead.</li>\n  <li>Ketchup leaves the bottle when you jerk the bottle downward and stop it: the bottle stops, the ketchup doesn\'t.</li>\n</ul>\n<p><strong>Worked example.</strong> A car travels at 20 m/s (72 km/h). During a crash it stops in about 0.1 s — but an unbelted passenger does not. Their body continues at 20 m/s until something stops it. A seatbelt supplies a controlled stopping force over the longest possible distance; that is inertia, taken deadly seriously by engineers.</p>\n<div class="did-you-know">\n  <h4>Try It Yourself: The Coin Drop</h4>\n  <p>Place a stiff card on top of a glass and a coin on top of the card. Flick the card sharply sideways: the card flies away and the coin drops straight into the glass. The flick lasts too briefly for friction to drag the coin along, so the coin simply stays put — inertia in action — then falls under gravity. The tablecloth-yanking trick is the same physics with higher stakes.</p>\n</div>'},{id:"friction",title:"Friction: The Force That Rubs Both Ways",content:'\n<p>Slide a book across a table and it stops. The culprit is <strong>friction</strong> — a force that appears wherever two surfaces touch and resists their sliding, always pointing against the motion (or attempted motion). Up close, even polished surfaces are mountain ranges of microscopic bumps that catch, snag, and weld momentarily; friction is the price of dragging those landscapes across each other.</p>\n<p>Friction comes in three varieties, in order of strength:</p>\n<ul>\n  <li><strong>Static friction</strong> holds surfaces that are not yet sliding — it is why a parked car stays put on a hill and why you can walk without slipping. It is usually the strongest.</li>\n  <li><strong>Sliding friction</strong> acts on surfaces slipping past each other — the book on the table, skis on snow.</li>\n  <li><strong>Rolling friction</strong> resists a wheel or ball rolling — typically far weaker than sliding, which is why humanity is so fond of the wheel and the ball bearing.</li>\n</ul>\n<p><strong>Worked example.</strong> Hook a spring scale to a 1 kg brick on a wooden table and pull gently. The reading climbs — 1 N, 2 N, 2.5 N — while the brick sits still (static friction matches your pull). At about 3 N the brick breaks loose, and keeping it sliding steadily takes roughly 2.5 N: sliding friction is a bit weaker than the static maximum. At steady speed your 2.5 N pull exactly balances 2.5 N of friction. Press down on the brick and every number grows — friction is stronger the harder the surfaces press together.</p>\n<p>Friction is neither villain nor hero — it is both, and engineering is largely the art of managing it:</p>\n<ul>\n  <li><strong>Wanted:</strong> tire grip, brake pads, shoe soles, nails holding in wood, knots staying tied. On ice, where friction nearly vanishes, walking itself becomes a physics problem.</li>\n  <li><strong>Unwanted:</strong> engine wear, squeaky hinges, energy lost as heat. Cures: smooth polishing, oil and grease (a liquid film keeps the mountain ranges apart), and replacing sliding with rolling via wheels and bearings.</li>\n</ul>\n<div class="analogy">\n  <h3>Analogy: Velcro Landscapes</h3>\n  <p>Two touching surfaces behave like gentle Velcro: countless tiny hooks and loops engaging. Pressing harder engages more of them (more friction); lubricant is like a film keeping the hooks apart; and rolling lifts the hooks out cleanly instead of dragging them — which is why a wheel beats a sled on almost every surface.</p>\n</div>'},{id:"elastic-force-hookes-law",title:"Elastic Force & Hooke's Law",content:"\n<p>Stretch a spring and it pulls back; squash a foam ball and it pushes out; sit on a mattress and it supports you. This restoring push or pull is the <strong>elastic force</strong> — it appears when an object is deformed and always acts to restore the original shape.</p>\n<p>Robert Hooke discovered in 1660 that springs are beautifully lawful. Stretch a spring twice as far and it pulls back exactly twice as hard:</p>\n<p style=\"text-align:center\"><strong>F = k \xd7 x</strong></p>\n<p>where x is the stretch (or compression) and k is the <strong>stiffness</strong> of the spring, in newtons per metre. A soft toy spring might have k = 50 N/m; a car suspension spring, 50,000 N/m. The law holds up to the <strong>elastic limit</strong> — overstretch a spring and it stays deformed, and the law (like the spring) is broken.</p>\n<p><strong>Worked example.</strong> A spring with k = 200 N/m is stretched by 5 cm = 0.05 m. The elastic force: F = 200 N/m \xd7 0.05 m = <strong>10 N</strong>. Hang a 1 kg mass (weight ≈ 10 N) from this spring and it stretches exactly 5 cm — the spring's pull grows with the stretch until it balances the weight, and everything hangs in equilibrium.</p>\n<p>This proportionality is precisely what makes a <strong>spring scale</strong> work: since stretch is proportional to force, a scale of equal marks along the spring's travel reads force directly. Kitchen scales, luggage scales, and the dynamometers of the physics lab are all Hooke's law with a pointer attached.</p>\n<p>Even \"rigid\" objects obey Hooke's law in miniature. A concrete floor sags imperceptibly under your feet and pushes back with precisely your weight; a table compresses a hair's breadth under a book. The <strong>support force</strong> that solid surfaces exert is elastic force — solids are simply springs too stiff to see flexing.</p>\n<div class=\"did-you-know\">\n  <h4>Did You Know? Bungee Jumping Is Applied Hooke</h4>\n  <p>A bungee cord is a giant soft spring. Designers choose its stiffness k and length so that the elastic force builds gradually, stopping a jumper over many metres with forces the body finds thrilling instead of injurious. The same calculation, with sterner numbers, designs climbing ropes and car crumple zones: stopping people is always a Hooke's-law problem.</p>\n</div>"},{id:"force-diagrams-and-resultants",title:"Force Diagrams, Balance & Resultants",content:"\n<p>Real objects rarely feel just one force — a book on a table feels gravity and the table's support; a towed sled feels the rope, gravity, the snow's support, and friction. To think clearly, physicists draw a <strong>force diagram</strong>: the object reduced to a box or dot, with one labelled arrow per force, each arrow's length showing its strength.</p>\n<p>The paydown is the <strong>resultant</strong> — the single force that would have the same effect as all of them combined. Along one line the arithmetic is simple:</p>\n<ul>\n  <li>Same direction: add. 300 N + 200 N of two people pushing a car = <strong>500 N</strong> forward.</li>\n  <li>Opposite directions: subtract; the resultant points with the larger force. In a tug-of-war, 400 N left vs 350 N right gives a resultant of <strong>50 N left</strong>.</li>\n</ul>\n<p>Now Newton's first law snaps into sharper focus:</p>\n<div class=\"key-concept\">\n  <h4>Key Concept: Balanced vs Unbalanced</h4>\n  <p>If the forces on an object <strong>balance</strong> (resultant = 0), its motion does not change: at rest it stays at rest; moving, it keeps its exact speed and direction. Only an <strong>unbalanced</strong> resultant changes motion. Constant velocity is therefore <em>not</em> evidence of a driving force winning — it is evidence of a perfect tie.</p>\n</div>\n<p><strong>Worked example.</strong> A car cruises down a straight highway at a steady 100 km/h. The engine drives it forward with 1,200 N while air resistance and rolling friction drag backward with a combined 1,200 N. Resultant: 0. The car keeps its velocity — moving fast, yet in perfect force balance, exactly like a parked car as far as the resultant is concerned. If the driver presses the accelerator and the drive force rises to 1,700 N, the resultant becomes 500 N forward and the car speeds up; ease off, and a backward resultant slows it.</p>\n<p>A useful reading habit: force diagrams tell you about <em>change</em>. See an object speeding up, slowing, or turning? Hunt for the unbalanced force. See steady motion or rest? Every arrow must be cancelled by another. Practising this one skill — diagram first, verdict second — is the surest way to make the rest of mechanics feel easy.</p>"}],quiz:[{question:"What does Newton's first law state?",options:["Every force has an equal and opposite reaction","Objects always slow down and stop unless a force keeps pushing them","An object keeps its state of rest or steady straight-line motion unless a force changes it","Heavier objects fall faster than lighter ones"],correctIndex:2,explanation:"Motion needs no force to continue — only to change. The everyday feeling that things 'naturally stop' is caused by friction, a real force doing the stopping. Remove it, and coasting lasts forever."},{question:"A bus brakes suddenly and the passengers lurch forward. Why?",options:["Their bodies keep moving at the old speed by inertia while the bus slows","The brakes push the passengers toward the front of the bus","Air inside the bus pushes them forward","Gravity acts more strongly during braking"],correctIndex:0,explanation:"No forward force acts on the passengers at all. The bus slows under them, but their bodies — by inertia — continue at the previous speed until seats, handrails, or seatbelts supply the slowing force."},{question:"A spring with stiffness k = 200 N/m is stretched by 5 cm (0.05 m). What force does it pull back with?",options:["1,000 N","40 N","4 N","10 N"],correctIndex:3,explanation:"Hooke's law: F = k \xd7 x = 200 N/m \xd7 0.05 m = 10 N. Watch the units — the stretch must be in metres. This proportionality between force and stretch is exactly what makes spring scales work."},{question:"The forces on a moving car are perfectly balanced (resultant = 0). What happens to the car?",options:["It gradually slows to a stop","It keeps moving at constant speed in a straight line","It immediately stops","It speeds up slowly"],correctIndex:1,explanation:"Balanced forces mean no change in motion — which for a moving object means constant velocity, not stopping. A cruising car with drive force exactly matching air resistance and friction is in the same force situation as a parked one."},{question:"In a tug-of-war, one team pulls with 400 N and the other with 150 N in the opposite direction. What is the resultant force on the rope?",options:["550 N toward the stronger team","275 N toward the stronger team","250 N toward the stronger team","Zero — the forces cancel"],correctIndex:2,explanation:"Opposite forces along one line subtract: 400 N − 150 N = 250 N, pointing toward the stronger team. Only equal opposite forces (400 vs 400) would balance and leave the rope's motion unchanged."}]},{id:"pressure-and-buoyancy",title:"Pressure & Buoyancy",subtitle:"P = F/A, Pascal, and Archimedes — the celebrated grade-8 block on fluids at rest",sections:[{id:"pressure",title:"Pressure: P = F/A",content:'\n<p>Why can you push a drawing pin into wood with a thumb, but not the same thumb alone? Why do snowshoes keep you on top of snow that swallows your boots? The answer in both cases is not force but <strong>pressure</strong> — how concentrated a force is over the area that carries it:</p>\n<p style="text-align:center"><strong>P = F/A</strong> (pressure = force \xf7 area)</p>\n<p>The unit is the <strong>pascal (Pa)</strong>: one newton spread over one square metre. A pascal is tiny — a sheet of paper lying flat presses on the table with about 1 Pa — so kilopascals (kPa, thousands) are the everyday currency.</p>\n<p><strong>Worked example.</strong> A 60 kg person weighs about 600 N. Standing in boots with a total sole area of 0.03 m\xb2, they press on the snow with P = 600 N \xf7 0.03 m\xb2 = <strong>20,000 Pa</strong> — and punch through the crust. On snowshoes of total area 0.3 m\xb2: P = 600 \xf7 0.3 = <strong>2,000 Pa</strong>, one tenth the pressure, and the snow holds. Same person, same force, different area — different outcome.</p>\n<p>Once you have the idea, you see area engineering everywhere:</p>\n<ul>\n  <li><strong>Making pressure small</strong> (spread the force): wide tractor tires and tank tracks on soft ground, broad foundations under buildings, wide shoulder straps on heavy backpacks.</li>\n  <li><strong>Making pressure large</strong> (concentrate the force): knife edges, needles, nails, ice skates, the drawing pin — whose point shrinks A so much that a modest thumb-force creates millions of pascals at the tip.</li>\n</ul>\n<p>The formula also runs backwards. A firm handshake force of 50 N applied through a needle point of one millionth of a square metre delivers 50,000,000 Pa — enough to pierce skin; that is the entire engineering principle of the syringe.</p>\n<div class="analogy">\n  <h3>Analogy: Butter on Bread</h3>\n  <p>Pressure is force the way thickness is butter: the same pat of butter spread over one slice lies thick, over ten slices lies thin. Same total force (butter), different area (bread), different pressure (thickness at each point). Sharp tools are simply devices for buttering all the force onto one crumb.</p>\n</div>'},{id:"pressure-in-liquids",title:"Pressure in Liquids: Deeper Means Stronger",content:"\n<p>Solids push only where they touch, and only downward under gravity. Liquids play by stranger rules, because their particles flow and shove in every direction:</p>\n<ul>\n  <li><strong>Liquid pressure acts in all directions</strong> — down, sideways, and even upward. A submerged diver feels squeezing on every side; water spurts out of a hole in a bottle's <em>side</em> just as readily as its bottom.</li>\n  <li><strong>Pressure grows with depth.</strong> Each layer of water must carry the weight of all the water above it, so the deeper you go, the greater the squeeze. In fresh water the rule of thumb is <strong>about 10 kPa for every metre of depth</strong> — one full atmosphere of extra pressure for every 10 m.</li>\n  <li><strong>Only depth matters, not width.</strong> At 2 m down, the pressure is the same in a narrow test tube, a swimming pool, and a lake. A denser liquid squeezes harder at the same depth: mercury, 13.6 times denser than water, produces 13.6 times the pressure.</li>\n</ul>\n<p><strong>Worked example.</strong> A dam holds a reservoir 40 m deep. Near the surface the extra water pressure is a few kPa; at the base it is about 10 kPa/m \xd7 40 m = <strong>400 kPa</strong> — four atmospheres, roughly the pressure in a racing-bike tire, pushing on every square metre of concrete. That is why dams are always built dramatically thicker at the bottom: the wall is a graph of pressure versus depth, drawn in concrete.</p>\n<p>The same arithmetic disciplines divers. At 20 m down, a scuba diver bears 200 kPa of water pressure on top of the atmosphere's 100 — triple the surface total. Ears must equalize; ascent must be slow; every diving rule is written by pressure-with-depth.</p>\n<div class=\"did-you-know\">\n  <h4>Try It Yourself: The Three-Hole Bottle</h4>\n  <p>Take a plastic bottle and poke three small holes in a vertical line — near the top, middle, and bottom. Fill it with water over a sink. The bottom jet shoots out farthest, the top one dribbles: deeper water is under higher pressure, and the jets measure it for you. You have built a working pressure-versus-depth demonstration for free.</p>\n</div>"},{id:"atmospheric-pressure",title:"The Ocean of Air: Atmospheric Pressure",content:'\n<p>You live at the bottom of an ocean — an ocean of air hundreds of kilometres deep. Air has weight (a cubic metre of it is about 1.3 kg), and the whole column stacked above your head presses down with a pressure of about <strong>100 kPa</strong> at sea level — 100,000 newtons on every square metre, equivalent to a 1 kg mass pressing on every square centimetre of your body.</p>\n<p>Why aren\'t you crushed? Because air pressure pushes in <em>all</em> directions — up, down, sideways — and the fluids inside your body push outward just as hard. You only notice the atmosphere when you create an imbalance, and then its strength is startling:</p>\n<ul>\n  <li><strong>Drinking through a straw:</strong> you don\'t pull the drink up — you lower the pressure in your mouth, and the atmosphere pushes the liquid up the straw for you.</li>\n  <li><strong>Suction cups:</strong> squeezing out the air leaves the atmosphere pressing the cup against the wall with nothing pushing back.</li>\n  <li><strong>The collapsing can:</strong> steam-fill a can, seal it, cool it — the steam condenses, inside pressure plummets, and the atmosphere crumples steel like paper.</li>\n</ul>\n<p><strong>Worked example.</strong> In 1643, Torricelli sealed a long glass tube, filled it with mercury, and upended it in a dish. The mercury fell until a column about <strong>760 mm</strong> high remained, held up by nothing but atmospheric pressure pressing on the dish. That column is the atmosphere\'s measuring stick — the first <strong>barometer</strong> — and "760 mm of mercury" still means standard pressure (101.3 kPa) today. Water, 13.6 times less dense, would need a tube over 10 m tall: the reason no suction pump on Earth can lift water higher than about 10 m.</p>\n<div class="did-you-know">\n  <h4>Try It Yourself: The Upside-Down Glass</h4>\n  <p>Fill a glass to the brim with water, press a stiff card flat on top, hold the card, and flip the glass over a sink. Let go of the card: it stays, holding the water in. The atmosphere pushes up on the card with roughly 100 kPa — hundreds of newtons on a card that size — while the water above pushes down with only a few. The air wins effortlessly.</p>\n</div>\n<p>Weather forecasters watch the barometer because falling pressure signals rising, stormy air; mountaineers feel pressure drop about 10 kPa per kilometre of altitude, which is why ears pop and high-altitude tea is disappointingly lukewarm — water boils below 100 \xb0C when the air presses down less.</p>'},{id:"pascals-principle",title:"Pascal's Principle & Hydraulic Machines",content:'\n<p>Squeeze one end of a sealed tube of toothpaste and paste comes out the other. Blaise Pascal turned that everyday fact into a law of nature: <strong>pressure applied to an enclosed fluid is transmitted undiminished to every part of the fluid and the walls of its container</strong>. Push on a trapped liquid anywhere, and the extra pressure appears everywhere — instantly, in all directions, at full strength.</p>\n<p>That sounds modest. It is actually a force-multiplying machine. Connect two cylinders with a pipe, fill with oil, and fit pistons: a small piston of area 1 cm\xb2 and a large one of 100 cm\xb2. Push the small piston with 10 N:</p>\n<ol>\n  <li>Pressure created: P = F/A = 10 N \xf7 0.0001 m\xb2 = 100,000 Pa.</li>\n  <li>Pascal: that same 100,000 Pa arrives under the large piston.</li>\n  <li>Force delivered: F = P \xd7 A = 100,000 Pa \xd7 0.01 m\xb2 = <strong>1,000 N</strong>.</li>\n</ol>\n<p>Ten newtons in, a thousand out — a hundredfold gain, set entirely by the ratio of piston areas. This is the <strong>hydraulic press</strong>, and it is everywhere: car brake pedals (your foot\'s push travels through brake fluid to all four wheels at once, equally — Pascal guarantees the balance), the jacks that lift cars, excavator arms, garbage-truck compactors, dentist chairs.</p>\n<p>There is no free lunch, only a fair trade. To raise the large piston 1 cm, the small piston must travel 100 cm, pushing through the same volume of fluid. You gain force exactly as much as you give up distance — a preview of the "golden rule of mechanics" waiting in the final chapter.</p>\n<div class="analogy">\n  <h3>Analogy: The Crowd in a Sealed Room</h3>\n  <p>A trapped liquid behaves like a tightly packed crowd in a closed room: shove one person at the door and the push propagates shoulder-to-shoulder until everyone, everywhere, presses outward a little harder — on every wall, in every direction, not just along the line of your shove. Liquids transmit pressure, not force — and pressure has no favourite direction.</p>\n</div>\n<p>Why liquids and not gases? Gases work (air brakes on trucks) but compress like sponges, making motion soft and delayed. Liquids are practically incompressible — squeeze water with 100 atmospheres and it shrinks by only half a percent — so hydraulic machines respond stiffly and immediately.</p>'},{id:"archimedes-and-floating",title:"Archimedes' Principle: Why Ships Float",content:'\n<p>Everything underwater feels lighter — you can lift a friend in a swimming pool. The lift is real: an upward <strong>buoyant force</strong> acts on any object in a fluid. Its origin is pressure-with-depth: water presses on the object\'s bottom harder than on its top (the bottom is deeper), and the mismatch adds up to a net upward push.</p>\n<div class="key-concept">\n  <h4>Archimedes\' Principle</h4>\n  <p>The buoyant force on an object equals the <strong>weight of the fluid it displaces</strong>. Push aside 2 litres of water (which weigh 20 N) and the water pushes you up with exactly 20 N — regardless of what you are made of.</p>\n</div>\n<p><strong>Worked example.</strong> A stone of volume 500 cm\xb3 and mass 1.5 kg (weight 15 N) is lowered into water. It displaces 500 cm\xb3 of water, which has mass 0.5 kg and weight 5 N. Buoyant force: <strong>5 N upward</strong>. The stone\'s apparent weight underwater is 15 − 5 = 10 N — a spring scale hooked to it reads exactly that. Buoyancy helps, but 5 N cannot beat 15 N: the stone sinks.</p>\n<p>The contest is always the same: weight down versus buoyancy up.</p>\n<ul>\n  <li><strong>Weight &gt; buoyancy</strong> (object denser than the fluid): it sinks.</li>\n  <li><strong>Weight &lt; buoyancy when fully submerged</strong> (object less dense): it rises and pops up, then floats — settling exactly deep enough that the water it displaces weighs precisely as much as it does. A floating object displaces its own weight of fluid.</li>\n</ul>\n<p>Now the steel ship makes complete sense. A 100,000-tonne ship settles until it has pushed aside 100,000 tonnes of seawater — its hollow hull has volume to spare for that. Load more cargo and it rides lower, displacing more; the painted <strong>Plimsoll line</strong> on every hull marks the legal limit. Submarines pump water into ballast tanks to make weight beat buoyancy (dive) and blow it out with compressed air to reverse the verdict (surface). Hot-air balloons float on the atmosphere by the same principle — a balloon full of hot, thin air weighs less than the cool air it displaces.</p>\n<div class="did-you-know">\n  <h4>Did You Know? The Original "Eureka!"</h4>\n  <p>King Hiero of Syracuse suspected his goldsmith had cut the crown\'s gold with silver. Archimedes (c. 250 BCE) realized in the bath that submerging the crown reveals its volume — and volume plus weight gives density. The crown displaced more water than an equal weight of pure gold: less dense, therefore adulterated. Legend says he ran home shouting "Eureka!", too excited to dress. The method — weigh it, dunk it, divide — is exactly the ρ = m/V experiment from the last chapter.</p>\n</div>'}],quiz:[{question:"A 600 N person stands on skis with a total area of 0.03 m\xb2. What pressure do they exert on the snow?",options:["18 Pa","20,000 Pa","180,000 Pa","2,000 Pa"],correctIndex:1,explanation:"P = F/A = 600 N \xf7 0.03 m\xb2 = 20,000 Pa. Spread the same 600 N over ten times the area and the pressure drops tenfold — the entire design principle behind skis, snowshoes, and tank tracks."},{question:"Why are dams built much thicker at the bottom than at the top?",options:["Water pressure increases with depth, so the base must withstand the greatest push","The extra thickness raises the dam's own weight so it cannot float away","Deeper water is colder and expands against the wall","It is cheaper to pour concrete at the bottom"],correctIndex:0,explanation:"Liquid pressure grows about 10 kPa per metre of water depth, so a 40 m reservoir pushes forty times harder at its base than one metre down. The dam's profile is essentially a pressure-versus-depth graph built in concrete."},{question:"In a hydraulic press, a 10 N push on a 1 cm\xb2 piston delivers what force at a connected 100 cm\xb2 piston?",options:["10 N — force is transmitted unchanged","0.1 N","1,000 N","100,000 N"],correctIndex:2,explanation:"Pascal's principle transmits pressure, not force: 10 N \xf7 1 cm\xb2 of pressure appears under the big piston too, and over 100 cm\xb2 that pressure delivers 100 times the force — 1,000 N. The catch: the small piston must move 100 times farther."},{question:"According to Archimedes' principle, the buoyant force on a submerged object equals…",options:["the object's own weight","the weight of the fluid the object displaces","the object's density times its depth","the atmospheric pressure on the fluid's surface"],correctIndex:1,explanation:"Buoyancy equals the weight of displaced fluid — displace 500 cm\xb3 of water (5 N) and you get 5 N of lift, whatever you are made of. Whether you float is then a contest between that lift and your own weight."},{question:"Torricelli's barometer holds up a mercury column about 760 mm tall. What holds the mercury up?",options:["The vacuum at the top of the tube sucks it upward","Surface tension between mercury and glass","The glass tube squeezes the mercury","Atmospheric pressure pushing on the mercury in the open dish"],correctIndex:3,explanation:"A vacuum cannot pull — it simply pushes with nothing. The atmosphere presses down on the open dish with about 101 kPa, and that push supports 760 mm of mercury. When air pressure changes with the weather, the column height changes with it: a barometer."}]},{id:"work-energy-power-and-machines",title:"Work, Energy, Power & Machines",subtitle:"W = Fd, energy conservation, and why no machine can cheat the golden rule of mechanics",sections:[{id:"work",title:"Work: W = Fd",content:'\n<p>In physics, <strong>work</strong> has a strict meaning far narrower than the everyday word: work is done only when a <strong>force moves something along its direction</strong>. The amount is the force times the distance moved:</p>\n<p style="text-align:center"><strong>W = F \xd7 d</strong></p>\n<p>The unit is the <strong>joule (J)</strong>: one newton acting through one metre. Lifting a small apple (weight ≈ 1 N) from the floor to a table 1 m up is almost exactly one joule — a handy mental anchor.</p>\n<p><strong>Worked example.</strong> You lift a 10 kg box (weight ≈ 100 N) from the floor onto a 1.5 m shelf. Work done against gravity: W = 100 N \xd7 1.5 m = <strong>150 J</strong>. Lift it twice as high, or lift a box twice as heavy: 300 J either way. Force and distance enter as equals.</p>\n<p>The strict definition produces verdicts that surprise the muscles:</p>\n<ul>\n  <li><strong>Holding a heavy suitcase perfectly still:</strong> force, yes (100 N up) — but d = 0, so W = 0. Your burning arms are doing physiological work inside the muscle fibres, but no work is done <em>on the suitcase</em>.</li>\n  <li><strong>Carrying the suitcase horizontally at steady speed:</strong> your force is upward, the motion is sideways — the force has no component along the motion, so again the work on the suitcase is zero.</li>\n  <li><strong>Dragging a sled 50 m with a 40 N pull along the ground:</strong> W = 40 \xd7 50 = 2,000 J. Now the force and motion line up, and real work flows.</li>\n</ul>\n<p>Nature keeps double-entry books. When you do 150 J of work lifting the box, gravity does 150 J of <em>negative</em> work resisting you — and stands ready to pay all 150 J back the moment the box falls. That repayment idea is the doorway to energy, next section.</p>\n<div class="analogy">\n  <h3>Analogy: Work Is Physics\' Currency</h3>\n  <p>Think of the joule as money and work as a payment. You pay 150 J into the box by lifting it; the box now holds 150 J of credit (energy) it can spend by falling. No motion along the force, no transaction — which is why the still, aching suitcase-holder is, in physics\' cold ledger, spending nothing on the suitcase at all.</p>\n</div>'},{id:"kinetic-and-potential-energy",title:"Kinetic & Potential Energy — and Conservation",content:'\n<p><strong>Energy is the ability to do work</strong> — the credit an object holds toward future pushes through distances. It is measured in joules, the same unit as work, because energy is simply stored work. In mechanics it comes in two great forms:</p>\n<ul>\n  <li><strong>Kinetic energy</strong> — energy of motion. A rolling bowling ball can do work on the pins; a moving hammer drives a nail. More mass and (especially) more speed mean more kinetic energy — doubling speed roughly <em>quadruples</em> it, which is why highway crashes are so much worse than parking-lot bumps.</li>\n  <li><strong>Potential energy</strong> — stored energy of position or shape. A raised hammer, water behind a dam, a drawn bow, a compressed spring: each holds work done earlier, waiting for release.</li>\n</ul>\n<p><strong>Worked example.</strong> Lifting a 2 kg hammer (weight ≈ 20 N) a height of 1.5 m stores W = 20 N \xd7 1.5 m = <strong>30 J</strong> of potential energy. Let it fall: gravity pays back the 30 J, converting it into kinetic energy on the way down, and the hammer arrives at the nail carrying 30 J to spend.</p>\n<p>Watch a playground swing and you see the two forms trading places twice per cycle: highest points, all potential; bottom of the arc, all kinetic; and the sum stays fixed. That constancy is one of the deepest laws in all of science:</p>\n<div class="key-concept">\n  <h4>Key Concept: Conservation of Energy</h4>\n  <p>Energy is never created and never destroyed — only transformed from one form to another or transferred from one object to another. Every machine, every collision, every process in this entire curriculum balances its energy books exactly. No exception has ever been observed.</p>\n</div>\n<p>But real swings do stop. Friction and air resistance skim energy off every pass — not destroying it, converting it to heat, gently warming the air and bearings. "Lost" energy is just energy that left the account you were watching for the messy small change of thermal energy — the subject of the next course, Heat.</p>\n<div class="did-you-know">\n  <h4>Did You Know? A Chocolate Bar Is a Mountain of Joules</h4>\n  <p>One 50 g chocolate bar stores about 1,000,000 J of chemical energy. Lifting your 700 N body up one 3 m floor costs W = 700 \xd7 3 = 2,100 J — so one bar funds, in principle, nearly 500 floors of climbing. Muscles are only about 20% efficient, so reality is closer to 100 floors — still the Empire State Building on a single snack.</p>\n</div>'},{id:"power",title:"Power: How Fast the Work Gets Done",content:'\n<p>A crane and a worker with a rope can both raise a tonne of bricks to the tenth floor — the same work, W = Fd, either way. The difference is <em>time</em>: the crane does it in half a minute, the worker takes all afternoon. The rate of doing work is <strong>power</strong>:</p>\n<p style="text-align:center"><strong>P = W/t</strong> (power = work \xf7 time)</p>\n<p>The unit is the <strong>watt (W)</strong>: one joule per second. It is the same watt as on light bulbs and phone chargers — electrical devices are rated by how fast they convert energy, which is exactly this quantity.</p>\n<p><strong>Worked example.</strong> You (weight 700 N) jog up a staircase 3 m high in 6 s. Work against gravity: W = 700 N \xd7 3 m = 2,100 J. Power: P = 2,100 J \xf7 6 s = <strong>350 W</strong> — about half a horsepower, and roughly the limit a fit human can sustain for more than a few seconds. Sprint it in 3 s and your power doubles to 700 W, though the work stays 2,100 J.</p>\n<p>Calibrate your sense of the watt:</p>\n<table>\n  <thead>\n    <tr><th>Source</th><th>Typical power</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Human, steady effort</td><td>75–100 W</td></tr>\n    <tr><td>Human, brief sprint</td><td>up to ≈ 1,000 W</td></tr>\n    <tr><td>One horsepower</td><td>746 W</td></tr>\n    <tr><td>Family car engine</td><td>≈ 80,000 W</td></tr>\n    <tr><td>Large wind turbine</td><td>≈ 5,000,000 W</td></tr>\n  </tbody>\n</table>\n<p>The "horsepower" is James Watt\'s own marketing invention from the 1780s: selling steam engines, he needed to tell mine owners how many horses each engine replaced, so he measured what a strong horse could sustain — about 746 W — and priced accordingly. The metric unit of power was later named for him; the horse got the imperial one.</p>\n<div class="did-you-know">\n  <h4>Try It Yourself: Measure Your Own Power</h4>\n  <p>Find a staircase, estimate its height (count steps \xd7 about 0.17 m each), and time yourself walking up, then running. Compute W = your weight in newtons \xd7 height, then P = W/t for each trip. Most people find walking gives 200–300 W and a hard run 600–1,000 W. You have just performed the classic physics-lab power experiment with a phone stopwatch.</p>\n</div>'},{id:"levers-and-moments",title:"Levers & the Law of Moments",content:'\n<p>"Give me a place to stand," Archimedes boasted, "and I will move the Earth." His instrument was the <strong>lever</strong> — a rigid bar pivoting on a fixed point, the <strong>fulcrum</strong> — and it is humanity\'s oldest force multiplier: crowbars, seesaws, scissors, wheelbarrows, bottle openers, your own forearm.</p>\n<p>What a force does to a lever depends not just on its strength but on <em>where it acts</em>. The turning effectiveness of a force is its <strong>moment</strong>:</p>\n<p style="text-align:center"><strong>moment = force \xd7 distance from the fulcrum</strong></p>\n<p>A lever balances when the turning effects match:</p>\n<div class="key-concept">\n  <h4>The Law of Moments</h4>\n  <p>A lever is in balance when the moment turning it one way equals the moment turning it the other: F₁ \xd7 d₁ = F₂ \xd7 d₂. A small force far from the fulcrum can hold — or beat — a large force close in.</p>\n</div>\n<p><strong>Worked example.</strong> A 600 N adult sits 1 m from a seesaw\'s pivot. Where must a 300 N child sit to balance? Moments must match: 600 N \xd7 1 m = 300 N \xd7 d, so d = <strong>2 m</strong>. Half the force needs twice the arm — the seesaw is a moment-balancing instrument that every playground calibrates daily.</p>\n<p><strong>Worked example.</strong> A crowbar 1 m long is set with its fulcrum 5 cm from the end under a crate weighing 1,000 N. Your hands push at 95 cm from the fulcrum. Required force: F \xd7 0.95 m = 1,000 N \xd7 0.05 m, giving F ≈ <strong>53 N</strong> — a one-finger push lifting a crate, with a force gain of about 19.</p>\n<p>Note what the crowbar quietly charges you: your end sweeps through 19 times more distance than the crate rises. The force is multiplied; the work, F \xd7 d, is not. Hold that thought for the final section.</p>\n<div class="analogy">\n  <h3>Analogy: The Stubborn Door</h3>\n  <p>You already play the law of moments daily: you push a door at the handle, as far from the hinges as possible. Push instead right beside the hinges and the same door feels immovable — tiny d, tiny moment. Door designers put handles at the far edge because everyone prefers small forces with long arms.</p>\n</div>'},{id:"machines-efficiency-golden-rule",title:"Pulleys, Efficiency & the Golden Rule of Mechanics",content:'\n<p>The lever\'s trade — less force, more distance — turns out to be the universal contract of every simple machine.</p>\n<p>A single <strong>fixed pulley</strong> (wheel on the well-top) multiplies nothing: you pull down with 100 N to raise 100 N of bucket. Its gift is redirection — pulling down is more convenient than hauling up. Add a <strong>movable pulley</strong> riding on the load, and the load hangs from <em>two</em> rope strands, each carrying half: now 200 N of load needs only about 100 N of pull. The price appears immediately — to lift the load 1 m you must haul in 2 m of rope, because both supporting strands must shorten. Block-and-tackle systems with more strands push the trade further: one sailor, six strands, six-fold force gain, six metres of rope hauled per metre of lift.</p>\n<p>The <strong>inclined plane</strong> makes the same bargain: rolling a 900 N barrel up a 3 m-long ramp onto a 1 m-high truck bed needs (ideally) only 300 N of push — one third the force, three times the distance. Levers, pulleys, ramps, screws, hydraulic presses: centuries of tinkering distilled into one law that no gearing can evade:</p>\n<div class="key-concept">\n  <h4>The Golden Rule of Mechanics</h4>\n  <p>Whatever a machine gains in force, it pays for in distance. No machine reduces the <em>work</em>: F \xd7 d out can never exceed F \xd7 d in. Machines reshape work into convenient forces — they never create it. This is energy conservation wearing overalls.</p>\n</div>\n<p>Reality is slightly worse than the golden rule, never better: friction in axles and the weight of the pulleys themselves eat a share. The honest scorecard is <strong>efficiency</strong>:</p>\n<p style="text-align:center"><strong>efficiency = (useful work out \xf7 work put in) \xd7 100%</strong></p>\n<p><strong>Worked example.</strong> Using the ramp, you actually push with 350 N (not the ideal 300 N) over its 3 m: work in = 350 \xd7 3 = 1,050 J. Useful work = lifting 900 N by 1 m = 900 J. Efficiency = 900 \xf7 1,050 \xd7 100% ≈ <strong>86%</strong> — the missing 150 J became heat in the scraping surfaces. Well-oiled pulleys reach 90%+; a car engine manages only about 25%; and every perpetual-motion machine ever proposed has failed for exactly this reason: you cannot win, and you cannot even break even.</p>'}],quiz:[{question:"A mover pushes a crate 4 m across a floor with a steady 50 N force. How much work is done?",options:["12.5 J","54 J","200 J","2,000 J"],correctIndex:2,explanation:"W = F \xd7 d = 50 N \xd7 4 m = 200 J. Work is force times the distance moved along the force's direction — both factors matter equally."},{question:"You carry a heavy suitcase 100 m along level ground at constant speed. How much work does your upward supporting force do on the suitcase?",options:["Zero — the force is vertical but the motion is horizontal","Your force \xd7 100 m","The suitcase's weight \xd7 100 m","It depends on how fast you walk"],correctIndex:0,explanation:"Physics work requires motion along the force. Your force points up, the motion is sideways, so W = 0 on the suitcase — however tired your arms feel. Lifting it onto a shelf, by contrast, is real work: force and motion align."},{question:"A motor does 3,000 J of work in 60 seconds. What is its power?",options:["180,000 W","3,000 W","20 W","50 W"],correctIndex:3,explanation:"P = W/t = 3,000 J \xf7 60 s = 50 W. Power is the rate of doing work — the same 3,000 J done in 10 s would be 300 W. Watts measure speed of energy conversion, not the amount."},{question:'What does the "golden rule of mechanics" say about simple machines?',options:["A machine multiplies both force and distance if built well","Whatever a machine gains in force, it loses in distance — work is never multiplied","Machines with more pulleys always waste more work than they save","Levers obey the rule but hydraulic presses do not"],correctIndex:1,explanation:"Every machine — lever, pulley, ramp, hydraulic press — trades force against distance, leaving the ideal work F \xd7 d unchanged. It is energy conservation in disguise, and it is why perpetual-motion machines are impossible."},{question:"You put 400 J of work into a pulley system, which does 300 J of useful lifting. What is its efficiency, and where did the rest go?",options:["75% — the remaining 100 J became heat through friction","133% — the machine multiplied the work","25% — the remaining energy was destroyed","75% — the remaining 100 J vanished from the universe"],correctIndex:0,explanation:"Efficiency = 300 \xf7 400 \xd7 100% = 75%. The missing 100 J was not destroyed — energy never is — it was converted to heat in rubbing axles and rope. Real machines always land below 100%, never above."}]}]},{id:"heat-and-particle-model",number:6,title:"Heat & the Particle Model",description:"See heat through the eyes of jostling molecules: the particle model, temperature and internal energy, heat transfer, and the engines that turned thermal physics into the industrial revolution.",phase:2,chapters:[{id:"the-particle-model-of-matter",title:"The Particle Model of Matter",subtitle:"Molecules, diffusion, and Brownian motion — the evidence that matter is made of moving particles",sections:[{id:"everything-is-particles",title:"Everything Is Made of Moving Particles",content:'\n<p>Here is the single most useful idea in all of thermal physics: <strong>everything around you — the air, your coffee, this screen — is made of unimaginably tiny particles that never stop moving.</strong> Solids, liquids and gases are all built from molecules (or atoms), and those particles are in constant, random motion. The hotter something is, the faster they move. That one sentence will explain almost everything in this subject.</p>\n<p>How tiny is tiny? A single water molecule is about 0.3 nanometres across. A single drop of water contains roughly <strong>1,500,000,000,000,000,000,000 molecules</strong> — about 200 billion times more molecules than there are people on Earth. They are far too small to see, even with an ordinary microscope, which is exactly why it took humanity so long to accept that they exist.</p>\n<div class="analogy">\n  <h3>Analogy: The Crowd You Can\'t See</h3>\n  <p>Imagine watching a stadium from an aeroplane so high up that the crowd blurs into a smooth patch of colour. You\'d swear it was one continuous thing. Matter is like that: it looks smooth and continuous only because we are "too far away" — the individual particles are below the limit of what our eyes can resolve.</p>\n</div>\n<p>The particle model makes three core claims:</p>\n<ul>\n  <li>All matter is made of tiny particles with empty space between them.</li>\n  <li>The particles are in constant, random motion — even in a solid, where they vibrate in place.</li>\n  <li>The particles attract each other, strongly when close (solids), weakly when far apart (gases).</li>\n</ul>\n<p>Notice what temperature becomes in this picture: not a mysterious fluid, but simply a measure of <strong>how vigorously the particles are moving</strong>. Heat a pan and its atoms vibrate harder. Cool a drink and its molecules slow down. When we say "this soup is hot," we are really saying "the molecules in this soup are jiggling furiously."</p>\n<div class="key-concept">\n  <h4>Key Concept</h4>\n  <p>Hot = fast particles. Cold = slow particles. Every phenomenon in this subject — melting, boiling, expansion, pressure, conduction — is this one idea wearing different costumes.</p>\n</div>'},{id:"diffusion-and-brownian-motion",title:"Diffusion & Brownian Motion: The Evidence",content:"\n<p>Claiming that matter is made of invisible moving particles is bold. What's the evidence? Two beautiful, everyday phenomena.</p>\n<p><strong>Diffusion</strong> is the spreading of one substance through another, all by itself. Open a bottle of perfume in the corner of a room, and within minutes someone across the room smells it — with no wind, no stirring. Drop a tea bag in still hot water and watch the colour creep outward. The particle model explains this effortlessly: perfume molecules are being knocked around by air molecules in a random zigzag, gradually wandering everywhere. No particles, no explanation.</p>\n<p>Crucially, <strong>diffusion is faster when it's hotter</strong> — sugar dissolves and spreads far faster in hot tea than iced tea — exactly as you'd expect if temperature means faster-moving particles.</p>\n<p><strong>Brownian motion</strong> is the clincher. In 1827, botanist Robert Brown looked through a microscope at pollen grains suspended in water and saw them jittering endlessly, as if alive. Dust did it too, so life wasn't the cause. The real reason: each visible grain is being bombarded from all sides by billions of invisible water molecules. Mostly the hits cancel out, but at any instant slightly more molecules strike one side than the other, so the grain lurches randomly. In 1905 Albert Einstein worked out the mathematics of this jitter, and Jean Perrin's experiments confirmed it — finally convincing the last scientific sceptics that atoms and molecules are physically real.</p>\n<div class=\"did-you-know\">\n  <h4>Did You Know?</h4>\n  <p>Perrin used Einstein's Brownian-motion equations to count how many molecules are in a gram of matter — and won the 1926 Nobel Prize for it. The jiggling of pollen let humans \"weigh\" the invisible.</p>\n</div>\n<div class=\"key-concept\">\n  <h4>Try It Yourself</h4>\n  <p>Fill one glass with hot tap water and one with cold. Let both go completely still, then gently add one drop of food colouring (or a splash of milk into tea) to each without stirring. Watch for five minutes. The colour spreads visibly faster through the hot water — you are watching molecular speed with your own eyes.</p>\n</div>"},{id:"three-states-one-model",title:"Solids, Liquids, Gases: One Model, Three States",content:'\n<p>Why is ice hard, water runny, and steam invisible — when all three are the same H₂O molecules? The particle model answers with a single dial: <strong>how particle motion compares with particle attraction.</strong></p>\n<table>\n  <thead>\n    <tr><th>State</th><th>Arrangement</th><th>Motion</th><th>Everyday result</th></tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>Solid</strong></td><td>Particles packed tightly in a fixed, regular pattern</td><td>Vibrate in place, held by strong attractions</td><td>Fixed shape, fixed volume</td></tr>\n    <tr><td><strong>Liquid</strong></td><td>Particles still touching, but no fixed pattern</td><td>Slide and tumble past one another</td><td>Fixed volume, but flows to fit its container</td></tr>\n    <tr><td><strong>Gas</strong></td><td>Particles far apart — mostly empty space</td><td>Fly freely at hundreds of metres per second, colliding constantly</td><td>No fixed shape or volume; fills any container</td></tr>\n  </tbody>\n</table>\n<p>In a solid, attractions dominate: each particle is locked to its neighbours like a person holding hands in a tight formation, able to jiggle but not to swap places. Warm it and the jiggling grows until, at the melting point, particles shake loose from the fixed pattern — the solid melts. Keep heating and the fastest particles start escaping the liquid\'s surface entirely: evaporation, and eventually boiling.</p>\n<p>The model also explains humbler facts. You can\'t squeeze a liquid into a smaller volume (the particles already touch), but you <em>can</em> compress a gas easily — a bicycle pump works because air is mostly empty space. Liquids flow because their particles can slide; solids keep their shape because theirs cannot.</p>\n<div class="analogy">\n  <h3>Analogy: The Dance Floor</h3>\n  <p>A solid is a formal line dance — everyone in position, swaying on the spot. A liquid is a crowded party — people constantly brushing past each other, but the room stays full. A gas is the car park afterwards — everyone sprinting off in different directions with huge gaps between them.</p>\n</div>\n<div class="key-concept">\n  <h4>Key Concept</h4>\n  <p>Melting and boiling are not new substances appearing — they are the same particles winning (or losing) a tug-of-war between thermal motion and mutual attraction.</p>\n</div>'},{id:"gas-pressure-collisions",title:"Gas Pressure: A Storm of Tiny Collisions",content:'\n<p>Press your thumb over the end of a bicycle pump and push. You feel the trapped air push back. Nothing solid is in there — so what is pushing?</p>\n<p>The particle model\'s answer: <strong>gas pressure is the drumming of countless molecular collisions.</strong> Air molecules travel at around 500 m/s at room temperature (faster than a passenger jet), and each square centimetre of your skin is struck by roughly 10\xb2\xb3 molecules every second. Each collision gives a minuscule push; together they add up to the steady, smooth pressure of the atmosphere — about 100,000 newtons on every square metre.</p>\n<p>This picture instantly explains real behaviour:</p>\n<ul>\n  <li><strong>Squeeze a gas into less space</strong> and the same molecules hit the walls more often — pressure rises. That\'s why pumping a tyre gets harder as it fills.</li>\n  <li><strong>Heat a gas in a sealed container</strong> and the molecules speed up, hitting harder and more often — pressure rises. This is why an aerosol can warns "do not incinerate": trapped, heated gas can raise the pressure until the can bursts.</li>\n  <li><strong>Let a gas expand</strong> and collisions on each patch of wall become rarer — pressure falls. A sealed crisp packet puffs up on a mountain because the thinner outside air pushes back less.</li>\n</ul>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>Car manuals tell you to check tyre pressure "cold" for a particle-model reason: after a long drive, friction warms the air inside, its molecules strike the tyre walls harder, and the reading can rise by 10–15% — fooling you into letting air out of a correctly inflated tyre.</p>\n</div>\n<div class="key-concept">\n  <h4>Key Concept</h4>\n  <p>A gas pushes on its container because its particles are constantly colliding with the walls. More collisions, or harder collisions, mean more pressure. In Subject 12 you\'ll turn this cartoon into full kinetic theory — deriving the gas laws from nothing but Newtonian mechanics applied to molecules.</p>\n</div>\n<p>Step back and admire what the model has done in one chapter: with nothing but "tiny particles, always moving, attracting each other," we\'ve explained smells crossing a room, jittering pollen, the three states of matter, and the invisible push of the air. That explanatory power is why the particle model is the foundation stone of this whole subject.</p>'}],quiz:[{question:"A drop of food colouring slowly spreads through a glass of still water without any stirring. What does the particle model say is happening?",options:["The dye is alive and swims outward","Gravity pulls the dye evenly through the water","Water molecules constantly knock the dye molecules around in random zigzags, so they gradually wander everywhere","The water dissolves the dye into nothing, and it reappears elsewhere"],correctIndex:2,explanation:"This is diffusion: dye molecules are bombarded by fast-moving water molecules and take a random walk through the liquid. No stirring is needed — the molecular motion is the stirring. It's faster in hot water because hotter molecules move faster."},{question:"Why was Brownian motion — pollen grains jittering in water — such powerful evidence for the existence of molecules?",options:["It showed the visible jitter of grains being unevenly bombarded by invisible molecules, and Einstein's maths of the jitter matched experiment","It proved pollen grains are the smallest particles of matter","It showed that water is alive at microscopic scales","It demonstrated that heat is a fluid flowing through the water"],correctIndex:0,explanation:"Each grain lurches because at any instant slightly more water molecules strike one side than the other. Einstein predicted the statistics of this random walk in 1905, Perrin confirmed them, and even the last sceptics accepted that molecules are real."},{question:"In which state of matter are the particles touching one another but able to slide and tumble past each other?",options:["Solid","Gas","Plasma","Liquid"],correctIndex:3,explanation:"In a liquid the particles are still in contact (so liquids barely compress and keep a fixed volume) but have enough energy to slip past their neighbours — which is exactly why liquids flow and take the shape of their container."},{question:"You can easily compress the air in a bicycle pump, but you cannot noticeably compress the water in a syringe. Why?",options:["Water molecules are harder than air molecules","Gas particles are far apart with mostly empty space between them, while liquid particles are already touching","Air molecules shrink under pressure but water molecules do not","Water is heavier than air, so it resists more"],correctIndex:1,explanation:"Compressing a gas just squeezes out empty space between widely separated particles. In a liquid the particles are already in contact, so there is almost no empty space left to remove."},{question:"An aerosol can is thrown onto a bonfire (don't do this!). According to the particle model, why does the pressure inside rise dangerously?",options:["The metal walls squeeze inward and compress the gas","New gas molecules are created by the heat","The gas molecules speed up, striking the walls harder and more often","The gas molecules expand to become individually larger"],correctIndex:2,explanation:"Heating a gas makes its molecules move faster. In a sealed can they can't spread out, so they hammer the walls with more frequent, more forceful collisions — pressure climbs until the can can burst. The molecules themselves don't grow or multiply."}]},{id:"temperature-and-internal-energy",title:"Temperature & Internal Energy",subtitle:"What thermometers actually measure, and the energy hidden inside every object",sections:[{id:"what-thermometers-measure",title:"What a Thermometer Actually Measures",content:'\n<p>You\'ve used thermometers all your life — but what, exactly, do they measure? The particle model gives a sharp answer: <strong>temperature is a measure of the average kinetic energy of the particles</strong> — how fast, on average, they are jiggling or flying about. Not the total energy, not the amount of "heat stuff" — the <em>average vigour per particle</em>.</p>\n<p>A classic liquid thermometer exploits the particle model directly. When you put it in hot tea, fast tea molecules collide with the glass, making the glass particles vibrate harder, which makes the alcohol or mercury particles inside jostle harder and take up slightly more room. The liquid expands up a narrow tube, and the tube is marked with a scale. Digital thermometers instead use a sensor whose electrical resistance changes with temperature — different mechanism, same underlying question: how agitated are the particles here?</p>\n<p>Three scales matter in practice:</p>\n<table>\n  <thead>\n    <tr><th>Scale</th><th>Water freezes</th><th>Water boils</th><th>Used for</th></tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>Celsius (\xb0C)</strong></td><td>0 \xb0C</td><td>100 \xb0C</td><td>Everyday life and science in most of the world</td></tr>\n    <tr><td><strong>Fahrenheit (\xb0F)</strong></td><td>32 \xb0F</td><td>212 \xb0F</td><td>Everyday life in the USA</td></tr>\n    <tr><td><strong>Kelvin (K)</strong></td><td>273 K</td><td>373 K</td><td>Physics — starts at absolute zero</td></tr>\n  </tbody>\n</table>\n<p>The Kelvin scale hints at something profound. If temperature is average particle motion, there must be a floor: the temperature at which motion is as small as nature allows. That floor is <strong>absolute zero, −273.15 \xb0C = 0 K</strong>. You can\'t go lower, because you can\'t have less than minimal motion. (Nothing in the universe has ever quite reached it; the record is within a few billionths of a kelvin.)</p>\n<div class="key-concept">\n  <h4>Key Concept</h4>\n  <p>Temperature = average kinetic energy per particle. This is why temperature doesn\'t care how big an object is: a drop of boiling water and a bathtub of boiling water are both at 100 \xb0C, because their molecules are moving equally fast on average.</p>\n</div>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>Galileo built one of the first thermometers around 1600, but for two more centuries scientists argued about what it measured — many believed heat was an invisible fluid called "caloric" that flowed into thermometers. The particle picture finally won in the 1800s.</p>\n</div>'},{id:"temperature-vs-internal-energy",title:"Temperature, Heat & Internal Energy: Three Different Things",content:'\n<p>Here\'s a puzzle that untangles three commonly confused ideas. A spark from a firework can be over 1000 \xb0C, yet it lands on your hand harmlessly. A bathtub of water at 40 \xb0C could scald no one — yet it holds vastly more thermal energy than the spark. How can the "hotter" thing carry less energy?</p>\n<p>The resolution is to keep three ideas separate:</p>\n<ul>\n  <li><strong>Temperature:</strong> the <em>average</em> kinetic energy per particle. The spark wins — its particles are moving ferociously fast.</li>\n  <li><strong>Internal energy:</strong> the <em>total</em> energy of all the particles in an object — all their motion energy plus the energy stored in the attractions between them. The bathtub wins by an enormous margin: it has around 10\xb2⁷ molecules, the spark perhaps 10\xb9⁶. A tiny average times a colossal number beats a huge average times a tiny number.</li>\n  <li><strong>Heat:</strong> internal energy <em>in transit</em> — energy flowing from a hotter object to a colder one. Heat is not something an object contains; it\'s something that happens between objects, like a payment between bank accounts.</li>\n</ul>\n<div class="analogy">\n  <h3>Analogy: Wealth vs Salary-per-Person</h3>\n  <p>Temperature is like the average income in a group; internal energy is like the group\'s total wealth. Ten billionaires have a spectacular average (high "temperature") but a small town of ordinary earners can hold more total money (more "internal energy"). And "heat" is the money actually being transferred when the two groups trade.</p>\n</div>\n<p>Direction of flow follows immediately: <strong>heat always flows from higher temperature to lower temperature</strong>, regardless of which object has more total energy. Drop a red-hot nail (small internal energy, high temperature) into a swimming pool (huge internal energy, low temperature) and heat flows from nail to pool — never the reverse — until they reach the same temperature. That end state is called <strong>thermal equilibrium</strong>: same average energy per particle everywhere, so the net flow stops.</p>\n<div class="key-concept">\n  <h4>Key Concept</h4>\n  <p>Temperature tells you which way heat will flow. Internal energy tells you how much energy is there in total. Heat is the flow itself. Keeping these three straight is the groundwork for the first law of thermodynamics in Subject 12.</p>\n</div>'},{id:"thermal-expansion",title:"Thermal Expansion: Why Bridges Need Breathing Room",content:'\n<p>Warm almost anything and it gets slightly bigger. The particle model explains why: hotter particles jiggle through larger excursions, so each one effectively claims a little more elbow room, and the whole object swells. The particles themselves do <em>not</em> get bigger — a common misconception — they simply move more and space themselves out.</p>\n<p>The effect is small but relentless, and engineers ignore it at their peril:</p>\n<ul>\n  <li><strong>Bridges</strong> include comb-like expansion joints. A 1 km steel bridge is roughly 40 cm longer on a 35 \xb0C summer day than on a −5 \xb0C winter night; without gaps it would buckle.</li>\n  <li><strong>Railway tracks</strong> are laid with expansion gaps or stretched ("pre-tensioned") so summer heat doesn\'t warp them into snake-like kinks.</li>\n  <li><strong>Power lines</strong> are strung with visible sag: they lengthen and droop on hot days, and engineers must guarantee clearance at maximum temperature.</li>\n  <li><strong>The Eiffel Tower</strong> grows up to 15 cm taller in summer, and the sun-facing side expands more, gently tilting the top away from the sun.</li>\n</ul>\n<p>Liquids expand too — that\'s precisely how the classic thermometer works — and generally expand more than solids for the same warming. Gases expand most of all, as their particles are free to spread.</p>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>Water is a famous rebel: it expands when it <em>freezes</em> (ice occupies about 9% more volume than the water it came from), because its molecules lock into an unusually open crystal pattern. That\'s why ice floats, why pipes burst in cold snaps, and why ponds freeze from the top down — letting fish survive winter underneath.</p>\n</div>\n<div class="key-concept">\n  <h4>Try It Yourself</h4>\n  <p>Next time a metal jar lid is stuck, run hot tap water over just the lid for 20–30 seconds. The metal lid expands more (and faster) than the glass beneath it, loosening its grip — thermal expansion as a kitchen tool. For a bonus demonstration, note how a fully inflated balloon left in a hot car swells, then shrinks in the fridge: gas expansion made visible.</p>\n</div>\n<p>From here on, whenever you see gaps in pavement slabs, wavy sag in summer cables, or a thermometer\'s rising thread, you\'re seeing the same silent fact: particle motion takes up room, and more motion takes up more.</p>'}],quiz:[{question:"According to the particle model, what does temperature actually measure?",options:["The total amount of heat stored in an object","The number of particles in an object","The average kinetic energy of the object's particles","The amount of empty space between particles"],correctIndex:2,explanation:"Temperature is the average kinetic energy per particle — how vigorously they move on average. That's why a drop and a bathtub of boiling water share the same temperature: same average motion, wildly different totals."},{question:"A white-hot firework spark (over 1000 \xb0C) lands on your skin almost harmlessly, but a 40 \xb0C bathtub holds far more thermal energy. What explains this?",options:["The spark has a higher average energy per particle, but the bathtub's enormous number of particles gives it a far greater total internal energy","The spark's temperature reading is an illusion caused by its brightness","The bathtub is hotter than the spark in every sense","Sparks are made of a special substance that cannot carry energy"],correctIndex:0,explanation:"Temperature is an average; internal energy is a total. The spark's few particles move extremely fast (high temperature) but there are so few of them that the total energy is tiny — which is also why it can't transfer enough energy to burn you badly."},{question:"What is special about absolute zero (0 K, −273.15 \xb0C)?",options:["It is the temperature at which water freezes","It is the coldest temperature ever recorded in a laboratory","It is the temperature at which all substances become gases","It is the lowest possible temperature — particle motion cannot get any smaller"],correctIndex:3,explanation:"If temperature measures particle motion, there's a floor: the state of minimal possible motion. That floor is absolute zero. Laboratories have come within billionths of a kelvin, but nothing can go below it."},{question:"Why are bridges built with expansion joints?",options:["To let rainwater drain through the road surface","Because the bridge lengthens in summer heat and would buckle without room to expand","To reduce the bridge's weight","Because bridge particles grow larger in the heat and need extra space"],correctIndex:1,explanation:"Hotter particles vibrate through wider excursions, so the whole structure lengthens — roughly 40 cm for a kilometre of steel over a 40 \xb0C seasonal swing. The joints give that growth somewhere to go. Note the particles move more; they don't get bigger."},{question:"A red-hot nail is dropped into a cold swimming pool. Which statement is correct?",options:["Heat flows from the pool to the nail, because the pool has more internal energy","No heat flows, because the pool is much bigger than the nail","Heat flows from the nail to the pool until both reach the same temperature","Heat flows both ways equally from the start"],correctIndex:2,explanation:"Heat flow is directed by temperature difference, not by total energy. The nail is hotter, so energy flows nail → pool until they reach thermal equilibrium — even though the pool's total internal energy dwarfs the nail's."}]},{id:"heat-transfer",title:"Heat Transfer",subtitle:"Conduction, convection, and radiation — how thermal energy moves and how we stop it",sections:[{id:"conduction",title:"Conduction: Heat Passed Hand to Hand",content:'\n<p>Leave a metal spoon in a pot of soup and within minutes the handle — nowhere near the flame — is too hot to hold. The energy travelled <em>through</em> the solid metal. This is <strong>conduction</strong>: heat transfer by direct particle-to-particle contact, with no bulk movement of material.</p>\n<p>The particle model makes it vivid. Particles at the hot end vibrate violently and jostle their neighbours, which jostle <em>their</em> neighbours, passing the agitation down the line like a rumour through a crowd. The particles themselves stay in place; only the energy travels.</p>\n<p>Metals conduct spectacularly well for an extra reason: they contain <strong>free electrons</strong> that wander through the whole metal. These fast couriers carry energy directly from hot regions to cold ones, far outpacing the vibration relay. That\'s why copper conducts heat about 1000 times better than wool, and why good electrical conductors tend to be good heat conductors too.</p>\n<p>Poor conductors — <strong>insulators</strong> — include wood, plastic, wool, and above all <strong>trapped air</strong>, whose sparse, far-apart particles pass energy along very badly. Most cosy materials (duvets, fleece, loft insulation, double glazing) work by trapping air in tiny pockets.</p>\n<div class="key-concept">\n  <h4>Key Concept: Why Tiles Feel Colder Than Carpet</h4>\n  <p>Step from carpet to bathroom tiles barefoot and the tiles feel icy — yet both are at the same room temperature. Your skin doesn\'t sense temperature; it senses <em>how fast heat leaves it</em>. Tile conducts heat away from your foot quickly; carpet, full of trapped air, barely conducts at all. Same temperature, different conduction — different feeling.</p>\n</div>\n<p>The kitchen is a museum of conduction engineering:</p>\n<ul>\n  <li>Pans have <strong>copper or aluminium bottoms</strong> to move heat into food fast — and <strong>plastic or wooden handles</strong> to keep it away from you.</li>\n  <li>An oven glove is thick fabric full of trapped air; a wet oven glove is dangerous because water conducts about 25 times better than air.</li>\n  <li>Wooden spoons stay grippable in a boiling pot for the same reason wooden benches feel warmer than metal ones.</li>\n</ul>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>Snow is such a good insulator (roughly 90% trapped air) that a well-built igloo can hold around 0 \xb0C inside while the Arctic night outside sits at −40 \xb0C — kept warm by nothing but body heat and a small lamp.</p>\n</div>'},{id:"convection",title:"Convection: Heat That Rides the Flow",content:'\n<p>Conduction is hopeless in air and water — their particles are too loosely connected. Yet a single radiator warms a whole room and a kettle boils from a heating element at the bottom. Fluids have their own transport trick: <strong>convection</strong>, where the heated fluid itself moves, carrying its energy with it.</p>\n<p>The mechanism is pure particle model plus buoyancy. Heat the fluid at the bottom; its particles speed up and spread out, so that region becomes <strong>less dense</strong> and floats upward through the cooler, denser fluid — which sinks to take its place, gets heated in turn, and rises. A continuous loop called a <strong>convection current</strong> forms, stirring heat throughout the fluid.</p>\n<p>Once you know the pattern — <em>hot rises, cold sinks</em> — you\'ll see it everywhere:</p>\n<ul>\n  <li><strong>Radiators</strong> sit low on walls: they warm air that rises, drifts across the ceiling, cools, and sinks on the far side, quietly circulating the whole room.</li>\n  <li><strong>Freezer compartments</strong> historically sat at the top of the fridge: cold air sinks from them through everything below.</li>\n  <li><strong>A kettle\'s element</strong> is at the bottom so rising hot water stirs the entire volume. An element at the top would boil a thin hot layer and leave the bottom cold.</li>\n  <li><strong>Underfloor heating</strong> turns the entire floor into the "bottom of the pot."</li>\n</ul>\n<div class="analogy">\n  <h3>Analogy: The Lava Lamp</h3>\n  <p>A lava lamp is a convection current slowed down enough to watch: wax warms at the bulb, expands, becomes less dense and rises; at the top it cools, contracts, and sinks. Your room\'s air is doing the same dance, invisibly, around every radiator.</p>\n</div>\n<p>Convection also runs the weather. On a sunny day at the coast, land warms faster than the sea; air over the land rises and cooler sea air flows in underneath — the afternoon <strong>sea breeze</strong>. At night the flow reverses. Scale it up and convection currents in the atmosphere drive winds and thunderstorms; glider pilots and hawks climb on rising columns of warm air called thermals. Even Earth\'s mantle convects — over millions of years, those slow currents move the continents themselves.</p>\n<div class="key-concept">\n  <h4>Key Concept</h4>\n  <p>Convection needs a fluid that is free to move. It cannot happen in solids (particles locked in place) or in a vacuum (no particles at all).</p>\n</div>'},{id:"radiation",title:"Radiation: Heat Across Empty Space",content:'\n<p>Between the Sun and Earth lie 150 million kilometres of near-perfect vacuum — no particles to conduct, no fluid to convect. Yet sunshine warms your face. The third transfer mechanism needs no matter at all: <strong>thermal radiation</strong>, energy carried by infrared waves (a family member of visible light that you\'ll meet properly in Subject 7).</p>\n<p><strong>Every object radiates</strong>, all the time, simply because it has a temperature — you, this book, an ice cube. Hotter objects radiate far more strongly, and hot enough objects begin to glow visibly: an electric hob glows red at about 700 \xb0C; the Sun\'s 5500 \xb0C surface floods us with visible light as well as infrared. You constantly radiate too — a thermal camera sees you glowing brightly at 37 \xb0C — but you also absorb radiation from everything around you. Net flow, as always, runs hot → cold.</p>\n<p>Surfaces matter enormously:</p>\n<ul>\n  <li><strong>Dark, matt surfaces</strong> are excellent absorbers <em>and</em> excellent emitters of radiation.</li>\n  <li><strong>Light, shiny surfaces</strong> are poor absorbers and poor emitters — they reflect radiation away.</li>\n</ul>\n<p>Hence a black car parked in the sun becomes an oven while a white one stays merely warm; houses in hot countries are traditionally whitewashed; solar water-heating panels are matt black; emergency "space blankets" are shiny foil to reflect a casualty\'s own radiation back at them; and a shiny teapot keeps tea hot longer than a dark one because it\'s a reluctant emitter.</p>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>On a clear, still night the ground radiates its heat straight out to space and can drop below the air temperature — which is why frost can form on car roofs and grass even when the forecast never fell below 3 \xb0C, and why cloudy nights stay milder: clouds radiate energy back down.</p>\n</div>\n<div class="key-concept">\n  <h4>Key Concept</h4>\n  <p>Radiation is the only heat-transfer mechanism that works through a vacuum. Conduction needs touching particles; convection needs a moving fluid; radiation needs nothing at all.</p>\n</div>\n<p>Real situations mix all three. A campfire warms your face by radiation (block it with your hand and the warmth vanishes instantly), sends smoke and hot air upward by convection, and heats the poker you left in the embers by conduction.</p>'},{id:"insulation-applications",title:"Keeping Heat In (and Out): The Art of Insulation",content:"\n<p>Once you know heat's three escape routes, you can block them — and that is the entire science of insulation: <strong>identify the route, then interrupt it.</strong></p>\n<p>The masterpiece is the <strong>vacuum flask</strong> (Thermos), which ambushes all three mechanisms at once:</p>\n<ul>\n  <li>A <strong>vacuum gap</strong> between double walls stops conduction and convection dead — no particles, no transfer.</li>\n  <li><strong>Silvered surfaces</strong> facing the gap reflect radiation back where it came from.</li>\n  <li>An <strong>insulating stopper</strong> plugs the last route, blocking conduction and stopping convection currents of escaping air.</li>\n</ul>\n<p>That's why the same flask keeps coffee hot <em>and</em> lemonade cold: it doesn't make heat — it simply refuses to let heat cross in either direction.</p>\n<p>A house loses heat through every surface, and home insulation targets each route:</p>\n<table>\n  <thead>\n    <tr><th>Measure</th><th>Mainly blocks</th><th>How</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Loft insulation (fibreglass/wool)</td><td>Conduction &amp; convection</td><td>Traps air in millions of tiny pockets under the roof, where rising warm air collects</td></tr>\n    <tr><td>Cavity wall insulation</td><td>Convection</td><td>Foam fills the wall gap so air can't circulate and ferry heat outward</td></tr>\n    <tr><td>Double glazing</td><td>Conduction</td><td>A thin layer of trapped air or argon between panes conducts poorly</td></tr>\n    <tr><td>Foil behind radiators</td><td>Radiation</td><td>Reflects infrared back into the room instead of warming the wall</td></tr>\n    <tr><td>Draught excluders</td><td>Convection</td><td>Stop warm air physically leaking out around doors</td></tr>\n  </tbody>\n</table>\n<p>Clothing works the same way: layers beat one thick coat because each layer traps a blanket of air, and wind is chilling because it strips away the warm air film your body maintains — that's the \"wind chill\" on weather reports. Penguins, polar bears, and puffer jackets all run on trapped air.</p>\n<div class=\"key-concept\">\n  <h4>Try It Yourself</h4>\n  <p>Fill two identical jars with equally hot tap water. Wrap one in a wool sock or tea towel; leave the other bare. Lidded, side by side, wait 30 minutes, then compare temperatures with a kitchen thermometer (or a clean finger). The wrapped jar stays noticeably warmer — trapped air at work. Bonus round: stand one jar on a metal tray and see conduction steal extra heat from below.</p>\n</div>"}],quiz:[{question:"Why are metals such good conductors of heat compared with wood or plastic?",options:["Metal particles are packed more loosely, letting heat slip between them","Metals contain free electrons that carry energy quickly through the material, on top of the particle-to-particle vibration relay","Metals are shiny, and shiny things attract heat","Metals contain no empty space at all"],correctIndex:1,explanation:"All solids conduct by vibrating particles jostling their neighbours, but metals add fast-moving free electrons that ferry energy directly from hot regions to cold — the same electrons that make metals good electrical conductors."},{question:"Which heat-transfer mechanism can cross the vacuum of space between the Sun and Earth?",options:["Radiation","Conduction","Convection","Diffusion"],correctIndex:0,explanation:"Conduction needs touching particles and convection needs a fluid free to circulate — a vacuum has neither. Radiation is energy carried by infrared (and visible) waves, which travel happily through empty space."},{question:"The vacuum gap between the double walls of a Thermos flask is there primarily to stop which heat transfers?",options:["Radiation only","Evaporation only","Conduction and convection","All heat transfer of every kind"],correctIndex:2,explanation:"With no particles in the gap, there is nothing to conduct heat and no fluid to convect it. Radiation still crosses a vacuum, which is why the flask adds silvered surfaces to reflect it back."},{question:"Bathroom tiles feel much colder under bare feet than the carpet next to them, even though both are at the same room temperature. Why?",options:["The tiles really are several degrees colder than the carpet","Tiles conduct heat away from your skin much faster than carpet, and your skin senses the rate of heat loss, not temperature","Carpet generates its own heat through friction with your feet","Cold air convects upward through tiles but not through carpet"],correctIndex:1,explanation:"Your skin is a heat-flow meter, not a thermometer. Tile is a decent conductor and pulls heat from your foot quickly; carpet is full of trapped air and pulls almost none. Equal temperatures, very unequal sensations."},{question:"Radiators are usually mounted low on a wall. What is the physics behind this choice?",options:["Heat radiation travels further when emitted from below waist height","Low mounting shortens the pipes and saves copper","Hot water is too heavy to pump higher up the wall","Warmed air becomes less dense and rises, setting up a convection current that circulates heat around the whole room"],correctIndex:3,explanation:"A radiator mostly heats the room by convection: air warmed at floor level expands, rises, drifts and cools across the ceiling, then sinks to be reheated. Mounted near the ceiling, it would just keep a warm layer trapped up there."}]},{id:"specific-and-latent-heat",title:"Specific & Latent Heat",subtitle:"Heating curves, Q = mcΔT, and the hidden energy of melting and boiling",sections:[{id:"q-mc-delta-t",title:"Q = mcΔT: The Price List for Warming Things Up",content:'\n<p>Time for this subject\'s one heavyweight formula — and it\'s a good one, because it turns "heating stuff" into simple arithmetic. The energy needed to change a substance\'s temperature is:</p>\n<p><strong>Q = m c ΔT</strong></p>\n<ul>\n  <li><strong>Q</strong> — energy transferred, in joules (J)</li>\n  <li><strong>m</strong> — mass being heated, in kilograms (kg)</li>\n  <li><strong>ΔT</strong> — the temperature <em>change</em>, in \xb0C (the Δ, "delta", means "change in")</li>\n  <li><strong>c</strong> — the <strong>specific heat capacity</strong>: the energy needed to warm 1 kg of that substance by 1 \xb0C</li>\n</ul>\n<p>Each substance has its own price tag c — its thermal stubbornness. Some values worth meeting:</p>\n<table>\n  <thead>\n    <tr><th>Substance</th><th>c (J/kg\xb7\xb0C)</th><th>Character</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Water</td><td>4200</td><td>Extremely stubborn — hard to heat, slow to cool</td></tr>\n    <tr><td>Cooking oil</td><td>≈2000</td><td>Heats about twice as fast as water</td></tr>\n    <tr><td>Aluminium</td><td>900</td><td>Responsive</td></tr>\n    <tr><td>Sand / brick</td><td>≈800</td><td>Quick to warm, quick to cool</td></tr>\n    <tr><td>Iron / steel</td><td>450</td><td>Fast to heat up</td></tr>\n    <tr><td>Copper</td><td>385</td><td>Very fast — a chef\'s favourite</td></tr>\n  </tbody>\n</table>\n<div class="key-concept">\n  <h4>Worked Example: One Mug of Tea</h4>\n  <p>Boil 0.3 kg of water (a big mug) from 20 \xb0C to 100 \xb0C. ΔT = 80 \xb0C, so Q = 0.3 \xd7 4200 \xd7 80 = <strong>100,800 J ≈ 101 kJ</strong>. A 2000 W kettle delivers 2000 J each second, so this takes about 50 seconds — check your own kettle against this and it will be impressively close.</p>\n</div>\n<div class="key-concept">\n  <h4>Worked Example: Why the Pan Beats the Water</h4>\n  <p>Warm a 1.5 kg copper pan from 20 \xb0C to 200 \xb0C: Q = 1.5 \xd7 385 \xd7 180 ≈ <strong>104 kJ</strong> — about the same energy as boiling one mug of water, despite a temperature climb more than twice as big and five times the mass. Copper\'s tiny c is why an empty pan reaches searing heat in a minute while a pan of water takes ages.</p>\n</div>\n<p>The formula also runs backwards: energy released on cooling is the same mcΔT, which is why a hot-water bottle (high m, huge c, big ΔT as it cools) can warm a bed for hours.</p>'},{id:"water-is-special",title:"Water: The Planet's Thermal Shock Absorber",content:"\n<p>Look back at that table: water's specific heat capacity, 4200 J/kg\xb7\xb0C, towers over almost every common substance — five times sand, eleven times copper. This one number quietly shapes your kitchen, your climate, and your body.</p>\n<p><strong>In the kitchen:</strong> water is why pasta pots take ages to boil while the empty frying pan next to them is smoking within a minute. It's also why boiling water is such an effective cooker — and such a serious scalding hazard: every kilogram of it carries an enormous cargo of energy to give up as it cools on contact.</p>\n<div class=\"key-concept\">\n  <h4>Worked Example: The Cost of a Bath</h4>\n  <p>A bath holds about 150 kg of water, heated from 15 \xb0C to 40 \xb0C. Q = 150 \xd7 4200 \xd7 25 = <strong>15,750,000 J ≈ 15.8 MJ ≈ 4.4 kWh</strong> — roughly the energy of running a 2000 W heater flat-out for over two hours, and a good chunk of a day's household energy use. Showers are cheaper for a purely mcΔT reason: less m.</p>\n</div>\n<p><strong>In the weather:</strong> oceans are gigantic thermal flywheels. They absorb summer heat with barely a temperature budge and release it slowly through winter. The result: coastal cities enjoy mild, damped seasons, while continental interiors — far from water, sitting on low-c rock and sand — swing brutally. Compare maritime London (typical range roughly 5–23 \xb0C across the year) with continental Ulaanbaatar (about −25 to +25 \xb0C). Deserts flip from scorching days to near-freezing nights for the same reason: sand responds fast, and dry air holds little water vapour to buffer the change.</p>\n<p><strong>In engineering and biology:</strong> water is the coolant in car engines and power stations precisely because each kilogram can swallow so much heat. And you are about 60% water — your high-c body resists dangerous temperature swings, buying time in heat waves and cold snaps alike.</p>\n<div class=\"did-you-know\">\n  <h4>Did You Know?</h4>\n  <p>The sea breeze from the last chapter is really a specific-heat story. Land (c ≈ 800) warms far faster in morning sun than the sea (c = 4200); the temperature gap drives the convection current. Two chapters, one mechanism — that's the particle model paying rent.</p>\n</div>"},{id:"heating-curves",title:"Heating Curves: When the Thermometer Stalls",content:"\n<p>Here's an experiment with a genuinely surprising result. Take ice from the freezer at −18 \xb0C, put a thermometer in it, heat it steadily, and plot temperature against time. You might expect one smooth rising line. Instead you get a staircase:</p>\n<ol>\n  <li><strong>Rising:</strong> the ice warms from −18 \xb0C to 0 \xb0C. (Q = mcΔT for ice, whose c ≈ 2100 J/kg\xb7\xb0C.)</li>\n  <li><strong>Flat at 0 \xb0C:</strong> the temperature <em>stops dead</em> while the ice melts — even though the hob keeps pouring energy in. Ice and water coexist, all of it at 0 \xb0C, until the last crystal is gone.</li>\n  <li><strong>Rising:</strong> now liquid water climbs from 0 \xb0C toward 100 \xb0C (c = 4200 J/kg\xb7\xb0C).</li>\n  <li><strong>Flat at 100 \xb0C:</strong> the temperature stalls again while the water boils away. A furiously boiling pot is no hotter than a gently simmering one — both sit at 100 \xb0C.</li>\n  <li><strong>Rising:</strong> only when all the liquid has become steam can the steam's temperature climb.</li>\n</ol>\n<p>Where does the energy go during the plateaus? Straight into the particle model's other account. Energy can do two different jobs inside matter: make particles move <em>faster</em> (temperature rises) or break the <em>attractions</em> between them (state changes, temperature constant). During melting, every incoming joule is spent prying particles out of the rigid solid lattice; during boiling, it's spent tearing them completely free of the liquid. Only when the demolition job is finished does energy go back to raising the speed — and the temperature.</p>\n<div class=\"analogy\">\n  <h3>Analogy: The Toll Bridge</h3>\n  <p>Driving across a country, your distance from home rises steadily — until you hit a toll bridge, where you sit paying the fee, moving nowhere. Heating is the same journey: temperature climbs steadily until each phase change demands its toll of energy, paid in full at constant temperature, before the climb resumes.</p>\n</div>\n<div class=\"key-concept\">\n  <h4>Try It Yourself</h4>\n  <p>Half-fill a saucepan with ice cubes and a little cold water, insert a kitchen thermometer, and heat gently, stirring and reading every minute. You'll watch the reading pin itself near 0 \xb0C for minute after minute while ice remains, then climb, then pin again near 100 \xb0C at the boil. You are tracing a genuine heating curve — the same graph printed in every physics textbook — on your own stove.</p>\n</div>"},{id:"latent-heat",title:"Latent Heat: The Energy in Hiding",content:'\n<p>The energy absorbed or released during a change of state is called <strong>latent heat</strong> — from the Latin for "hidden," because it changes no thermometer reading. It goes into rearranging particles, not speeding them up. And the amounts involved are astonishing:</p>\n<ul>\n  <li>Melting 1 kg of ice at 0 \xb0C into water at 0 \xb0C takes about <strong>334,000 J (334 kJ)</strong> — enough energy to heat that same water from 0 \xb0C all the way to ≈80 \xb0C.</li>\n  <li>Boiling 1 kg of water at 100 \xb0C into steam at 100 \xb0C takes about <strong>2,260,000 J (2260 kJ)</strong> — more than five times the energy needed to heat it from 0 \xb0C to 100 \xb0C in the first place. Tearing particles fully apart is expensive.</li>\n</ul>\n<p>Latent heat flows both ways: freezing <em>releases</em> 334 kJ per kilogram, condensing steam <em>releases</em> 2260 kJ per kilogram. That reversal explains a family of everyday facts:</p>\n<ul>\n  <li><strong>Steam burns are worse than boiling-water burns.</strong> Steam at 100 \xb0C first dumps its enormous latent heat into your skin as it condenses, <em>then</em> cools as hot water. Same temperature, several times the energy.</li>\n  <li><strong>Sweating cools you.</strong> Evaporating sweat steals its latent heat from your skin. Humid days feel oppressive because evaporation stalls; a breeze feels cool because it speeds it up. Dogs pant, elephants flap wet ears — same physics.</li>\n  <li><strong>Ice is the perfect drink cooler.</strong> A 30 g cube absorbs ≈10,000 J just to melt, all while sitting at 0 \xb0C. Cold water at 0 \xb0C chills far less, because it lacks that latent-heat appetite.</li>\n  <li><strong>Frost warnings for orchards:</strong> growers spray crops with water because freezing water <em>releases</em> latent heat, holding the fruit near 0 \xb0C instead of far below.</li>\n</ul>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>A summer thunderstorm is powered by latent heat. Water evaporates from warm ground and sea, rises, and condenses into cloud droplets — releasing its 2260 kJ per kilogram back into the air, which surges upward and condenses more vapour. A single large storm can release more energy than a nuclear weapon, all of it banked earlier by evaporation.</p>\n</div>\n<div class="key-concept">\n  <h4>Key Concept</h4>\n  <p>Energy bookkeeping for heating: Q = mcΔT pays for temperature changes; latent heat pays for state changes. Total energy = the sum of every step. This is calorimetry, and Subject 12 will sharpen it into a precision tool.</p>\n</div>'}],quiz:[{question:"How much energy does it take to heat 2 kg of water by 10 \xb0C? (c of water = 4200 J/kg\xb7\xb0C)",options:["84,000 J","8,400 J","42,000 J","840,000 J"],correctIndex:0,explanation:"Q = mcΔT = 2 \xd7 4200 \xd7 10 = 84,000 J (84 kJ). Multiply mass, specific heat capacity, and the temperature change — the units cancel to leave joules."},{question:"A steadily heated pan of melting ice sits at exactly 0 \xb0C for several minutes even though the hob keeps supplying energy. Where is that energy going?",options:["It is escaping into the air before reaching the ice","It is stored and released later as extra temperature","It is breaking the attractions holding particles in the solid lattice, converting ice to water at constant temperature","It is making the water molecules physically larger"],correctIndex:2,explanation:"During a phase change, incoming energy does the work of freeing particles from their fixed arrangement rather than speeding them up. Since temperature measures particle speed, the thermometer stalls until the last ice has melted. This is latent heat."},{question:"Why does a steam burn at 100 \xb0C injure far more severely than a splash of boiling water at the same 100 \xb0C?",options:["Steam is actually much hotter than 100 \xb0C","Condensing steam first releases its huge latent heat (≈2260 kJ per kg) into the skin, then cools as hot water on top of that","Steam penetrates the skin, while water stays on the surface","Water evaporates off the skin before it can transfer energy"],correctIndex:1,explanation:"At the same temperature, steam carries an extra energy cargo: the latent heat of vaporisation. On contact it condenses, dumping about five times more energy per kilogram than boiling water releases while cooling — same thermometer reading, far more joules delivered."},{question:"Which of these is a direct consequence of water's unusually high specific heat capacity (4200 J/kg\xb7\xb0C)?",options:["Water boils at a lower temperature at altitude","Ice floats on liquid water","Water conducts electricity when salty","Coastal cities have milder seasons than continental interiors, because the ocean warms and cools very slowly"],correctIndex:3,explanation:"High c means the ocean absorbs enormous summer heat with little temperature rise and releases it gently in winter — a thermal flywheel that damps coastal climates. Interiors on low-c rock and sand swing far more violently. (The other options are real but come from different physics.)"},{question:"Which needs more energy: melting 1 kg of ice at 0 \xb0C, or heating the resulting 1 kg of water from 0 \xb0C to 50 \xb0C?",options:["Heating the water — temperature changes always cost more than phase changes","They are exactly equal by definition","Melting the ice: about 334 kJ, versus 1 \xd7 4200 \xd7 50 = 210 kJ for the heating","It cannot be compared without knowing the heating time"],correctIndex:2,explanation:"Melting 1 kg of ice costs ≈334 kJ of latent heat, while Q = mcΔT for the 50 \xb0C rise is 210 kJ. Dismantling the solid lattice is more expensive than a substantial temperature climb — which is exactly why ice is so effective at chilling drinks."}]},{id:"heat-engines-and-energy-use",title:"Heat Engines & Energy Use",subtitle:"From steam turbines to car engines — turning heat into work, and the price of efficiency",sections:[{id:"heat-into-work",title:"The Big Trick: Turning Heat into Work",content:'\n<p>For most of human history, muscle, wind, and falling water were the only ways to move anything. Then, in the 1700s, engineers learned a world-changing trick: <strong>heat can be made to push.</strong> A machine that turns heat into useful mechanical work is called a <strong>heat engine</strong>, and every one ever built — steam engine, car engine, jet, power-station turbine — runs on the same particle-model logic.</p>\n<p>The recipe has three steps:</p>\n<ol>\n  <li><strong>Heat a gas.</strong> Burn fuel (or split atoms) to make gas molecules move violently fast.</li>\n  <li><strong>Let the hot gas expand and push.</strong> Fast molecules hammering on a piston or turbine blade transfer their energy as ordered motion — this is where heat becomes work.</li>\n  <li><strong>Dump the leftover heat somewhere cold and repeat.</strong> The gas must be cooled or exhausted so the cycle can start again — a step that turns out to be unavoidable, and expensive.</li>\n</ol>\n<p>You\'ve already felt the principle. A lid rattling on a boiling pot is steam pushing with enough pressure to lift metal — a tiny, accidental heat engine. Thomas Newcomen (1712) and James Watt (1769) turned that push into machines that drained mines and drove factories; put a Watt-style engine on wheels and you get the railway; refine the idea into turbines and internal combustion, and you get the modern world. The industrial revolution was, at bottom, the discovery that <strong>burning fuel could replace muscle</strong>.</p>\n<div class="analogy">\n  <h3>Analogy: The Crowd and the Door</h3>\n  <p>A hot gas is like a dense crowd of sprinting people in a room. Give them a movable wall — a piston — and their random shoving drives it outward in one useful direction. The engine\'s genius is converting chaotic molecular battering into the orderly turning of a wheel.</p>\n</div>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>A single litre of petrol releases about 34 MJ when burned — roughly the work output of one labourer digging hard for a week. Cheap fuel plus heat engines is why one farmer with a tractor now does what once took a village.</p>\n</div>\n<div class="key-concept">\n  <h4>Key Concept</h4>\n  <p>All heat engines share one blueprint: hot gas expands and pushes something. The differences — steam vs petrol, piston vs turbine — are engineering variations on this single physical theme.</p>\n</div>'},{id:"steam-turbines",title:"Steam Turbines: How Most of Your Electricity Is Made",content:'\n<p>Here is an underappreciated fact: coal plants, gas plants, nuclear plants, and even geothermal and concentrated-solar plants are all, at heart, <strong>the same machine</strong>. They differ only in how they make heat. After that, nearly every large power station on Earth follows one chain:</p>\n<ol>\n  <li><strong>Boiler:</strong> the heat source turns water into high-pressure steam at 500–600 \xb0C. (Recall the latent-heat chapter — vaporising water banks a huge energy cargo in every kilogram of steam.)</li>\n  <li><strong>Turbine:</strong> the steam blasts through sets of angled blades, hammering them into rotation at typically 3000 revolutions per minute. Molecular chaos becomes spinning shaft — heat has become work.</li>\n  <li><strong>Generator:</strong> the shaft spins magnets inside coils of wire, converting rotation into electricity (the beautiful induction physics waiting for you in Subject 8).</li>\n  <li><strong>Condenser:</strong> the spent steam is cooled back into water — dumping its latent heat into a river, the sea, or those iconic wide-waisted cooling towers — and pumped back to the boiler to go around again.</li>\n</ol>\n<p>Those cooling towers deserve a correction: the white plumes rising from them are <strong>not smoke</strong> — they\'re clouds of condensing water vapour, the visible signature of step 4, the waste-heat dump every heat engine requires.</p>\n<table>\n  <thead>\n    <tr><th>Plant type</th><th>Heat source</th><th>Then what?</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Coal / gas</td><td>Burning fossil fuel</td><td>Steam → turbine → generator</td></tr>\n    <tr><td>Nuclear</td><td>Fission of uranium nuclei</td><td>Steam → turbine → generator</td></tr>\n    <tr><td>Geothermal</td><td>Earth\'s internal heat</td><td>Steam → turbine → generator</td></tr>\n    <tr><td>Concentrated solar</td><td>Mirror-focused sunlight</td><td>Steam → turbine → generator</td></tr>\n  </tbody>\n</table>\n<div class="key-concept">\n  <h4>Key Concept</h4>\n  <p>"Nuclear power" and "coal power" are both really steam power — Victorian turbine physics with different fires underneath. Only solar panels (directly converting light), wind, and hydro escape the steam cycle.</p>\n</div>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>The largest steam turbines, in nuclear plants, output about 1,750 MW — the sustained power of roughly 15,000 family cars — from a single spinning shaft. Charles Parsons\'s first turbine-powered ship, <em>Turbinia</em>, gatecrashed Queen Victoria\'s 1897 naval review and outran every vessel sent to catch it.</p>\n</div>'},{id:"internal-combustion",title:"The Internal Combustion Engine: Explosions in a Box",content:'\n<p>A steam engine burns fuel <em>outside</em> the working cylinder; a car engine cuts out the middleman and burns fuel <strong>inside</strong> it — hence <em>internal</em> combustion. Each cylinder hosts thousands of tiny, precisely timed explosions every minute, each one a miniature demonstration of gas pressure from particle collisions.</p>\n<p>Most car engines run a four-step dance — the <strong>four-stroke cycle</strong>, one stroke per piston movement:</p>\n<ol>\n  <li><strong>Intake ("suck"):</strong> the piston slides down, drawing in a mix of air and petrol vapour through an open valve.</li>\n  <li><strong>Compression ("squeeze"):</strong> valves shut; the piston rises, squashing the mixture to about a tenth of its volume. Compressing the gas crowds its molecules and primes the mixture to burn fast.</li>\n  <li><strong>Power ("bang"):</strong> the spark plug fires. Combustion heats the trapped gas past 2000 \xb0C in milliseconds; its molecules, now furiously fast, slam the piston down with a force of several tonnes. <em>This is the only stroke that delivers work</em> — the other three are bookkeeping.</li>\n  <li><strong>Exhaust ("blow"):</strong> the piston rises again, expelling the spent gases out through the exhaust valve — the waste-heat dump, again.</li>\n</ol>\n<p>A crankshaft converts the pistons\' up-and-down into rotation, and multiple cylinders (typically 3, 4, 6, or 8) fire in sequence so the shaft is always being pushed by something. Diesel engines skip the spark plug: they compress air so hard it heats past the fuel\'s ignition point (another particle-model effect — squeezing a gas fast makes it hot), then inject fuel that ignites on contact.</p>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>An engine cruising at 3000 rpm fires each cylinder 25 times every second. A four-cylinder car on a one-hour commute hosts about 360,000 controlled explosions — while you listen to a podcast.</p>\n</div>\n<div class="key-concept">\n  <h4>Key Concept</h4>\n  <p>The power stroke is the particle model at full volume: heat a trapped gas and its molecular bombardment of the piston becomes an irresistible push. Everything else — valves, spark timing, crankshaft — exists to set up and harvest that one moment.</p>\n</div>'},{id:"efficiency-and-energy-resources",title:"Efficiency: The Unavoidable Price of the Trick",content:"\n<p>Here is the uncomfortable ledger of every heat engine. <strong>Efficiency</strong> means the fraction of the fuel's energy that becomes useful work:</p>\n<p><strong>efficiency = useful energy out \xf7 total energy in</strong> (\xd7 100 for a percentage)</p>\n<p>The numbers are humbling:</p>\n<table>\n  <thead>\n    <tr><th>Machine</th><th>Typical efficiency</th><th>Where the rest goes</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Petrol car engine</td><td>25–30%</td><td>Hot exhaust, hot radiator, friction</td></tr>\n    <tr><td>Diesel engine</td><td>30–40%</td><td>Exhaust and cooling</td></tr>\n    <tr><td>Coal power station</td><td>≈35–40%</td><td>Condenser cooling water, flue gases</td></tr>\n    <tr><td>Modern gas (combined-cycle) plant</td><td>up to ≈60%</td><td>Still mostly waste heat</td></tr>\n    <tr><td>Old steam locomotive</td><td>≈8%</td><td>Nearly everything</td></tr>\n    <tr><td>Electric motor (not a heat engine)</td><td>90%+</td><td>A little friction and warming</td></tr>\n  </tbody>\n</table>\n<p>Read that first row again: of every 50 litres of petrol you buy, roughly 35 litres' worth becomes waste heat streaming from the exhaust pipe and radiator. Only about 15 litres' worth turns the wheels. This is not sloppy engineering — remember step 3 of the heat-engine recipe: <strong>every cycle must dump heat into something cold to reset itself.</strong> That dumped heat is work you can never collect. A deep law of nature — the second law of thermodynamics, your destination in Subject 12 — sets a hard ceiling on efficiency that no cleverness can beat, a ceiling that rises only with hotter sources and colder exhausts. That's why engineers chase exotic alloys that survive ever-hotter turbine temperatures.</p>\n<p>Efficiency framing also clarifies the energy landscape. Fossil fuels (coal, oil, gas) are ancient sunlight banked as chemical energy — dense, convenient, finite, and CO₂-emitting. Renewables (solar, wind, hydro) and nuclear sidestep the emissions; notably, wind, hydro, and solar panels aren't heat engines at all, so they skip combustion losses entirely. And the cheapest energy remains the energy never wasted: LED lighting, insulation (chapter 3 pays dividends), and heat pumps — clever devices that use a little work to <em>move</em> heat rather than make it.</p>\n<div class=\"did-you-know\">\n  <h4>Did You Know?</h4>\n  <p>An electric car converts grid energy to motion at 85–90% efficiency versus a petrol car's ≈25% — one big reason for the switch. Some Scandinavian cities pipe power-station waste heat into \"district heating\" for homes, selling the same joules twice.</p>\n</div>\n<div class=\"key-concept\">\n  <h4>Key Concept</h4>\n  <p>No heat engine can be 100% efficient — not from bad design, but from physical law. Why nature charges this tax is one of the deepest questions in physics; hold onto it until Subject 12, where the second law of thermodynamics answers it.</p>\n</div>"}],quiz:[{question:"What working principle is shared by every heat engine — steam turbine, petrol engine, and jet alike?",options:["A magnetic field converts heat directly into rotation","A heated gas expands, and its fast-moving molecules push on a piston or turbine blade, turning heat into work","Burning fuel produces electricity, which then drives a motor","Cold gas contracts and pulls a piston inward"],correctIndex:1,explanation:"Every heat engine follows one blueprint: heat a gas so its molecules move violently, let the gas expand against something movable, and harvest that push as work — then dump the leftover heat and repeat. All the famous designs are variations on this cycle."},{question:"What do coal, nuclear, geothermal, and concentrated-solar power stations all have in common?",options:["They all use heat to make steam that spins a turbine connected to a generator","They all burn fossil fuels","They all convert sunlight directly into electricity","They all operate without producing any waste heat"],correctIndex:0,explanation:"These plants differ only in the fire: burning coal, splitting uranium, Earth's heat, or focused sunlight. Downstream, they're the same machine — boiler, steam turbine, generator, condenser. Only solar panels, wind, and hydro escape the steam cycle."},{question:"In the four-stroke petrol engine cycle, which is the correct order of strokes?",options:["Compression → intake → exhaust → power","Power → compression → intake → exhaust","Intake → compression → power → exhaust","Intake → power → compression → exhaust"],correctIndex:2,explanation:"Suck, squeeze, bang, blow: draw in the fuel-air mix, compress it, ignite it so the hot expanding gas drives the piston (the only work-producing stroke), then push out the exhaust. The cycle then repeats — 25 times a second per cylinder at 3000 rpm."},{question:"Roughly what efficiency does a typical petrol car engine achieve?",options:["90–95%","70–80%","50–60%","25–30%"],correctIndex:3,explanation:"Only about a quarter to a third of petrol's chemical energy becomes motion; the rest leaves as hot exhaust and radiator heat. This is close to a fundamental limit for its operating temperatures, not mere sloppiness — one reason electric drivetrains (90%+ efficient motors) are attractive."},{question:"A power station is described as 38% efficient. What happens to the other 62% of the fuel's energy?",options:["It is destroyed during combustion","It is released as waste heat — mainly through the condenser cooling water and towers — because every heat-engine cycle must dump heat to reset","It is stored in batteries for later use","It leaks away as electricity into the ground"],correctIndex:1,explanation:"Energy is never destroyed — it is conserved. The unconverted 62% leaves as low-temperature waste heat, mostly via the condenser (those cloud-topped cooling towers). Why some heat must always be discarded is the second law of thermodynamics, coming in Subject 12."}]}]},{id:"sound-light-optics",number:7,title:"Sound, Light & Optics",description:"From vibrating strings to rainbows: your first pass through waves, sound, mirrors, lenses, and the electromagnetic spectrum — the physics of everything you see and hear.",phase:2,chapters:[{id:"sound",title:"Sound",subtitle:"Vibrations traveling through air — pitch, loudness, echoes, and ultrasound",sections:[{id:"everything-that-sounds-vibrates",title:"Everything That Sounds, Vibrates",content:'\n<p>Touch your throat and hum. That buzz under your fingertips is the whole secret of sound: <strong>every sound begins as a vibration</strong>. A guitar string flutters back and forth, a drumhead trembles, your vocal cords open and close hundreds of times per second. The vibrating object shoves the air molecules next to it; those molecules shove their neighbours; the shove travels outward as a ripple of squeezed and stretched air. When that ripple reaches your ear, it pushes your eardrum in and out in the same rhythm, and your brain hears sound.</p>\n<p>Notice what travels and what does not. The air itself does not fly from the guitar to your ear — each molecule just jiggles around its home spot and passes the push along. What crosses the room is the <strong>pattern of compressions</strong>, and the energy it carries. That makes sound our first real example of a <em>wave</em>: a travelling disturbance, not travelling stuff.</p>\n<div class="analogy">\n  <h3>Analogy: The Stadium Wave</h3>\n  <p>In a stadium wave, no spectator runs around the arena — each person just stands up and sits down at the right moment. Yet "the wave" visibly races through the crowd. Sound moves through air exactly this way: molecules bob in place while the disturbance sprints past them.</p>\n</div>\n<p>Because sound is molecules pushing molecules, it needs a material to travel through — air, water, wood, bone, anything with particles to pass the push along. This is why a ringing alarm clock sealed inside a jar goes silent as the air is pumped out: the clapper still hammers away, but with no molecules to shove, no sound escapes.</p>\n<ul>\n  <li><strong>Solids</strong> carry sound best — their particles are packed tight and spring-connected. Put your ear on a table and tap the far end.</li>\n  <li><strong>Liquids</strong> carry it well — whales call to each other across kilometres of ocean.</li>\n  <li><strong>Gases</strong> carry it more slowly and weakly — but well enough for every conversation you have ever had.</li>\n  <li><strong>Vacuum</strong> carries no sound at all. Space battles are silent, whatever the movies say.</li>\n</ul>\n<div class="key-concept">\n  <h4>Key Concept</h4>\n  <p>Sound is a travelling vibration passed from particle to particle through a medium. No medium, no sound — the energy moves, the material stays put.</p>\n</div>'},{id:"the-speed-of-sound",title:"How Fast Does Sound Travel?",content:'\n<p>Watch someone hammering a fence post from far across a field and you will see the hammer strike, then hear the clang a beat later. Light reaches you almost instantly; sound takes its time. In air at room temperature, sound travels at about <strong>343 metres per second</strong> — roughly 1,235 km/h, or about 1 kilometre every 3 seconds.</p>\n<p>That number is not fixed. Sound is molecules shoving molecules, so anything that changes how quickly the shove passes along changes the speed:</p>\n<table>\n  <thead>\n    <tr><th>Medium</th><th>Speed of sound</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Air (20 \xb0C)</td><td>≈ 343 m/s</td></tr>\n    <tr><td>Air (0 \xb0C)</td><td>≈ 331 m/s</td></tr>\n    <tr><td>Water</td><td>≈ 1,480 m/s</td></tr>\n    <tr><td>Steel</td><td>≈ 5,900 m/s</td></tr>\n  </tbody>\n</table>\n<p>The pattern surprises many people: sound is <strong>faster in liquids than in gases, and fastest in stiff solids</strong>. Tightly bonded particles pass the push along almost instantly, like a shove travelling down a line of people holding rigid poles rather than loose ropes. Warmer air is slightly faster than cold air because its molecules are already moving quickly and deliver their collisions sooner.</p>\n<div class="key-concept">\n  <h4>Worked Example: How Far Is the Storm?</h4>\n  <p>You see a lightning flash and count 6 seconds before the thunder. Light arrives essentially instantly, so the delay is all sound. Distance = speed \xd7 time = 343 m/s \xd7 6 s ≈ 2,060 m. The strike was about <strong>2 km away</strong>. Handy rule: every 3 seconds of delay ≈ 1 km (every 5 seconds ≈ 1 mile).</p>\n</div>\n<p>Compare 343 m/s with light\'s 300,000 <em>kilometres</em> per second and you see why we always see before we hear: fireworks bloom silently, then boom; a distant bat strikes the ball before the crack reaches the stands. Jet aircraft can outrun their own sound — flying past the "sound barrier" piles the pressure ripples into a single shock wave that reaches the ground as a sonic boom.</p>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>Orchestras tune before every concert partly because the speed of sound in air shifts with temperature — and so does the pitch of wind instruments. A cold hall literally plays flat until it warms up.</p>\n</div>'},{id:"pitch-and-loudness",title:"Pitch and Loudness: Frequency and Amplitude",content:'\n<p>Two knobs control what a sound is like. How <em>often</em> the source vibrates sets the <strong>pitch</strong>; how <em>far</em> it swings sets the <strong>loudness</strong>. Physics gives each knob a name.</p>\n<p><strong>Frequency</strong> is the number of complete vibrations per second, measured in <strong>hertz (Hz)</strong>. A string vibrating 262 times per second produces 262 compressions of air per second, and you hear middle C. Double the frequency and you hear the same note an octave higher. Concert orchestras tune to A at 440 Hz. High frequency = high pitch; low frequency = low pitch — a mosquito\'s wings beat around 600 times per second (a whine), a bumblebee\'s about 130 (a hum).</p>\n<p><strong>Amplitude</strong> is the size of the vibration — how far the string swings, how strongly the air is compressed. Pluck gently and the string barely moves: small amplitude, soft sound. Pluck hard and the same note comes out loud. Amplitude carries the energy; frequency carries the identity of the note. Loudness is commonly quoted in decibels (dB) — whisper ≈ 30 dB, conversation ≈ 60 dB, rock concert ≈ 110 dB — a scale you will meet properly in the second pass.</p>\n<ul>\n  <li>Human hearing spans roughly <strong>20 Hz to 20,000 Hz</strong>. The top end fades with age — many adults cannot hear above ≈ 15,000 Hz.</li>\n  <li>Below 20 Hz is <strong>infrasound</strong> (elephants and storms rumble here); above 20,000 Hz is <strong>ultrasound</strong> (dogs, bats, dolphins).</li>\n  <li>Pitch and loudness are independent: a piccolo can play a high note quietly, a tuba a low note thunderously.</li>\n</ul>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Press a ruler flat on a table with about 20 cm hanging over the edge, then twang the free end. Now slide it in so only 10 cm overhangs and twang again: the shorter overhang vibrates faster and the pitch jumps up. Twang harder without moving the ruler — same pitch, more loudness. You have just separated frequency (length of the vibrating part) from amplitude (how hard you pluck) with your own hands.</p>\n</div>\n<div class="key-concept">\n  <h4>Key Concept</h4>\n  <p>Frequency (vibrations per second, in Hz) determines pitch. Amplitude (size of the vibration) determines loudness. They are separate dials — every combination of high/low and loud/soft is possible.</p>\n</div>'},{id:"echoes-and-ultrasound",title:"Echoes, Sonar, and Seeing with Sound",content:'\n<p>Shout at a cliff and the cliff shouts back. Sound, like any wave, <strong>reflects</strong> when it hits a large obstacle, and a reflection you hear separately from the original is an <strong>echo</strong>. Your ear needs roughly a tenth of a second between the original and the reflection to notice two sounds, so a distinct echo needs a wall at least about 17 m away — sound must cover the round trip of 34 m in 0.1 s. Closer walls still reflect, but the reflections blur into the original as the reverberation that makes bathrooms flattering to singers and empty halls boomy.</p>\n<div class="key-concept">\n  <h4>Worked Example: Echo Ranging</h4>\n  <p>A ship\'s sonar pings straight down and hears the echo 1.2 s later. Sound in seawater travels ≈ 1,500 m/s, so the ping covered 1,500 \xd7 1.2 = 1,800 m — <em>down and back</em>. The seabed is half that: <strong>900 m deep</strong>. Divide by two is the step everyone forgets; the sound made a round trip.</p>\n</div>\n<p>Turning echoes into measurements is called <strong>echolocation</strong>, and it is everywhere:</p>\n<ul>\n  <li><strong>Sonar</strong> maps the seafloor, finds shipwrecks and fish shoals, and guides submarines — light barely penetrates deep water, but sound travels kilometres.</li>\n  <li><strong>Bats</strong> shriek ultrasonic chirps (up to ≈ 100,000 Hz) and steer through pitch-dark caves by the returning echoes, catching moths on the wing.</li>\n  <li><strong>Parking sensors</strong> in car bumpers ping obstacles and beep faster as the echo time shrinks.</li>\n</ul>\n<p>The medical star is <strong>ultrasound imaging</strong>. Sound above 20,000 Hz is inaudible but reflects beautifully from boundaries between tissues. A probe on the skin sends millions of tiny pulses (typically 2–18 million Hz), times the echoes from each depth, and a computer paints the reflections into a live image — a beating heart, blood flow, or a baby sucking its thumb months before birth. Unlike X-rays, ultrasound deposits no ionising radiation, which is why it is the imaging tool of choice in pregnancy.</p>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>Some blind people navigate by clicking their tongues and reading the returning echoes — human echolocation. Brain scans show their visual cortex lights up while they do it: they are, in a real sense, seeing with sound.</p>\n</div>'}],quiz:[{question:"Why can no sound cross the vacuum of space?",options:["Sound waves are too slow to escape a planet's gravity","Sound needs particles to pass the vibration along, and a vacuum has none","It is too cold in space for sound to form","Sound is absorbed by starlight"],correctIndex:1,explanation:"Sound is a vibration handed from particle to particle. In a vacuum there are no molecules to shove one another, so the disturbance has nothing to travel through — the energy simply cannot propagate."},{question:"You see lightning and hear thunder 9 seconds later. Roughly how far away was the strike? (Sound travels ≈ 343 m/s.)",options:["About 3 km","About 300 m","About 9 km","About 30 km"],correctIndex:0,explanation:"Light arrives almost instantly, so the 9 s delay is all sound: 343 m/s \xd7 9 s ≈ 3,100 m ≈ 3 km. The quick rule — 3 seconds per kilometre — gives the same answer."},{question:"A guitarist plucks the same string twice: first gently, then hard. What changes?",options:["The pitch rises because the string vibrates faster","Both pitch and loudness rise together","The loudness increases but the pitch stays the same","Nothing changes — plucking force has no effect"],correctIndex:2,explanation:"Plucking harder increases the amplitude (how far the string swings), so the sound is louder. The frequency — set by the string's length, tension, and thickness — is unchanged, so the pitch stays the same. Frequency and amplitude are independent dials."},{question:"In which medium does sound travel fastest?",options:["Warm air","Cold air","Water","Steel"],correctIndex:3,explanation:"Sound speeds up as particles couple more stiffly: ≈ 343 m/s in air, ≈ 1,480 m/s in water, and ≈ 5,900 m/s in steel. Tightly bonded solid particles pass the vibration along almost instantly — which is why you hear an approaching train through the rails before you hear it through the air."},{question:"A sonar ping returns from the seabed after 2 s. Sound in seawater travels ≈ 1,500 m/s. How deep is the water?",options:["3,000 m","1,500 m","750 m","6,000 m"],correctIndex:1,explanation:"The ping travelled 1,500 m/s \xd7 2 s = 3,000 m in total, but that distance covers the trip down AND back up. The depth is half: 1,500 m. Forgetting to halve the round trip is the classic sonar mistake."}]},{id:"wave-basics",title:"Wave Basics",subtitle:"Transverse and longitudinal waves, and the master formula v = fλ",sections:[{id:"two-ways-to-wave",title:"Two Ways to Wave: Transverse and Longitudinal",content:'\n<p>Drop a pebble in a pond and rings spread outward. Shout across a canyon and your voice crosses it. A radio signal slips through your walls. These are all <strong>waves</strong> — travelling disturbances that carry <em>energy</em> from place to place <em>without carrying material</em>. The pond water does not migrate to the shore; a bobbing duck just moves up and down as the rings pass beneath it.</p>\n<p>Every wave in nature moves in one of two basic styles, and a stretched slinky can demonstrate both:</p>\n<ul>\n  <li><strong>Transverse waves:</strong> shake one end of the slinky <em>side to side</em> and a snake-like wiggle runs along it. The coils move <strong>perpendicular</strong> to the direction the wave travels. Water ripples, waves on guitar strings, and — crucially — <strong>light</strong> are transverse.</li>\n  <li><strong>Longitudinal waves:</strong> push and pull the slinky <em>along its own length</em> and you will see bunched-up regions race down the spring. The coils move <strong>back and forth along</strong> the travel direction, creating alternating squeezes (<em>compressions</em>) and stretches (<em>rarefactions</em>). <strong>Sound</strong> is longitudinal: air is squeezed and released, over and over, all the way to your ear.</li>\n</ul>\n<div class="analogy">\n  <h3>Analogy: Flag vs. Traffic Jam</h3>\n  <p>A flag rippling in the wind is transverse — each patch of cloth flaps sideways while the ripple runs along the flag. A motorway traffic jam is longitudinal — cars bunch up and spread out along the same line they drive in, and the "wave" of brake lights travels backwards down the road while every car keeps pointing forward.</p>\n</div>\n<p>Why care about the difference? Because the style of vibration decides what a wave can do. Transverse waves can be <em>polarised</em> (filtered by orientation — how polarised sunglasses cut glare), longitudinal waves cannot. And some waves need a medium while others do not: sound must have air, water, or rock to squeeze, but light\'s transverse wiggle is carried by electric and magnetic fields themselves, so it crosses the emptiness of space with ease — which is why you can see the Sun but never hear it.</p>\n<div class="key-concept">\n  <h4>Key Concept</h4>\n  <p>A wave transports energy, not matter. If the medium vibrates across the travel direction, the wave is transverse (light, water ripples); if it vibrates along the travel direction, it is longitudinal (sound).</p>\n</div>'},{id:"wave-anatomy",title:"The Anatomy of a Wave",interactive:"wave-superposition",content:'\n<p>To do physics with waves we need to measure them, and it takes only four numbers to describe any simple wave completely. Picture a snapshot of ripples frozen in time: a repeating chain of high points (<strong>crests</strong>) and low points (<strong>troughs</strong>).</p>\n<ul>\n  <li><strong>Wavelength (λ, "lambda"):</strong> the length of one complete cycle — crest to next crest, or trough to next trough. Measured in metres. For a sound wave it is the distance from one compression to the next.</li>\n  <li><strong>Amplitude:</strong> the maximum displacement from the rest position — how tall the crests are, measured from the middle line, not trough to crest. Amplitude is the wave\'s <em>energy</em> dial: bigger amplitude means brighter light, louder sound, taller ocean swell.</li>\n  <li><strong>Frequency (f):</strong> how many complete cycles pass a fixed point each second, in hertz (Hz). Stand on a pier and count crests passing per second — that is the frequency.</li>\n  <li><strong>Period (T):</strong> the time for one complete cycle to pass. It is simply the flip side of frequency: T = 1/f. A wave with f = 4 Hz has a period of 0.25 s.</li>\n</ul>\n<p>Frequency has a special property: it is stamped on the wave by its <strong>source</strong> and never changes afterwards. A 440 Hz tuning fork makes 440 compressions per second whether the sound then travels through air, water, or a wall — the receiving end must wiggle 440 times per second too. Wavelength, by contrast, stretches or shrinks when the wave changes speed in a new medium. Remember: <strong>frequency belongs to the source; wavelength adjusts to the medium</strong>.</p>\n<div class="analogy">\n  <h3>Analogy: A Marching Band</h3>\n  <p>Watch a marching band from a bridge. The drummer sets how many rows step past you per minute (frequency). The spacing between rows is the wavelength. If the band suddenly marches into mud and slows down, rows bunch closer together — same frequency, shorter wavelength. Waves entering a slower medium do exactly this.</p>\n</div>\n<p>Use the interactive below to build waves and watch these quantities in action: slide the frequency up and see the cycles crowd together; raise the amplitude and watch the crests grow; then add a second wave and see how overlapping waves stack — crest on crest reinforcing, crest on trough cancelling. That stacking behaviour, called superposition, is a wave signature nothing else in physics shares.</p>\n<div class="key-concept">\n  <h4>Key Concept</h4>\n  <p>Wavelength λ = length of one cycle (m). Frequency f = cycles per second (Hz). Amplitude = maximum displacement, and it carries the energy. Period T = 1/f. Frequency is fixed by the source; wavelength adapts to the medium.</p>\n</div>'},{id:"the-master-formula",title:"v = fλ: The One Formula Every Wave Obeys",content:'\n<p>Here is the most important equation of this entire subject, and one of the most universal in physics:</p>\n<p style="text-align:center;"><strong>wave speed = frequency \xd7 wavelength&nbsp;&nbsp;&nbsp;v = fλ</strong></p>\n<p>It is really just common sense in symbols. If 5 waves pass you every second (f = 5 Hz), and each wave is 2 m long (λ = 2 m), then 5 \xd7 2 = 10 metres of wave march past per second: v = 10 m/s. Frequency counts the cycles; wavelength measures each one; multiply and you get the speed of the parade.</p>\n<div class="key-concept">\n  <h4>Worked Example 1: The Length of a Musical Note</h4>\n  <p>Concert A has f = 440 Hz, and sound in air travels v = 343 m/s. Rearranged, λ = v / f = 343 / 440 ≈ <strong>0.78 m</strong>. Each cycle of that note is about the length of your arm. A low bass note at 55 Hz stretches λ = 343 / 55 ≈ 6.2 m — longer than a car, which is one reason bass rolls around corners and through walls so easily.</p>\n</div>\n<div class="key-concept">\n  <h4>Worked Example 2: Radio</h4>\n  <p>An FM station broadcasts at 100 MHz (100,000,000 Hz). Radio is a light-family wave, so v = 300,000,000 m/s. λ = 300,000,000 / 100,000,000 = <strong>3 m</strong>. FM antennas are sized around this wavelength — that is why they are metre-scale rods, not centimetre studs.</p>\n</div>\n<p>Three habits make the formula foolproof:</p>\n<ol>\n  <li><strong>Keep the units straight:</strong> f in Hz, λ in metres, v in m/s. Convert kHz and MHz to Hz before multiplying.</li>\n  <li><strong>Know which quantity is fixed.</strong> In one medium, v is set by the medium (343 m/s for air), so f and λ trade off: double the frequency, halve the wavelength.</li>\n  <li><strong>Rearrange freely:</strong> f = v/λ and λ = v/f are the same statement. Cover the symbol you want in the triangle v over f\xb7λ if that helps.</li>\n</ol>\n<p>The reach of this little equation is astonishing. It governs ripples in your teacup, sound in a concert hall, light from a star, radio from a satellite, X-rays in a hospital, and — as you will meet in the quantum subjects — even electrons, which turn out to have wavelengths of their own. Learn v = fλ once, and you will use it for the rest of the course.</p>'},{id:"waves-carry-energy",title:"What Waves Deliver: Energy on the Move",content:'\n<p>Why does the universe bother with waves? Because they are nature\'s delivery service: they move <strong>energy and information</strong> from one place to another without shipping any material. Sunlight crosses 150 million km of empty space and still warms your face — no substance made the trip, yet energy clearly arrived. An earthquake in the seafloor rattles buildings hundreds of kilometres away. A phone call rides radio waves from a tower to your pocket. In each case something real was transported — energy — while the medium (if there even was one) stayed home, only trembling in place.</p>\n<p>How much energy a wave delivers depends chiefly on its <strong>amplitude</strong>. Doubling the amplitude of a wave more than doubles its energy — for many waves, quadruples it. That is why amplitude differences feel so dramatic:</p>\n<ul>\n  <li>A 1 m ocean swell rocks a boat; a 10 m tsunami flattens a town.</li>\n  <li>A whisper barely moves your eardrum; a jet engine at close range can damage it permanently.</li>\n  <li>Gentle sunlight tans slowly; a focused laser of the same colour but huge amplitude cuts steel.</li>\n</ul>\n<p>Waves also do things particles cannot, and these behaviours will be your recurring test for "is this a wave?" throughout physics:</p>\n<ul>\n  <li><strong>Reflection:</strong> waves bounce off barriers (echoes, mirrors — the next chapter).</li>\n  <li><strong>Refraction:</strong> waves bend when they change speed in a new medium (the chapter after).</li>\n  <li><strong>Diffraction:</strong> waves bend around edges and spread through gaps — why you hear music through a doorway before you see the band.</li>\n  <li><strong>Superposition:</strong> two waves pass through each other and simply add — crest on crest grows, crest on trough cancels — then continue unchanged, as you saw in the simulator.</li>\n</ul>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>Noise-cancelling headphones are applied superposition. A microphone samples the incoming noise, a chip generates the same wave flipped upside down — trough where the noise has crest — and the two add to near-silence in your ear canal. You are listening to deliberate, engineered cancellation.</p>\n</div>\n<p>Hold on to this picture: a wave is a travelling pattern that carries energy, described by amplitude, wavelength, and frequency, obeying v = fλ. Sound demonstrated it; light is about to run with it.</p>'}],quiz:[{question:"In a longitudinal wave, the particles of the medium move…",options:["perpendicular to the direction the wave travels","in circles around the wave's path","back and forth along the direction the wave travels","not at all — only the energy moves"],correctIndex:2,explanation:"Longitudinal waves like sound vibrate the medium along the travel direction, creating compressions and rarefactions. (Transverse waves vibrate perpendicular to travel.) The particles do move — they oscillate about fixed positions — but they are not carried along with the wave."},{question:"A wave has frequency 50 Hz and wavelength 4 m. What is its speed?",options:["200 m/s","12.5 m/s","54 m/s","0.08 m/s"],correctIndex:0,explanation:"v = fλ = 50 Hz \xd7 4 m = 200 m/s. Fifty cycles pass per second, each 4 m long, so 200 metres of wave stream past every second."},{question:"Which property of a wave is set by the source and does NOT change when the wave enters a new medium?",options:["Wavelength","Speed","Amplitude","Frequency"],correctIndex:3,explanation:"Frequency is stamped on the wave by its source — the new medium must wiggle at the same rate the wave arrives. Speed changes with the medium, and wavelength adjusts to match via λ = v/f, like marching rows bunching up when the band hits mud."},{question:"Sound travels at 343 m/s in air. What is the wavelength of a 686 Hz whistle?",options:["2 m","0.5 m","343 m","235,000 m"],correctIndex:1,explanation:"λ = v / f = 343 / 686 = 0.5 m. Notice the trade-off: this frequency is high (twice 343), so the wavelength comes out short (half a metre). In a fixed medium, higher frequency always means shorter wavelength."},{question:"Why can you see the Sun but never hear it, despite its violently roiling surface?",options:["The Sun is too far away for any wave to reach us","Light is transverse and needs no medium, but sound needs matter to travel through — and space is a near-vacuum","The Sun's sound is at frequencies too low for human ears","Light travels faster, so the sound has not arrived yet"],correctIndex:1,explanation:"Light's vibrating electric and magnetic fields carry themselves through empty space, but sound is a mechanical wave — it must squeeze a medium, and the near-vacuum between Sun and Earth gives it nothing to squeeze. The Sun does roar with pressure waves internally, but they can never cross the gap to us."}]},{id:"reflection-and-mirrors",title:"Reflection & Mirrors",subtitle:"The law of reflection and the images formed by plane and curved mirrors",sections:[{id:"light-in-straight-lines",title:"Rays and the Law of Reflection",content:'\n<p>Optics begins with one simplifying idea: in a uniform material, <strong>light travels in straight lines</strong>. Sunbeams slicing through dusty air, laser pointers, the crisp edges of shadows — all testify to it. So we draw light as <strong>rays</strong>: straight arrows showing the direction of travel. A ray is not a thing; it is a bookkeeping device, and it is powerful enough to explain every mirror, lens, camera, and telescope in this subject.</p>\n<p>When a ray strikes a surface and bounces, it obeys one beautifully simple rule, the <strong>law of reflection</strong>. Draw the <strong>normal</strong> — an imaginary line perpendicular to the surface at the point of impact. Measure the incoming ray\'s angle from that normal (the <em>angle of incidence</em>, i) and the outgoing ray\'s angle from the same normal (the <em>angle of reflection</em>, r). Then, always and everywhere:</p>\n<p style="text-align:center;"><strong>angle of incidence = angle of reflection&nbsp;&nbsp;(i = r)</strong></p>\n<p>A ray arriving at 30\xb0 from the normal leaves at 30\xb0 on the other side; a ray arriving head-on (0\xb0) bounces straight back. Billiards players know this law in their bones — a ball banked off a cushion follows the same geometry.</p>\n<p>Why, then, can you see your face in polished steel but not in brushed concrete, when both reflect light?</p>\n<ul>\n  <li><strong>Specular reflection:</strong> a surface smooth at microscopic scale (mirror, calm water) reflects parallel rays as parallel rays. The organised bundle preserves the picture — you get an image.</li>\n  <li><strong>Diffuse reflection:</strong> a rough surface (paper, skin, walls) obeys i = r at every point, but the surface tilts every which way, so the rays scatter in all directions. No image survives — but scattering is exactly why you can see the object at all, from anywhere in the room.</li>\n</ul>\n<div class="key-concept">\n  <h4>Key Concept</h4>\n  <p>Every reflection, from a shaving mirror to a satellite dish, obeys i = r measured from the normal. Smooth surfaces keep rays organised and form images (specular); rough surfaces scatter them and merely make objects visible (diffuse).</p>\n</div>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>Apollo astronauts left suitcase-sized reflector panels on the Moon. Observatories still fire lasers at them and time the reflection — about 2.5 seconds for the round trip — measuring the Moon\'s distance to millimetre precision. The measurements show the Moon spiralling away from Earth by 3.8 cm per year.</p>\n</div>'},{id:"plane-mirror-images",title:"The Person Behind the Glass: Plane Mirrors",content:'\n<p>Look into a flat (plane) mirror and someone looks back — apparently standing <em>behind</em> the glass. There is nobody there, of course. Here is what actually happens: rays leave your face, reflect off the mirror obeying i = r, and enter your eye. Your brain, which always assumes light travels in straight lines, traces those diverging rays <em>backwards</em> — and the backward extensions meet at a point behind the mirror. That meeting point is where your brain places the image.</p>\n<p>Because no light actually passes through or comes from that point, it is called a <strong>virtual image</strong>. You cannot catch it on a screen held behind the mirror; there is nothing there to catch. Yet its geometry is precise:</p>\n<ul>\n  <li>The image is exactly <strong>as far behind the mirror as you are in front</strong>. Stand 2 m away and your image stands 2 m behind the glass — 4 m from you, which is why your eyes focus on it as a distant object.</li>\n  <li>The image is <strong>the same size</strong> as you, upright, and moves with you — step back 1 m and it retreats 1 m.</li>\n  <li>The image is <strong>reversed front-to-back</strong>. The mirror does not actually swap left and right — your right hand is still on your right side of the glass. It swaps <em>towards-and-away</em>: your nose points at you, and that front-back flip is what makes text appear "mirror writing" and makes your reflection seem left-right swapped.</li>\n</ul>\n<div class="key-concept">\n  <h4>Key Concept: The Half-Height Mirror</h4>\n  <p>To see your full body you need a mirror only <strong>half your height</strong>, no matter how far you stand from it. Geometry: the ray from your toes to your eye bounces off the mirror at its halfway point (i = r), so the glass below eye-level need only reach halfway down to your toes\' level. Try marking a large mirror with sticky notes at the points where you see your hairline and toes — the notes will span half your height at any distance.</p>\n</div>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Stand two small mirrors upright at 90\xb0 to each other (a hinged makeup mirror works). Look into the corner: the double reflection flips your image front-to-back <em>twice</em>, so you see yourself as others see you — un-reversed. Wink your right eye and, unlike in a single mirror, the eye on your right as you see it winks back. Text held up to the corner reads normally.</p>\n</div>\n<p>Plane mirrors are the simplest image-formers in optics — every ray honestly obeys one law, and a life-size virtual twin appears. Curve the mirror, though, and far stranger and more useful things happen.</p>'},{id:"curved-mirrors",title:"Curved Mirrors: Focusing and Spreading Light",content:'\n<p>Bend a mirror and you gain a superpower: the ability to <strong>concentrate or spread</strong> light, not just redirect it. Each point of the curved surface still obeys i = r — but because the surface tilts continuously, the reflected rays converge or diverge on purpose. Both kinds live in your kitchen: the inside of a polished spoon is a <strong>concave</strong> mirror (caves inward), the back is a <strong>convex</strong> mirror (bulges outward).</p>\n<p><strong>Concave mirrors</strong> collect. Rays arriving parallel to the axis (as from something distant) reflect inward and cross at one spot — the <strong>focal point</strong>, at a distance called the focal length, f, from the mirror. What you see depends on where the object sits:</p>\n<ul>\n  <li><strong>Object beyond the focal point:</strong> the reflected rays really do cross, forming a <strong>real, inverted image</strong> — one you can project onto a screen. Look into a spoon\'s bowl at arm\'s length and your tiny reflection is upside down.</li>\n  <li><strong>Object inside the focal point:</strong> the rays diverge after reflecting, and tracing them backwards gives a <strong>virtual, upright, magnified image</strong>. This is the shaving and makeup mirror: lean in close and your face looms larger.</li>\n</ul>\n<p>Run the light the other way and concave mirrors become beam-makers: put a bulb <em>at</em> the focal point and reflected rays leave parallel — the principle of torches, car headlights, and lighthouse beams. Aimed at the sky, big concave mirrors gather faint starlight to a focus: every major telescope on Earth (and Webb in space) is built around one.</p>\n<p><strong>Convex mirrors</strong> scatter. Parallel rays reflect outward as if from a focal point <em>behind</em> the mirror, so a convex mirror always shows a <strong>virtual, upright, shrunken</strong> image — of a very wide scene. That trade of size for field of view makes them the mirrors of safety: shop-corner domes, blind-driveway mirrors, and the passenger-side mirror stamped <em>"objects in mirror are closer than they appear"</em> — the shrunken image fools your brain into judging cars smaller and farther than they are.</p>\n<table>\n  <thead>\n    <tr><th>Mirror</th><th>Image</th><th>Used for</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Plane</td><td>Virtual, upright, same size</td><td>Dressing, decorating</td></tr>\n    <tr><td>Concave (object close)</td><td>Virtual, upright, magnified</td><td>Makeup, shaving, dentistry</td></tr>\n    <tr><td>Concave (object far)</td><td>Real, inverted</td><td>Telescopes, headlights (reversed), solar furnaces</td></tr>\n    <tr><td>Convex</td><td>Virtual, upright, smaller, wide view</td><td>Security, car mirrors</td></tr>\n  </tbody>\n</table>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Hold a shiny tablespoon at arm\'s length, bowl towards you: you are beyond its focal point, so your face is small and upside down. Bring it slowly closer than the focal length (a few centimetres) and your image flips upright and swells. Turn the spoon over — the convex back always shows you upright, shrunken, and set in a wide little world, exactly like a security mirror.</p>\n</div>'}],quiz:[{question:"A light ray strikes a plane mirror at 25\xb0 from the normal. At what angle does it reflect?",options:["50\xb0 from the normal","65\xb0 from the normal","25\xb0 from the normal","It depends on the mirror's material"],correctIndex:2,explanation:"The law of reflection says angle of incidence = angle of reflection, both measured from the normal (the perpendicular to the surface). In at 25\xb0, out at 25\xb0 — for every mirror, always. (65\xb0 would be the answer only if angles were measured from the surface itself.)"},{question:"Why can't you project your bathroom-mirror image onto a piece of paper held behind the mirror?",options:["The image is virtual — no light actually passes through the point where it appears","The mirror absorbs too much light for projection","The paper would need to be photographic film","You can — if the room is dark enough"],correctIndex:0,explanation:"A plane mirror's image is virtual: your brain traces the reflected rays backwards to a point behind the glass, but no rays are actually there. Only real images — where rays genuinely converge, as from a concave mirror or a camera lens — can land on a screen."},{question:"You stand 1.5 m in front of a plane mirror. How far is your image from you?",options:["1.5 m","3.0 m","0.75 m","It depends on the mirror's size"],correctIndex:1,explanation:"The image forms as far behind the mirror as you stand in front: 1.5 m behind the glass. Your distance to it is 1.5 + 1.5 = 3.0 m — which is why your eyes must refocus when you glance from the mirror frame to your own reflection."},{question:"Why do shops and driveways use convex mirrors rather than plane or concave ones?",options:["Convex mirrors magnify intruders so they are easier to identify","Convex mirrors form real images that can be recorded","Convex mirrors are the only mirrors that work in dim light","Convex mirrors show a much wider field of view, at the cost of a smaller image"],correctIndex:3,explanation:"A convex mirror spreads reflected rays outward, packing a wide scene into one small upright image — ideal for watching a whole aisle or a hidden driveway at a glance. The shrunken image is the price, which is why car door mirrors warn that objects are closer than they appear."},{question:"A torch bulb is placed exactly at the focal point of a concave mirror. What does the reflected light do?",options:["It converges back onto the bulb","It emerges as a parallel beam","It forms an upside-down image of the bulb on the wall","It scatters evenly in all directions"],correctIndex:1,explanation:"Rays from the focal point reflect off the concave surface and leave parallel to the axis — reflection run in reverse. This is precisely how torches, headlights, and lighthouses turn a small bulb into a straight, far-reaching beam."}]},{id:"refraction-and-lenses",title:"Refraction & Lenses",subtitle:"Bending light: total internal reflection, optical fibres, and ray diagrams for lenses",sections:[{id:"bending-light",title:"Refraction: Why Light Bends",content:'\n<p>Put a straw in a glass of water and it appears snapped at the surface. Coins at the bottom of pools look closer than they are; spear-fishers must aim <em>below</em> the fish they see. Behind all these illusions is <strong>refraction</strong>: light changes direction when it crosses from one transparent material into another.</p>\n<p>The cause is a change of <strong>speed</strong>. Light\'s famous 300,000 km/s is its speed in vacuum; in materials it is slower — about 225,000 km/s in water and 200,000 km/s in glass. Each material has a <strong>refractive index</strong>, n: how many times slower light moves there than in vacuum (water n ≈ 1.33, glass n ≈ 1.5, diamond n ≈ 2.4). When a ray crosses a boundary at an angle, one side of the beam slows before the other, and the beam swings around.</p>\n<div class="analogy">\n  <h3>Analogy: The Shopping Trolley on the Lawn</h3>\n  <p>Push a trolley at an angle from smooth pavement onto grass. The wheel that hits the grass first slows while the other still rolls freely, so the trolley pivots towards the grass side. Light entering glass at an angle does the same — the edge that enters first is held back, and the ray bends. Leaving the grass, the first-freed wheel speeds ahead and the trolley swings the other way.</p>\n</div>\n<p>The rules to remember, always measuring angles from the normal:</p>\n<ul>\n  <li>Entering a <strong>slower</strong> medium (air → water, air → glass): the ray bends <strong>towards the normal</strong>.</li>\n  <li>Entering a <strong>faster</strong> medium (glass → air): the ray bends <strong>away from the normal</strong>.</li>\n  <li>Hitting the boundary <strong>head-on</strong> (along the normal): the ray slows but does not bend.</li>\n  <li>Frequency never changes at the boundary — the wavelength shrinks or stretches instead, exactly as v = fλ demands.</li>\n</ul>\n<p>Refraction is why the pool floor looks raised (rays from the bottom bend away from the normal as they exit, and your brain traces them straight back to a shallower point), why stars twinkle (starlight refracts through churning layers of air of different densities), and why the setting Sun is still visible when it is geometrically below the horizon — the atmosphere bends its light around the curve of the Earth by about half a degree, the Sun\'s own width.</p>\n<div class="key-concept">\n  <h4>Key Concept</h4>\n  <p>Light bends at a boundary because it changes speed. Slower medium: bend towards the normal. Faster medium: bend away. Every lens in the world — including the two in your head — is engineered refraction.</p>\n</div>'},{id:"total-internal-reflection",title:"Trapped Light: Total Internal Reflection and Optical Fibres",content:'\n<p>Refraction has a dramatic breaking point. Picture a ray trying to leave glass into air. It bends <em>away</em> from the normal on exit — the outgoing ray leans ever closer to the surface as you steepen the angle inside. At one particular angle of incidence, the <strong>critical angle</strong>, the refracted ray skims exactly along the surface. Push past it and the light cannot get out at all: the boundary behaves as a perfect mirror and reflects 100% of the light back inside. This is <strong>total internal reflection</strong> (TIR).</p>\n<ul>\n  <li>It only happens going from a <strong>slower medium towards a faster one</strong> (glass → air, water → air) — never on the way in.</li>\n  <li>The critical angle depends on the material: about <strong>49\xb0</strong> for water, <strong>42\xb0</strong> for ordinary glass, and a mere <strong>24\xb0</strong> for diamond.</li>\n  <li>Unlike metal mirrors, which absorb a few percent of the light at each bounce, TIR is genuinely <em>total</em> — lossless, bounce after bounce.</li>\n</ul>\n<p>Diamond\'s tiny critical angle explains its fire: light entering a well-cut stone finds almost every internal surface beyond 24\xb0, so it ricochets around inside and finally blazes out through the top facets. Swimmers see TIR too — look up from underwater at a shallow angle and the surface turns into a silver mirror reflecting the pool floor.</p>\n<div class="key-concept">\n  <h4>Key Concept: The Optical Fibre</h4>\n  <p>Draw glass into a hair-thin thread and light launched down its core strikes the walls at glancing angles far beyond the critical angle. It ricochets forward by TIR, bounce after lossless bounce, and emerges at the far end — even if the fibre bends and loops. Modern fibres are so pure that a signal can run ~100 km before needing a boost. Bundle thousands of fibres into submarine cables and you have the physical internet: nearly all intercontinental data — this course included — crosses the oceans as flashes of laser light totally internally reflected inside glass threads thinner than fishing line.</p>\n</div>\n<p>Medicine borrows the same trick: an <strong>endoscope</strong> packs one fibre bundle to pipe light into the body and another to carry the image back, letting surgeons inspect and operate through keyhole incisions. Reflecting prisms in binoculars and periscopes use TIR instead of mirrors for the same reason — no silvering, no loss.</p>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>A signal in optical fibre actually travels slower than radio through air (light in glass moves at about two-thirds speed), but fibre wins on capacity: a single modern fibre pair can carry hundreds of terabits per second — millions of video calls in a strand of glass you could thread through a needle.</p>\n</div>'},{id:"lenses",title:"Lenses: Refraction Put to Work",content:'\n<p>A <strong>lens</strong> is a piece of transparent material shaped so that refraction at its two curved surfaces bends every ray by just the right amount to organise light on purpose. Two families cover everything:</p>\n<ul>\n  <li><strong>Converging (convex) lenses</strong> — fatter in the middle. Rays arriving parallel to the axis are bent inward and meet at the <strong>focal point</strong>, a distance f (the <strong>focal length</strong>) behind the lens. A fat, strongly curved lens has a short focal length — it is a <em>strong</em> lens. Magnifying glasses, camera lenses, projectors, and your own cornea are converging.</li>\n  <li><strong>Diverging (concave) lenses</strong> — thinner in the middle. Parallel rays are spread outward, as if they had come from a virtual focal point <em>in front of</em> the lens. On their own they always produce a smaller, upright, virtual view — you will meet them correcting short sight in the next chapter and taming light inside camera lenses.</li>\n</ul>\n<p>A converging lens is a double-crossing machine, and where the object sits decides everything:</p>\n<ul>\n  <li><strong>Object far beyond the focal length:</strong> rays converge to a <strong>real, inverted, shrunken image</strong> just beyond f on the far side. This is the camera and the eye: the vast world imaged small and upside down on a sensor or retina.</li>\n  <li><strong>Object just beyond f:</strong> a real, inverted, <strong>enlarged</strong> image forms far behind the lens — the projector, throwing a small slide huge onto a wall (the slide is loaded upside down so the picture comes out right).</li>\n  <li><strong>Object closer than f:</strong> the rays leave the lens still spreading; traced backwards they form a <strong>virtual, upright, magnified image</strong>. This is the magnifying glass — the image floats behind the print, larger, on the same side as the object.</li>\n</ul>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>On a sunny day, hold a magnifying glass over pavement and move it until the bright blur shrinks to a dazzling dot: you have found its focal length — the dot is a real image of the Sun (careful: it burns; never look at the Sun through it). Indoors, hold the same lens about that distance from a wall facing a bright window: a sharp, upside-down, full-colour image of the window scene appears on the wall. A real image, caught on a screen — exactly what happens on your retina right now.</p>\n</div>\n<div class="key-concept">\n  <h4>Key Concept</h4>\n  <p>Converging lenses bring parallel light to a focal point at distance f; diverging lenses spread it from a virtual focal point. Object outside f → real, inverted image (camera). Object inside f → virtual, upright, magnified image (magnifying glass).</p>\n</div>'},{id:"ray-diagrams-and-magnification",title:"Ray Diagrams and Magnification",content:"\n<p>You can predict any lens image with a pencil, a ruler, and <strong>three special rays</strong> whose paths are known in advance. Draw the lens as a vertical line, the axis through its middle, mark the focal point F at distance f on each side, and stand your object (an upright arrow) on the axis. From the arrow's tip, launch:</p>\n<ol>\n  <li><strong>The parallel ray:</strong> travels parallel to the axis, then refracts through the far focal point.</li>\n  <li><strong>The central ray:</strong> passes straight through the centre of the lens undeviated (the middle acts like flat glass).</li>\n  <li><strong>The focal ray:</strong> passes through the near focal point, then leaves the lens parallel to the axis (ray 1 in reverse).</li>\n</ol>\n<p>Where the rays cross, the image of the tip sits. Any two rays suffice; the third is your check. If the rays cross on the far side, the image is <strong>real and inverted</strong> (drawn below the axis). If they leave the lens still spreading, extend them backwards with dashed lines — they meet on the object's side at a <strong>virtual, upright</strong> image, which is exactly the geometry of a magnifying glass.</p>\n<p>How much bigger or smaller? That is <strong>magnification</strong>:</p>\n<p style=\"text-align:center;\"><strong>magnification = image height \xf7 object height = image distance \xf7 object distance</strong></p>\n<p>Magnification has no units — it is a pure ratio. m = 3 means three times life size; m = 0.5 means half size; and on your diagram an inverted image gives a flipped arrow.</p>\n<div class=\"key-concept\">\n  <h4>Worked Example</h4>\n  <p>A stamp 2 cm tall sits 6 cm from a magnifying glass, and the ray diagram puts its virtual image 18 cm from the lens. Magnification = 18 \xf7 6 = <strong>3</strong>, so the image height = 3 \xd7 2 cm = <strong>6 cm</strong>. Upright, enlarged, floating behind the stamp — just what a collector sees. For contrast: a camera photographs a 1.8 m person from 6 m with the image forming about 5 cm behind the lens. m = 0.05 \xf7 6 ≈ 0.008, so the image is 1.8 m \xd7 0.008 ≈ 1.5 cm — the whole person, upside down, comfortably inside the camera sensor.</p>\n</div>\n<p>These humble arrow-and-ruler sketches are the working language of optics. In the next chapter you will chain them — one lens's image becoming the next lens's object — and that single move builds every microscope and telescope ever made. Subject 13 will add the algebra (the thin-lens equation) to make the diagrams fully quantitative.</p>"}],quiz:[{question:"A ray of light passes from air into glass at an angle. What happens to it?",options:["It speeds up and bends away from the normal","It slows down and bends towards the normal","It slows down and bends away from the normal","It continues in a straight line at the same speed"],correctIndex:1,explanation:"Glass is optically denser: light drops from 300,000 km/s to about 200,000 km/s, and the ray pivots towards the normal — like a trolley swinging as its first wheel hits grass. (Only a ray entering exactly along the normal goes unbent, though it still slows.)"},{question:"Total internal reflection can occur only when light travels…",options:["from a slower (denser) medium towards a faster one, beyond the critical angle","from a faster medium towards a slower one, beyond the critical angle","between any two media, if the light is bright enough","when light hits any boundary exactly along the normal"],correctIndex:0,explanation:"TIR needs the ray to be trying to exit into a faster medium (glass → air, water → air) at an angle beyond the critical angle — then the boundary reflects 100% of the light back. Going the other way, some light always gets through, no matter the angle or brightness."},{question:"How do optical fibres carry internet signals across oceans?",options:["Electric currents flow through a copper core inside the glass","The glass amplifies radio waves as they pass through","Light ricochets along the glass core by total internal reflection, bounce after lossless bounce","Mirrors coated on the outside of the fibre reflect the light forward"],correctIndex:2,explanation:"Light launched down the hair-thin core hits the walls beyond the critical angle, so total internal reflection returns it forward with no loss at each bounce — no silvered coating needed. Ultra-pure glass lets the signal run about 100 km between boosts, and bundles of such fibres form the physical backbone of the internet."},{question:"A stamp is placed closer to a converging lens than its focal length. The image is…",options:["real, inverted, and smaller","real, inverted, and larger","impossible — no image forms","virtual, upright, and magnified"],correctIndex:3,explanation:"Inside the focal length the refracted rays still diverge after the lens; traced backwards they form an upright, enlarged, virtual image on the stamp's own side. That is precisely the magnifying-glass arrangement. Real, inverted images only occur when the object sits outside the focal length."},{question:"An object 4 cm tall forms an image 12 cm tall. What is the magnification?",options:["0.33","3","48","8"],correctIndex:1,explanation:"Magnification = image height \xf7 object height = 12 \xf7 4 = 3. It is a pure ratio with no units: this image is three times life size. (48 comes from multiplying instead of dividing; 0.33 from dividing the wrong way round.)"}]},{id:"the-eye-cameras-and-instruments",title:"The Eye, Cameras & Instruments",subtitle:"Optics applied: vision and its correction, cameras, microscopes, and telescopes",sections:[{id:"the-eye",title:"The Eye: A Living Camera",content:"\n<p>Everything in the last two chapters is running in your head right now, twice. The human eye is a self-focusing, self-cleaning, auto-exposing optical instrument, and by this point in the course you can read its blueprint:</p>\n<ul>\n  <li><strong>Cornea:</strong> the transparent front window — and, surprisingly, the eye's main lens. The big speed change from air into watery tissue makes the cornea do about two-thirds of all the focusing, fixed and unadjustable.</li>\n  <li><strong>Iris and pupil:</strong> the coloured ring is a muscular diaphragm; the pupil is simply the hole in it. In dim light it opens to ≈ 8 mm; in sunshine it narrows to ≈ 2 mm — an automatic aperture.</li>\n  <li><strong>Crystalline lens:</strong> a soft converging lens behind the pupil that supplies the adjustable third of the focusing.</li>\n  <li><strong>Retina:</strong> the light-sensitive screen at the back where a <strong>real, inverted image</strong> forms — your world arrives upside down, and your brain silently flips it.</li>\n</ul>\n<p>A camera focuses by moving its lens; the eye does something cleverer — it <strong>reshapes</strong> its lens. Ring muscles around the lens relax for distant scenes, pulling it thin and weak, and tighten for close work, letting it bulge fat and strong. This continuous refocusing is <strong>accommodation</strong>, and you can feel its limit: bring a fingertip towards your nose and it blurs at the <em>near point</em>, about 25 cm for young adults, where the lens can bulge no further. The lens stiffens with age, which is why near points recede and reading glasses appear in most people's forties — presbyopia.</p>\n<p>The retina's 100+ million detectors come in two kinds: <strong>rods</strong> (super-sensitive, colour-blind, night vision — peripheral and starlight specialists) and <strong>cones</strong> (colour vision in three types, packed into the central fovea where you point your gaze). One patch has no detectors at all — where the optic nerve exits — yet you never notice the blind spot because the brain seamlessly paints over it.</p>\n<div class=\"did-you-know\">\n  <h4>Try it yourself</h4>\n  <p>Draw a small \xd7 and a • about 8 cm apart on paper. Close your left eye, stare at the \xd7 with your right, and slowly move the page towards you from arm's length. Around 25–30 cm the dot vanishes — its image has landed on your blind spot. Keep staring: the paper appears unbroken, because your brain fabricates the missing patch. You are watching your own visual system make things up.</p>\n</div>\n<div class=\"key-concept\">\n  <h4>Key Concept</h4>\n  <p>Cornea + adjustable lens form a real, inverted image on the retina. Focusing is done by reshaping the lens (accommodation); brightness by the iris; detection by rods (dim, monochrome) and cones (colour).</p>\n</div>"},{id:"vision-correction",title:"When Focus Fails: Glasses and Vision Correction",content:"\n<p>Perfect vision means the eye's optics land a sharp image exactly on the retina for whatever you look at. If the focus falls short of the retina or beyond it, the world blurs — and the fix is beautifully simple lens physics.</p>\n<p><strong>Short sight (myopia):</strong> the eyeball is slightly too long, or the cornea too strongly curved, so distant objects focus <em>in front of</em> the retina; by the time the light reaches the screen it has crossed and re-spread into blur. Near objects are fine — their diverging rays push the focus back onto the retina. The cure is a <strong>diverging (concave) lens</strong>: it pre-spreads incoming parallel light just enough that the over-eager eye focuses it on, not before, the retina. Prescriptions for myopia read negative (say, −2.5 dioptres) — a diverging correction.</p>\n<p><strong>Long sight (hyperopia):</strong> the eyeball is too short or the optics too weak, so near objects would focus <em>behind</em> the retina — reading becomes the struggle, while distance may stay clear. The cure is a <strong>converging (convex) lens</strong> that adds focusing power; prescriptions read positive (+1.5 dioptres and the like). Age-related <strong>presbyopia</strong> — the stiffening lens that can no longer bulge for close work — is fixed the same way, with reading glasses, or bifocals that put distance correction on top and reading power below.</p>\n<table>\n  <thead>\n    <tr><th>Condition</th><th>Where focus falls</th><th>Blurry range</th><th>Correcting lens</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Myopia (short sight)</td><td>In front of retina</td><td>Far away</td><td>Diverging (−)</td></tr>\n    <tr><td>Hyperopia (long sight)</td><td>Behind retina</td><td>Close up</td><td>Converging (+)</td></tr>\n    <tr><td>Presbyopia (ageing lens)</td><td>Behind retina for near objects</td><td>Close up</td><td>Converging (+) for reading</td></tr>\n  </tbody>\n</table>\n<p>Contact lenses are the same corrections floating on the tear film. Laser surgery (LASIK) goes one step further: since the cornea does most of the focusing, reshaping it by a few hundredths of a millimetre — flattening it for myopia — rebuilds the correction into the eye itself. Astigmatism, blur from a cornea curved unevenly (more rugby ball than football), is corrected with lenses ground with different power in different directions.</p>\n<div class=\"did-you-know\">\n  <h4>Did You Know?</h4>\n  <p>Myopia is surging worldwide — in some East Asian cities over 80% of school-leavers are short-sighted, roughly double the rate two generations ago. The strongest protective factor found so far is simply time outdoors in daylight: bright light appears to slow the eyeball's elongation during childhood.</p>\n</div>"},{id:"cameras",title:"Cameras: Capturing the Image",content:'\n<p>A camera is an eye rebuilt in metal and silicon, and comparing the two is a masterclass in optics. Both use a converging lens to throw a <strong>real, inverted image</strong> onto a light-sensitive surface; nearly every difference lies in <em>how</em> each one manages focus and light.</p>\n<ul>\n  <li><strong>Focusing:</strong> your eye reshapes its lens; a camera slides its (rigid glass) lens towards or away from the sensor. Distant subject → lens close to the sensor, near the focal length; close subject → lens racked outward. "Macro" mode is simply permission to rack further.</li>\n  <li><strong>Aperture:</strong> an iris of overlapping blades sets the size of the light-admitting hole, quoted as f-numbers (f/2, f/8, f/16 — bigger number, <em>smaller</em> hole). Like your pupil, it manages brightness; unlike your pupil, it also chooses <strong>depth of field</strong>: a wide aperture focuses sharply on one plane and melts the background (portraits), a tiny aperture keeps near and far acceptably sharp (landscapes).</li>\n  <li><strong>Shutter:</strong> the eye watches continuously; a camera opens for a measured slice of time — 1/1000 s freezes a hummingbird, a 30 s exposure gathers starlight the eye could never accumulate.</li>\n  <li><strong>Sensor:</strong> where the retina has rods and cones, a digital sensor has millions of pixels, each counting the light that lands on it; colour comes from a mosaic of red, green, and blue filters over the pixels — an idea you will recognise in the next chapter.</li>\n</ul>\n<div class="key-concept">\n  <h4>Key Concept: Exposure Is a Budget</h4>\n  <p>A correctly exposed photo needs a set amount of light, spendable three ways: aperture (how wide the tap opens), shutter time (how long it runs), and sensor sensitivity (ISO). Open the aperture one step and you can halve the shutter time. Every camera setting, and every smartphone "night mode," is an allocation of this one budget.</p>\n</div>\n<p>Strip the idea to its minimum and you get the <strong>pinhole camera</strong> — no lens at all, just a tiny hole in a box. Each point of the scene can send only one narrow ray bundle through the hole, so a dim, inverted image forms on the back wall: straight-line propagation, nothing more. It proves an image needs only geometry; the lens\'s contribution is brightness (gathering a wide cone of rays per point) and, with it, the need for focusing.</p>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>Your smartphone camera\'s lens is a stack of five to eight tiny moulded plastic lenses, each correcting the flaws of the others, squeezed into a few millimetres — plus software that removes the residual distortion. A century of lens design, folded into your pocket.</p>\n</div>'},{id:"microscopes-and-telescopes",title:"Microscopes and Telescopes: Chaining Lenses",content:"\n<p>One converging lens makes a decent magnifier — around 10\xd7 before the image distorts. The breakthrough of the 1600s was the <strong>two-stage instrument</strong>: let one lens form a real image, then examine <em>that image</em> with a second lens as if it were an object. Magnifications multiply, and two modest lenses outperform any single one.</p>\n<p><strong>The compound microscope</strong> attacks the very small. A short-focal-length <strong>objective</strong> lens sits just beyond its focal length from the specimen, projecting a real, inverted, enlarged image up the tube. The <strong>eyepiece</strong> then works as a magnifying glass on that image. The powers multiply: a 40\xd7 objective with a 10\xd7 eyepiece gives <strong>400\xd7</strong> — enough to turn a smear of pond water into a zoo of darting cells. With oil-immersion objectives, light microscopes reach about 1,500\xd7, their practical ceiling (set, as Subject 13 will show, by the wavelength of light itself). It was through such stacked lenses that van Leeuwenhoek and Hooke first saw bacteria and cells in the 1670s — arguably optics' greatest gift to medicine.</p>\n<p><strong>The telescope</strong> attacks the very far. A refracting telescope's big objective lens (long focal length) forms a real image of the Moon or a ship at its focal plane; the short-focal-length eyepiece magnifies that image. The angular magnification is the ratio of the focal lengths — objective f = 100 cm with eyepiece f = 5 cm gives 20\xd7, and an inverted view, which astronomers cheerfully ignore. But a telescope's first job is not magnification — it is <strong>light-gathering</strong>. A 10 cm objective collects about 200 times more light than your ≈ 7 mm dark-adapted pupil, unveiling stars far too faint for the naked eye.</p>\n<p>Big lenses, however, sag under their own weight and tint the image (different colours focus at slightly different points). Newton's fix in 1668: swap the objective lens for a <strong>concave mirror</strong>, which weighs less, has no colour error, and can be supported from behind. Every major telescope since is a <strong>reflector</strong> — from observatory giants with 10 m mirror mosaics to the James Webb Space Telescope's 6.5 m gold-coated mirror, a concave reflector from the mirrors chapter, catching light that has travelled for over 13 billion years.</p>\n<div class=\"key-concept\">\n  <h4>Key Concept</h4>\n  <p>Microscope and telescope share one architecture: objective forms a real image; eyepiece magnifies it. Microscope: short-f objective, close object, magnifications multiply (40\xd7 \xd7 10\xd7 = 400\xd7). Telescope: long-f objective for distant objects, magnification = objective f \xf7 eyepiece f — and aperture, which sets light-gathering, matters most.</p>\n</div>"}],quiz:[{question:"Which part of the eye does most of the focusing?",options:["The pupil","The cornea","The retina","The crystalline lens"],correctIndex:1,explanation:"The cornea — the curved front window — does about two-thirds of the eye's focusing, because the biggest light-speed change happens where light passes from air into tissue. The crystalline lens supplies the adjustable remainder (accommodation); the retina is the screen, and the pupil is just the aperture."},{question:"A short-sighted (myopic) person sees nearby objects clearly but distant ones blurred. Why, and what corrects it?",options:["Distant objects focus behind the retina; a converging lens corrects it","The retina has too few cones; no lens can correct it","Distant objects focus in front of the retina; a diverging lens corrects it","The pupil is too small; brighter light corrects it"],correctIndex:2,explanation:"In myopia the eyeball is slightly too long (or the optics too strong), so parallel light from distant objects converges before reaching the retina and blurs. A diverging (concave) lens pre-spreads the light so the eye's focus lands exactly on the retina — that is why myopic prescriptions are negative."},{question:"The image formed on your retina and on a camera sensor is…",options:["virtual and upright","virtual and inverted","real and upright","real and inverted"],correctIndex:3,explanation:"Both the eye and the camera place the object well outside the focal length of a converging lens, which always yields a real, inverted image — light genuinely converges on the retina or sensor, upside down. Your brain flips the view; a camera flips it in software."},{question:"A microscope has a 40\xd7 objective and a 10\xd7 eyepiece. What is its total magnification, and why?",options:["400\xd7 — the eyepiece magnifies the real image already enlarged by the objective, so the powers multiply","50\xd7 — the two powers add together","40\xd7 — only the objective's power counts","4\xd7 — the eyepiece divides the objective's power"],correctIndex:0,explanation:"Two-stage instruments chain their lenses: the objective forms a real image 40 times enlarged, and the eyepiece then magnifies that image a further 10 times, like enlarging an already-enlarged photograph. Stages multiply: 40 \xd7 10 = 400\xd7."},{question:"Why are all large modern telescopes built around mirrors rather than lenses?",options:["Mirrors magnify more than lenses of the same size","Large mirrors can be supported from behind and have no colour errors, while big lenses sag and tint the image","Mirrors work in the dark but lenses do not","Lenses cannot form real images of very distant objects"],correctIndex:1,explanation:"A big lens can only be held by its rim and sags under its own weight, and it focuses different colours at slightly different points. A concave mirror has neither problem — it reflects all colours identically and can rest on supports across its whole back. Newton built the first reflector in 1668; Webb's 6.5 m gold-coated mirror continues the tradition."}]},{id:"colour-and-the-em-spectrum",title:"Colour & the EM Spectrum",subtitle:"Dispersion, rainbows, and light's vast invisible family from radio waves to gamma rays",sections:[{id:"dispersion-and-rainbows",title:"White Light Undone: Dispersion and Rainbows",content:'\n<p>In 1666, a young Isaac Newton let a sunbeam through a hole in his window shutter into a glass prism — and out came a band of colour: red, orange, yellow, green, blue, violet. The prevailing view was that the glass <em>added</em> the colours. Newton\'s decisive move was a second prism: he isolated just the green light and passed it through — and it stayed green. Then he sent the whole spectrum through a reversed prism and got <strong>white light back</strong>. Conclusion: white light is not pure but a <strong>mixture of all colours</strong>; the prism merely sorts what was already there.</p>\n<p>The sorting mechanism is refraction with a twist called <strong>dispersion</strong>: in glass or water, different colours travel at very slightly different speeds — violet slowest, red fastest — so each bends by a slightly different angle. Violet bends most, red least, and a white beam entering a prism fans out into the spectrum. (In this course, each colour is simply light of a different <strong>wavelength</strong>: red ≈ 700 nm down to violet ≈ 400 nm — a millionth of a millimetre scale.)</p>\n<p>A <strong>rainbow</strong> is dispersion performed by millions of raindrops. Sunlight enters each drop, refracts (and disperses) at the front surface, reflects once off the back of the drop, and refracts again on exit. The geometry concentrates the returning light at about <strong>42\xb0</strong> from the point directly opposite the Sun — a slightly different angle for each colour. Every drop flings out a full spectrum; you see red from drops positioned higher in the sky and violet from lower ones, painting an arc with red on the outside.</p>\n<ul>\n  <li>You need the <strong>Sun behind you</strong> and water droplets ahead — rainbows always stand opposite the Sun.</li>\n  <li>A <strong>double rainbow</strong> adds a fainter bow at 51\xb0 from light reflecting <em>twice</em> inside each drop — with its colours reversed, violet outside.</li>\n  <li>No two people see the same rainbow: your bow is made by the particular drops at 42\xb0 from <em>your</em> eye. It is an image, not an object — you can never reach its end.</li>\n</ul>\n<div class="did-you-know">\n  <h4>Try it yourself</h4>\n  <p>Make a rainbow on demand: with your back to a low sun, mist a garden hose to fine spray and look at it about 42\xb0 from your shadow\'s head — an arc appears, red outside. No hose? A glass of water on a sunny windowsill throws a small spectrum onto white paper on the floor, and the grooves of a CD held in sunlight fan out spectra too. In every case you are un-mixing white light.</p>\n</div>\n<div class="key-concept">\n  <h4>Key Concept</h4>\n  <p>White light is a mixture of all visible wavelengths. Dispersion — refraction that varies slightly with wavelength — separates them, in prisms (once through glass) and rainbows (refraction, internal reflection, refraction in each raindrop, concentrated near 42\xb0).</p>\n</div>'},{id:"the-colours-of-things",title:"Why Things Have Colour",content:'\n<p>A tomato has no red light source inside it. Objects get their colours by <strong>editing</strong> the white light that falls on them: a surface absorbs some wavelengths and reflects the rest, and the reflected remainder is the colour you see. A tomato absorbs greens and blues and bounces back red; grass absorbs red and blue and returns green; snow reflects everything (white); charcoal absorbs nearly everything (black — which is also why dark surfaces heat up in sunshine: absorbed light becomes heat).</p>\n<p>This means colour is a <strong>partnership between object and light</strong>. A red tomato under pure blue light looks black — there is no red in the beam for it to reflect. That is why clothes bought under a shop\'s warm lighting can surprise you in daylight, and why "daylight" bulbs are sold for jobs where colour judgement matters. A <strong>colour filter</strong> works by the same subtraction on transmitted light: red glass passes red and absorbs the rest, so a white torch behind it becomes a red torch.</p>\n<p>Mixing colours follows two opposite sets of rules, and confusing them is the classic mistake:</p>\n<ul>\n  <li><strong>Mixing light (additive):</strong> the primaries are <strong>red, green, and blue</strong>. Red + green light makes yellow; all three together make <strong>white</strong>. Every screen you own works this way — each pixel is a tiny trio of red, green, and blue lamps, and your eye, with only three cone types, is fooled into seeing millions of colours from three ingredients.</li>\n  <li><strong>Mixing paints and inks (subtractive):</strong> each pigment <em>absorbs</em> part of the spectrum, so mixing means subtracting more and more. Printer primaries are <strong>cyan, magenta, and yellow</strong>; pile them all on and you approach <strong>black</strong> (printers add real black ink, the K in CMYK, to do it properly).</li>\n</ul>\n<div class="analogy">\n  <h3>Analogy: Adding Lamps vs. Stacking Sunglasses</h3>\n  <p>Mixing light is switching on more lamps — every addition brightens the result, and enough lamps give white. Mixing pigments is stacking tinted sunglasses — every layer steals more of the spectrum, and enough layers give black. Same word, "mixing"; opposite arithmetic.</p>\n</div>\n<p>One more colour puzzle: the sky. Air molecules scatter short wavelengths (blue) far more strongly than long ones (red), so blue sunlight is strewn across the whole sky — the blue you see overhead is scattered sunlight arriving sideways. At sunset, light reaching you has crossed so much air that the blue has been scattered away en route, leaving the Sun\'s disc and clouds red and gold. The day sky and the sunset are two ends of a single scattering story.</p>\n<div class="key-concept">\n  <h4>Key Concept</h4>\n  <p>Surfaces make colour by selective absorption: you see what they reflect. Light mixes additively (R + G + B = white); pigments mix subtractively (C + M + Y ≈ black). An object\'s colour always depends on the light you view it under.</p>\n</div>'},{id:"the-em-spectrum-family",title:"The Electromagnetic Family: A Tour from Radio to Gamma",content:'\n<p>Here is this chapter\'s big reveal: visible light — the entire subject so far — is one thin slice of a vast continuous family. Light is an <strong>electromagnetic wave</strong>: vibrating electric and magnetic fields carrying themselves through space, no medium required, all travelling at the same speed c ≈ 300,000 km/s in vacuum. What distinguishes the family members is only <strong>wavelength</strong> (equivalently frequency, since c = fλ). Ordered from the longest, laziest waves to the shortest, most energetic:</p>\n<table>\n  <thead>\n    <tr><th>Band</th><th>Typical wavelength</th><th>Uses / where you meet it</th></tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>Radio</strong></td><td>km down to ≈ 30 cm</td><td>Broadcasting, Wi-Fi, aircraft communication, radio astronomy</td></tr>\n    <tr><td><strong>Microwaves</strong></td><td>30 cm – 1 mm</td><td>Ovens, radar, mobile networks, satellite links</td></tr>\n    <tr><td><strong>Infrared (IR)</strong></td><td>1 mm – 700 nm</td><td>Heat radiation, remote controls, thermal cameras, night vision</td></tr>\n    <tr><td><strong>Visible</strong></td><td>700 – 400 nm</td><td>The rainbow: everything any eye has ever seen</td></tr>\n    <tr><td><strong>Ultraviolet (UV)</strong></td><td>400 – 10 nm</td><td>Sunburn and tanning, sterilising, fluorescent security marks</td></tr>\n    <tr><td><strong>X-rays</strong></td><td>10 – 0.01 nm</td><td>Medical imaging, airport scanners, crystallography</td></tr>\n    <tr><td><strong>Gamma rays</strong></td><td>&lt; 0.01 nm</td><td>Radioactive decay, cancer therapy, cosmic explosions</td></tr>\n  </tbody>\n</table>\n<p>Notice the trend that organises the whole table: as wavelength shrinks, the waves carry <strong>more energy</strong> and become more penetrating and more dangerous. Radio passes through you unnoticed; infrared warms you; ultraviolet burns skin; X-rays pass through flesh (but not bone — hence skeleton photographs); gamma rays can damage the molecules of life, which is exactly why, carefully aimed, they can also destroy tumours.</p>\n<p>The visible band is astonishingly narrow — 400 to 700 nm, less than one octave in a spectrum spanning more than fifteen octaves. It is no accident that eyes evolved here: this is where the Sun shines most strongly, and these wavelengths pass cleanly through both the atmosphere and water, where eyes first appeared.</p>\n<div class="did-you-know">\n  <h4>Did You Know?</h4>\n  <p>Many animals read bands we cannot: bees see ultraviolet "landing-strip" patterns on flowers, pit vipers sense infrared from warm prey in total darkness, and your phone camera can often see the IR flicker of a TV remote — point the remote at the camera, press a button, and watch the screen show a flash your eyes cannot detect.</p>\n</div>\n<div class="key-concept">\n  <h4>Key Concept</h4>\n  <p>Radio, microwave, infrared, visible, ultraviolet, X-ray, gamma: one family, one nature, one vacuum speed c. Only wavelength varies — and with it energy, penetration, and use. Visible light is a sliver less than one octave wide.</p>\n</div>'},{id:"one-speed-one-formula",title:"One Speed, One Formula: Working with the Spectrum",content:'\n<p>Because every electromagnetic wave in vacuum moves at the same c ≈ 3 \xd7 10⁸ m/s, the master formula from the wave chapter — with v replaced by c — unlocks the entire spectrum:</p>\n<p style="text-align:center;"><strong>c = fλ&nbsp;&nbsp;so&nbsp;&nbsp;f = c/λ&nbsp;&nbsp;and&nbsp;&nbsp;λ = c/f</strong></p>\n<div class="key-concept">\n  <h4>Worked Example 1: Your Wi-Fi</h4>\n  <p>A 2.4 GHz Wi-Fi router transmits at f = 2,400,000,000 Hz. λ = c/f = 300,000,000 \xf7 2,400,000,000 = <strong>0.125 m ≈ 12.5 cm</strong> — a microwave about the width of your hand. Kitchen microwave ovens run nearby at 2.45 GHz, tuned to be strongly absorbed by water molecules; your router just uses far less power.</p>\n</div>\n<div class="key-concept">\n  <h4>Worked Example 2: Green Light</h4>\n  <p>Green light has λ ≈ 500 nm = 0.0000005 m. f = c/λ = 300,000,000 \xf7 0.0000005 = <strong>6 \xd7 10\xb9⁴ Hz</strong> — six hundred trillion vibrations per second. Compare the two answers: from Wi-Fi to green light, wavelength shrank by a factor of 250,000 and frequency grew by exactly the same factor. On one fixed speed, f and λ are locked in a perfect see-saw.</p>\n</div>\n<p>The formula also explains the engineering all around you:</p>\n<ul>\n  <li><strong>Antennas match wavelengths.</strong> Efficient antennas are sized around the waves they handle — metre-scale masts for FM radio (λ ≈ 3 m), finger-length traces inside your phone for mobile bands (λ ≈ 15–30 cm).</li>\n  <li><strong>Long waves flow around obstacles.</strong> Radio\'s metre-to-kilometre waves diffract around hills and buildings, which is why reception survives where line of sight fails; light\'s sub-micrometre waves cannot, which is why shadows are sharp.</li>\n  <li><strong>Short waves probe small things.</strong> A wave only "feels" details about its own wavelength or larger — the deep reason light microscopes max out near 1,500\xd7 and X-rays (λ ≈ atom spacing) can map crystals and DNA.</li>\n</ul>\n<p>And with that, your first pass through sound, light, and optics is complete: vibrations became waves, waves obeyed v = fλ, rays bounced and bent through mirrors and lenses into eyes and telescopes, and colour unfolded into a fifteen-octave electromagnetic family. Two promissory notes remain. Subject 8 will reveal <em>why</em> electromagnetic waves exist — electricity and magnetism regenerating each other in flight. And the quantum subjects will ask the sharpest question of all: is light really a wave? Nature\'s answer — both wave and particle — is where physics gets truly strange.</p>'}],quiz:[{question:"What did Newton's two-prism experiment prove about white light?",options:["That glass adds colour to light passing through it","That white light is a mixture of all colours, which a prism separates but does not create","That light is made of particles","That only sunlight contains all the colours"],correctIndex:1,explanation:"When Newton passed isolated green light through a second prism it stayed green — the glass created nothing. And when he recombined the whole fan of colours with a reversed prism he recovered white light. The prism merely sorts, by dispersion, the wavelengths already mixed in the beam."},{question:"To see a rainbow, where must the Sun be?",options:["Behind you, with rain or spray in front of you","Directly overhead at noon","In front of you, behind the rain","Below the horizon"],correctIndex:0,explanation:"Raindrops send sunlight back towards the Sun's side after refraction, one internal reflection, and refraction — concentrated about 42\xb0 from the point directly opposite the Sun. So the bow always stands opposite the Sun: light source behind you, droplets ahead."},{question:"A ripe (red) tomato is lit with pure blue light. What colour does it appear?",options:["Red, as always","Blue","Black","Purple"],correctIndex:2,explanation:"A red tomato is red because it reflects red and absorbs other wavelengths. Pure blue light contains no red to reflect, so the tomato absorbs essentially everything and looks black. An object's colour is a partnership between its surface and the light falling on it."},{question:"Which of these lists electromagnetic bands correctly from longest wavelength to shortest?",options:["Gamma → X-ray → ultraviolet → visible → infrared → radio","Radio → infrared → ultraviolet → visible → X-ray → gamma","Visible → radio → microwave → gamma → X-ray → infrared","Radio → microwave → infrared → visible → ultraviolet → X-ray → gamma"],correctIndex:3,explanation:"From kilometre-long radio waves the wavelengths shrink through microwaves, infrared, the narrow visible band (700–400 nm), ultraviolet, and X-rays down to sub-atomic gamma rays. Energy and penetrating power grow in the same order — the organising trend of the whole spectrum."},{question:"All electromagnetic waves in vacuum travel at c = 3 \xd7 10⁸ m/s. What is the wavelength of a 100 MHz FM radio signal?",options:["0.33 m","30 m","3 m","3 \xd7 10\xb9⁶ m"],correctIndex:2,explanation:"λ = c/f = 300,000,000 \xf7 100,000,000 = 3 m. That metre-scale wavelength is why FM antennas are rod-sized, and why radio flows around buildings while visible light — with wavelengths half a million times shorter — casts sharp shadows."}]}]},{id:"electricity-and-magnetism",number:8,title:"Electricity & Magnetism",description:"From static sparks to the power grid: charge, circuits, Ohm's law, magnetism, and the motors and generators that electrified the world — all at first-pass, one-formula depth.",phase:2,chapters:[{id:"static-electricity",title:"Static Electricity",subtitle:"Charge, attraction and repulsion, lightning, and a first feel for the electric field",sections:[{id:"charge-and-electrization",title:"Charge: The Hidden Property of Matter",content:'\n<p>Around 600 BCE, Greek philosophers noticed something odd: rub a piece of amber with fur, and it picks up bits of straw. The Greek word for amber is <em>elektron</em> — and that little party trick is where the entire modern world of electricity begins.</p>\n<p>What the Greeks were seeing was <strong>electric charge</strong>, a fundamental property of matter, as basic as mass. Every atom contains charged particles: <strong>protons</strong> in the nucleus carry positive charge, and <strong>electrons</strong> orbiting around it carry negative charge. Ordinary objects contain staggering numbers of both — but in equal amounts, so the charges cancel and the object appears neutral.</p>\n<p>Rubbing changes that balance. When you rub a balloon on your hair, some electrons are literally scraped off your hair and onto the balloon. The balloon, now with extra electrons, becomes negatively charged; your hair, missing electrons, becomes positively charged. This process is called <strong>electrization</strong>, and it can happen three ways:</p>\n<ul>\n  <li><strong>By friction:</strong> rubbing two different materials transfers electrons from one to the other (balloon on hair, shoes on carpet, clothes in a dryer).</li>\n  <li><strong>By contact:</strong> touching a charged object to a neutral one shares some of the charge.</li>\n  <li><strong>By induction:</strong> simply bringing a charged object <em>near</em> a neutral one shifts the charges inside it around, without any touching at all.</li>\n</ul>\n<div class="analogy">\n  <h3>Analogy: Moving Sand, Not Making It</h3>\n  <p>Charging an object never creates charge — it only moves it, like scooping sand from one bucket into another. The balloon gains exactly the electrons your hair loses. Physicists call this the <strong>conservation of charge</strong>: in every process ever observed, the total amount of charge stays the same.</p>\n</div>\n<p>Crucially, it is almost always the <strong>electrons</strong> that move. Protons are locked deep inside atomic nuclei; electrons on the outer fringes of atoms are comparatively easy to dislodge. So "positively charged" nearly always means "missing some electrons," not "gained protons." Keep that picture in mind — it explains everything from static cling to the current in a wire.</p>'},{id:"attraction-repulsion-elementary-charge",title:"Opposites Attract: The Rules of Charge",content:'\n<p>Two simple rules govern how charges interact, and they are worth committing to memory because all of electricity flows from them:</p>\n<ul>\n  <li><strong>Like charges repel</strong> — positive pushes away positive, negative pushes away negative.</li>\n  <li><strong>Unlike charges attract</strong> — positive and negative pull toward each other.</li>\n</ul>\n<p>The force grows rapidly as charges get closer, and fades as they separate. (Subject 14 will make this exact with Coulomb\'s law; for now, "closer means much stronger" is the right intuition.)</p>\n<p>Here is the remarkable part: charge is not a continuous fluid. It comes in indivisible packets. The smallest possible amount is the <strong>elementary charge</strong>, written <em>e</em>, carried by a single electron (negative) or proton (positive):</p>\n<table>\n  <thead>\n    <tr><th>Particle</th><th>Charge</th><th>Location in atom</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Proton</td><td>+e</td><td>Nucleus</td></tr>\n    <tr><td>Neutron</td><td>0</td><td>Nucleus</td></tr>\n    <tr><td>Electron</td><td>−e</td><td>Outer shells</td></tr>\n  </tbody>\n</table>\n<p>Measured in the standard unit of charge, the <strong>coulomb (C)</strong>, one elementary charge is tiny: e ≈ 1.6 \xd7 10⁻\xb9⁹ C. Flip that around and one coulomb is about six billion billion electrons — the coulomb is a wholesale unit.</p>\n<div class="key-concept">\n  <h4>Key Concept: Charge Is Quantized</h4>\n  <p>Every charge ever measured is a whole-number multiple of e. You can have 5e or 1,000,000e of charge, but never 2.5e. Charge comes in steps, like coins with no smaller denomination.</p>\n</div>\n<h3>Try it yourself: Kitchen static lab</h3>\n<ol>\n  <li>Rub an inflated balloon vigorously on your hair or a wool sweater for ten seconds.</li>\n  <li>Hold it near small torn scraps of paper — they leap up and stick. The charged balloon attracts even <em>neutral</em> paper by induction.</li>\n  <li>Turn on a tap to a thin, gentle stream and bring the balloon close: the water visibly bends toward it.</li>\n  <li>Press the balloon to a wall — it stays there, held by nothing but electrical attraction.</li>\n</ol>\n<p>Dry days work best; humidity lets charge leak away through the air.</p>'},{id:"lightning",title:"Lightning: Static Electricity at Full Scale",content:'\n<p>The spark that snaps from your finger to a doorknob and a bolt of lightning are the same phenomenon — separated charge violently reuniting — just at wildly different scales.</p>\n<p>Inside a thundercloud, powerful updrafts hurl ice crystals and slushy hail pellets past each other. Their countless collisions act like trillions of tiny balloon-on-hair rubbings: lighter ice crystals tend to lose electrons and get carried to the top of the cloud, while heavier pellets gain electrons and sink. The result is a cloud with a <strong>positive top and a strongly negative base</strong> — a charge separation measured in hundreds of millions of volts.</p>\n<p>The negative cloud base also pushes electrons away from the ground beneath it (induction again), leaving the ground positively charged. When the strain becomes too great, air itself — normally an excellent insulator — breaks down. An invisible, branching channel called a <strong>stepped leader</strong> zigzags down from the cloud; when it nears the ground, a connecting spark rises to meet it, and then the main event, the <strong>return stroke</strong>, blasts upward along the completed channel.</p>\n<ul>\n  <li>A typical stroke carries a current of roughly <strong>30,000 amperes</strong> — a household circuit carries 10 to 20.</li>\n  <li>The channel is heated to about 30,000 \xb0C, several times hotter than the Sun\'s surface.</li>\n  <li>That sudden heating makes the air explode outward — the shockwave we hear as <strong>thunder</strong>.</li>\n</ul>\n<div class="key-concept">\n  <h4>Key Concept: Lightning Safety</h4>\n  <p>The safest nearby place in a storm is inside a building or a metal-bodied car — not because of the rubber tires, but because current flows through the metal shell <em>around</em> the occupants and into the ground. Never shelter under an isolated tree: lightning favors the tallest path, and a struck tree can splash lethal current through the ground around it.</p>\n</div>\n<div class="did-you-know">\n  <h3>Did You Know?</h3>\n  <p>Earth hosts about 100 lightning flashes every second. And that doorknob spark of yours? It needs several thousand volts to jump even a few millimetres — but it involves so little total charge that it stings instead of harms. Voltage alone isn\'t what makes electricity dangerous; sustained current is.</p>\n</div>'},{id:"electric-field-qualitative",title:"The Electric Field: Action at a Distance",content:'\n<p>The balloon on the wall raises an awkward question: how does one charge pull on another <em>without touching it</em>? Nothing visible stretches between them, yet the force is undeniably there. Physics answers with one of its most powerful ideas: the <strong>electric field</strong>.</p>\n<p>The picture is this: a charge doesn\'t reach across empty space to grab another charge. Instead, it modifies the space around itself — it fills its surroundings with an electric field. Any other charge sitting in that field feels a force from the field <em>right where it is</em>. The field is the middleman.</p>\n<div class="analogy">\n  <h3>Analogy: The Weather Map</h3>\n  <p>A wind map assigns an arrow to every point on the map — direction and strength of the wind there. An electric field does the same for space itself: at every point, it has a direction (which way a small positive charge would be pushed) and a strength (how hard). A charge dropped into the field simply reads its local arrow and responds.</p>\n</div>\n<p>We visualize fields with <strong>field lines</strong>, drawn by convention pointing <em>away from positive</em> charges and <em>toward negative</em> ones. Two reading rules:</p>\n<ul>\n  <li>The arrow direction shows which way a positive charge would be pushed.</li>\n  <li>Where lines crowd together, the field is strong; where they spread out, it is weak. Near a charge the lines bunch tightly — matching the strong force there.</li>\n</ul>\n<p>For a single positive charge, lines radiate outward like a starburst. For a positive and negative pair, lines arc gracefully from one to the other — the classic pattern you can almost see when charged hair strands reach toward a balloon.</p>\n<div class="key-concept">\n  <h4>Key Concept: The Field Is Real</h4>\n  <p>The field may sound like a bookkeeping trick, but it is physically real: fields store energy, and — as you\'ll see in later subjects — ripples in electric and magnetic fields travel through space as light itself. For now, hold the qualitative picture: <strong>charges create fields; fields push on charges.</strong> Subject 14 makes it quantitative.</p>\n</div>'}],quiz:[{question:"When you rub a balloon on your hair, what actually happens?",options:["Protons move from the balloon to your hair","New negative charge is created on the balloon","Electrons transfer from your hair to the balloon","Both objects gain positive charge"],correctIndex:2,explanation:"Only electrons move — protons are locked in atomic nuclei. Your hair loses electrons (becoming positive) and the balloon gains exactly those electrons (becoming negative). No charge is ever created or destroyed, only transferred."},{question:"Two balloons are both rubbed on the same wool sweater and then hung side by side. What happens?",options:["They push apart, because both carry the same kind of charge","They snap together, because rubbing always causes attraction","Nothing, because balloons cannot hold charge","They spin in circles around each other"],correctIndex:0,explanation:"Both balloons take electrons from the wool, so both end up negatively charged. Like charges repel, so the balloons visibly push apart — a classic demonstration you can do at home."},{question:"What does it mean that charge is 'quantized'?",options:["Charge can only exist inside atoms","All charge comes in whole-number multiples of the elementary charge e","Charge gets weaker with distance","Positive and negative charges always cancel exactly"],correctIndex:1,explanation:"Every measured charge is an exact multiple of e ≈ 1.6 \xd7 10⁻\xb9⁹ C, the charge of one proton (or minus that, for an electron). You can have 3e or a billion e, but never half of e — charge comes in indivisible steps."},{question:"Why is a metal-bodied car a relatively safe place during a lightning storm?",options:["The rubber tires insulate it from the ground","Cars are too small for lightning to notice","The engine absorbs the electrical energy","Current flows through the metal shell around the occupants and into the ground"],correctIndex:3,explanation:"The common 'rubber tires' explanation is a myth — no tire insulates against millions of volts. The real protection is the conducting metal body, which carries the current around the outside of the passenger compartment to the ground."},{question:"In a diagram of electric field lines, what does it mean where the lines are drawn close together?",options:["The charge there is negative","The field there is strong","The field there is weak","No charge can exist at that location"],correctIndex:1,explanation:"Field-line density encodes field strength: crowded lines mean a strong field, spread-out lines mean a weak one. That's why lines bunch tightly near a charge, where the force on other charges is greatest."}]},{id:"current-and-circuits",title:"Current & Circuits",subtitle:"Current, voltage, and resistance — and how to read and build series and parallel circuits",sections:[{id:"what-is-current",title:"Current: Charge on the Move",content:"\n<p>Static electricity is charge sitting still. Set it flowing, and you have <strong>electric current</strong> — the working fluid of every device you own. Current is simply the rate at which charge flows past a point:</p>\n<div class=\"key-concept\">\n  <h4>Key Concept: The Ampere</h4>\n  <p>Current (symbol <strong>I</strong>) is measured in <strong>amperes</strong>, or amps (A). One ampere means one coulomb of charge — about six billion billion electrons — flowing past a point every second. A phone charger cable carries around 1–2 A; a kettle draws about 10 A; a lightning bolt, roughly 30,000 A.</p>\n</div>\n<p>In a metal wire, the moving charges are the loosely-held outer electrons of the metal atoms — a sea of them, free to drift. Two things about this drift surprise almost everyone:</p>\n<ul>\n  <li><strong>The electrons themselves crawl.</strong> Their average drift speed in a household wire is well under a millimetre per second. What travels near the speed of light is the electric field — the <em>push</em> — which sets electrons everywhere in the wire moving almost simultaneously. It's like a pipe already full of water: open the valve and water emerges at the far end at once, even though no single water molecule sprinted through.</li>\n  <li><strong>Conventional current points the 'wrong' way.</strong> By historical accident (Benjamin Franklin guessed before electrons were discovered), current is defined as flowing from the battery's positive terminal, around the circuit, to the negative terminal — opposite to the actual electron drift. Every diagram on Earth uses this convention, so we will too. It makes no difference to any calculation.</li>\n</ul>\n<p>For current to flow at all, charges need an unbroken loop — a <strong>closed circuit</strong> — from one battery terminal to the other. Break the loop anywhere, even with a millimetre air gap, and the flow stops everywhere instantly. That's all a switch is: a deliberate, reusable break.</p>\n<div class=\"did-you-know\">\n  <h3>Did You Know?</h3>\n  <p>Batteries deliver <strong>direct current (DC)</strong> — a steady one-way flow. Wall outlets deliver <strong>alternating current (AC)</strong>, in which the push reverses direction 50 or 60 times per second, so the electrons just jiggle back and forth. Why the grid prefers AC becomes clear in the final chapter, when you meet the transformer.</p>\n</div>"},{id:"voltage-and-resistance",title:"Voltage Pushes, Resistance Resists",content:'\n<p>Current doesn\'t flow on its own — something must push it, and something always opposes it. Those two somethings complete the three-word vocabulary of circuits.</p>\n<p><strong>Voltage</strong> (symbol <em>V</em>, unit the <strong>volt</strong>) is the push. More precisely, it measures how much energy the source gives to each coulomb of charge it drives around the circuit: one volt is one joule per coulomb. A 9 V battery hands each coulomb nine joules of energy to spend — in the bulb, the motor, wherever the circuit directs it.</p>\n<div class="analogy">\n  <h3>Analogy: The Water Circuit</h3>\n  <p>Picture a closed loop of pipe with a pump. The pump (battery) creates pressure difference (voltage), water flows around the loop (current), and a narrow constriction in the pipe (resistance) limits how fast it can flow. Note what the pump does <em>not</em> do: it doesn\'t create water, it just pushes existing water around. Likewise a battery creates no electrons — the wire is already full of them — it only pumps them.</p>\n</div>\n<p>Some everyday voltages:</p>\n<table>\n  <thead>\n    <tr><th>Source</th><th>Voltage</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>AA battery</td><td>1.5 V</td></tr>\n    <tr><td>Phone charger (USB)</td><td>5 V</td></tr>\n    <tr><td>Car battery</td><td>12 V</td></tr>\n    <tr><td>Mains outlet</td><td>230 V (120 V in North America)</td></tr>\n    <tr><td>Overhead transmission line</td><td>up to 400,000 V</td></tr>\n    <tr><td>Thundercloud to ground</td><td>~100,000,000 V</td></tr>\n  </tbody>\n</table>\n<p><strong>Resistance</strong> (symbol <em>R</em>, unit the <strong>ohm, Ω</strong>) is the opposition. As electrons drift, they constantly collide with the vibrating atoms of the material, losing energy at every bump — that\'s why wires warm up. Every component has some resistance: thick copper wire has very little, a bulb filament has a lot on purpose, and an open air gap has so much that current effectively stops.</p>\n<div class="key-concept">\n  <h4>Key Concept: The Circuit Triangle</h4>\n  <p><strong>Voltage</strong> is the push (volts). <strong>Current</strong> is the flow (amps). <strong>Resistance</strong> is the opposition (ohms). Every circuit question you will ever meet is about how these three negotiate with each other — and the next chapter reveals the single formula that ties them together.</p>\n</div>'},{id:"circuit-diagrams",title:"Reading Circuit Diagrams",content:"\n<p>Real circuits are a tangle of wires, but electrically only one thing matters: <em>what is connected to what</em>. Circuit diagrams (schematics) strip away the tangle and show pure connection logic, using standard symbols any engineer on Earth can read:</p>\n<ul>\n  <li><strong>Battery:</strong> a pair of parallel lines, one long (positive terminal) and one short (negative).</li>\n  <li><strong>Wire:</strong> a straight line — drawn with right-angle corners for tidiness, though real wires bend any way they like.</li>\n  <li><strong>Bulb:</strong> a circle with a cross or loop inside.</li>\n  <li><strong>Resistor:</strong> a small rectangle (or a zigzag in the American style).</li>\n  <li><strong>Switch:</strong> a break in the line with a pivoting lever — open means off, closed means on.</li>\n  <li><strong>Ammeter (A in a circle):</strong> measures current, placed <em>in</em> the path of the flow.</li>\n  <li><strong>Voltmeter (V in a circle):</strong> measures voltage, connected <em>across</em> a component like a bridge.</li>\n</ul>\n<p>To read any schematic, put your finger on the battery's positive terminal and trace the loop: every complete path back to the negative terminal is a route current can take. If your finger can't get home without crossing a gap, no current flows on that route.</p>\n<h3>Try it yourself: The one-bulb circuit</h3>\n<ol>\n  <li>You need: one AA battery, one small flashlight bulb (or a bulb from a battery-powered string light), and a strip of aluminium foil about 20 cm long, folded into a narrow ribbon.</li>\n  <li>Press one end of the foil ribbon against the battery's flat negative end.</li>\n  <li>Touch the bulb's metal base to the battery's positive bump, and touch the other end of the foil to the metal side of the bulb.</li>\n  <li>The bulb lights — you have built a complete circuit. Lift any contact and it dies instantly: the loop is broken.</li>\n</ol>\n<div class=\"key-concept\">\n  <h4>Safety Note</h4>\n  <p>Battery experiments at 1.5 V are completely safe — the voltage is far too low to push harmful current through your skin. The one rule: <strong>never experiment with mains outlets or their wiring.</strong> At 230 V, the same curiosity is lethal. Batteries only.</p>\n</div>\n<p>One more habit worth building: a wire directly from one battery terminal to the other with <em>nothing</em> in between is a <strong>short circuit</strong> — near-zero resistance, so a huge current flows, and the battery and wire heat up fast. Even in your foil experiment, you'll notice the foil warming if bulb contact slips. Circuits always need something in the loop to do the resisting.</p>"},{id:"series-and-parallel",title:"Series and Parallel: The Two Ways to Connect",content:"\n<p>Give a battery two bulbs and you face electricity's most fundamental design decision. There are exactly two pure ways to wire them, and they behave completely differently.</p>\n<p><strong>Series</strong> means one after another, in a single loop — the current has no choice but to pass through both bulbs in turn.</p>\n<ul>\n  <li>The <strong>same current</strong> flows through every component (there's nowhere else for it to go).</li>\n  <li>The components <strong>share the battery's voltage</strong> between them — two identical bulbs get half each, so each glows dimmer than it would alone.</li>\n  <li>Adding more components increases total resistance, so the current drops.</li>\n  <li>The fatal flaw: <strong>one break kills everything</strong>. If one bulb burns out, the loop is open and all go dark — the misery of old-style Christmas-light strings, hunting for the one dead bulb.</li>\n</ul>\n<p><strong>Parallel</strong> means side by side, each component on its own branch bridging the battery's terminals.</p>\n<ul>\n  <li>Every branch gets the <strong>full battery voltage</strong>, so each bulb glows at full brightness.</li>\n  <li>The current <strong>splits</strong> among the branches and rejoins — the battery supplies the sum, and works harder with every branch added.</li>\n  <li>Each branch is <strong>independent</strong>: switch one off, unscrew one bulb, and the others don't even notice.</li>\n</ul>\n<table>\n  <thead>\n    <tr><th></th><th>Series</th><th>Parallel</th></tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>Current</strong></td><td>Same everywhere</td><td>Splits among branches</td></tr>\n    <tr><td><strong>Voltage</strong></td><td>Shared between components</td><td>Full voltage on every branch</td></tr>\n    <tr><td><strong>One component fails</strong></td><td>All stop</td><td>Others unaffected</td></tr>\n  </tbody>\n</table>\n<div class=\"key-concept\">\n  <h4>Key Concept: Your Home Is Parallel</h4>\n  <p>Every outlet and light in your house is wired in parallel across the mains supply. That's why each appliance receives the full 230 V (or 120 V), and why turning off the toaster doesn't darken the fridge. It's also why plugging in more appliances draws more total current — a fact that matters enormously in the chapter on fuses and safety.</p>\n</div>\n<div class=\"did-you-know\">\n  <h3>Did You Know?</h3>\n  <p>Series connections have their uses too: batteries stacked in series add their voltages. The 9 V rectangular battery is secretly six tiny 1.5 V cells in series inside one shell, and an electric-car pack puts thousands of small cells in series-parallel combinations to reach around 400 V.</p>\n</div>"}],quiz:[{question:"What does a current of 1 ampere physically mean?",options:["One electron passes each second","One volt of push is applied to the wire","One coulomb of charge flows past a point each second","The wire has one ohm of resistance"],correctIndex:2,explanation:"Current is the rate of charge flow: 1 A = 1 coulomb per second. Since one coulomb is about six billion billion elementary charges, even a small current involves an immense number of electrons."},{question:"Which statement best describes voltage?",options:["The number of electrons stored in a battery","The speed of the electrons in the wire","The opposition a wire offers to current","The energy given to each coulomb of charge — the 'push' driving the current"],correctIndex:3,explanation:"Voltage is energy per charge: one volt is one joule per coulomb. A battery doesn't create or store electrons — the wire is already full of them — it gives each passing coulomb energy to spend around the circuit, like a pump creating pressure."},{question:"Three bulbs are wired in series and one of them burns out. What happens to the other two?",options:["They both go dark, because the single loop is broken","They glow brighter, since they now share the voltage two ways","They keep glowing at the same brightness","They flicker but stay lit"],correctIndex:0,explanation:"A series circuit is one single loop, and current must pass through every component. A burned-out bulb is an open gap, so current stops everywhere — this is why old series-wired holiday lights all died together."},{question:"Why are household outlets wired in parallel rather than in series?",options:["Parallel wiring uses less copper wire","Each appliance gets the full mains voltage and works independently of the others","Parallel circuits carry less total current","Series wiring only works with batteries, not AC"],correctIndex:1,explanation:"In parallel, every branch spans the full supply voltage, and switching one branch off doesn't affect the rest. In series, appliances would share the voltage unpredictably and unplugging one would kill them all."},{question:"Electrons drift through a wire at less than a millimetre per second. Why does a lamp light the instant you flip the switch?",options:["Electrons secretly travel at the speed of light","The lamp stores electrons from the last time it was on","Heat from the switch travels to the bulb","The electric field's push spreads through the wire almost instantly, moving all the electrons at once"],correctIndex:3,explanation:"The wire is already packed with free electrons, like a hose already full of water. Closing the switch lets the field propagate at nearly light speed, so electrons everywhere in the circuit — including inside the lamp — begin drifting essentially simultaneously."}]},{id:"ohms-law-and-resistance",title:"Ohm's Law & Resistance",subtitle:"V = IR — the one formula that governs every circuit — and what resistance depends on",sections:[{id:"v-equals-ir",title:"V = IR: The Law That Runs Every Circuit",interactive:"ohms-law",content:'\n<p>In the 1820s, a German schoolteacher named Georg Ohm did something painstaking: he measured, for wire after wire, how much current flowed when he applied different voltages. The pattern he found is the single most-used equation in all of electricity:</p>\n<div class="key-concept">\n  <h4>Key Concept: Ohm\'s Law</h4>\n  <p><strong>V = I \xd7 R</strong> — voltage equals current times resistance. Push harder (more volts) and proportionally more current flows; oppose harder (more ohms) and proportionally less flows. One ohm is defined by this very relationship: a component has a resistance of 1 Ω if 1 volt drives 1 ampere through it.</p>\n</div>\n<p>The real power of the law is that knowing any two of the three quantities hands you the third. Rearranged:</p>\n<ul>\n  <li><strong>I = V / R</strong> — to find the current: a 12 V battery across a 6 Ω resistor drives I = 12/6 = <strong>2 A</strong>.</li>\n  <li><strong>R = V / I</strong> — to find the resistance: if a bulb draws 0.5 A from a 3 V supply, its resistance is R = 3/0.5 = <strong>6 Ω</strong>.</li>\n  <li><strong>V = I \xd7 R</strong> — to find the voltage: pushing 2 A through a 10 Ω heating element requires V = 2 \xd7 10 = <strong>20 V</strong>.</li>\n</ul>\n<p>Notice what the proportionality buys you, thanks to the ratio reasoning you\'ve practiced since Subject 1: double the voltage and the current doubles; double the resistance and the current halves. No recalculation needed — just scale.</p>\n<div class="analogy">\n  <h3>Analogy: The Garden Hose</h3>\n  <p>Turn the tap higher (more voltage) and more water flows. Pinch the hose (more resistance) and less flows. V = IR is nothing more than this everyday intuition, made exact enough to engineer with.</p>\n</div>\n<p>Use the interactive circuit below to make the law physical: drag the voltage up and watch the current rise in lockstep; crank up the resistance and watch it choke the flow. Try to predict each meter reading <em>before</em> you release the slider — that habit, predict-then-check, is how the formula becomes instinct.</p>\n<div class="did-you-know">\n  <h3>Did You Know?</h3>\n  <p>Not everything obeys Ohm\'s law. A filament\'s resistance climbs as it heats; diodes and transistors flout the law entirely — which is precisely what makes them useful. Materials that do obey it, like metals at steady temperature, are called <em>ohmic</em>. For this course, V = IR is your reliable workhorse.</p>\n</div>'},{id:"what-resistance-depends-on",title:"What Makes a Wire Resist?",content:'\n<p>Ohm\'s law treats resistance as a given number. But where does that number come from? Picture the microscopic scene: drifting electrons threading their way through a lattice of vibrating atoms, colliding constantly. Everything that shapes a wire\'s resistance follows from that picture.</p>\n<table>\n  <thead>\n    <tr><th>Factor</th><th>Effect on resistance</th><th>Why</th></tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>Length</strong></td><td>Longer wire → more resistance (double the length, double the R)</td><td>More lattice to fight through — more collisions per trip</td></tr>\n    <tr><td><strong>Thickness</strong></td><td>Thicker wire → less resistance (double the cross-section area, halve the R)</td><td>More side-by-side lanes for electrons to use</td></tr>\n    <tr><td><strong>Material</strong></td><td>Copper conducts superbly; nichrome resists ~65\xd7 more; rubber essentially blocks flow</td><td>Materials differ hugely in how many free electrons they offer and how often those electrons scatter</td></tr>\n    <tr><td><strong>Temperature</strong></td><td>Hotter metal → more resistance</td><td>Heated atoms vibrate harder and get in the way more</td></tr>\n  </tbody>\n</table>\n<div class="analogy">\n  <h3>Analogy: The Crowded Corridor</h3>\n  <p>Electrons in a wire are like people crossing a crowded station hall. A longer hall means more people to dodge (length). A wider hall offers more open lanes (thickness). Some halls are naturally emptier than others (material). And if the crowd is agitated and milling about, crossing gets even harder (temperature).</p>\n</div>\n<p>These four factors show up all over daily life:</p>\n<ul>\n  <li><strong>Extension cords</strong> for heaters must be short and thick. A long, thin cord adds real resistance in series with the appliance — it steals voltage and, worse, heats up itself.</li>\n  <li><strong>Jump-starting a car</strong> takes fat cables: hundreds of amps would cook a thin wire.</li>\n  <li><strong>An incandescent filament</strong> is deliberately long, hair-thin, and coiled — maximum resistance packed into a tiny space, so it runs white-hot.</li>\n  <li><strong>Charging cables</strong> that are cheap and thin visibly charge phones more slowly than short, thick ones.</li>\n</ul>\n<div class="key-concept">\n  <h4>Key Concept: Design, Not Accident</h4>\n  <p>Every wire in every device is a deliberate trade-off between these four factors. Where engineers want current delivered — power cords, wiring in walls — resistance is minimized. Where they want heat or light — toasters, filaments — resistance is built in on purpose.</p>\n</div>'},{id:"resistivity-intro",title:"Resistivity: A Number for Every Material",content:"\n<p>Length and thickness describe a particular wire, but the \"material\" factor deserves its own number — one that captures how much a substance resists current regardless of its shape. That number is <strong>resistivity</strong>, symbol ρ (the Greek letter rho).</p>\n<p>The relationship is tidy: resistance equals resistivity times length, divided by cross-sectional area — <strong>R = ρL/A</strong>. You won't need to calculate with it much in this first pass; what matters is reading it. It says exactly what the last section showed: R grows with length, shrinks with thickness, and is scaled overall by the material's ρ.</p>\n<p>What's astonishing is the <em>range</em> of resistivities in nature — about 24 powers of ten, one of the widest ranges of any physical property:</p>\n<table>\n  <thead>\n    <tr><th>Material</th><th>Resistivity (Ω\xb7m)</th><th>Role</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Silver</td><td>1.6 \xd7 10⁻⁸</td><td>Best common conductor — too pricey for wiring</td></tr>\n    <tr><td>Copper</td><td>1.7 \xd7 10⁻⁸</td><td>The workhorse of wiring</td></tr>\n    <tr><td>Aluminium</td><td>2.8 \xd7 10⁻⁸</td><td>Overhead power lines (light and cheap)</td></tr>\n    <tr><td>Tungsten</td><td>5.6 \xd7 10⁻⁸</td><td>Filaments — survives white heat</td></tr>\n    <tr><td>Nichrome</td><td>≈ 1.1 \xd7 10⁻⁶</td><td>Heating elements in toasters and kettles</td></tr>\n    <tr><td>Glass, rubber</td><td>≈ 10\xb9⁰ to 10\xb9⁴</td><td>Insulation</td></tr>\n  </tbody>\n</table>\n<p>Read the engineering straight off the table. Copper: second-best conductor, affordable — into the walls it goes. Aluminium: slightly worse per metre but far lighter — it wins for kilometre-long cables hanging from pylons. Nichrome: resists ~65 times more than copper and shrugs off high temperatures without oxidizing — perfect for glowing toaster coils. And the insulators' colossal values are why a millimetre of plastic sheathing lets you safely grip a live cord.</p>\n<div class=\"did-you-know\">\n  <h3>Did You Know?</h3>\n  <p>Cool certain materials far enough and their resistivity doesn't just shrink — it vanishes. <strong>Superconductors</strong> carry current with exactly zero resistance; a current started in a superconducting ring has been observed to circulate for years without any battery. MRI scanners use superconducting coils to sustain their enormous magnetic fields. The catch: they need extreme cold, typically below about −180 \xb0C.</p>\n</div>"}],quiz:[{question:"A 230 V supply is connected across a heating element with a resistance of 46 Ω. What current flows?",options:["0.2 A","10.6 kA","5 A","46 A"],correctIndex:2,explanation:"Use I = V/R: 230 V \xf7 46 Ω = 5 A. Ohm's law rearranges to give whichever quantity you're missing — here, voltage and resistance were known, so divide to find the current."},{question:"A bulb draws 0.5 A when connected to a 3 V battery. What is its resistance?",options:["1.5 Ω","6 Ω","0.17 Ω","3.5 Ω"],correctIndex:1,explanation:"R = V/I = 3 V \xf7 0.5 A = 6 Ω. A common slip is multiplying instead of dividing (giving 1.5) — remember resistance asks how many volts are needed per ampere of current."},{question:"You replace a wire with one of the same material and thickness but twice as long. Its resistance…",options:["doubles","halves","stays the same","quadruples"],correctIndex:0,explanation:"Resistance is proportional to length: twice the wire means twice the atomic lattice for electrons to fight through, so twice the resistance. To reduce resistance you'd shorten the wire — or make it thicker."},{question:"Which change would decrease a wire's resistance?",options:["Making it longer","Letting it heat up","Swapping copper for nichrome","Making it thicker"],correctIndex:3,explanation:"A thicker wire offers more parallel 'lanes' for electron flow — doubling the cross-sectional area halves the resistance. The other three options all increase it: more length, more thermal jostling, or a material with ~65\xd7 copper's resistivity."},{question:"Why is nichrome, rather than copper, used for the glowing element in a toaster?",options:["Nichrome is a better conductor than copper","Nichrome has high resistivity and survives high temperatures, so it heats up strongly without failing","Copper cannot carry enough current","Nichrome is much cheaper than copper"],correctIndex:1,explanation:"A heating element needs substantial resistance to convert electrical energy into heat, plus the ability to run red-hot in air without melting or oxidizing away. Nichrome delivers both; copper's resistivity is ~65\xd7 lower — great for delivering current, terrible for deliberately making heat."}]},{id:"electrical-power-and-home-electricity",title:"Electrical Power & Home Electricity",subtitle:"P = VI, Joule heating, your electricity bill, and the safety systems in your walls",sections:[{id:"p-equals-vi",title:"P = VI: How Much Power Does It Draw?",content:'\n<p>Every appliance in your home is, at heart, a device for converting electrical energy into something else — light, heat, motion, sound. The rate of that conversion is <strong>power</strong>, measured in <strong>watts</strong> (W): one watt is one joule of energy per second, the same unit you met in mechanics.</p>\n<div class="key-concept">\n  <h4>Key Concept: The Power Formula</h4>\n  <p><strong>P = V \xd7 I</strong> — power equals voltage times current. It makes intuitive sense: voltage is the energy each coulomb carries (joules per coulomb), and current is how many coulombs arrive per second. Multiply them and you get joules per second — watts.</p>\n</div>\n<p>This formula turns the label on any appliance into real information. Typical values:</p>\n<table>\n  <thead>\n    <tr><th>Appliance</th><th>Power</th><th>Current at 230 V</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Phone charger</td><td>10 W</td><td>≈ 0.04 A</td></tr>\n    <tr><td>LED bulb</td><td>9 W</td><td>≈ 0.04 A</td></tr>\n    <tr><td>Laptop</td><td>60 W</td><td>≈ 0.26 A</td></tr>\n    <tr><td>Refrigerator (running)</td><td>150 W</td><td>≈ 0.65 A</td></tr>\n    <tr><td>Microwave oven</td><td>1,100 W</td><td>≈ 4.8 A</td></tr>\n    <tr><td>Electric kettle</td><td>2,300 W</td><td>10 A</td></tr>\n    <tr><td>Electric shower</td><td>8,500 W</td><td>≈ 37 A (needs its own heavy circuit)</td></tr>\n  </tbody>\n</table>\n<p>The pattern leaps out: <strong>anything that makes heat is power-hungry</strong>. Electronics sip; kettles, heaters, ovens, and dryers gulp. Rearranging to I = P/V is how electricians size wiring: a 2,300 W kettle on a 230 V supply draws 2300/230 = 10 A, so its circuit and plug must handle at least that.</p>\n<p>P = VI also teams up with Ohm\'s law. Since V = IR, you can substitute to taste: the same power can be written P = I\xb2R or P = V\xb2/R. You don\'t need to memorize the variants now — just notice that power, voltage, current, and resistance are one interlocking family, and any two determine the rest.</p>\n<div class="did-you-know">\n  <h3>Did You Know?</h3>\n  <p>In North America, outlets supply 120 V, so the same 1,800 W kettle draws 15 A — right at the limit of a standard circuit. That\'s why kettles are noticeably slower there, and why 230 V regions have a small practical edge in tea-making.</p>\n</div>'},{id:"joule-heating",title:"Joule Heating: Wires That Warm",content:'\n<p>Wherever current flows through resistance, electrical energy becomes heat. The drifting electrons collide with the atoms of the material, and every collision passes on a jolt of energy that sets the atoms vibrating harder — which is exactly what "getting hotter" means. This is <strong>Joule heating</strong>, named for James Joule, the same brewer-physicist behind the energy unit.</p>\n<p>Whether Joule heating is a feature or a menace depends entirely on where it happens.</p>\n<p><strong>On purpose</strong> — a whole catalogue of appliances is nothing but a resistor engineered to run hot:</p>\n<ul>\n  <li>Toasters and kettles: nichrome elements glowing red or heating water.</li>\n  <li>Electric ovens, irons, hair dryers, space heaters, underfloor heating.</li>\n  <li>The old incandescent bulb: a tungsten filament Joule-heated to ~2,700 \xb0C until it glows white. Only ~5% of its energy became light — the other 95% was heat, which is why LEDs, giving the same light for a tenth of the power, replaced it worldwide.</li>\n</ul>\n<p><strong>By accident</strong> — the same physics turns dangerous when heat appears where it isn\'t wanted:</p>\n<ul>\n  <li><strong>Overloaded extension cords:</strong> plug a heater into a thin cord and the cord\'s own resistance dissipates real power along its length. Coiled or under a carpet, that heat can\'t escape — cords have started house fires this way. Always match the cord\'s current rating to the appliance.</li>\n  <li><strong>Loose connections:</strong> a corroded or loose contact is a spot of unexpected resistance; at high current it becomes a tiny hotplate inside a wall socket. Warm plugs and scorch marks are warnings to take seriously.</li>\n  <li><strong>Transmission losses:</strong> every kilometre of grid cable wastes some energy as heat. Utilities fight this with thick aluminium conductors and — as the final chapter explains — extremely high voltages, which allow the same power to flow at low, low current.</li>\n</ul>\n<div class="analogy">\n  <h3>Analogy: Friction for Electricity</h3>\n  <p>Joule heating is the electrical twin of friction. Rub your hands and motion becomes warmth; push current through resistance and electrical energy becomes warmth. Both are unavoidable taxes — and both can be harnessed (striking a match, toasting bread) or minimized (oiling a bearing, thickening a wire), depending on what you\'re trying to do.</p>\n</div>\n<div class="key-concept">\n  <h4>Key Concept: Heat Rises with the Square of Current</h4>\n  <p>Because heating power is P = I\xb2R, doubling the current through a wire makes it heat <strong>four times</strong> faster. This is why overloads escalate quickly, and why every safety device in the next sections watches current above all else.</p>\n</div>'},{id:"kwh-and-bills",title:"The Kilowatt-Hour: Buying Energy by the Box",content:"\n<p>Your electricity provider doesn't sell you power — it sells you <strong>energy</strong>: power multiplied by time. The billing unit is the <strong>kilowatt-hour (kWh)</strong>: the energy used by a 1,000 W appliance running for one hour. In mechanics units, 1 kWh = 1,000 W \xd7 3,600 s = <strong>3.6 million joules</strong> — the joule is simply too small a coin for monthly billing.</p>\n<p>The recipe for any appliance's cost is three steps: <strong>kilowatts \xd7 hours = kWh, then kWh \xd7 price = cost.</strong> Using a typical price of $0.25 per kWh (check your own bill — prices vary widely by country and utility):</p>\n<table>\n  <thead>\n    <tr><th>Appliance</th><th>Power</th><th>Usage</th><th>Energy</th><th>Cost</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Kettle (one boil)</td><td>2.3 kW</td><td>3 min (0.05 h)</td><td>0.115 kWh</td><td>≈ 3 cents</td></tr>\n    <tr><td>LED bulb, evening</td><td>0.009 kW</td><td>5 h</td><td>0.045 kWh</td><td>≈ 1 cent</td></tr>\n    <tr><td>Laptop workday</td><td>0.06 kW</td><td>8 h</td><td>0.48 kWh</td><td>≈ 12 cents</td></tr>\n    <tr><td>Space heater, month</td><td>2 kW</td><td>6 h/day \xd7 30</td><td>360 kWh</td><td>≈ $90</td></tr>\n    <tr><td>Fridge, month</td><td>≈ 0.05 kW average</td><td>24 h/day \xd7 30</td><td>≈ 36 kWh</td><td>≈ $9</td></tr>\n  </tbody>\n</table>\n<p>Two lessons hide in that table. First, <strong>heat plus hours equals money</strong>: the space heater costs ten times more per month than the always-on fridge, because it combines high power with long runtimes. Cutting one hour of heater use per day saves more than obsessively switching off every LED in the house. Second, small powers still add up when they never turn off: a home's <strong>standby load</strong> — TVs, routers, chargers, consoles idling — commonly totals 20–40 W around the clock, which at 30 W is 0.03 kW \xd7 720 h ≈ 22 kWh a month, roughly $5.40 for nothing.</p>\n<div class=\"key-concept\">\n  <h4>Key Concept: Power Is a Rate, Energy Is an Amount</h4>\n  <p>A kilowatt (kW) is like a car's speed; a kilowatt-hour (kWh) is like the distance travelled. Your meter is an odometer for energy: the spinning disc or digital counter accumulates kWh, and the bill is just the month's difference times the price.</p>\n</div>\n<div class=\"did-you-know\">\n  <h3>Did You Know?</h3>\n  <p>One kWh — a few cents' worth of electricity — equals the mechanical work of a fit human labouring for most of a day. Measured in servant-hours, electricity is history's greatest bargain, which is precisely why its arrival transformed civilization within two generations.</p>\n</div>"},{id:"fuses-earthing-safety",title:"Fuses, Earthing, and Staying Alive",content:'\n<p>Mains electricity delivers marvellous power at lethal voltage; it feels mundane only because of the safety engineering stacked in your walls. Each layer is worth knowing.</p>\n<p><strong>Layer 1: Fuses and circuit breakers — protecting the wiring.</strong> A fuse is a deliberately weak link: a thin wire that Joule-heats and melts if the current exceeds its rating, breaking the circuit. A circuit breaker does the same job with an electromagnet or thermal strip tripping a switch — resettable instead of sacrificial. The rating (13 A, 16 A, 20 A…) is chosen to be above normal demand but below the current that would dangerously overheat the cables in the wall. Two rules follow: never replace a fuse with a higher-rated one (the fuse will be fine — your wall wiring becomes the fuse), and never "fix" one with foil or a nail.</p>\n<p><strong>Layer 2: Earthing — protecting against live metal.</strong> The third pin on a plug connects the appliance\'s metal casing, via the earth wire, literally to a rod in the ground. Suppose a loose live wire inside a washing machine touches the metal case. Without earthing, the case silently sits at 230 V, waiting for a hand. With earthing, the fault current instantly floods down the low-resistance earth path, the surge blows the fuse, and the appliance goes dead — failing <em>safe</em>.</p>\n<p><strong>Layer 3: RCD / GFCI — protecting people directly.</strong> A residual current device compares the current flowing out along the live wire with the current returning on the neutral. They should be exactly equal. A mismatch of even ~30 mA means current is escaping somewhere — possibly through a person — and the RCD cuts the power within a few hundredths of a second. This is the device that makes bathroom and outdoor sockets survivable, and the test button on it deserves a monthly press.</p>\n<div class="key-concept">\n  <h4>Key Concept: Current Kills, Milliamps Suffice</h4>\n  <p>Through the human body, ~1 mA is a tingle, ~10–20 mA can lock muscles so you cannot let go, and ~50–100 mA across the chest can stop the heart. Wet skin drops your body\'s resistance dramatically — by Ohm\'s law, the same voltage then drives far more current. Hence the iron rule: water and mains electricity never mix — no dripping hands on switches, no electrical devices near baths.</p>\n</div>\n<div class="did-you-know">\n  <h3>Did You Know?</h3>\n  <p>Birds perch unharmed on bare power lines because both feet touch the <em>same</em> wire — with no voltage difference across their bodies, no current flows through them. The danger is touching two points at different voltages, like a line and the ground. Which is why kites, ladders, and pruning poles near overhead lines are a genuinely bad idea.</p>\n</div>'}],quiz:[{question:"A 2,300 W electric kettle runs on a 230 V supply. What current does it draw?",options:["0.1 A","10 A","529 A","23 A"],correctIndex:1,explanation:"Rearrange P = VI to I = P/V: 2300 W \xf7 230 V = 10 A. This is exactly how electricians size circuits and choose fuse ratings — heat-making appliances draw the most current by far."},{question:"What exactly does a kilowatt-hour measure?",options:["Energy — the total amount of electrical work delivered","Power — how fast energy is being used","Current — the flow of charge per hour","Voltage supplied over one hour"],correctIndex:0,explanation:"A kWh is power \xd7 time: 1 kW sustained for 1 hour, equal to 3.6 million joules. Power (kW) is the rate, like speed; energy (kWh) is the accumulated amount, like distance — and energy is what the bill charges for."},{question:"A 2 kW space heater runs 5 hours a day for 30 days. At $0.25 per kWh, roughly what does that month of heating cost?",options:["$7.50","$2.50","$75","$300"],correctIndex:2,explanation:"Energy = 2 kW \xd7 5 h \xd7 30 days = 300 kWh. Cost = 300 \xd7 $0.25 = $75. High power combined with long hours is what makes bills climb — heating and cooling dominate almost every household's electricity cost."},{question:"How does a fuse protect a circuit?",options:["It stores excess charge until the surge passes","It lowers the voltage when too many appliances are connected","It cools the wiring in the walls","Its thin wire melts when current exceeds the rating, breaking the circuit"],correctIndex:3,explanation:"A fuse is a sacrificial weak link that exploits Joule heating: excess current melts it first, cutting the circuit before the wall wiring can overheat. Replacing a fuse with a higher-rated one (or foil) removes this protection and invites an electrical fire."},{question:"Why is the metal casing of a washing machine connected to the earth wire?",options:["To give static charge a place to accumulate","So that if a live wire touches the case, a large fault current flows to ground and blows the fuse, cutting the power","To improve the motor's efficiency","To reduce the electricity bill by recycling current"],correctIndex:1,explanation:"Earthing makes a fault fail-safe. Without it, a loose live wire would leave the case silently at mains voltage, waiting for a touch. With it, the fault current surges through the low-resistance earth path, the fuse blows immediately, and the appliance goes dead instead of deadly."}]},{id:"magnetism",title:"Magnetism",subtitle:"Magnets, fields, Earth's compass, and the discovery that currents are magnetic too",sections:[{id:"magnets-and-fields",title:"Poles, Fields, and Iron Filings",content:'\n<p>Magnetism, like static electricity, was known to the ancients as a curiosity: lodestones — naturally magnetized rocks — that attracted iron. Two thousand years later, the rules are crisp.</p>\n<p>Every magnet has two <strong>poles</strong>, named north and south (for reasons the next section makes clear). The interaction rule mirrors electric charge exactly:</p>\n<ul>\n  <li><strong>Like poles repel:</strong> north pushes away north, south pushes away south.</li>\n  <li><strong>Unlike poles attract:</strong> north and south pull together.</li>\n  <li>The force weakens rapidly with distance, and acts through air, water, plastic, even your hand.</li>\n</ul>\n<p>But one deep difference separates magnetism from electricity. You can isolate a positive charge — but you cannot isolate a north pole. <strong>Cut a bar magnet in half and you get two complete smaller magnets</strong>, each with its own north and south. Cut again: four magnets. Keep going to the atomic scale and the poles still come in pairs. No isolated magnetic pole — a "monopole" — has ever been found. Magnetism at root comes from moving charge, notably the motion of electrons inside atoms; in iron, nickel, and cobalt, these atomic magnets can align in unison, making the whole piece magnetic. In most other materials they point randomly and cancel, which is why copper coins and aluminium foil ignore magnets.</p>\n<p>Like charges, magnets act at a distance through a <strong>magnetic field</strong> filling the space around them. And this field you can actually see: lay a sheet of paper over a bar magnet, sprinkle iron filings, tap gently — the filings snap into sweeping arcs from pole to pole, a portrait of the field. By convention field lines run <strong>from north to south outside the magnet</strong>, and where they crowd — at the poles — the field is strongest, exactly the field-line grammar you learned for electricity.</p>\n<div class="key-concept">\n  <h4>Key Concept: One Field-Reading Skill, Two Fields</h4>\n  <p>Direction from the arrows, strength from the crowding: the skill transfers unchanged from electric to magnetic fields. Physics reuses its best ideas — and in the next chapter these two fields will turn out to be intimate partners.</p>\n</div>\n<div class="did-you-know">\n  <h3>Did You Know?</h3>\n  <p>A refrigerator magnet grips through printed paper but its field fades within a centimetre or so — many are cleverly magnetized in alternating strips (strong on the gripping face, weak on the back). Meanwhile an MRI scanner\'s field, ~3 tesla, is powerful enough to yank steel oxygen cylinders across the room, which is why MRI suites screen everything that enters.</p>\n</div>'},{id:"earths-magnetic-field",title:"Earth: The Planet-Sized Magnet",content:"\n<p>Float a magnetized needle on a leaf and it slowly swings to point north-south. That humble observation — the compass — guided ships across oceans for a millennium before anyone knew <em>why</em> it worked. The answer: <strong>Earth itself is a giant magnet</strong>, and every compass needle is simply aligning with its field, just like one filing in the world's largest iron-filing experiment.</p>\n<p>Where does the planet's field come from? Not from a buried bar magnet — Earth's interior is far too hot for permanent magnetism to survive. Instead, the outer core is an ocean of <strong>molten iron</strong>, churning with heat-driven currents while the planet rotates. Moving molten metal means moving charge, and moving charge — as the next section reveals — generates magnetism. This self-sustaining engine is called the <strong>geodynamo</strong>, and it's a preview of the chapter's big idea: electricity and magnetism are one subject.</p>\n<p>A delightful naming tangle: a compass needle's north pole points toward Earth's Arctic. But unlike poles attract — so the thing in the Arctic attracting all those north poles is, magnetically speaking, a <em>south</em> pole. Convention papers over this by calling compass-north \"north-seeking,\" and navigation carries on regardless.</p>\n<ul>\n  <li>The magnetic poles don't coincide with the geographic ones, and they <strong>wander</strong> — the north magnetic pole has drifted from Canada toward Siberia at up to ~50 km per year in recent decades, forcing periodic updates to navigation systems.</li>\n  <li>The rock record shows Earth's field has <strong>flipped polarity</strong> hundreds of times — most recently ~780,000 years ago. Cooling lava locks in the field's direction like a tape recording, striping the ocean floor with the evidence.</li>\n  <li>The field extends far into space, where it deflects the <strong>solar wind</strong> — the Sun's stream of charged particles. Some particles funnel down near the poles, crash into the upper atmosphere, and make it glow: the auroras.</li>\n</ul>\n<div class=\"did-you-know\">\n  <h3>Did You Know?</h3>\n  <p>Compasses aren't only human technology. Migratory birds, sea turtles, and even some bacteria carry biological magnetic sensors, navigating by the same planetary field — a trick evolution discovered long before the lodestone.</p>\n</div>"},{id:"current-magnetic-field",title:"Oersted's Surprise: Currents Make Magnetism",content:"\n<p>Until 1820, electricity and magnetism sat in separate chapters of every book: one about charges and sparks, the other about lodestones and compasses. Then, during a lecture, Danish physicist Hans Christian Oersted noticed something that changed physics forever: when he switched on a current in a wire, <strong>a compass needle lying nearby twitched and swung</strong>. The current was creating a magnetic field.</p>\n<p>Follow-up experiments mapped the field's shape: it forms <strong>closed circles around the wire</strong>, like ripples around a stalk. There's a handy rule for the direction — the <strong>right-hand grip rule</strong>: point your right thumb along the (conventional) current, and your curled fingers show which way the circular field lines run. Stronger current gives a stronger field; farther from the wire, it fades.</p>\n<div class=\"key-concept\">\n  <h4>Key Concept: The Great Unification Begins</h4>\n  <p>Moving charge creates magnetism. That single sentence welds two sciences into one — electromagnetism. Every electromagnet, motor, generator, and transformer in the coming sections is engineering built on Oersted's twitching needle. Even permanent magnets fit the pattern: their magnetism comes from electron motion inside atoms.</p>\n</div>\n<h3>Try it yourself: Recreate Oersted's discovery</h3>\n<ol>\n  <li>You need: a compass (a phone compass app works, though a real needle compass is more vivid), one AA battery, and a ~30 cm length of wire — a strip of aluminium foil folded into a ribbon works too.</li>\n  <li>Lay the compass flat and let the needle settle. Stretch the wire directly <em>over</em> the compass, parallel to the needle's rest direction.</li>\n  <li>Press the wire's ends to the battery terminals for <strong>one second only</strong> — this is nearly a short circuit, so the wire warms quickly; brief taps are plenty (and safe at 1.5 V).</li>\n  <li>Watch the needle jump sideways the instant current flows, and relax when it stops. Swap the battery ends and it jumps the other way — you've just steered a magnetic field by reversing a current, two centuries after Oersted.</li>\n</ol>\n<div class=\"did-you-know\">\n  <h3>Did You Know?</h3>\n  <p>News of Oersted's demonstration raced across Europe in months. Within weeks Andr\xe9-Marie Amp\xe8re had worked out that two parallel currents attract or repel each other magnetically — wires acting like magnets on each other, no iron involved. The unit of current honours him for it.</p>\n</div>"},{id:"electromagnets",title:"Electromagnets: Magnetism on Demand",content:"\n<p>A single straight wire makes a feeble magnet. The genius move is to concentrate it: <strong>wind the wire into a coil</strong>. Each loop's circular field adds to its neighbours', and inside the coil the combined field runs straight along the axis — the coil behaves exactly like a bar magnet, with a north face and a south face. Physicists call such a coil a <em>solenoid</em>.</p>\n<p>Then comes the multiplier: slide an <strong>iron core</strong> into the coil. The coil's field aligns iron's atomic magnets, and their contribution stacks on top — boosting the total field enormously, often by a factor in the hundreds. Coil plus core is the classic <strong>electromagnet</strong>. Its strength grows with:</p>\n<ul>\n  <li><strong>More turns</strong> of wire in the coil,</li>\n  <li><strong>More current</strong> through the wire,</li>\n  <li><strong>A better core</strong> — soft iron being the standard choice.</li>\n</ul>\n<p>What makes electromagnets revolutionary isn't raw strength — it's <strong>control</strong>. Compare:</p>\n<table>\n  <thead>\n    <tr><th></th><th>Permanent magnet</th><th>Electromagnet</th></tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>On/off</strong></td><td>Always on</td><td>Switchable with the current</td></tr>\n    <tr><td><strong>Strength</strong></td><td>Fixed</td><td>Adjustable — turn the current up or down</td></tr>\n    <tr><td><strong>Poles</strong></td><td>Fixed</td><td>Reversible — flip the current, swap N and S</td></tr>\n  </tbody>\n</table>\n<p>That trio of tricks — switchable, adjustable, reversible — runs a startling amount of your day:</p>\n<ul>\n  <li><strong>Scrapyard cranes</strong> lift a car with the current on, drop it with the current off.</li>\n  <li><strong>Relays and door locks:</strong> a small current energizes a coil that pulls a switch or bolt — the office door buzzer is an electromagnet letting go.</li>\n  <li><strong>Loudspeakers and earbuds:</strong> a coil glued to the cone sits near a permanent magnet; the audio current flips the coil's push-pull thousands of times a second, vibrating the cone into sound.</li>\n  <li><strong>MRI scanners and maglev trains:</strong> superconducting electromagnets at the extreme end of the art.</li>\n</ul>\n<div class=\"analogy\">\n  <h3>Analogy: A Tap for Magnetism</h3>\n  <p>A permanent magnet is like a spring that never stops flowing. An electromagnet is a tap: open it, close it, throttle it, even reverse it. Once magnetism became controllable, it became <em>technology</em> — and the next chapter turns that tap into motors and generators.</p>\n</div>"}],quiz:[{question:"What happens if you cut a bar magnet in half?",options:["One half is a pure north pole, the other a pure south pole","Both halves lose their magnetism","You get two complete smaller magnets, each with a north and a south pole","The halves can no longer attract iron"],correctIndex:2,explanation:"Poles always come in pairs — cutting a magnet just creates new pole faces at the cut. However finely you divide it, down to the atomic scale, no isolated north or south pole (monopole) has ever been found."},{question:"What do iron filings sprinkled around a bar magnet reveal?",options:["The pattern of the magnetic field lines around the magnet","The electric charge stored in the magnet","The temperature distribution of the magnet","The direction of electron flow through the magnet"],correctIndex:0,explanation:"Each filing becomes a tiny magnet and aligns with the local field, so together they trace the field-line pattern — arcs sweeping from pole to pole, crowding where the field is strongest."},{question:"What did Oersted discover in 1820?",options:["That Earth's magnetic poles wander over time","That an electric current creates a magnetic field, deflecting a nearby compass","That iron is the only magnetic material","That magnets can generate electric current"],correctIndex:1,explanation:"Oersted noticed a compass needle twitch when a nearby current was switched on — the first evidence that electricity and magnetism are one linked subject. (Magnets generating current is Faraday's later discovery of induction, in the next chapter.)"},{question:"Which of the following would NOT make an electromagnet stronger?",options:["Increasing the current through the coil","Winding more turns of wire","Inserting a soft iron core","Replacing the iron core with a plastic rod"],correctIndex:3,explanation:"Strength grows with more turns, more current, and an iron core whose atomic magnets align with and multiply the coil's field. Plastic has no such alignable atomic magnets, so a plastic core adds nothing — the electromagnet drops back to bare-coil strength."},{question:"What generates Earth's magnetic field?",options:["A gigantic deposit of permanently magnetized iron at the centre","The Moon's gravitational pull on the oceans","Churning molten iron in the outer core acting as a self-sustaining dynamo","Sunlight striking the atmosphere near the poles"],correctIndex:2,explanation:"Earth's deep interior is too hot for permanent magnetism to survive. Instead, convecting molten iron in the rotating outer core carries electric currents that sustain the field — the geodynamo. Its restlessness explains why the magnetic poles wander and have even flipped throughout geological history."}]},{id:"motors-generators-and-induction",title:"Motors, Generators & Induction",subtitle:"The physics that electrified civilization: motors, Faraday's induction, and the grid",sections:[{id:"force-on-a-wire",title:"The Motor Effect: A Wire That Jumps",content:"\n<p>Oersted showed that a current makes a magnetic field. Flip the logic: if a current-carrying wire is a magnet, then placing it in <em>someone else's</em> magnetic field should produce a force between them. It does — and the wire visibly jumps. This is the <strong>motor effect</strong>, and it is the muscle behind every electric motor on Earth.</p>\n<p>The rules of the force, all discoverable with a wire, a battery, and a horseshoe magnet:</p>\n<ul>\n  <li><strong>Direction:</strong> the force is perpendicular to <em>both</em> the current and the field — a wire running left-right in a field pointing away from you gets pushed up or down, not sideways. (Physicists keep track with a finger-pointing rule; for this first pass, \"perpendicular to both\" is the key fact.)</li>\n  <li><strong>Reversibility:</strong> reverse the current, and the force flips. Reverse the field instead — same flip. Reverse both, and it's back where it started.</li>\n  <li><strong>Strength:</strong> more current, a stronger field, or more wire in the field all mean more force.</li>\n  <li><strong>Alignment matters:</strong> the force is greatest when current and field are perpendicular, and vanishes when the wire runs parallel to the field.</li>\n</ul>\n<div class=\"analogy\">\n  <h3>Analogy: Two Magnets in Disguise</h3>\n  <p>You already know magnets push and pull on each other. The current-carrying wire simply <em>is</em> a magnet (Oersted's discovery), so of course a nearby field pushes on it. The motor effect is magnet-on-magnet force, with one of the magnets switchable, adjustable, and reversible — an electromagnet's full bag of tricks.</p>\n</div>\n<p>Even before building a full motor, the bare effect does real work:</p>\n<ul>\n  <li><strong>Loudspeakers:</strong> the audio signal is a current wiggling through a coil attached to the speaker cone, sitting in a permanent magnet's field. Every wiggle of current is a push or pull on the cone — sound, manufactured by the motor effect thousands of times per second.</li>\n  <li><strong>Analog meters:</strong> the classic swinging-needle ammeter is a coil in a field; more current, more force, bigger swing.</li>\n</ul>\n<div class=\"key-concept\">\n  <h4>Key Concept: Force From Field Plus Current</h4>\n  <p>Field alone does nothing to a dead wire. Current alone, no field, no push. But current <em>in</em> a field yields force — motion from electricity. Arrange that force to act around an axle, and you've invented the motor. That's the next section.</p>\n</div>"},{id:"the-dc-motor",title:"Inside the DC Motor",content:"\n<p>A force that pushes a wire once is a party trick. A motor needs continuous rotation — and getting there requires one genuinely clever widget. Here's the machine, step by step.</p>\n<ol>\n  <li><strong>Start with a loop.</strong> Place a rectangular loop of wire between the poles of a magnet, free to spin on an axle. Send current around the loop.</li>\n  <li><strong>Opposite pushes.</strong> Current flows one way along the loop's left side and the opposite way along its right side. By the motor effect, the two sides feel <strong>opposite forces</strong> — one up, one down. A pair of opposite forces on either side of an axle is exactly a twist: the loop rotates.</li>\n  <li><strong>The problem at half-turn.</strong> After 180\xb0, the loop's sides have swapped places — but each still carries current the same way around the loop, so the forces now twist it <em>backwards</em>. Left alone, the loop would just wobble to a halt, stuck at the balance point.</li>\n  <li><strong>The commutator's fix.</strong> The loop's ends connect to a <strong>split ring</strong> — a metal ring cut into two halves, spinning with the loop — fed by stationary contacts called <strong>brushes</strong>. Every half-turn, each brush slides onto the other half of the ring, <strong>reversing the current through the loop at exactly the right moment</strong>. The forces therefore always twist the same way, and the loop spins continuously.</li>\n</ol>\n<div class=\"key-concept\">\n  <h4>Key Concept: The Commutator</h4>\n  <p>The split-ring commutator is the motor's one stroke of genius: a rotary switch that flips the loop's current every half-revolution so the twist never reverses. Master this idea and you understand the DC motor completely.</p>\n</div>\n<p>Real motors refine the toy: <strong>many loops</strong> at different angles around the axle (so the twist is strong and smooth at every position), wound on an <strong>iron core</strong> to concentrate the field, with either permanent magnets or field coils supplying the magnetism. Spin direction reverses by reversing the supply; speed rises with current. Many modern \"brushless\" motors replace the sliding contacts with electronic switching — same principle, transistors instead of brushes.</p>\n<div class=\"did-you-know\">\n  <h3>Did You Know?</h3>\n  <p>Count the motors around you: phone vibration, electric toothbrush, fans, hard drives, washing machine, power tools, car windows and wipers — a typical household runs dozens. An electric car's drive motor delivers full twisting force from a standstill, which is why EVs launch so briskly, with roughly one moving part where a petrol engine has hundreds.</p>\n</div>"},{id:"induction-and-generators",title:"Faraday's Reverse Trick: Induction and Generators",content:'\n<p>By 1831, the score read: electricity makes magnetism (Oersted), and magnetism pushes on currents (the motor effect). Michael Faraday chased the symmetry for a decade — could magnetism make <em>electricity</em>? His answer electrified the world, literally.</p>\n<p>The discovery: <strong>thrust a magnet into a coil of wire, and a current flows in the coil — with no battery anywhere.</strong> Pull the magnet out, and the current flows the other way. Hold the magnet still, and… nothing at all. That last observation is the heart of the matter:</p>\n<div class="key-concept">\n  <h4>Key Concept: Electromagnetic Induction</h4>\n  <p>A <strong>changing</strong> magnetic field through a coil induces a voltage, driving a current if the circuit is closed. No change, no current — a stationary magnet resting in a coil forever generates nothing. It is the <em>motion</em>, the changing of the field through the loop, that does the work.</p>\n</div>\n<p>The induced effect grows with:</p>\n<ul>\n  <li><strong>Faster</strong> movement — quicker change, bigger voltage;</li>\n  <li><strong>More turns</strong> on the coil — each loop adds its share;</li>\n  <li><strong>A stronger magnet</strong> — more field to change.</li>\n</ul>\n<p>Now the payoff. A generator is simply a coil and a magnet in continuous relative rotation: spin the coil in the field (or spin magnets past the coil), and the field through the loop changes relentlessly, inducing voltage as long as the spinning continues. <strong>A generator is a motor run in reverse</strong> — the motor turns current into motion, the generator turns motion into current; the hardware is nearly identical.</p>\n<p>Notice something natural about the output: as the coil rotates, the induced push cycles smoothly — one way, then the other, once per revolution. Rotation naturally produces <strong>alternating current</strong>, which is a big part of why the grid runs on AC.</p>\n<p>Step back and survey the world\'s power stations: coal, gas, and nuclear plants boil water into steam to spin a turbine; hydroelectric dams use falling water; wind turbines use moving air. <strong>Every one of them is just a different way to spin Faraday\'s coil.</strong> Roughly 95% of the world\'s electricity — the light over your head included — comes from induction in a spinning generator. Solar panels are the notable exception, converting light directly.</p>\n<div class="did-you-know">\n  <h3>Did You Know?</h3>\n  <p>Asked (so the story goes) what use this induction business was, Faraday reputedly answered, "What use is a newborn baby?" The baby grew up to be the power grid. On a smaller scale, shake-to-charge torches, bicycle dynamos, and induction cooktops are all Faraday\'s coil in disguise.</p>\n</div>'},{id:"transformers-and-the-grid",title:"Transformers and the Journey to Your Wall Socket",content:'\n<p>One puzzle stands between the power station and your toaster. Generators produce electricity at thousands of volts, your outlet delivers 230 V, and the cables in between run at hundreds of thousands. Who keeps changing the voltage, and why bother? The answers: the transformer, and Joule heating.</p>\n<p><strong>Why high voltage?</strong> Power delivered is P = VI — the same power can travel as high voltage with small current, or low voltage with enormous current. But the cable\'s heating loss grows steeply with current (recall: quadruple the heat for double the current). So the grid\'s strategy is: <strong>crank the voltage up, squeeze the current down</strong>, and the long-distance cables barely warm. Transmitting at 400,000 V instead of 230 V cuts the current by a factor of ~1,700 — turning what would be catastrophic losses into a few percent.</p>\n<p><strong>How a transformer changes voltage.</strong> Two coils share an iron core, with no electrical connection between them:</p>\n<ol>\n  <li>AC in the <strong>primary coil</strong> creates a magnetic field in the core that grows, collapses, and reverses 50–60 times per second.</li>\n  <li>The iron core channels this ever-changing field through the <strong>secondary coil</strong>.</li>\n  <li>A changing field through a coil — Faraday\'s induction — induces a voltage in the secondary. No moving parts; the "motion" is the field\'s own pulsing.</li>\n</ol>\n<p>The voltage ratio equals the <strong>turns ratio</strong>: a secondary with 10\xd7 the primary\'s turns steps voltage up 10\xd7; a secondary with a tenth of the turns steps it down to a tenth. (Energy is conserved: what you gain in voltage, you give up in available current.) And now the grid\'s AC preference is fully explained: <strong>a transformer needs a changing field, so it only works on AC.</strong> Feed it steady DC and the field just sits there — no change, no induction, no output.</p>\n<div class="key-concept">\n  <h4>Key Concept: The Journey of a Watt</h4>\n  <p>Generator (~20,000 V) → step-<strong>up</strong> transformer → transmission lines (110,000–400,000 V, tiny current, tiny losses) → step-<strong>down</strong> transformers at substations → local lines (~11,000 V) → the neighbourhood transformer on a pole or in a green box → your home at 230 V (120 V in North America). Milliseconds after generation, the energy lighting your room was steam, falling water, or wind.</p>\n</div>\n<div class="did-you-know">\n  <h3>Did You Know?</h3>\n  <p>You own transformers by the drawer-full: every charger and power brick steps mains voltage down (phones charge at 5–20 V). The faint buzz of a substation is its transformer cores physically flexing with the 50 Hz field. And the great AC-versus-DC "War of the Currents" between Edison and Westinghouse/Tesla in the 1880s was settled largely by the transformer — AC could change voltage cheaply, so AC won the grid.</p>\n</div>'}],quiz:[{question:"In a DC motor, what is the job of the split-ring commutator?",options:["To increase the voltage supplied to the coil","To reverse the current through the coil every half-turn so the twisting force keeps the same direction","To hold the magnets in place around the axle","To convert the motor's AC output into DC"],correctIndex:1,explanation:"Without the commutator, the forces on the spinning loop would reverse after half a turn and the loop would wobble to a stop. The split ring swaps the current direction at exactly that moment, so the twist always drives the rotation onward."},{question:"A strong magnet rests motionless inside a coil connected to a sensitive meter. What does the meter read?",options:["Zero — induction requires the magnetic field through the coil to be changing","A large steady current, because the magnet is strong","A small steady current that slowly drains the magnet","An alternating current at 50 Hz"],correctIndex:0,explanation:"Faraday's key finding: only a changing field induces voltage. Move the magnet (or the coil) and current flows — faster movement, more turns, or a stronger magnet all increase it — but a stationary magnet, however strong, induces nothing."},{question:"What is a generator, at its core?",options:["A device that stores electrical energy in chemical form","A transformer with additional turns on the secondary coil","A coil and magnet in relative rotation, converting motion into electric current by induction","An electromagnet powerful enough to create current from nothing"],correctIndex:2,explanation:"Spin a coil in a magnetic field (or magnets past a coil) and the changing field induces a voltage continuously — a motor run in reverse. Coal, gas, nuclear, hydro, and wind power all ultimately just spin generators; only the source of the spinning differs."},{question:"Why does the grid transmit power at hundreds of thousands of volts?",options:["High voltage makes the electricity travel faster","Generators can only produce very high voltages","High voltage keeps birds off the cables","At high voltage the same power flows with much less current, so far less energy is lost heating the cables"],correctIndex:3,explanation:"P = VI: raising the voltage lets the current shrink for the same delivered power, and cable heating falls steeply as current drops (halving current cuts the heat to a quarter). Step-up transformers at the plant and step-down transformers near your home make this strategy practical."},{question:"Why do transformers work only with alternating current?",options:["Induction in the secondary coil requires a changing magnetic field, which steady DC cannot provide","DC would melt the iron core","AC is safer than DC at all voltages","The two coils must alternate carrying the current"],correctIndex:0,explanation:"A transformer is pure Faraday induction: the primary's field must keep changing to induce voltage in the secondary. AC reverses 50–60 times a second, so the field pulses constantly; steady DC creates a constant field — no change, no induction, no output. This is the main reason the grid adopted AC."}]}]},{id:"atoms-nuclei-energy",number:9,title:"Atoms, Nuclei & Energy",description:"The first-pass finale: journey inside the atom, meet radioactivity and nuclear power, and step back to ask how humanity should power its future.",phase:2,chapters:[{id:"inside-the-atom",title:"Inside the Atom",subtitle:"From Thomson's plum pudding to Bohr's orbits — how we discovered what atoms are made of",sections:[{id:"the-electron",title:"1897: The First Crack in the Atom",content:'\n<p>The word <strong>atom</strong> comes from the Greek <em>atomos</em> — "uncuttable." For most of the 1800s that\'s exactly what chemists believed: atoms were tiny, featureless billiard balls, the smallest possible pieces of matter. Then physics did what it does best — it broke its own favorite idea.</p>\n<p>The detective in this first act is <strong>J.J. Thomson</strong>, working at Cambridge\'s Cavendish Laboratory. His evidence was the mysterious glow inside a <strong>cathode ray tube</strong> — a glass tube with most of the air pumped out and a high voltage across it. Something streamed from the negative electrode. But what?</p>\n<p>Thomson interrogated the rays the way a detective checks alibis:</p>\n<ul>\n  <li>They bent toward a positive plate — so they carried <strong>negative charge</strong>.</li>\n  <li>They also bent in a magnetic field — so they behaved like moving charged <strong>particles</strong>, not light.</li>\n  <li>By balancing electric against magnetic deflection, he measured their charge-to-mass ratio — and found something absurd: they were nearly <strong>2000 times lighter than a hydrogen atom</strong>, the lightest atom known.</li>\n</ul>\n<p>Most damning of all: he got the <em>same particle</em> no matter what metal the electrode was made of or what trace gas was in the tube. This wasn\'t a fragment of one element — it was a universal ingredient of <em>all</em> matter. The "uncuttable" atom had parts. Thomson had discovered the <strong>electron</strong>.</p>\n<div class="key-concept">\n  <h4>Key Concept: The Plum Pudding Model</h4>\n  <p>Atoms are electrically neutral, so if they contain negative electrons, positive charge must be hiding somewhere too. Thomson\'s guess: a diffuse ball of positive "pudding" with electron "plums" dotted through it. It was reasonable, it was testable — and as we\'re about to see, it was gloriously wrong.</p>\n</div>\n<div class="did-you-know">\n  <h4>Did you know?</h4>\n  <p>Thomson won the Nobel Prize for showing the electron is a particle. His son George later won one for showing electrons behave as <em>waves</em>. Both were right — a paradox Subject 15 will resolve.</p>\n</div>'},{id:"gold-foil",title:"The Gold-Foil Shock",content:"\n<p>Every good detective story has a twist nobody saw coming. Here it arrived in 1909, in the Manchester lab of <strong>Ernest Rutherford</strong>, when his assistants Hans Geiger and Ernest Marsden fired <strong>alpha particles</strong> — heavy, fast, positively charged projectiles from radioactive decay — at a sheet of gold foil just a few hundred atoms thick.</p>\n<p>The plum pudding model made a clear prediction. If an atom's positive charge is smeared out like pudding, an alpha particle should punch through like a cannonball through fog, deflecting by a fraction of a degree at most. And indeed, almost all of them did exactly that.</p>\n<p>But about <strong>1 in 8000</strong> bounced back toward the source.</p>\n<p>Rutherford's reaction became one of physics' most famous quotes: <em>\"It was almost as incredible as if you fired a 15-inch shell at a piece of tissue paper and it came back and hit you.\"</em> Fog cannot bounce a cannonball. Something small, heavy, and intensely charged had to be hiding inside the atom.</p>\n<p>Rutherford's deduction, published in 1911, rebuilt the atom from the evidence:</p>\n<ul>\n  <li>Nearly all the atom's mass and all its positive charge sit in a tiny central <strong>nucleus</strong>.</li>\n  <li>The electrons occupy the vast space around it.</li>\n  <li>The atom is therefore almost entirely <strong>empty space</strong> — which is why most alphas sailed straight through, while the rare head-on shot rebounded off the concentrated nucleus.</li>\n</ul>\n<div class=\"analogy\">\n  <h3>Analogy: A Fly in a Cathedral</h3>\n  <p>Scale an atom up to the size of a large cathedral and the nucleus is a fly hovering at the center — yet that fly holds about 99.97% of the atom's mass. Everything you have ever touched is, by volume, almost entirely nothing.</p>\n</div>\n<div class=\"did-you-know\">\n  <h4>Did you know?</h4>\n  <p>A typical nucleus is about 10,000 times smaller across than its atom. If atoms could be squeezed to pure nuclear density, all of humanity would fit in a sugar cube.</p>\n</div>"},{id:"bohr-model",title:"Bohr's Quantum Rescue",content:'\n<p>Rutherford\'s miniature solar system — electrons orbiting a nuclear "sun" — was beautiful, and it had a fatal flaw. You met the reason in the electricity and waves subjects: an accelerating charge radiates electromagnetic waves, and a circling electron is always accelerating. It should continuously broadcast away its energy and spiral into the nucleus in about a hundred-millionth of a microsecond. Classical physics predicted that <strong>atoms cannot exist</strong>. Since you are made of atoms and are currently reading this, something was missing.</p>\n<p>There was a second clue in the case file. When you pass an electric current through hydrogen gas, it glows — but not with a full rainbow. A prism reveals only a few sharp, specific colors: a <strong>line spectrum</strong>, like a barcode unique to each element. Why would an atom emit only those exact colors and nothing in between?</p>\n<p>In 1913 the young Danish physicist <strong>Niels Bohr</strong> made a move that felt like cheating: he simply postulated new rules.</p>\n<ol>\n  <li>Electrons may occupy only certain <strong>allowed orbits</strong>, each with a definite energy. In these orbits — against everything classical physics said — they do not radiate.</li>\n  <li>An electron can <strong>jump</strong> between orbits. Falling to a lower orbit releases the energy difference as a single flash of light whose color is fixed by that difference.</li>\n</ol>\n<p>Fixed energy rungs mean fixed jumps, which mean fixed colors — the barcode explained. Better still, Bohr\'s model predicted the hydrogen spectrum\'s wavelengths with stunning precision.</p>\n<div class="analogy">\n  <h3>Analogy: A Ladder, Not a Ramp</h3>\n  <p>A ball on a ramp can rest at any height; a person on a ladder can stand only on the rungs. Bohr replaced the ramp with a ladder: electron energy comes in discrete steps, and light is emitted only when stepping down a rung.</p>\n</div>\n<div class="key-concept">\n  <h4>Key Concept: A Brilliant Stepping Stone</h4>\n  <p>Bohr\'s model works quantitatively only for hydrogen, and electrons turn out not to follow neat circular paths at all. But its core idea — <strong>energy is quantized</strong> — survived and became the seed of quantum mechanics, the full story of Subject 15.</p>\n</div>'},{id:"protons-neutrons-isotopes",title:"The Full Cast: Protons, Neutrons & Isotopes",content:'\n<p>Two more discoveries completed the picture. In 1919 Rutherford showed that hydrogen nuclei — soon named <strong>protons</strong> — are building blocks of all nuclei. But protons alone couldn\'t explain atomic masses: helium has 2 protons yet weighs as much as 4 hydrogens. The missing piece stayed hidden until 1932, when James Chadwick found the <strong>neutron</strong>: a particle about as heavy as a proton but with <strong>no electric charge</strong>, which is exactly why it took so long to detect.</p>\n<table>\n  <thead>\n    <tr><th>Particle</th><th>Charge</th><th>Mass (vs proton)</th><th>Location</th></tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>Proton</strong></td><td>+1</td><td>1</td><td>Nucleus</td></tr>\n    <tr><td><strong>Neutron</strong></td><td>0</td><td>≈ 1</td><td>Nucleus</td></tr>\n    <tr><td><strong>Electron</strong></td><td>−1</td><td>≈ 1/1836</td><td>Around the nucleus</td></tr>\n  </tbody>\n</table>\n<p>Two numbers now describe any nucleus:</p>\n<ul>\n  <li><strong>Atomic number Z</strong> — the proton count. This defines the element and its chemistry: 6 protons is always carbon, 79 is always gold.</li>\n  <li><strong>Mass number A</strong> — protons plus neutrons, the total nucleon count. Carbon-14 means Z = 6, A = 14, so 8 neutrons.</li>\n</ul>\n<div class="key-concept">\n  <h4>Key Concept: Isotopes</h4>\n  <p>Atoms with the same number of protons but different numbers of neutrons are <strong>isotopes</strong> of one element. Carbon-12 and carbon-14 behave identically in chemical reactions — your body can\'t tell them apart — but their nuclei differ. Hydrogen has three: ordinary hydrogen (1 proton), deuterium (add 1 neutron), and tritium (add 2).</p>\n</div>\n<p>Why do neutrons matter so much? They act as nuclear glue-spacers, diluting the fierce electrical repulsion between protons. Get the proton–neutron balance wrong and the nucleus becomes <strong>unstable</strong> — it will sooner or later rearrange itself and spit out radiation. Carbon-12 is perfectly stable; carbon-14 is radioactive. That single word, <em>unstable</em>, is the doorway to the next chapter.</p>\n<div class="did-you-know">\n  <h4>Did you know?</h4>\n  <p>A free neutron outside a nucleus is itself unstable: on average it survives about 15 minutes before decaying. Inside a stable nucleus, it can last forever.</p>\n</div>'}],quiz:[{question:"What convinced Thomson that electrons are ingredients of all matter, not fragments of one element?",options:["Cathode rays only appeared when gold electrodes were used","Electrons were exactly as heavy as hydrogen atoms","He obtained identical particles regardless of the electrode metal or gas in the tube","The rays traveled in curved paths even with no fields applied"],correctIndex:2,explanation:"Thomson found the same charge-to-mass ratio no matter what material produced the rays. A particle that emerges identically from every substance must be a universal building block of atoms — and it was nearly 2000 times lighter than hydrogen."},{question:"In the gold-foil experiment, what observation destroyed the plum pudding model?",options:["A tiny fraction of alpha particles bounced almost straight back","All alpha particles were absorbed by the foil","The foil became positively charged","Every alpha particle deflected by exactly the same small angle"],correctIndex:0,explanation:"A diffuse 'pudding' of positive charge can only nudge a heavy, fast alpha particle. The rare violent rebounds (about 1 in 8000) proved the positive charge is concentrated in a tiny, massive nucleus — and that atoms are mostly empty space."},{question:"Why did classical physics say Rutherford's orbiting-electron atom was impossible?",options:["Electrons are too light to stay in orbit","The nucleus's neutrons would repel the electrons","Gravity between electron and nucleus is too weak","An orbiting electron accelerates, so it should radiate away its energy and spiral into the nucleus"],correctIndex:3,explanation:"Circular motion is accelerated motion, and accelerating charges emit electromagnetic waves. A classical orbiting electron would lose energy continuously and crash into the nucleus almost instantly. Bohr's fix: only certain orbits are allowed, and in them the electron simply does not radiate."},{question:"Carbon-12 and carbon-14 are isotopes. What do they share, and how do they differ?",options:["Same neutrons, different protons — so they are different elements","Same protons (6), different neutrons (6 vs 8) — identical chemistry, different nuclear stability","Same total mass, different charge","Same electrons, but carbon-14 has 14 protons"],correctIndex:1,explanation:"The proton count (Z = 6) defines carbon and fixes its chemistry, so isotopes are chemically identical. The neutron count differs — and that nuclear difference is why carbon-12 is stable while carbon-14 is radioactive."},{question:"How did Bohr's model explain why glowing hydrogen emits only a few sharp colors instead of a full rainbow?",options:["Hydrogen atoms filter out most colors from white light","The nucleus absorbs all wavelengths except a few","Electrons can only jump between fixed energy rungs, so only specific energy differences — specific colors — can be emitted","Electrons emit light continuously as they spiral inward"],correctIndex:2,explanation:"With quantized energy levels, an electron falling to a lower level releases exactly the energy difference as light of one definite color. Fixed rungs mean fixed jumps mean a line spectrum — each element's unique barcode."}]},{id:"radioactivity",title:"Radioactivity",subtitle:"Alpha, beta, gamma, and half-life — unstable nuclei and what their radiation can do",sections:[{id:"alpha-beta-gamma",title:"Three Rays from Broken Nuclei",content:'\n<p>An unstable nucleus is like an over-stressed spring: sooner or later it rearranges itself into something more stable, and the excess energy has to go somewhere. It leaves as <strong>radiation</strong>. When Rutherford sorted the emissions from radioactive materials, he found three distinct types and named them after the first three Greek letters.</p>\n<ul>\n  <li><strong>Alpha (α):</strong> a chunky package of 2 protons + 2 neutrons — literally a helium nucleus — ejected at high speed. Heavy and doubly charged, it barrels through matter ionizing everything nearby, exhausting itself within centimeters of air.</li>\n  <li><strong>Beta (β):</strong> a fast electron fired out of the nucleus. Strange but true — the nucleus contains no electrons. Instead, a neutron transforms into a proton and the electron is created in the act and flung out.</li>\n  <li><strong>Gamma (γ):</strong> not a particle of matter at all, but a pulse of electromagnetic energy — the same family as light and X-rays, only more energetic. It usually follows an α or β decay, as the rearranged nucleus sheds leftover energy.</li>\n</ul>\n<table>\n  <thead>\n    <tr><th>Type</th><th>What it is</th><th>Charge</th><th>Stopped by</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>α</td><td>Helium nucleus (2p + 2n)</td><td>+2</td><td>Paper, skin, a few cm of air</td></tr>\n    <tr><td>β</td><td>Fast electron</td><td>−1</td><td>A few mm of aluminium</td></tr>\n    <tr><td>γ</td><td>High-energy EM wave</td><td>0</td><td>Thick lead or concrete (reduced, never fully)</td></tr>\n  </tbody>\n</table>\n<div class="key-concept">\n  <h4>Key Concept: Decay Changes the Element</h4>\n  <p>α and β decay alter the proton count — and the proton count <em>is</em> the element. Radium (88 protons) emits an α and becomes radon (86 protons). This is genuine transmutation: nature performs the alchemy medieval alchemists dreamed of, one nucleus at a time.</p>\n</div>\n<div class="did-you-know">\n  <h4>Did you know?</h4>\n  <p>Penetrating power and danger are not the same thing. Alpha is stopped by your skin\'s dead outer layer — but if an alpha emitter is <em>inhaled or swallowed</em>, all that ionizing punch lands on living tissue. That\'s why radon gas seeping into basements is the largest natural radiation risk in many countries.</p>\n</div>'},{id:"half-life",title:"Half-Life: Predictable Unpredictability",content:'\n<p>Here is the strangest fact in this chapter: it is <strong>impossible, even in principle,</strong> to predict when one particular unstable nucleus will decay. It has no age, no wear, no warning signs. A carbon-14 nucleus that has existed for 10,000 years is no more "due" than one created this morning. Decay is genuinely random.</p>\n<p>And yet radioactive decay is one of the most precisely predictable processes in nature. How can both be true? <strong>Statistics.</strong> You can\'t predict one coin flip, but flip a million coins and you can bet confidently on very close to half a million heads. Nuclei play the same game: each one has a fixed <em>probability</em> of decaying in a given time, so a large population shrinks on a perfectly reliable schedule.</p>\n<div class="key-concept">\n  <h4>Key Concept: Half-Life</h4>\n  <p>The <strong>half-life</strong> is the time for half of any sample to decay. Whatever amount you start with, one half-life later half remains; another half-life, a quarter; another, an eighth. The clock never resets and never runs out — you halve, and halve, and halve.</p>\n</div>\n<p>No formulas needed yet — just halving arithmetic. Start with 1000 atoms of a substance with an 8-day half-life:</p>\n<table>\n  <thead>\n    <tr><th>Time</th><th>Half-lives</th><th>Atoms left</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>0 days</td><td>0</td><td>1000</td></tr>\n    <tr><td>8 days</td><td>1</td><td>500</td></tr>\n    <tr><td>16 days</td><td>2</td><td>250</td></tr>\n    <tr><td>24 days</td><td>3</td><td>125</td></tr>\n    <tr><td>32 days</td><td>4</td><td>≈ 63</td></tr>\n  </tbody>\n</table>\n<p>Half-lives span an absurd range: polonium-214 lasts a ten-thousandth of a second; iodine-131 (a medical isotope) 8 days; carbon-14 about 5,700 years; uranium-238 about 4.5 <em>billion</em> years — which is exactly why uranium is still around from Earth\'s formation, and why comparing uranium to its decay products lets geologists date the Earth itself.</p>\n<div class="analogy">\n  <h3>Analogy: Popcorn</h3>\n  <p>Watch one kernel and you cannot say when it will pop. Watch the whole pot and the popping follows a smooth, reliable pattern. Individual randomness, collective predictability — that\'s radioactivity. (The exponential decay law behind this gets its full quantitative treatment in Subject 15.)</p>\n</div>'},{id:"try-it-dice",title:"Try It Yourself: Decay in a Dice Cup",content:'\n<p>You can hold a "radioactive sample" in your hands tonight — no radiation required. All you need is randomness with a fixed probability, and coins or dice provide exactly that. Each coin is a nucleus; each shake is a tick of the clock; heads means "decayed."</p>\n<div class="key-concept">\n  <h4>Try It Yourself: The Coin-Flip Nucleus</h4>\n  <p><strong>You need:</strong> about 100 coins (or 50 — it still works) and a box with a lid.</p>\n  <ol>\n    <li>Put all coins in the box. Shake, open, and remove every coin showing <strong>heads</strong> — those nuclei have decayed.</li>\n    <li>Count and write down how many "undecayed" coins remain.</li>\n    <li>Repeat shaking and removing until fewer than ~5 coins survive.</li>\n    <li>Plot coins remaining vs. shake number.</li>\n  </ol>\n  <p>Each coin has a 1-in-2 chance of decaying per shake, so the half-life is <strong>1 shake</strong>: expect roughly 100 → 50 → 25 → 12 → 6 → 3.</p>\n</div>\n<p><strong>Dice variant (longer half-life):</strong> use dice and remove only the ones showing a <strong>six</strong>. Now each "nucleus" has just a 1-in-6 chance of decaying per throw, so the population shrinks more gently — it takes about 3.8 throws to lose half. Same physics, different decay constant.</p>\n<p>Three things to notice as you play:</p>\n<ul>\n  <li><strong>Your numbers won\'t be perfect.</strong> You might get 54 survivors, then 22. Real Geiger-counter data is jittery in exactly the same way — randomness guarantees scatter around the trend.</li>\n  <li><strong>The curve never hits zero on schedule.</strong> Halving 6 gives 3, then 1 or 2 stubborn survivors linger. A few long-lived nuclei always remain, which is why "when is it all gone?" is the wrong question and "what\'s the half-life?" is the right one.</li>\n  <li><strong>No coin remembers.</strong> A coin that survived ten shakes still has exactly a 1-in-2 chance next shake. Nuclei don\'t age — they only gamble.</li>\n</ul>\n<div class="did-you-know">\n  <h4>Did you know?</h4>\n  <p>Pool results with friends and the combined curve gets noticeably smoother. That\'s the statistics of large numbers in action — and precisely why a gram of material with its trillions of trillions of nuclei decays with clockwork regularity.</p>\n</div>'},{id:"detection-safety-uses",title:"Detecting the Invisible — and Putting It to Work",content:'\n<p>Radiation is invisible, silent, and odorless, so every fact in this chapter depended on instruments. The classic is the <strong>Geiger–M\xfcller tube</strong>: a gas-filled tube with a high voltage across it. A single particle of radiation entering the tube ionizes gas atoms, triggering an avalanche of charge — one audible <em>click</em> per particle. Cloud chambers make particle tracks visible as delicate vapor trails (you can build one with dry ice and alcohol), and workers wear <strong>film badges or electronic dosimeters</strong> that tally their accumulated dose.</p>\n<p>Turn on a Geiger counter anywhere and it clicks. This is <strong>background radiation</strong>: radon gas from rocks and soil, cosmic rays from space, traces of radioactive potassium in bananas, Brazil nuts — and in you. Radioactivity is not a human invention; it is a permanent feature of nature. The sensible question is never "is there radiation?" but "<strong>how much, compared to background?</strong>"</p>\n<p>Handled with respect, radioactivity is spectacularly useful:</p>\n<ul>\n  <li><strong>Smoke detectors:</strong> a speck of americium-241 ionizes air; smoke disrupts the tiny current and trips the alarm.</li>\n  <li><strong>Carbon dating:</strong> living things constantly refresh their carbon-14; death stops the intake, and the 5,700-year half-life clock starts. Comparing remaining \xb9⁴C to the expected level dates bones, wood, and cloth tens of thousands of years back.</li>\n  <li><strong>Medicine:</strong> gamma-emitting tracers like technetium-99m (half-life 6 hours — long enough to image, short enough to vanish) light up organs from inside; focused radiotherapy beams destroy tumors.</li>\n  <li><strong>Sterilization:</strong> gamma rays sterilize medical instruments and food without heat.</li>\n</ul>\n<div class="key-concept">\n  <h4>Key Concept: Time, Distance, Shielding</h4>\n  <p>All radiation safety reduces to three moves: minimize <strong>time</strong> near a source, maximize <strong>distance</strong> (intensity falls with the square of distance — the same 1/r\xb2 law as light), and put <strong>shielding</strong> between you and it. Also keep two ideas separate: <em>irradiation</em> (being exposed to rays, which stops when you walk away) and <em>contamination</em> (radioactive material on or in you, which keeps emitting until removed).</p>\n</div>\n<div class="did-you-know">\n  <h4>Did you know?</h4>\n  <p>A typical chest X-ray delivers about the same dose as a few days of ordinary background radiation, and a long-haul flight (thinner atmosphere, more cosmic rays) is comparable. Context turns scary-sounding numbers into informed decisions.</p>\n</div>'}],quiz:[{question:"Which correctly ranks the three radiation types from least to most penetrating?",options:["Gamma, beta, alpha","Alpha, beta, gamma","Beta, alpha, gamma","Alpha, gamma, beta"],correctIndex:1,explanation:"Heavy, doubly charged alpha particles ionize furiously and stop in paper or skin; betas need a few millimeters of aluminium; uncharged gamma rays need thick lead or concrete and are only ever reduced, never completely blocked."},{question:"A sample contains 800 atoms of an isotope with a half-life of 6 hours. About how many remain after 24 hours?",options:["400","200","0","50"],correctIndex:3,explanation:"24 hours is 4 half-lives. Halve four times: 800 → 400 → 200 → 100 → 50. Notice the sample is never scheduled to hit zero — it just keeps halving."},{question:"Why is it impossible to predict when a single nucleus will decay, yet possible to date ancient bones with carbon-14?",options:["Individual decay is random, but huge populations follow reliable halving statistics","Nuclei weaken with age, and old nuclei decay faster","Carbon-14 decays at a steady rate only inside living tissue","Decay is predictable for single nuclei but random for large samples"],correctIndex:0,explanation:"Each nucleus only has a fixed probability of decaying per unit time — like a coin flip, individually unpredictable. But a bone contains vast numbers of \xb9⁴C nuclei, so the fraction remaining tracks elapsed half-lives with statistical precision. Nuclei do not age or weaken."},{question:"Why can an alpha-emitting substance be nearly harmless in a sealed smoke detector yet dangerous if inhaled as dust?",options:["Alpha particles only become active in the lungs","Inhaling it converts the alpha emitter into a gamma emitter","Alpha barely penetrates — skin or casing stops it, but inhaled, it delivers intense ionization directly to living tissue","Smoke detectors use a special non-radioactive form of americium"],correctIndex:2,explanation:"Penetrating power and danger are different things. Alpha's short range means external exposure is stopped by dead skin or the detector housing — but the same heavy ionizing punch, released inside the lungs, damages living cells at point-blank range. This is also why radon gas matters."},{question:"In your coin-flip decay simulation, a coin has survived ten shakes in a row. What is its chance of 'decaying' on the next shake?",options:["Much higher than 1 in 2 — it is overdue","Exactly 1 in 2, the same as always","Much lower than 1 in 2 — it has proven itself stable","Exactly zero — survivors are permanently stable"],correctIndex:1,explanation:"Coins — and nuclei — have no memory. The decay probability per time step never changes, no matter how long the particle has survived. This 'memorylessness' is precisely what produces the halving pattern of half-life."}]},{id:"nuclear-energy",title:"Nuclear Energy",subtitle:"Fission, fusion, and reactors — the enormous energy locked inside the nucleus",sections:[{id:"mass-energy",title:"The Missing Mass",content:'\n<p>Weigh a helium nucleus and something bizarre shows up: it is about <strong>0.7% lighter</strong> than the two protons and two neutrons that make it. Assemble the parts, and mass goes missing. Where did it go?</p>\n<p>Einstein answered in 1905 with the most famous equation in science: <strong>E = mc\xb2</strong>. Mass and energy are two forms of the same thing, exchangeable at the rate of c\xb2 — the speed of light squared. When nucleons bind together, they settle into a lower-energy arrangement, and the released energy carries the missing mass away with it. The mass deficit <em>is</em> the binding energy, on Einstein\'s exchange rate.</p>\n<p>And what an exchange rate. Because c ≈ 300,000,000 m/s, c\xb2 is a colossal number: <strong>one gram of mass converts to about 90 trillion joules</strong> — roughly the energy released by 20,000 tonnes of TNT, or a large city\'s electricity for a day, packed into a paperclip\'s worth of matter.</p>\n<div class="key-concept">\n  <h4>Key Concept: Why Nuclear Beats Chemical a Million to One</h4>\n  <p>Chemical reactions (burning coal, digesting lunch) rearrange <em>electrons</em>, releasing a few electron-volts per atom. Nuclear reactions rearrange <em>nucleons</em>, gripped by the far stronger nuclear force, releasing <em>millions</em> of electron-volts per nucleus. That factor of about a million is why a fuel pellet the size of a fingertip matches the energy of a tonne of coal.</p>\n</div>\n<p>One more idea unlocks both halves of this chapter. Nuclei are not all equally tightly bound. Plot binding-per-nucleon across the elements and it rises steeply through the light elements, peaks around <strong>iron</strong>, then gently declines toward uranium. Iron sits at the bottom of the energy valley — the most contented nucleus in nature. That shape means there are <em>two</em> directions to release energy:</p>\n<ul>\n  <li><strong>Split a very heavy nucleus</strong> into middleweight pieces closer to iron — <strong>fission</strong>.</li>\n  <li><strong>Merge very light nuclei</strong> into heavier ones closer to iron — <strong>fusion</strong>.</li>\n</ul>\n<div class="did-you-know">\n  <h4>Did you know?</h4>\n  <p>E = mc\xb2 works in reverse for chemistry too — a charged phone battery is heavier than a dead one. But the difference is around a billionth of a gram, hopelessly beyond any scale. Only nuclear energies make the mass change measurable.</p>\n</div>'},{id:"fission",title:"Fission: Splitting the Giant",content:'\n<p>In December 1938, Otto Hahn and Fritz Strassmann bombarded uranium with neutrons and found, to their bafflement, <em>barium</em> — an element barely half uranium\'s size — in the debris. Lise Meitner and her nephew Otto Frisch, working through the physics over a snowy Christmas walk, realized the unthinkable: the neutron had split the uranium nucleus roughly in half. Frisch borrowed a term from cell biology: <strong>fission</strong>.</p>\n<p>Here\'s the picture. A uranium-235 nucleus is a bloated giant, 92 mutually repelling protons barely held together. A slow neutron drifting in is like a pebble hitting an overfilled water balloon: the nucleus wobbles, stretches, and electrical repulsion tears it into two middleweight fragments, releasing about <strong>200 million electron-volts</strong> per split — tens of millions of times the energy of any chemical reaction.</p>\n<p>But the detail that changed history is this: each fission also flings out <strong>two or three fresh neutrons</strong>.</p>\n<div class="key-concept">\n  <h4>Key Concept: The Chain Reaction</h4>\n  <p>If, on average, at least one released neutron triggers another fission, the reaction feeds itself. One split becomes 2, then 4, 8, 16 — your halving arithmetic from last chapter running in reverse, as doubling. In a power reactor the chain is held at exactly <strong>one</strong> new fission per fission: steady output. A bomb is engineered for runaway doubling in a sphere of highly enriched material. Same physics, profoundly different machines.</p>\n</div>\n<p>Whether a chain sustains depends on the competition between neutrons causing fission and neutrons escaping or being absorbed. Too small a lump leaks too many neutrons from its surface; past the <strong>critical mass</strong>, the chain can sustain itself.</p>\n<p>One subtlety matters enormously for the next section: natural uranium is over 99% uranium-238, which mostly swallows neutrons without splitting. Only the rare isotope <strong>uranium-235 (about 0.7%)</strong> fissions readily. Reactor fuel is enriched to just 3–5% U-235 — which is why a power reactor <em>physically cannot</em> explode like a nuclear bomb, no matter how badly its day is going. Bomb material requires around 90% enrichment, an enormous industrial undertaking.</p>\n<div class="did-you-know">\n  <h4>Did you know?</h4>\n  <p>Fission fragments are typically radioactive isotopes with half-lives from seconds to centuries — this is reactor waste, and we\'ll weigh it honestly in the next section. Meitner, who first explained fission, was excluded from the Nobel Prize awarded to Hahn; element 109, meitnerium, now carries her name.</p>\n</div>'},{id:"fusion",title:"Fusion: How Stars Do It",content:'\n<p>Walk the binding-energy valley the other way. Merge light nuclei into heavier ones and the payoff is even richer, gram for gram, than fission: <strong>fusing hydrogen into helium releases roughly four times more energy per kilogram</strong> than splitting uranium. This is the engine of the universe. Every second, the Sun fuses about 600 million tonnes of hydrogen into helium, converting around 4 million tonnes of mass directly into sunshine — and has done so for 4.6 billion years. Every element in your body heavier than hydrogen was forged by fusion inside a star. You are, quite literally, recycled starfire.</p>\n<p>So why don\'t we have fusion power plants already? Because fusion has a ferocious entry fee. Nuclei are positively charged, and the electric force pushes them apart harder the closer they get. The strong nuclear force only grabs hold at nearly point-blank range. To slam nuclei together fast enough, the fuel must reach temperatures around <strong>100–150 million \xb0C</strong> — ten times hotter than the Sun\'s core (the Sun compensates with crushing gravitational pressure and colossal patience; we can\'t).</p>\n<p>At those temperatures matter is a <strong>plasma</strong> — a gas of bare nuclei and electrons — and no material container can touch it. Two main strategies exist:</p>\n<ul>\n  <li><strong>Magnetic confinement:</strong> cage the charged plasma in a doughnut of magnetic fields (a <em>tokamak</em>, like the international ITER project) — using the same "magnetic force on moving charges" physics you met in Subject 8.</li>\n  <li><strong>Inertial confinement:</strong> crush a peppercorn-sized fuel pellet with the world\'s most powerful lasers. In December 2022, the US National Ignition Facility achieved <em>ignition</em> — fusion output exceeding the laser energy delivered to the target — a genuine first, though still far from a power plant.</li>\n</ul>\n<div class="key-concept">\n  <h4>Key Concept: Why Fusion Is Worth the Struggle</h4>\n  <p>Fusion fuel (deuterium from seawater, tritium bred from lithium) is effectively inexhaustible. There is no chain reaction to run away — any disturbance and the plasma simply fizzles out. And it produces no long-lived high-level waste. The physics works; the remaining battle is engineering a machine that produces more electricity than it consumes, reliably, for decades.</p>\n</div>\n<div class="did-you-know">\n  <h4>Did you know?</h4>\n  <p>The deuterium in an average bathtub of seawater holds fusion energy equivalent to burning about 40 tonnes of coal. The fuel is not the problem — the container is.</p>\n</div>'},{id:"reactors-risk",title:"Reactors: Taming the Chain — and Weighing the Risks",content:'\n<p>A nuclear power station is, at heart, a very exotic kettle: fission heat boils water, steam spins a turbine, the turbine spins a generator — the same electromagnetic induction you met in Subject 8. The nuclear part is about keeping the chain reaction at exactly steady state:</p>\n<ul>\n  <li><strong>Fuel rods:</strong> pellets of enriched uranium oxide stacked in metal tubes.</li>\n  <li><strong>Moderator</strong> (usually water): slows fast neutrons, because slow neutrons split U-235 far more effectively — counterintuitive but decisive.</li>\n  <li><strong>Control rods</strong> (boron, cadmium): neutron absorbers raised and lowered to hold the chain at exactly one fission per fission; fully inserted, they shut the reactor down.</li>\n  <li><strong>Coolant</strong> carries heat to the steam loop; a massive steel-and-concrete <strong>containment building</strong> encloses everything.</li>\n</ul>\n<p>Now the honest ledger. <strong>The risks are real.</strong> Chernobyl (1986) — a flawed Soviet design with no containment, run outside its safe envelope — killed plant workers and firefighters directly and released contamination across Europe; the UN-linked scientific estimates put eventual attributable cancer deaths in the low thousands. Fukushima (2011) melted down after a tsunami overwhelmed its seawalls; radiation deaths were essentially zero, though the chaotic evacuation itself cost lives and displaced over 100,000 people. Reactor waste stays hazardous for many millennia and, while its volume is tiny, several countries have only now begun opening permanent deep repositories. Plants are also slow and expensive to build.</p>\n<p><strong>The benefits are real too.</strong> Nuclear delivers carbon-free electricity around the clock, independent of weather, from astonishingly little fuel and land. Counting all accidents, nuclear power\'s death rate per unit of electricity is on par with wind and solar — and hundreds of times lower than the coal it often replaces, whose air pollution kills quietly but continuously.</p>\n<div class="key-concept">\n  <h4>Key Concept: Compare Risks to Alternatives, Not to Zero</h4>\n  <p>Every energy source has a body count and a footprint; "perfectly safe" is not on the menu. The rational question is never "is nuclear risky?" but "risky <em>compared to what</em>?" Fear responds to vivid, concentrated accidents; data also counts the diffuse, invisible harms of everyday combustion. The next chapter puts numbers on all of it.</p>\n</div>\n<div class="did-you-know">\n  <h4>Did you know?</h4>\n  <p>Coal ash from a coal plant carries trace uranium and thorium into the environment — a typical coal station releases <em>more</em> radioactivity in normal operation than a normally operating nuclear plant.</p>\n</div>'}],quiz:[{question:"A helium nucleus weighs measurably less than its two protons and two neutrons weighed separately. Why?",options:["Some protons convert into weightless neutrons during assembly","The electrons orbiting the nucleus cancel part of its mass","Measurement error — the masses are actually identical","Binding released energy, and by E = mc\xb2 that energy carried mass away"],correctIndex:3,explanation:"Bound nucleons sit in a lower-energy arrangement than free ones. The energy released on binding is the mass deficit times c\xb2 — mass and energy are interchangeable, and c\xb2 is so large that tiny mass changes represent enormous energies."},{question:"What makes a fission chain reaction possible in uranium-235?",options:["Each fission releases 2–3 fresh neutrons that can trigger further fissions","Uranium spontaneously splits when warmed","The fission fragments themselves collide and split other nuclei","Gamma rays from one fission split neighboring nuclei"],correctIndex:0,explanation:"The self-sustaining loop is neutrons: each split ejects 2–3 of them. If at least one, on average, causes another fission, the reaction continues — held at exactly one per fission in a reactor, allowed to double runaway-style in a bomb."},{question:"Why does fusion require temperatures of around 100 million \xb0C when fission works at ordinary temperatures?",options:["Fusion fuel is frozen and must first be melted","Heat is needed to break the light nuclei apart before rejoining them","Positively charged nuclei repel; only at extreme speeds can they get close enough for the nuclear force to fuse them","The plasma must glow brightly enough to sustain the reaction"],correctIndex:2,explanation:"Fission is triggered by neutrons, which have no charge and enter the nucleus freely. Fusion must slam two positive nuclei together against their fierce electrical repulsion, which requires the colossal collision speeds of a 100-million-degree plasma."},{question:"Why can a nuclear power reactor not explode like a nuclear bomb?",options:["Control rods react faster than any explosion could develop","Its fuel is only 3–5% U-235 — far below the ~90% enrichment a bomb's runaway chain requires","The water coolant would extinguish any nuclear explosion","Reactors contain no uranium, only plutonium"],correctIndex:1,explanation:"A bomb needs highly enriched material so the chain reaction can double explosively fast. Reactor-grade fuel is diluted with neutron-absorbing U-238; the worst physical failure is a meltdown — genuinely serious, but a different phenomenon from a nuclear detonation."},{question:"Which statement best reflects an honest, data-driven view of nuclear power's safety record?",options:["Counting all accidents, its deaths per unit of electricity are comparable to wind and solar, and far below coal","Nuclear power has never harmed anyone","Nuclear accidents make it the deadliest energy source per unit of electricity","Its risks cannot be compared with other energy sources"],correctIndex:0,explanation:"Chernobyl and Fukushima were real disasters with real costs — and even including them, nuclear's death toll per terawatt-hour is on par with renewables and hundreds of times below coal, whose air pollution kills continuously but invisibly. Rational risk assessment compares to alternatives, not to zero."}]},{id:"energy-and-society",title:"Energy & Society",subtitle:"Energy resources, renewables, and the physics behind humanity's biggest decisions",sections:[{id:"world-energy-bill",title:"The World's Energy Bill",content:'\n<p>Before debating how to power civilization, a physicist asks: how big is the job? Humanity\'s primary energy consumption runs at roughly <strong>180,000 terawatt-hours per year</strong> — a continuous average power draw of about <strong>20 terawatts</strong>, or 20 trillion joules every second, day and night.</p>\n<p>Numbers that size mean nothing until scaled to a person. Divide by 8 billion people and the global average is about <strong>2,500 watts per person</strong>, around the clock — as if 25 old 100 W light bulbs burned continuously on your behalf. That is not mostly your phone and lights; it is your share of factories, fertilizer, freight, steel, cement, heating, and flights. The average is also wildly uneven: a typical American draws roughly 9,000 W, a typical European 4,000–5,000 W, and hundreds of millions of people get by on a few hundred.</p>\n<p>Where does it currently come from?</p>\n<table>\n  <thead>\n    <tr><th>Source</th><th>Share of world primary energy (approx.)</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Oil</td><td>≈ 30%</td></tr>\n    <tr><td>Coal</td><td>≈ 26%</td></tr>\n    <tr><td>Natural gas</td><td>≈ 23%</td></tr>\n    <tr><td>Hydropower</td><td>≈ 6%</td></tr>\n    <tr><td>Nuclear</td><td>≈ 4%</td></tr>\n    <tr><td>Wind, solar &amp; other renewables</td><td>≈ 8% and climbing fast</td></tr>\n  </tbody>\n</table>\n<p>Read the top three rows together: <strong>about four-fifths of civilization still runs on burning fossil carbon</strong>. That single fact frames the entire energy debate.</p>\n<div class="key-concept">\n  <h4>Key Concept: Energy Is Never "Used Up"</h4>\n  <p>The conservation law that has anchored every subject since Phase 1 still rules here. We don\'t consume energy; we <em>degrade</em> it — from concentrated chemical or nuclear form into disordered waste heat. What civilization actually consumes is <strong>useful, ordered energy</strong>, and roughly two-thirds of the energy in our fuels is lost as waste heat before doing anything useful. Efficiency is a genuine energy resource.</p>\n</div>\n<div class="did-you-know">\n  <h4>Did you know?</h4>\n  <p>A fit human on a bicycle generator can sustain about 100 W. Your 2,500 W global-average share would take 25 full-time human cyclists — which is why cheap energy, historically, is what replaced human and animal muscle.</p>\n</div>'},{id:"comparing-contenders",title:"Comparing the Contenders — with Data",content:'\n<p>Energy debates run hot on slogans and cold on numbers. Physics offers a better way: put every source on the same table and compare like with like. Three metrics do most of the work — climate impact per kilowatt-hour, safety per terawatt-hour, and reliability (what fraction of the time the source actually delivers).</p>\n<table>\n  <thead>\n    <tr><th>Source</th><th>CO₂ (g per kWh, lifecycle)</th><th>Deaths per TWh (accidents + pollution)</th><th>Typical capacity factor</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>Coal</td><td>≈ 820</td><td>≈ 25</td><td>≈ 50%</td></tr>\n    <tr><td>Natural gas</td><td>≈ 490</td><td>≈ 3</td><td>≈ 55%</td></tr>\n    <tr><td>Hydro</td><td>≈ 24</td><td>≈ 1.3</td><td>≈ 40%</td></tr>\n    <tr><td>Solar</td><td>≈ 40</td><td>≈ 0.02</td><td>≈ 15–25%</td></tr>\n    <tr><td>Wind</td><td>≈ 11</td><td>≈ 0.04</td><td>≈ 25–40%</td></tr>\n    <tr><td>Nuclear</td><td>≈ 12</td><td>≈ 0.03</td><td>≈ 90%</td></tr>\n  </tbody>\n</table>\n<p>Reading the table honestly cuts against several popular intuitions:</p>\n<ul>\n  <li><strong>Coal is the outlier, and not in a good way</strong> — the highest emissions <em>and</em> a death rate hundreds of times worse than nuclear, wind, or solar, mostly through the slow grind of air pollution rather than dramatic accidents. A terawatt-hour is roughly one hour of electricity for a country of moderate size; coal\'s ≈ 25 deaths for each one add up to millions of early deaths from fossil air pollution worldwide every year.</li>\n  <li><strong>Nuclear, wind, and solar cluster together</strong> at the clean, safe end — including Chernobyl and Fukushima in nuclear\'s ledger. The data refuse to match the fear rankings.</li>\n  <li><strong>Hydro\'s average hides a skew:</strong> it is very safe per dam, but a single catastrophe (the 1975 Banqiao dam failure in China killed tens of thousands) dominates its statistics.</li>\n  <li><strong>Capacity factor is the honest fine print.</strong> A solar farm\'s "100 MW" nameplate delivers 15–25% of that on average — night and clouds are facts of physics. Nuclear\'s ≈ 90% is the reliability benchmark.</li>\n</ul>\n<div class="key-concept">\n  <h4>Key Concept: Every Choice Is a Trade-off</h4>\n  <p>No column wins everything. Gas is dispatchable but carbon-heavy; solar is safe and clean but intermittent and land-hungry; nuclear is reliable and clean but slow and costly to build, with long-lived waste. Adult energy policy means choosing trade-offs with open eyes — not pretending some option is free.</p>\n</div>\n<div class="did-you-know">\n  <h4>Did you know?</h4>\n  <p>These figures come from lifecycle studies aggregated by projects like Our World in Data — they count mining, construction, fuel, operation, and disposal, not just the smokestack. Always ask what a favorable-sounding energy number leaves out.</p>\n</div>'},{id:"renewables-physics",title:"The Physics of Renewables",content:"\n<p>Renewables all cash the same check: energy income from the Sun (directly, or laundered through wind and rain) rather than drawing down Earth's fossil savings account. Each comes with physics that sets hard limits — and knowing them separates real plans from wishful thinking.</p>\n<ul>\n  <li><strong>Solar:</strong> sunlight delivers about <strong>1,000 W per square meter</strong> at noon on a clear day. Commercial panels convert around 20%, so figure ≈ 200 W/m\xb2 at peak and, after night, clouds, and seasons, an average of 10–40 W/m\xb2. The resource is stupendous — the Sun sends Earth more energy in about an hour than humanity uses in a year — but it is <em>dilute</em>, so collecting terawatts takes serious area.</li>\n  <li><strong>Wind:</strong> a turbine harvests the kinetic energy of moving air, and the available power scales as <strong>wind speed cubed</strong> — double the wind, eight times the power. That cube is why offshore sites with steady strong winds are gold, and why calm days matter so much. A hard theorem (the Betz limit) caps any turbine at 59% of the wind's power; good modern machines reach about 45%.</li>\n  <li><strong>Hydro:</strong> gravitational potential energy, mgh, of rain that the Sun lifted uphill. Dense, dispatchable, and proven — but most of the world's best river sites are already dammed, so hydro grows slowly.</li>\n</ul>\n<p>The deepest challenge is not generation but <strong>timing</strong>. Demand peaks on winter evenings; solar peaks at summer noon; wind blows on its own schedule. A reliable grid needs storage (batteries for hours; pumped hydro — pumping water uphill to replay the mgh trick later — still holds most of the world's stored electricity), long transmission lines to average weather over continents, and dispatchable partners for dark, still weeks.</p>\n<div class=\"analogy\">\n  <h3>Analogy: Salary vs. Savings</h3>\n  <p>Fossil fuels are an inheritance: concentrated, spendable any time, but finite and with a cleanup bill attached. Renewables are a salary: arriving forever, but on a schedule you don't control. Living on salary requires a buffer account — that's what storage is.</p>\n</div>\n<div class=\"did-you-know\">\n  <h4>Did you know?</h4>\n  <p>The price of solar electricity fell about <strong>90% between 2010 and 2020</strong>, making new solar the cheapest electricity in history across much of the world. Engineering-driven cost curves, not physics, were the real barrier — and they moved.</p>\n</div>"},{id:"energy-future",title:"Choosing the Energy Future",content:'\n<p>Sustainability, stripped of buzzwords, is a physics question: <strong>can this continue?</strong> Fossil fuels fail the test twice. They are finite — concentrated solar energy banked by geology over hundreds of millions of years, being spent in a few centuries. And burning them moves carbon from underground into the atmosphere, where CO₂ has climbed from about 280 ppm before the industrial era past <strong>420 ppm</strong> today, strengthening the greenhouse effect you met in the thermal physics subject. The physics of that warming is not controversial; what to do about it is where the real debate lives.</p>\n<p>What does the evidence suggest? A few load-bearing conclusions:</p>\n<ul>\n  <li><strong>There is no silver bullet.</strong> Every source carries trade-offs, so credible plans are <em>portfolios</em>: cheap solar and wind doing bulk work, storage and transmission smoothing their schedule, firm low-carbon sources — hydro, nuclear, geothermal, perhaps one day fusion — carrying dark, still weeks.</li>\n  <li><strong>Efficiency is the quiet giant.</strong> Since roughly two-thirds of primary energy is lost as waste heat, better insulation, heat pumps, LEDs, and electric drivetrains (≈ 90% efficient vs ≈ 25% for combustion engines) deliver the same civilization for far less energy. Engineers call efficiency "the first fuel."</li>\n  <li><strong>Scale honestly.</strong> Replacing a 20-terawatt fossil habit is a decades-long industrial project measured in thousands of plants and millions of turbines — which is an argument for starting seriously, not for despairing.</li>\n</ul>\n<div class="key-concept">\n  <h4>Key Concept: Back-of-Envelope Citizenship</h4>\n  <p>You now own the toolkit this entire first pass was building toward. When a headline claims some gadget will "power a million homes," you can check it: a home draws ≈ 1 kW on average, so that claim means a steady gigawatt — one large power station\'s output. Numbers beat slogans. Demand the numbers.</p>\n</div>\n<p>And with that, your first full tour of physics is complete — from pushing a shopping cart in Subject 1 to weighing civilization\'s energy budget here, with one idea running through it all: <strong>energy is conserved, only transformed</strong>. Phase 3 starts the second pass, with vectors and calculus-grade tools that turn today\'s intuitions into precise calculations — including, in Subject 15, the exponential decay law and binding energies we promised.</p>\n<div class="did-you-know">\n  <h4>Did you know?</h4>\n  <p>In several countries, solar and wind already supply over 40% of annual electricity — a share considered impossible by many experts two decades ago. Energy systems can change faster than conventional wisdom expects, when physics and economics finally point the same way.</p>\n</div>'}],quiz:[{question:"Humanity's average primary energy use is roughly 2,500 W per person. What does that figure mostly represent?",options:["Household electricity for lights and devices","The power of each person's car engine","Each person's share of everything — industry, transport, agriculture, heating — running continuously","Energy lost only through body heat"],correctIndex:2,explanation:"The 2,500 W is total civilization power divided by population: your slice of steel mills, fertilizer plants, freight, heating, and flights, averaged around the clock. Personal electricity is only a modest fraction — which is why energy policy is about far more than switching off lights."},{question:"Per terawatt-hour of electricity, which comparison does the safety data actually support?",options:["Nuclear is by far the deadliest source because of its accidents","Coal causes hundreds of times more deaths than nuclear, wind, or solar","All sources have roughly equal death rates","Hydro is the deadliest source in ordinary operation"],correctIndex:1,explanation:"Coal's ≈ 25 deaths per TWh — mostly from air pollution's slow, invisible toll — dwarf the ≈ 0.02–0.04 of nuclear, wind, and solar, even with Chernobyl and Fukushima counted. Vivid accidents dominate headlines; diffuse everyday harm dominates the statistics."},{question:"Why does doubling the wind speed matter so much to a wind turbine?",options:["It doubles the power output","It quadruples the power output","It has little effect — turbines cap output at all speeds","Available power scales with speed cubed, so it increases eightfold"],correctIndex:3,explanation:"Wind power scales as v\xb3: twice the speed carries 2\xb3 = 8 times the power. This cube law is why steady, strong offshore winds are so valuable and why output collapses on calm days — the physics behind wind's intermittency."},{question:"A '100 MW' solar farm has a capacity factor of about 20%. What does that mean in practice?",options:["It averages about 20 MW over the year, because of night, clouds, and seasons","It delivers 100 MW continuously, day and night","Only 20% of its panels function at any time","It converts 20% of its electricity into waste heat"],correctIndex:0,explanation:"Nameplate capacity is peak output under ideal sun. Averaged over nights, weather, and seasons, a 20% capacity factor means ≈ 20 MW of continuous-equivalent power. Comparing sources by nameplate alone is one of the commonest errors in energy debates — always ask for the capacity factor."},{question:"Why do engineers call energy efficiency 'the first fuel'?",options:["Efficient devices generate their own energy","Efficiency was historically the earliest energy source","It only applies to fossil-fuel power stations","Since about two-thirds of primary energy becomes waste heat, cutting losses supplies 'new' useful energy without building anything that generates it"],correctIndex:3,explanation:"Energy is conserved but degrades to waste heat; civilization actually runs on the useful fraction. Heat pumps, insulation, LEDs, and electric drivetrains deliver the same services from far less primary energy — often more cheaply than building new supply. The cheapest kilowatt-hour is the one you never need."}]}]},{id:"precalculus-and-vectors",number:10,title:"Precalculus & Vectors",description:"The complete math upgrade for quantitative physics: functions, logs, deep trigonometry, vectors, complex numbers, and the first taste of calculus — everything Phase 3 needs, exactly one step ahead.",phase:3,chapters:[{id:"functions",title:"Functions",subtitle:"The function concept, transformations, and reasoning about how quantities depend on each other",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Physics is the study of how one quantity depends on another, and the function is the mathematical machine that captures dependence. This chapter builds the concept properly — composition, inverses, transformations that shift and stretch graphs — and teaches the qualitative and asymptotic reasoning physicists use constantly: what happens as x grows huge or shrinks to zero? These habits of thinking about behavior, not just computing values, mark the shift from school math to physics-ready math.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Function concept</li>\n  <li>Composition</li>\n  <li>Inverses</li>\n  <li>Transformations</li>\n  <li>Rational functions</li>\n  <li>Qualitative/asymptotic reasoning</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"exponentials-and-logarithms",title:"Exponentials & Logarithms",subtitle:"Growth, decay, e, and the log scales — dB, pH, Richter — that tame huge ranges",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Radioactive decay, capacitor discharge, sound intensity, earthquake magnitude — an astonishing amount of physics is exponential, and logarithms are how you read it. This chapter covers exponential growth and decay, the special number e, log rules drilled to automaticity, and the log scales (decibels, pH, Richter) plus semilog plots that turn exponential curves into readable straight lines. You\'ll use these tools directly in the decay law of Subject 15 and the decibel work of Subject 13.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Exponential growth &amp; decay</li>\n  <li>e</li>\n  <li>Log rules (to automaticity)</li>\n  <li>Log scales (dB, pH, Richter)</li>\n  <li>Semilog plots</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"trigonometry-mastery",title:"Trigonometry Mastery",subtitle:"The unit circle from memory, radians, identities — the never-skip chapter of the math ladder",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The curriculum lists the unit circle among the skills you must never skip, because trigonometry is the language of everything that rotates, oscillates, or waves. This chapter takes you well past SOH-CAH-TOA: the unit circle from memory, radians as the natural angle measure, the graphs of sin, cos, and tan with amplitude, period, and phase, plus the identity toolkit and trig equations. Simple harmonic motion, wave equations like y = A sin(kx − ωt), and AC circuits all read like applied trigonometry afterward.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The unit circle (from memory)</li>\n  <li>Radians</li>\n  <li>Graphs of sin/cos/tan</li>\n  <li>Amplitude, period, phase</li>\n  <li>Pythagorean/sum/double-angle identities</li>\n  <li>Trig equations</li>\n  <li>Inverse trig</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"vectors",title:"Vectors",subtitle:"Components, dot and cross products — the mathematical objects forces actually are",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Force, velocity, acceleration, and field are all vectors — quantities with direction — and this never-skip chapter teaches you to compute with them: components, addition, and the two products (dot and cross) with their geometric meanings. The entire second pass through mechanics in Subject 11 is titled "with vectors" because this is the upgrade that makes inclined planes, projectiles, and torque tractable. Work as a dot product and magnetic force as a cross product will feel natural once this chapter is behind you.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Components</li>\n  <li>Addition</li>\n  <li>Dot product</li>\n  <li>Cross product</li>\n  <li>Geometric meaning</li>\n  <li>Vectors in physics</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"complex-numbers",title:"Complex Numbers",subtitle:"The Argand plane, polar form, and a preview of Euler's formula — quantum's native language",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Complex numbers begin as a curiosity — a number whose square is negative — and end up as physics's secret weapon: AC circuit analysis, wave superposition, and the whole of quantum mechanics run on them. This chapter covers complex arithmetic, the Argand-plane picture that makes multiplication a rotation, polar form, and a preview of Euler's formula e^(iθ) = cos θ + i sin θ, often called the most beautiful equation in mathematics. Investing here pays compound interest through Phases 4 and 5.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Arithmetic</li>\n  <li>The Argand plane</li>\n  <li>Polar form</li>\n  <li>Euler's formula preview</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"sequences-series-and-approximation",title:"Sequences, Series & Approximation",subtitle:"Geometric series, the binomial theorem, and small-x expansions — physics's favorite move",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The curriculum calls small-x expansion "the most-used move in physics" — and lists Taylor-expansion thinking among the skills never to skip — because real physics problems are rarely solved exactly; they\'re approximated intelligently. This chapter builds up from arithmetic and geometric series through the binomial theorem to that art of approximation: replacing complicated expressions with simple ones valid when a quantity is small. It\'s how the pendulum becomes simple harmonic and how relativity reduces to Newton at everyday speeds.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Arithmetic &amp; geometric series</li>\n  <li>Binomial theorem</li>\n  <li>The art of approximation (small-x expansions — the most-used move in physics)</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"limits-and-the-idea-of-calculus",title:"Limits & the Idea of Calculus",subtitle:"The derivative as rate, the integral as area, and first calculus applied to motion",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Here you meet the two greatest ideas in applied mathematics: the derivative as an instantaneous rate (the exact slope your motion graphs have been hinting at) and the integral as accumulated area. Following the Singapore Additional-Math model, you\'ll immediately apply basic calculus to kinematics — velocity as the derivative of position, distance as the integral of velocity — so the concepts land on physics you already know. This preview makes the full calculus sequence of Subject 16, and F = ma as a differential equation, far less of a cliff.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Limits &amp; continuity</li>\n  <li>The derivative as slope/rate</li>\n  <li>The integral as area</li>\n  <li>Kinematics with basic calculus (the Singapore Additional-Math move)</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"probability-and-statistics-foundations",title:"Probability & Statistics Foundations",subtitle:"Counting, distributions, mean and variance, and the ubiquitous normal curve",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Modern physics is statistical to its core — quantum mechanics predicts probabilities, and thermodynamics is the statistics of 10\xb2\xb3 particles — so probabilistic thinking belongs in your foundation. This chapter covers counting, the probability rules, an introduction to distributions, mean and variance, and the normal curve that appears everywhere from measurement error to molecular speeds. It also underpins honest data analysis: every lab measurement you\'ll ever quote needs an uncertainty, and uncertainty is statistics.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Counting</li>\n  <li>Probability rules</li>\n  <li>Distributions intro</li>\n  <li>Mean &amp; variance</li>\n  <li>The normal curve</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]},{id:"mechanics-with-vectors",number:11,title:"Mechanics",description:"The second pass through mechanics, now armed with vectors and trigonometry: projectiles, Newton's laws in full, momentum, energy, orbits, rotation, oscillations, and fluids at A-level/NCERT depth.",phase:3,chapters:[{id:"measurement-and-uncertainty",title:"Measurement & Uncertainty",subtitle:"SI units, dimensional analysis, and honest error handling — the craft of quantitative science",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Quantitative physics begins with knowing exactly what your numbers mean, and this chapter professionalizes that: the SI system in full, dimensional analysis as a superpower for checking (and sometimes deriving) formulas, and the basics of error propagation with significant figures done properly. Dimensional thinking alone will save you from more wrong answers than any other single habit. Every multi-step problem in the rest of Phase 3 leans on the discipline you build here.</p>\n<h3>Topics</h3>\n<ul>\n  <li>SI system</li>\n  <li>Dimensional analysis</li>\n  <li>Error propagation basics</li>\n  <li>Significant figures properly</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"kinematics-in-1d-and-2d",title:"Kinematics in 1D & 2D",subtitle:"The suvat equations, free fall, and projectile motion — vectors earning their keep",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The suvat equations turn uniformly accelerated motion into pure algebra, and free fall becomes their most famous application. Then the vector toolkit from Subject 10 unlocks two dimensions: projectile motion splits into independent horizontal and vertical stories, and suddenly you can predict where the ball lands. Relative motion rounds out the chapter — the gateway idea to reference frames that special relativity will one day make profound.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The suvat equations</li>\n  <li>Free fall</li>\n  <li>Projectile motion</li>\n  <li>Relative motion</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"newtons-laws-properly",title:"Newton's Laws Properly",subtitle:"Force decomposition, friction models, tension, and connected bodies — real problem-solving begins",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>This is where mechanics becomes a true problem-solving discipline: all three of Newton\'s laws deployed with vector decomposition on inclined planes, quantitative friction models, and the tension and normal forces that appear in every free-body diagram. Connected bodies — blocks and pulleys moving together — and apparent weight in accelerating elevators are the classic multi-step problems of the A-level/JEE tradition. The systematic method you learn here is the template for attacking any force problem for the rest of the curriculum.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The three laws</li>\n  <li>Force decomposition on inclines</li>\n  <li>Friction models</li>\n  <li>Tension &amp; normal forces</li>\n  <li>Connected bodies</li>\n  <li>Apparent weight</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"momentum-and-collisions",title:"Momentum & Collisions",subtitle:"Impulse, conservation of momentum, and the physics of crashes, recoil, and rockets",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Momentum is the first of the great conservation laws you'll wield as a computational tool: in any collision or explosion, total momentum before equals total momentum after, no matter how messy the details. This chapter covers impulse (why airbags and crumple zones save lives), elastic versus inelastic collisions, and the recoil logic that makes rockets work by throwing mass backward. Conservation-law reasoning — solving problems while ignoring complicated intermediate forces — is a habit of mind you'll use through quantum mechanics and particle physics.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Impulse</li>\n  <li>Conservation of momentum</li>\n  <li>Elastic &amp; inelastic collisions</li>\n  <li>Recoil &amp; rockets</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"work-energy-and-conservation",title:"Work, Energy & Conservation",subtitle:"Varying forces, conservative forces, and energy conservation as a problem-solving superpower",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The energy ideas from the first pass return with full quantitative teeth: work done by varying forces, kinetic and potential energy precisely defined, and the crucial concept of a conservative force — one whose work depends only on endpoints, letting you define potential energy at all. Energy conservation then becomes your most elegant solver: problems that would demand pages of force analysis fall in three lines. With power added, this chapter completes the energy toolkit that Phases 4 and 5 will deepen with calculus and reformulate as Lagrangians.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Work by a varying force</li>\n  <li>KE &amp; PE</li>\n  <li>Conservative forces</li>\n  <li>Energy conservation</li>\n  <li>Power</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"circular-motion-and-gravitation",title:"Circular Motion & Gravitation",subtitle:"Centripetal acceleration, Newton's gravity, Kepler's laws, and the physics of orbits",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Circular motion holds a beautiful surprise: an object moving at constant speed is still accelerating, because its direction changes — and that centripetal acceleration explains banked curves, spin cycles, and every orbit in the sky. Newton's law of gravitation then performs history's great unification, showing the fall of an apple and the orbit of the Moon are the same physics, with Kepler's laws emerging as consequences. Gravitational fields, potential energy, and satellite motion complete a chapter that runs from race tracks to the Solar System.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Centripetal acceleration</li>\n  <li>Banked curves</li>\n  <li>Newton's law of gravitation</li>\n  <li>Orbits &amp; Kepler's laws</li>\n  <li>Gravitational field &amp; potential energy</li>\n  <li>Satellites</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"rotation-and-statics",title:"Rotation & Statics",subtitle:"Torque, moment of inertia, angular momentum, and why structures stand or fall",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Rotation gets its own complete dynamics, in perfect parallel with what you know: torque plays the role of force, moment of inertia the role of mass, and angular momentum the role of momentum — conserved, which is why spinning skaters speed up when they pull in their arms. Rolling motion combines translation and rotation, while statics applies the equilibrium conditions to explain why bridges, ladders, and cranes stand. This rotational toolkit returns with integrals in Phase 4 and with the inertia tensor in Phase 5.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Torque</li>\n  <li>Moment of inertia</li>\n  <li>Angular momentum</li>\n  <li>Rolling</li>\n  <li>Equilibrium &amp; stability</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"oscillations",title:"Oscillations",subtitle:"Simple harmonic motion, pendulums and springs, damping and resonance — the heartbeat of physics",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Simple harmonic motion may be the single most important model in physics: pendulums, springs, molecules, bridges, and quantum fields all oscillate, and the trigonometry you mastered in Subject 10 now describes them exactly. You\'ll analyze the pendulum and spring quantitatively, track how energy sloshes between kinetic and potential forms, and meet damping and resonance — the phenomenon that shatters wine glasses and topples bridges. SHM is also the direct on-ramp to waves in Subject 13 and the oscillator ODEs of Phase 4.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Simple harmonic motion</li>\n  <li>Pendulum &amp; spring</li>\n  <li>Energy in SHM</li>\n  <li>Damping &amp; resonance</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"fluids",title:"Fluids",subtitle:"Continuity, Bernoulli's principle, and a first look at viscosity — mechanics of flow",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>The pressure and buoyancy of the first pass return with mathematics, and then the fluid starts moving: the continuity equation says what flows in must flow out (why rivers speed up where they narrow), and Bernoulli's principle — energy conservation applied to flow — connects fast-moving fluid to low pressure. Together they illuminate airplane wings, chimney draft, and blood flow, with viscosity introduced as the fluid's internal friction. It's the mechanics finale that shows Newton's framework handles matter that flows.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Pressure revisited</li>\n  <li>Continuity equation</li>\n  <li>Bernoulli's principle</li>\n  <li>Viscosity intro</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]}]},{id:"thermal-physics",number:12,title:"Thermal Physics",description:"Heat becomes exact: the ideal gas from kinetic theory, the first law's energy bookkeeping, and the second law's deep truth about engines, entropy, and the arrow of time.",phase:3,chapters:[{id:"temperature-and-ideal-gases",title:"Temperature & Ideal Gases",subtitle:"The gas laws, PV = nRT, and deriving pressure from molecules in motion",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>This chapter delivers one of physics's great payoffs: starting from the particle model of Phase 2, you'll derive the pressure of a gas from nothing but molecules bouncing off walls — connecting the invisible microscopic world to a formula you can test with a pump. Along the way come thermal equilibrium and the zeroth law, the historical gas laws, and their unification in the ideal-gas equation, plus the distribution of molecular speeds. It's your first genuine taste of the statistical thinking that Phase 5's statistical mechanics builds into a full theory.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Thermal equilibrium &amp; the zeroth law</li>\n  <li>Gas laws</li>\n  <li>Ideal-gas equation</li>\n  <li>Kinetic-theory derivation of pressure</li>\n  <li>Molecular speeds</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"the-first-law",title:"The First Law",subtitle:"Internal energy, heat, and work — energy bookkeeping on P–V diagrams",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>The first law of thermodynamics is energy conservation with the books finally balanced: a gas's internal energy changes only through heat flowing in or work being done. You'll learn why gases have two specific heats, follow isothermal and adiabatic processes, and master the P–V diagram — the graphical language where the area under a curve is work, and closed loops become engine cycles. This bookkeeping is the foundation for the engines and entropy of the next chapter and for all of thermodynamics beyond.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Internal energy</li>\n  <li>Heat &amp; work</li>\n  <li>Specific heats of gases</li>\n  <li>Isothermal &amp; adiabatic processes</li>\n  <li>P–V diagrams</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"the-second-law-intro",title:"The Second Law (intro)",subtitle:"Heat engines, Carnot's limit, and a first meeting with entropy and time's arrow",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The second law is arguably the deepest statement in classical physics: heat flows one way, no engine can be perfect, and the universe keeps score with a quantity called entropy. This chapter analyzes heat engines and refrigerators, derives the Carnot efficiency — the fundamental ceiling no engineering cleverness can beat, answering the question planted back in Subject 6 — and gives you a first look at entropy. Subject 28 will rebuild it all from counting microstates; here you meet the law that gives time its direction.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Heat engines</li>\n  <li>Refrigerators</li>\n  <li>Carnot efficiency</li>\n  <li>Entropy first look</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"thermal-properties-of-matter",title:"Thermal Properties of Matter",subtitle:"Calorimetry with rigor, phase diagrams, humidity, and where the ideal gas breaks down",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Real matter is richer than the ideal gas, and this chapter maps that richness: calorimetry revisited with full quantitative rigor, and phase diagrams — the pressure–temperature maps showing where a substance is solid, liquid, or gas, complete with triple and critical points. Humidity brings the physics of water vapor into weather you experience daily, and real gases show where and why the ideal model bends. It closes the Phase 3 thermal story and sets up the deeper treatment of phase transitions in statistical mechanics.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Calorimetry revisited</li>\n  <li>Phase diagrams</li>\n  <li>Humidity</li>\n  <li>Real gases</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]},{id:"waves-and-optics",number:13,title:"Waves & Optics",description:"The quantitative second pass at waves — from y = A sin(kx − ωt) to superposition, the Doppler effect, double-slit interference, and the lens equation.",phase:3,chapters:[{id:"wave-motion",title:"Wave Motion",subtitle:"Travelling waves, the sinusoidal wave function, and what carries the energy",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Here the wave picture from Phase 2 becomes exact: a travelling wave is a moving sinusoid, y = A sin(kx − ωt), and every symbol in that expression earns its keep. You'll connect wave speed to the properties of the medium and learn how energy and intensity ride along — the mathematics that Phase 4's wave equation will later derive from first principles.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Travelling waves</li>\n  <li>y = A sin(kx − ωt)</li>\n  <li>Wave speed on strings</li>\n  <li>Energy &amp; intensity</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"superposition",title:"Superposition",subtitle:"Interference, standing waves, harmonics, and beats",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Superposition is the single most consequential property of waves: two waves in the same place simply add. From that one rule comes interference, the standing waves that make guitar strings and organ pipes musical, and the beats piano tuners listen for. Quantum mechanics will reuse every idea in this chapter.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Interference</li>\n  <li>Standing waves</li>\n  <li>Harmonics &amp; music</li>\n  <li>Beats</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"sound-and-doppler",title:"Sound & Doppler",subtitle:"Sound made quantitative — decibels, moving sources, and shock waves",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Sound gets numbers: intensity and the logarithmic decibel scale (your log fluency from Subject 10 at work), then the Doppler effect that shifts a siren\'s pitch as it passes — the same physics astronomers use to measure the expanding universe — and the shock cones of supersonic flight.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Quantitative sound</li>\n  <li>Intensity &amp; decibels</li>\n  <li>The Doppler effect</li>\n  <li>Shock waves</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"wave-optics",title:"Wave Optics",subtitle:"Interference and diffraction — the experiments that prove light is a wave",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Young's double slit settled a century-long argument by making light interfere with itself. This chapter works through the geometry of interference fringes, diffraction from single slits and gratings, polarization, and the thin-film colors on soap bubbles — the evidence and mathematics behind light's wave nature.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Huygens' principle</li>\n  <li>Double-slit interference</li>\n  <li>Diffraction</li>\n  <li>Gratings</li>\n  <li>Polarization</li>\n  <li>Thin films</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"ray-optics-quantitative",title:"Ray Optics Quantitative",subtitle:"Mirror and lens equations, instruments, and the limits of resolution",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The ray diagrams of Phase 2 become predictive formulas: the mirror and lens equations locate every image exactly, and combinations of lenses explain microscopes and telescopes. Diffraction returns at the end to set the ultimate resolution limit of any optical instrument — including your eye.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Mirror &amp; lens equations</li>\n  <li>Optical instruments</li>\n  <li>Resolution</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]},{id:"fields-circuits-electromagnetism",number:14,title:"Fields, Circuits & Electromagnetism",description:"The full A-level/H2-style treatment of electricity and magnetism: Coulomb's law and fields, capacitors, Kirchhoff's circuits, magnetic forces, Faraday's induction, and alternating current.",phase:3,chapters:[{id:"electric-fields",title:"Electric Fields",subtitle:"Coulomb's law, field strength, potential, and charges in motion",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>The field concept — physics's answer to action at a distance — takes center stage. Coulomb's law gives the force, field lines make it visible, and potential turns hard vector problems into easy energy bookkeeping. Charged-particle motion in uniform fields reruns projectile motion with electrons.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Coulomb's law</li>\n  <li>Field lines &amp; field strength</li>\n  <li>Potential &amp; potential difference</li>\n  <li>Equipotentials</li>\n  <li>Charged-particle motion in fields</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"capacitance",title:"Capacitance",subtitle:"Storing energy in fields — capacitors, dielectrics, and RC charging",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Capacitors store energy in the electric field itself — the first hint that fields are physical things, not bookkeeping. You\'ll compute capacitance, follow the energy, see how dielectrics help, and meet the exponential charge/discharge curves that reappear everywhere from camera flashes to neuron membranes.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Capacitors</li>\n  <li>Energy storage</li>\n  <li>Dielectrics</li>\n  <li>RC charge/discharge</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"dc-circuits",title:"DC Circuits",subtitle:"EMF, Kirchhoff's laws, and the art of circuit analysis",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Ohm's law from Phase 2 grows into full circuit analysis: real batteries with internal resistance, Kirchhoff's two laws (which are just conservation of charge and energy in disguise), resistor networks, and the classic measuring instruments. This is the problem-solving heart of school electricity.</p>\n<h3>Topics</h3>\n<ul>\n  <li>EMF &amp; internal resistance</li>\n  <li>Kirchhoff's laws</li>\n  <li>Resistor networks</li>\n  <li>Meters</li>\n  <li>Potentiometer &amp; Wheatstone bridge</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"magnetic-fields",title:"Magnetic Fields",subtitle:"Forces on moving charges — from F = qvB to the mass spectrometer",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Magnetism reveals its true identity: a force on moving charge. F = qvB and F = BIL unlock motors, the circular dance of charges in magnetic fields, the mass spectrometer that weighs atoms, and the Hall effect that lets your phone sense magnets.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Fields of currents</li>\n  <li>F = qvB and F = BIL</li>\n  <li>The Lorentz force</li>\n  <li>Mass spectrometer</li>\n  <li>Hall effect</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"electromagnetic-induction",title:"Electromagnetic Induction",subtitle:"Faraday's law — the principle behind nearly all electricity generation",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Faraday's discovery that changing magnetic flux drives current is arguably the most economically important physics ever done: it is how virtually every watt of grid electricity is generated. Flux, Faraday's and Lenz's laws, generators, eddy currents, and inductance — the complete induction toolkit.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Magnetic flux</li>\n  <li>Faraday's &amp; Lenz's laws</li>\n  <li>Generators</li>\n  <li>Eddy currents</li>\n  <li>Self &amp; mutual inductance</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"alternating-current",title:"Alternating Current",subtitle:"RMS values, transformers, and why the grid is AC",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>AC won the war of currents because transformers make voltage conversion nearly lossless. You'll handle RMS values (why '230 V' is an average of sorts), reactance, transformer physics, and power transmission — then meet the electromagnetic waves that close out the classical story.</p>\n<h3>Topics</h3>\n<ul>\n  <li>RMS values</li>\n  <li>Reactance</li>\n  <li>Transformers</li>\n  <li>Power transmission</li>\n  <li>EM waves intro</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]}]},{id:"modern-physics",number:15,title:"Modern Physics",description:"The first quantitative pass at the twentieth century: special relativity, photons, wave-particle duality, the nucleus, semiconductors — and a tour of the frontier that motivates everything ahead.",phase:3,chapters:[{id:"special-relativity-intro",title:"Special Relativity Intro",subtitle:"Two postulates that rewrite space and time",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Einstein's two innocuous-sounding postulates — physics is the same in all inertial frames, and light's speed is invariant — force time dilation, length contraction, and the relativity of simultaneity. This first pass builds the intuition and the basic calculations; Phase 4's full course adds four-vectors and dynamics.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The postulates</li>\n  <li>Time dilation</li>\n  <li>Length contraction</li>\n  <li>Simultaneity</li>\n  <li>E = mc\xb2 (first quantitative pass)</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"quantization-of-light",title:"Quantization of Light",subtitle:"The photoelectric effect and the birth of the photon",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Classical physics predicted a blackbody catastrophe that never happens; Planck's fix and Einstein's photoelectric analysis revealed light comes in packets. The photoelectric effect, photon energy E = hf, Compton scattering, and X-rays — the experiments that started the quantum revolution.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The blackbody problem</li>\n  <li>Photoelectric effect</li>\n  <li>Photons</li>\n  <li>Compton scattering</li>\n  <li>X-rays</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"wave-particle-duality-atoms",title:"Wave–Particle Duality & Atoms",subtitle:"de Broglie's matter waves and the quantum atom",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>If light waves act like particles, do particles act like waves? de Broglie said yes, electron diffraction proved it, and Bohr used it to crack the hydrogen spectrum. Energy levels, spectral lines, and the uncertainty principle — the conceptual core that Quantum Mechanics I will make rigorous.</p>\n<h3>Topics</h3>\n<ul>\n  <li>de Broglie waves</li>\n  <li>Electron diffraction</li>\n  <li>Bohr model &amp; atomic spectra</li>\n  <li>Energy levels</li>\n  <li>Uncertainty principle intro</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"nucleus-quantitative",title:"The Nucleus, Quantitatively",subtitle:"Binding energy, the decay law, and nuclear energetics",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The nucleus gets numbers: mass defect and binding energy explain why iron is the most stable element and why both fission and fusion release energy. The exponential decay law N = N₀e^(−λt) puts your exponential/log fluency to work on half-lives and radiometric dating.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Binding energy &amp; mass defect</li>\n  <li>The decay law N = N₀e^(−λt)</li>\n  <li>Fission &amp; fusion energetics</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"semiconductors-electronics",title:"Semiconductors & Electronics",subtitle:"Bands, diodes, transistors — the physics inside every chip",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>A qualitative pass at the physics that powers civilization: energy bands, doping, the pn junction diode, LEDs, transistors as switches, and logic gates. If this hooks you, the LearnSemi sibling course and Phase 6\'s Solid State Physics go much deeper.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Energy bands qualitatively</li>\n  <li>Diodes &amp; LEDs</li>\n  <li>Transistors</li>\n  <li>Logic gates</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"particles-and-universe",title:"Particles & the Universe",subtitle:"A motivating tour of the Standard Model and the Big Bang",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>The 'physics is alive' chapter: a guided tour of quarks, leptons, and force carriers, the cosmic rays striking the atmosphere right now, and the three great lines of evidence for the Big Bang. No problem sets — just the map of where Phases 4–6 are headed.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Standard Model tour</li>\n  <li>Cosmic rays</li>\n  <li>Evidence for the Big Bang</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]}]},{id:"calculus-1-2",number:16,title:"Calculus I & II",description:"Single-variable calculus at MIT 18.01-level (Stewart/Thomas depth) — derivatives, integrals, series, and first differential equations, arriving exactly one step ahead of the calculus-based mechanics that needs them.",phase:4,chapters:[{id:"limits-derivatives",title:"Limits & Derivatives",subtitle:"Formal limits and the full differentiation toolkit, from the chain rule to related rates",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The derivative is the single most important idea in mathematical physics: it turns "how fast is this changing?" into something you can compute. This chapter makes limits precise and then builds the complete differentiation toolkit — the machinery you will use on day one of Classical Mechanics I, where velocity and acceleration become derivatives of position.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Formal limits</li>\n  <li>Differentiation rules</li>\n  <li>Chain rule</li>\n  <li>Implicit differentiation</li>\n  <li>Related rates</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"applications-of-derivatives",title:"Applications of Derivatives",subtitle:"Using derivatives to optimize, approximate, and analyze the shape of functions",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Once you can differentiate, you can answer real questions: where is a quantity largest, how does a function behave near a point, and what happens in tricky limiting cases. Linearization in particular is the physicist's reflex — replacing a complicated function by its tangent line is how half of physics gets solved. These skills return constantly, from finding stable equilibria in energy diagrams to small-angle approximations in oscillations.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Optimization</li>\n  <li>Linearization</li>\n  <li>L'H\xf4pital</li>\n  <li>Curve analysis</li>\n</ul>\n<div class=\"key-concept\">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>"}],quiz:[]},{id:"integration",title:"Integration",subtitle:"The fundamental theorem and the full toolkit of integration techniques",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Integration is addition taken to its logical extreme — summing infinitely many infinitesimal pieces — and the fundamental theorem of calculus reveals it as the inverse of differentiation. This chapter builds fluency with the standard techniques, because in Electromagnetism I you will integrate charge distributions and in mechanics you will recover motion from acceleration. The ∫ symbol is about to become your most-used tool.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The fundamental theorem</li>\n  <li>Substitution</li>\n  <li>Integration by parts</li>\n  <li>Partial fractions</li>\n  <li>Trig integrals</li>\n  <li>Improper integrals</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"applications-of-integration",title:"Applications of Integration",subtitle:"Areas, volumes, arc length, work, and centre of mass — integrals doing physics",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Here the integral stops being abstract and starts computing physical things: the volume of a solid, the work done by a varying force, the balance point of an extended body. The "slice, sum, take the limit" pattern you practice here is exactly how physicists set up integrals for the rest of the curriculum — from moments of inertia to field calculations.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Areas & volumes</li>\n  <li>Arc length</li>\n  <li>Work & centre of mass</li>\n  <li>Average value</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"infinite-series",title:"Infinite Series",subtitle:"Convergence, power series, and Taylor expansions — physics's favourite approximation tool",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Taylor series are arguably the most-used tool in all of theoretical physics: nearly every "approximately equals" you will ever see is a truncated series. This chapter teaches when infinite sums converge, how to expand any function into powers of x, and how to control the error you make by stopping early. Master this and moves like sin θ ≈ θ or the low-speed limit of relativity become second nature.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Convergence</li>\n  <li>Power series</li>\n  <li>Taylor & Maclaurin series</li>\n  <li>Error bounds</li>\n  <li>Series as physics\'s favourite tool</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"intro-differential-equations",title:"Intro Differential Equations",subtitle:"First-order ODEs, exponential models, and direction fields — your first taste of physics's native language",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Newton\'s second law is a differential equation, so learning to solve simple ODEs is learning to read the laws of nature in their native language. This chapter covers separable and first-order linear equations and the exponential growth/decay models that describe everything from radioactive decay to RC circuits. It is the direct warm-up for terminal velocity — your first real ODE — in Classical Mechanics I.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Separable & first-order linear ODEs</li>\n  <li>Exponential models</li>\n  <li>Direction fields</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"parametric-polar",title:"Parametric & Polar",subtitle:"Curves as functions of time, polar coordinates, and vector-valued motion",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Physical trajectories are naturally parametric — position as a function of time — and many problems (orbits especially) are far simpler in polar coordinates than Cartesian ones. This chapter connects calculus to geometry in motion, ending with vector-valued functions: the exact mathematical form kinematics takes in the very next subject.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Parametric curves</li>\n  <li>Polar coordinates</li>\n  <li>Vector-valued functions & motion</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]}]},{id:"classical-mechanics-1",number:17,title:"Classical Mechanics I",description:"Newtonian mechanics done properly with calculus, in the MIT 8.01 spirit with Kleppner & Kolenkow / Morin depth — F = ma becomes a differential equation, and energy, momentum, rotation, and orbits follow from it.",phase:4,chapters:[{id:"kinematics-via-calculus",title:"Kinematics via Calculus",subtitle:"Position, velocity, and acceleration as derivatives — and your first real ODE",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Everything you learned about motion gets rebuilt on calculus: velocity is the derivative of position, acceleration the derivative of velocity, and motion is recovered from acceleration by integration. The payoff comes immediately — air drag gives you your first genuine differential equation, and terminal velocity falls out of it. This is the moment the physics you know becomes the physics universities teach.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Position, velocity, acceleration as derivatives</li>\n  <li>Motion from integrals</li>\n  <li>Drag & terminal velocity (your first real ODE)</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"newtons-laws-as-differential-equations",title:"Newton's Laws as Differential Equations",subtitle:"Solving F = ma as an equation of motion, with a first look at oscillators and numerics",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>F = ma is not a formula to plug into — it is a differential equation whose solution is the entire future of a system. This chapter teaches you to set up and solve equations of motion, previews the harmonic oscillator (the most important system in physics), and introduces numerical solution, the technique that handles everything analytic methods cannot. This way of thinking carries you all the way to Lagrangian mechanics and beyond.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Solving F = ma</li>\n  <li>The oscillator preview</li>\n  <li>Numerical solutions intro</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"momentum-systems-of-particles",title:"Momentum & Systems of Particles",subtitle:"Centre of mass, rockets, and two-dimensional collisions",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Real objects are systems of many particles, and the centre-of-mass concept is what lets Newton\'s laws apply to them as if they were points. This chapter handles systems whose mass changes — the rocket equation is the classic — and extends collision analysis to two dimensions, where conservation of momentum becomes a genuinely vectorial statement.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Centre of mass</li>\n  <li>Variable-mass systems (rockets)</li>\n  <li>Collisions in 2D</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"energy-methods",title:"Energy Methods",subtitle:"Work–energy via integrals, F = −dU/dx, and reading physics from energy diagrams",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>With calculus, energy stops being a bookkeeping trick and becomes a predictive method: force is the negative slope of potential energy, so a single U(x) curve tells you where a system can go, where it sits in equilibrium, and whether that equilibrium is stable. Energy-diagram reasoning developed here is the same reasoning you will use for molecular bonds, planetary orbits, and quantum wells.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Work–energy via integrals</li>\n  <li>Potential energy & force (F = −dU/dx)</li>\n  <li>Potential wells & stability</li>\n  <li>Energy diagrams</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"angular-momentum-rigid-bodies",title:"Angular Momentum & Rigid Bodies",subtitle:"Rotational dynamics with real integrals, gyroscopes, and precession",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Rotation gets the full calculus treatment: moments of inertia computed by integration rather than looked up in tables, and angular momentum as a conserved vector quantity with sometimes startling consequences. The gyroscope — which seems to defy gravity by precessing instead of falling — is the showcase, and the rotational machinery built here returns in rigid-body motion, atomic physics, and quantum spin.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Rotational dynamics properly</li>\n  <li>Moment of inertia by integration</li>\n  <li>Gyroscopes & precession</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"oscillations-in-depth",title:"Oscillations in Depth",subtitle:"SHM as an ODE, damping, driving, resonance, and the first coupled oscillators",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The harmonic oscillator is the most important system in physics — almost everything, near equilibrium, is one. This chapter solves it properly as a differential equation, then adds damping and driving to get resonance quantitatively, and closes with coupled oscillators, the doorway to the waves course. The mathematics you build here reappears in AC circuits, quantum mechanics, and quantum field theory.</p>\n<h3>Topics</h3>\n<ul>\n  <li>SHM as an ODE</li>\n  <li>Damped & driven oscillations</li>\n  <li>Resonance quantitatively</li>\n  <li>Coupled oscillators intro</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"central-forces-orbits",title:"Central Forces & Orbits",subtitle:"Effective potential, the orbit equation, and Kepler's laws derived from first principles",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>This is one of the great triumphs of physics: starting from Newton's law of gravitation and conservation laws, you derive Kepler's laws — the actual shapes of planetary orbits — with pencil and paper. The effective-potential technique that makes it possible is a completely general tool, and orbital transfers connect the theory directly to how real spacecraft navigate the solar system.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Effective potential</li>\n  <li>The orbit equation</li>\n  <li>Kepler's laws derived</li>\n  <li>Orbital transfers</li>\n</ul>\n<div class=\"key-concept\">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>"}],quiz:[]},{id:"noninertial-frames",title:"Noninertial Frames",subtitle:"Pseudo-forces, rotating frames, the Coriolis force, and tides",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Newton\'s laws hold in inertial frames — but we live on a rotating planet, so pseudo-forces like the centrifugal and Coriolis forces are part of everyday physics, steering hurricanes and ocean currents. This chapter teaches you to work in accelerating and rotating frames confidently, explains the tides properly, and plants a seed: the idea that "fictitious" forces reflect your frame of reference is the very intuition Einstein pushed all the way to general relativity.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Pseudo-forces</li>\n  <li>Rotating frames</li>\n  <li>The Coriolis force</li>\n  <li>Tides</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]}]},{id:"multivariable-vector-calculus",number:18,title:"Multivariable & Vector Calculus",description:"Calculus in three dimensions at MIT 18.02-level, with the div-grad-curl intuition of Schey's classic — the exact toolkit you need in hand before electromagnetism, because Gauss and Stokes ARE Maxwell's equations.",phase:4,chapters:[{id:"functions-of-several-variables",title:"Functions of Several Variables",subtitle:"Partial derivatives, the gradient, and the multivariable chain rule",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Physical fields — temperature in a room, potential in space — depend on several variables at once, and this chapter extends calculus to handle them. The star is the gradient ∇f, the vector that points uphill and encodes how a field changes in every direction at once. You will meet it again almost immediately: the electric field is the (negative) gradient of the potential.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Partial derivatives</li>\n  <li>The gradient</li>\n  <li>Chain rule</li>\n  <li>Differentials</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"optimization-lagrange-multipliers",title:"Optimization & Lagrange Multipliers",subtitle:"Critical points and constrained optimization — a technique statistical mechanics will need again",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Finding extrema in several variables is a fundamental skill, and the method of Lagrange multipliers — optimizing under a constraint — is one of the most elegant tricks in mathematics. Learn it well now: it is exactly how statistical mechanics derives the Boltzmann distribution, by maximizing entropy subject to fixed energy.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Critical points</li>\n  <li>Constrained optimization (needed again in stat mech)</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"multiple-integrals",title:"Multiple Integrals",subtitle:"Double and triple integrals, Jacobians, and the coordinate systems physics lives in",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>To find the total charge in a volume or the mass of a solid body, you integrate over regions of space — and choosing the right coordinate system makes the difference between a nightmare and a three-line calculation. Cylindrical and spherical coordinates, with the Jacobian to convert between systems, are the working currency of every field calculation in electromagnetism and quantum mechanics.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Double & triple integrals</li>\n  <li>Jacobians</li>\n  <li>Cylindrical & spherical coordinates</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"vector-fields",title:"Vector Fields",subtitle:"Line integrals, conservative fields, and flux through surfaces",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Vector fields — an arrow at every point in space — are how physics describes forces, flows, and electromagnetic fields. This chapter teaches the two great ways to integrate them: along curves (work) and through surfaces (flux). The idea that some fields are conservative, with a potential function behind them, explains why potential energy exists at all — and flux is the concept at the heart of Gauss\'s law.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Line integrals</li>\n  <li>Conservative fields & potentials</li>\n  <li>Surface integrals & flux</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"the-big-theorems",title:"The Big Theorems",subtitle:"Green, Stokes, and divergence — the Maxwell-ready toolkit of div, grad, and curl",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>The three great theorems of vector calculus relate what happens inside a region to what happens on its boundary — and they are not merely tools for electromagnetism, they essentially <em>are</em> electromagnetism: Maxwell's equations in integral and differential form are connected by exactly these theorems. Build genuine intuition for divergence (sources) and curl (circulation) here, and Maxwell's equations in the next two subjects will read like sentences instead of hieroglyphics.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Green's, Stokes', and the divergence theorem</li>\n  <li>Div/grad/curl intuition — the Maxwell-ready toolkit</li>\n</ul>\n<div class=\"key-concept\">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>"}],quiz:[]}]},{id:"electromagnetism-1",number:19,title:"Electromagnetism I",description:"Calculus-based electricity and magnetism from MIT 8.02 up to Purcell & Morin level — from Gauss's law to the full set of Maxwell's equations and the stunning conclusion that light is an electromagnetic wave.",phase:4,chapters:[{id:"electrostatics-with-calculus",title:"Electrostatics with Calculus",subtitle:"From Coulomb's law to continuous charge distributions and the power of Gauss's law",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Armed with integrals, you can now compute the field of any charge distribution — rings, disks, planes, spheres — not just point charges. Then Gauss's law arrives and shows that symmetry can replace pages of integration with a single line: this is the first of Maxwell's equations, and your vector-calculus investment starts paying dividends immediately.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Coulomb → fields of continuous charge distributions</li>\n  <li>Gauss's law & its applications</li>\n</ul>\n<div class=\"key-concept\">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>"}],quiz:[]},{id:"potential-theory",title:"Potential Theory",subtitle:"Moving between field and potential, energy of charge configurations, and conductors",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The scalar potential V is often far easier to work with than the vector field E — and the gradient connects them in both directions. This chapter builds fluency in switching representations, computes the energy stored in arrangements of charge, and explains the special behaviour of conductors, where charge rearranges itself to make the interior field vanish.</p>\n<h3>Topics</h3>\n<ul>\n  <li>V from E and E from V</li>\n  <li>Energy of charge configurations</li>\n  <li>Conductors</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"capacitors-dielectrics",title:"Capacitors & Dielectrics",subtitle:"Computing capacitance, energy stored in fields, and what dielectrics do microscopically",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Capacitors are where field theory meets hardware — and the deeper lesson of this chapter is that the energy is stored not in the charges but in the field itself, an idea that becomes central to all of physics. You will calculate capacitance from geometry and understand microscopically how a dielectric\'s polarized molecules boost it.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Capacitance calculations</li>\n  <li>Energy stored in fields</li>\n  <li>Dielectrics microscopically</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"current-dc-circuits",title:"Current & DC Circuits",subtitle:"Current density, the microscopic view of Ohm's law, and RC circuits as differential equations",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Ohm's law gets its microscopic explanation — electrons drifting through a lattice under an applied field — turning V = IR from an empirical rule into derived physics. Then RC circuits become your differential equations in action: charging and discharging follow exponentials you can now predict, not just observe.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Current density</li>\n  <li>Microscopic Ohm's law</li>\n  <li>RC circuits as ODEs</li>\n</ul>\n<div class=\"key-concept\">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>"}],quiz:[]},{id:"magnetostatics",title:"Magnetostatics",subtitle:"Biot–Savart, Amp\xe8re's law, and the fields of steady currents",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Steady currents create magnetic fields, and this chapter gives you two ways to compute them: Biot–Savart for brute-force integration and Amp\xe8re's law for elegant symmetry arguments — the magnetic mirror image of Coulomb versus Gauss. Magnetic dipoles introduced here are the key to understanding magnetism in matter, from compass needles to MRI machines.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Biot–Savart</li>\n  <li>Amp\xe8re's law</li>\n  <li>Magnetic dipoles</li>\n  <li>Magnetism in matter intro</li>\n</ul>\n<div class=\"key-concept\">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>"}],quiz:[]},{id:"induction-inductance",title:"Induction & Inductance",subtitle:"Faraday's law properly, inductors, and LR/LC/RLC circuits as differential equations",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Faraday's law — changing magnetic flux creates electric fields — is the principle behind every generator and transformer on Earth, and here it gets its full integral-calculus treatment. LC and RLC circuits then reveal something beautiful: the equations are <em>identical</em> to the mechanical oscillators of Classical Mechanics I, with charge sloshing instead of mass — the same mathematics describing wholly different physics.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Faraday's law in integral form</li>\n  <li>Inductors</li>\n  <li>LR, LC, RLC circuits as ODEs</li>\n  <li>Energy in magnetic fields</li>\n</ul>\n<div class=\"key-concept\">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>"}],quiz:[]},{id:"maxwells-equations-light",title:"Maxwell's Equations & Light",subtitle:"The complete set of equations, the wave solution, and the discovery that light is electromagnetic",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Maxwell noticed that Amp\xe8re\'s law was incomplete, added the displacement current, and the closed set of four equations then predicted waves travelling at exactly the measured speed of light — the greatest unification in the history of physics. In this capstone chapter you follow that derivation yourself and meet the Poynting vector, which tracks where electromagnetic energy flows. Everything from radio to gamma rays falls out of four lines of vector calculus.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Displacement current</li>\n  <li>The complete set</li>\n  <li>The wave solution</li>\n  <li>The EM spectrum revisited</li>\n  <li>Energy flow & Poynting intro</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]}]},{id:"waves-vibrations-optics",number:20,title:"Waves, Vibrations & Optics",description:"The MIT 8.03-style hinge course (French's Vibrations and Waves) — normal modes, the wave equation, and Fourier thinking, the prerequisite that unlocks both quantum mechanics and statistical physics.",phase:4,chapters:[{id:"coupled-oscillators-normal-modes",title:"Coupled Oscillators & Normal Modes",subtitle:"Where matrices meet physics — beats, normal modes, and the road to the continuum",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Couple two pendulums with a spring and something remarkable happens: the motion decomposes into special collective patterns — normal modes — each oscillating at its own frequency. This is the moment matrices meet physics, and it is the conceptual template for everything from molecular vibrations to quantum states. Push the number of oscillators toward infinity and you arrive at waves, the subject of the rest of this course.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Matrices meet physics</li>\n  <li>Beats</li>\n  <li>The many-body limit</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"the-wave-equation",title:"The Wave Equation",subtitle:"Deriving the wave equation on a string, superposition, and standing waves done formally",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Apply F = ma to a tiny piece of stretched string and out comes the wave equation — one of the most important partial differential equations in physics, governing sound, light, and (in modified form) quantum wavefunctions. This chapter derives it honestly, then explores superposition and how boundary conditions select the discrete standing-wave patterns: your first real taste of how confinement leads to quantization.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Derivation on a string</li>\n  <li>Superposition</li>\n  <li>Boundary conditions</li>\n  <li>Standing waves formally</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"fourier-analysis-intro",title:"Fourier Analysis Intro",subtitle:"Fourier series, spectra, wave packets — and a classical preview of the uncertainty principle",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Fourier's insight — any wave can be built from sines and cosines — is one of the most powerful ideas in science, underpinning music, signal processing, and quantum theory alike. Here you learn to decompose signals into spectra and build wave packets, discovering along the way a purely classical fact: a short pulse needs many frequencies. That trade-off, ported to matter waves, <em>is</em> Heisenberg's uncertainty principle.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Fourier series</li>\n  <li>Spectra</li>\n  <li>Wave packets</li>\n  <li>The uncertainty relation previewed classically</li>\n</ul>\n<div class=\"key-concept\">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>"}],quiz:[]},{id:"em-waves-polarization",title:"EM Waves & Polarization",subtitle:"Plane waves, polarization states, and what happens when light meets a boundary",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The electromagnetic waves predicted at the end of Electromagnetism I now get explored as waves: plane-wave solutions, the polarization states that sunglasses and LCD screens exploit, and reflection at boundaries in the spirit of Fresnel. Polarization is also quietly profound — its two-state structure is the classical ancestor of the qubit.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Plane waves</li>\n  <li>Polarization states</li>\n  <li>Reflection at boundaries (Fresnel-lite)</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"interference-diffraction-quantitative",title:"Interference & Diffraction Quantitative",subtitle:"Phasors, gratings, single-slit patterns, and the fundamental limits of resolution",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Interference and diffraction get the full quantitative treatment using phasors — a graphical technique that turns messy sums of waves into simple geometry. You will predict exact fringe patterns for N slits and gratings, understand why every optical instrument has a fundamental resolution limit, and build the wave-superposition intuition that quantum mechanics will soon demand of you.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Phasors</li>\n  <li>N-slit & gratings</li>\n  <li>Single-slit</li>\n  <li>Resolution limits</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"geometrical-optics-from-waves",title:"Geometrical Optics from Waves",subtitle:"Why rays work at all — the eikonal idea, matrix optics, instruments, and lasers",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Ray optics is not a separate theory — it is the short-wavelength limit of wave optics, and the eikonal idea makes that connection precise. This chapter revisits lenses and instruments with that deeper understanding, introduces the elegant matrix method for tracing rays through optical systems, and ends with the laser: wave physics, atomic physics, and engineering meeting in one device.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The eikonal idea</li>\n  <li>Matrix optics taste</li>\n  <li>Instruments revisited</li>\n  <li>Lasers intro</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]}]},{id:"special-relativity",number:21,title:"Special Relativity",description:"A full MIT 8.033-style course in the physics of spacetime (Morin; Taylor & Wheeler) — from the two postulates to four-vectors, relativistic collisions, and the revelation that magnetism is relativity in disguise.",phase:4,chapters:[{id:"postulates-the-lorentz-transformation",title:"Postulates & the Lorentz Transformation",subtitle:"Deriving the Lorentz transformation and learning to read spacetime diagrams",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Two innocent-sounding postulates — physics looks the same in every inertial frame, and light\'s speed is the same for everyone — force a complete rebuild of space and time. This chapter derives the Lorentz transformation from them and introduces spacetime diagrams and the invariant interval, the tools that make relativity visual and computable rather than paradoxical and mysterious.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Derivation</li>\n  <li>Spacetime diagrams</li>\n  <li>The invariant interval</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"relativistic-kinematics",title:"Relativistic Kinematics",subtitle:"Velocity addition, the relativistic Doppler effect, and the classic paradoxes laid to rest",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Velocities do not simply add near light speed, and the Doppler effect picks up a relativistic twist that astronomers use daily to read the expansion of the universe. The heart of this chapter is confronting the famous "paradoxes" — the twins, the pole in the barn — and resolving each one cleanly, which is the true test that you understand relativity rather than merely knowing its formulas.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Velocity addition</li>\n  <li>Relativistic Doppler</li>\n  <li>The classic paradoxes resolved</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"four-vectors-dynamics",title:"Four-Vectors & Dynamics",subtitle:"4-momentum, E\xb2 = (pc)\xb2 + (mc\xb2)\xb2, and the physics of particle collisions",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Four-vectors unify energy and momentum into a single spacetime object, and suddenly relativistic dynamics becomes as systematic as Newtonian mechanics ever was. The master relation E\xb2 = (pc)\xb2 + (mc\xb2)\xb2 governs everything from nuclear binding energies to collider physics, and the collision techniques you learn here are exactly the ones particle physicists use to discover new particles.</p>\n<h3>Topics</h3>\n<ul>\n  <li>4-momentum</li>\n  <li>E\xb2 = (pc)\xb2 + (mc\xb2)\xb2</li>\n  <li>Collisions & particle creation</li>\n  <li>Mass–energy</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"relativity-electromagnetism",title:"Relativity & Electromagnetism",subtitle:"How E and B mix between frames — magnetism unmasked as a relativistic effect",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Here is one of the most beautiful results in physics: electric and magnetic fields are not separate things but two faces of one entity, mixing into each other when you change reference frames. The magnetic force from a current-carrying wire can be derived as a purely electric effect seen from a moving frame — magnetism is relativity you can demonstrate with a battery and a compass. This insight sets up the covariant electrodynamics of Phase 5.</p>\n<h3>Topics</h3>\n<ul>\n  <li>How E and B mix between frames</li>\n  <li>Magnetism as a relativistic effect</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"toward-general-relativity",title:"Toward General Relativity",subtitle:"The equivalence principle, gravitational time dilation, and why GPS needs Einstein",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Einstein called it his happiest thought: a person in free fall feels no gravity, which means gravity and acceleration are locally indistinguishable. From that equivalence principle alone you can derive gravitational time dilation — clocks tick slower deeper in a gravity well — an effect GPS satellites must correct for every second to keep your position accurate. This chapter is the bridge to the full theory of curved spacetime waiting in Phase 6.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The equivalence principle</li>\n  <li>Gravitational time dilation</li>\n  <li>GPS</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]}]},{id:"differential-equations-linear-algebra",number:22,title:"Differential Equations & Linear Algebra",description:"The MIT 18.03 + 18.06 (Strang) pair in one subject — second-order ODEs, eigenvalue problems, and inner-product spaces, timed so that linear algebra lands immediately before the quantum formalism that is built on it.",phase:4,chapters:[{id:"second-order-odes",title:"Second-Order ODEs",subtitle:"Constant-coefficient linear equations and the mathematics behind resonance",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Second-order linear ODEs are the equations of oscillation, and here you learn to solve them completely and systematically. Every damped, driven oscillator you met in mechanics and every RLC circuit from electromagnetism is a special case — and resonance, treated mathematically at last, explains precisely when and why a driven system\'s response blows up.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Linear ODEs with constant coefficients</li>\n  <li>Oscillator applications</li>\n  <li>Resonance, mathematically</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"systems-of-odes-phase-portraits",title:"Systems of ODEs & Phase Portraits",subtitle:"Coupled equations, eigen-analysis, and reading stability from phase portraits",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Real systems have many interacting variables, so their equations of motion couple together — and eigenvalues are what untangle them. This chapter teaches you to analyze systems of ODEs, draw phase portraits, and classify equilibria by stability at a glance. These are the exact tools behind normal modes, chaos theory in Classical Mechanics II, and dynamical systems everywhere from ecology to engineering.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Coupled systems</li>\n  <li>Eigen-analysis of systems</li>\n  <li>Stability</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"laplace-transforms-greens-function-idea",title:"Laplace Transforms & Green's-Function Idea",subtitle:"Transform methods and the impulse-response way of thinking",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Transform methods convert differential equations into algebra: solve, transform back, done. Beyond the technique, this chapter plants a deep idea — characterize a system by its response to a single sharp kick (the impulse response), and you can build its response to anything by superposition. That Green\'s-function way of thinking recurs in electrodynamics, quantum mechanics, and field theory.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Transform methods</li>\n  <li>Impulse response</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"linear-algebra-core",title:"Linear Algebra Core",subtitle:"Vector spaces, bases, and matrices as transformations",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Linear algebra is the language quantum mechanics is written in, and this chapter builds it properly: vector spaces as abstract structures, bases as coordinate choices, and matrices as transformations rather than grids of numbers. When quantum mechanics declares that "states are vectors," everything you learn here is what makes that sentence meaningful.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Vector spaces</li>\n  <li>Linear independence & bases</li>\n  <li>Matrices as transformations</li>\n  <li>Determinants</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"eigenvalues-diagonalization",title:"Eigenvalues & Diagonalization",subtitle:"Eigenproblems, Hermitian matrices, and normal modes seen through new eyes",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Eigenvectors are the directions a transformation merely stretches, and finding them — diagonalization — is the single most useful computation in applied mathematics. Symmetric and Hermitian matrices, with their real eigenvalues and orthogonal eigenvectors, are precisely the mathematical objects quantum mechanics will use to represent observables; the normal modes you found by physical intuition in the waves course reappear here as a clean eigenproblem.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Eigenproblems</li>\n  <li>Symmetric/Hermitian matrices</li>\n  <li>Quadratic forms</li>\n  <li>Normal modes revisited</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"inner-product-spaces",title:"Inner-Product Spaces",subtitle:"Orthogonality, projections, and function spaces — the quantum-ready chapter",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The dot product generalizes into the inner product, bringing geometry — lengths, angles, orthogonality — to abstract vector spaces, including spaces whose "vectors" are functions. The stunning payoff: Fourier series is just projection onto an orthogonal basis of sines and cosines. This is the quantum-ready chapter — wavefunctions live in exactly such a space, and expansion in eigenstates is exactly this projection.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Orthogonality</li>\n  <li>Projections</li>\n  <li>Gram–Schmidt</li>\n  <li>Function spaces & Fourier as linear algebra — the quantum-ready chapter</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]}]},{id:"mathematical-methods",number:23,title:"Mathematical Methods for Physicists",description:"The Boas-level math-methods spine (with Riley/Hobson/Bence for depth) — complex analysis, variational calculus, PDEs, transforms, tensors, probability, and a first taste of group theory: every tool the theoretical core four will demand.",phase:5,chapters:[{id:"complex-analysis",title:"Complex Analysis",subtitle:"Analytic functions, contour integration, and residues — magic that computes real integrals",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Functions of a complex variable are astonishingly well-behaved: differentiable once means differentiable forever, and integrals around closed contours are determined entirely by a few special points inside. The residue theorem turns impossible-looking real integrals into short exercises, and complex methods run beneath the surface of scattering theory, Green\'s functions, and quantum field theory.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Analytic functions</li>\n  <li>Contour integration</li>\n  <li>Residues</li>\n  <li>Physical applications</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"calculus-of-variations",title:"Calculus of Variations",subtitle:"Functionals and the Euler–Lagrange equation — the door to Lagrangian mechanics",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Instead of asking "where is this function smallest?", the calculus of variations asks "which entire path makes this quantity smallest?" — and the Euler–Lagrange equation answers it. The brachistochrone (fastest descent curve) is the classic showcase, but the real reason this chapter sits here is timing: it is the door to Lagrangian mechanics, where all of classical physics is rewritten as a single optimization principle.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Functionals</li>\n  <li>The Euler–Lagrange equation</li>\n  <li>Brachistochrone</li>\n  <li>Constraints — the door to Lagrangian mechanics</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"partial-differential-equations",title:"Partial Differential Equations",subtitle:"Laplace, heat, and wave equations solved by separation of variables in every coordinate system",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The fundamental equations of physics — Laplace, heat, wave, Schr\xf6dinger — are partial differential equations, and separation of variables is the master technique for solving them. Practicing it in Cartesian, cylindrical, and spherical coordinates prepares you for the two flagship calculations ahead: boundary-value problems in electrodynamics and the hydrogen atom in quantum mechanics.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Laplace, heat, and wave equations</li>\n  <li>Separation of variables in Cartesian, cylindrical, spherical coordinates</li>\n  <li>Boundary-value problems</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"special-functions",title:"Special Functions",subtitle:"Legendre, Bessel, Hermite, spherical harmonics, and the unifying Sturm–Liouville theory",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Separate variables in a round or spherical problem and special functions appear automatically: Legendre polynomials, Bessel functions, spherical harmonics. Far from being a zoo of formulas, they are unified by Sturm–Liouville theory — each family is an orthogonal basis, exactly like sines and cosines. Spherical harmonics in particular will label the shapes of atomic orbitals; Hermite polynomials will build the quantum oscillator.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Legendre & Bessel functions</li>\n  <li>Hermite polynomials</li>\n  <li>Spherical harmonics</li>\n  <li>Sturm–Liouville theory & orthogonality</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"fourier-integral-transforms",title:"Fourier & Integral Transforms",subtitle:"Fourier transforms, convolution, the Dirac delta, and Green's functions",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>The Fourier transform extends Fourier series to non-periodic functions, translating between position and frequency descriptions of the same physics — the mathematical backbone of the quantum position–momentum relationship. Alongside it you meet the Dirac delta (the idealized point impulse), convolution, and Green's functions in full: solve for a point source once, superpose, and you have solved for every source.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Fourier transforms</li>\n  <li>Convolution</li>\n  <li>The Dirac delta</li>\n  <li>Green's functions</li>\n</ul>\n<div class=\"key-concept\">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>"}],quiz:[]},{id:"tensors-index-notation",title:"Tensors & Index Notation",subtitle:"Einstein summation, Kronecker delta, Levi-Civita, and the inertia tensor",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Index notation with the Einstein summation convention compresses pages of vector algebra into single lines — and the Kronecker delta and Levi-Civita symbols make identities like the double cross product almost mechanical. Tensors themselves, introduced here through the concrete inertia tensor of a rigid body, are the objects general relativity is written in; this chapter is where that language training begins.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Einstein summation</li>\n  <li>Kronecker delta & Levi-Civita</li>\n  <li>Cartesian tensors</li>\n  <li>The inertia tensor</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]},{id:"probability-for-physics",title:"Probability for Physics",subtitle:"Distributions, the central limit theorem, random walks, and the stat-mech toolkit",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Statistical mechanics is applied probability, and this chapter assembles its toolkit: distributions, the central limit theorem (why the Gaussian appears everywhere), random walks, and the two workhorses of every partition-function calculation — Stirling's formula and Gaussian integrals. Entropy, temperature, and the arrow of time will all be built from the combinatorics you master here.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Distributions</li>\n  <li>Central limit theorem</li>\n  <li>Random walks</li>\n  <li>Stirling's formula & Gaussian integrals — the stat-mech toolkit</li>\n</ul>\n<div class=\"key-concept\">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>"}],quiz:[]},{id:"group-theory-primer",title:"Group Theory Primer",subtitle:"Symmetry groups, representations, and a first look at SO(3) and SU(2)",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Group theory is the mathematics of symmetry, and modern physics is organized around it: conservation laws, particle classifications, and selection rules all flow from symmetry groups and their representations. This primer introduces the key ideas gently, previewing the rotation groups SO(3) and SU(2) whose strange double-cover relationship is the mathematical origin of spin-\xbd — and whose bigger cousins classify the particles of the Standard Model.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Symmetry groups</li>\n  <li>The representation idea</li>\n  <li>Rotations, SO(3) and SU(2) preview</li>\n</ul>\n<div class="key-concept">\n  <h4>Status</h4>\n  <p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p>\n</div>'}],quiz:[]}]},{id:"classical-mechanics-2",number:24,title:"Classical Mechanics II — Lagrangian & Hamiltonian",description:"Mechanics reborn from a single principle — least action. Lagrangians, Noether's theorem, rigid bodies, Hamiltonian phase space, and chaos, at the Taylor/Landau level.",phase:5,chapters:[{id:"principle-of-least-action",title:"The Principle of Least Action",subtitle:"All of mechanics from one variational statement",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Nature extremizes action — and from that single statement all of Newtonian mechanics follows. Armed with the calculus of variations from Subject 23, you\'ll reformulate mechanics in generalized coordinates where constraints handle themselves.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The variational formulation</li>\n  <li>Generalized coordinates</li>\n  <li>Constraints</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"lagrangian-mechanics",title:"Lagrangian Mechanics",subtitle:"Euler–Lagrange in practice — problems Newton's laws make painful",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Write L = T − V, turn the crank, and equations of motion fall out — no force diagrams, no constraint forces. Cyclic coordinates hand you conservation laws for free, and effective potentials tame two-dimensional problems.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Euler–Lagrange in practice</li>\n  <li>Cyclic coordinates</li>\n  <li>Effective-potential problems</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"symmetry-and-conservation",title:"Symmetry & Conservation",subtitle:"Noether's theorem — why conservation laws exist at all",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Emmy Noether proved the deepest theorem in classical physics: every continuous symmetry implies a conservation law. Time symmetry gives energy, space symmetry gives momentum, rotational symmetry gives angular momentum. This idea organizes all of modern physics, from particle physics to cosmology.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Noether\'s theorem</li>\n  <li>The deep meaning of conservation laws</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"central-forces-revisited",title:"Two-Body & Central Forces Revisited",subtitle:"Reduced mass, orbits, and the language of scattering",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The two-body problem collapses to one body with a reduced mass, and orbits follow elegantly. Then the setup inverts: instead of bound orbits, particles fly past and scatter — introducing the cross sections that nuclear and particle physics (Subject 31) measure daily.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Reduced mass</li>\n  <li>Scattering</li>\n  <li>Cross sections</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"rigid-body-motion",title:"Rigid-Body Motion",subtitle:"Euler angles, the inertia tensor, and why tops don't fall",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Real rotation is gloriously three-dimensional: the inertia tensor (your Subject 23 tensors at work), Euler's angles and equations, and the gyroscopic precession that keeps a spinning top upright and torque-free satellites tumbling predictably.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Euler angles</li>\n  <li>The inertia tensor</li>\n  <li>Euler's equations</li>\n  <li>Tops &amp; precession</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"small-oscillations",title:"Small Oscillations",subtitle:"Normal modes as an eigenvalue problem — done right",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Every stable system oscillates harmonically near equilibrium. The normal-modes formalism diagonalizes the physics — literally: eigenvalues give frequencies, eigenvectors give mode shapes, and molecular vibration spectra follow.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The normal-modes formalism</li>\n  <li>Molecular vibrations</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"hamiltonian-mechanics",title:"Hamiltonian Mechanics",subtitle:"Phase space, Poisson brackets, and the doorway to quantum mechanics",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>The Legendre transform trades velocities for momenta and reveals mechanics as flow in phase space. Poisson brackets, Liouville's theorem, and canonical transformations aren't just elegant — they are the exact classical skeleton onto which quantum mechanics grafts (Poisson brackets become commutators).</p>\n<h3>Topics</h3>\n<ul>\n  <li>Legendre transform</li>\n  <li>Phase space</li>\n  <li>Poisson brackets</li>\n  <li>Liouville's theorem</li>\n  <li>Canonical transformations</li>\n  <li>Hamilton–Jacobi glimpse</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"nonlinear-dynamics-chaos",title:"Nonlinear Dynamics & Chaos",subtitle:"Deterministic yet unpredictable — sensitivity and strange attractors",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Determinism does not imply predictability: tiny differences in initial conditions grow exponentially. The driven pendulum from Phase 4 returns as a gateway to attractors, bifurcations, and the modern science of chaos.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Sensitivity to initial conditions</li>\n  <li>Attractors</li>\n  <li>The driven pendulum revisited</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"classical-to-quantum-continuum",title:"From Classical to Quantum & Continuum",subtitle:"Action-angle variables, adiabatic invariants, and continuous media",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Two bridges out of particle mechanics: action-angle variables and adiabatic invariants (the historical route to quantization), and a taste of continuum mechanics — fluids and elasticity — where the Lagrangian idea extends to fields.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Action-angle variables &amp; adiabatic invariants</li>\n  <li>Fluids &amp; elasticity taste</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]},{id:"electrodynamics",number:25,title:"Electrodynamics",description:"The full Griffiths-level theory of the electromagnetic field: boundary-value problems, fields in matter, complete Maxwell equations, radiation, and the relativistic formulation.",phase:5,chapters:[{id:"electrostatics-redone",title:"Electrostatics Redone",subtitle:"Boundary-value problems — images, separation of variables, multipoles",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Electrostatics at full mathematical strength: Laplace\'s equation with your Subject 23 PDE toolkit, the sly method of images, separation of variables in spherical coordinates (hello, Legendre polynomials), and the multipole expansion that organizes any charge distribution.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Vector calculus at full strength</li>\n  <li>Boundary-value problems</li>\n  <li>Method of images</li>\n  <li>Separation of variables</li>\n  <li>Multipole expansion</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"fields-in-matter",title:"Fields in Matter",subtitle:"Polarization, magnetization, and the auxiliary fields D and H",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Real materials respond to fields: dielectrics polarize, magnetic materials magnetize. The auxiliary fields D and H keep the bookkeeping honest and explain everything from capacitor dielectrics to why iron is special.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Polarization &amp; the D field</li>\n  <li>Dielectrics</li>\n  <li>Magnetization &amp; the H field</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"magnetostatics-deepened",title:"Magnetostatics Deepened",subtitle:"The vector potential and magnetic multipoles",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The vector potential A steps out of the shadows — a calculational device here, but destined to become physically real in quantum mechanics (the Aharonov–Bohm effect of Subject 27) and fundamental in QFT.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The vector potential</li>\n  <li>Magnetic multipoles</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"maxwell-equations",title:"Electrodynamics & Maxwell's Equations",subtitle:"The complete field equations, their conservation laws, and gauge freedom",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Displacement current completes Maxwell's equations, and the theory's inner accounting emerges: field energy, field momentum, the Poynting vector, and the stress tensor. Gauge freedom — seemingly a technicality — foreshadows the organizing principle of the Standard Model.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Maxwell's equations complete</li>\n  <li>Gauge freedom</li>\n  <li>Field energy &amp; momentum</li>\n  <li>Poynting's theorem</li>\n  <li>The stress tensor</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"em-waves",title:"EM Waves",subtitle:"Light in vacuum, matter, and conductors — dispersion to waveguides",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Maxwell\'s equations sing: waves in vacuum, refraction and dispersion in media, attenuation in conductors, the Fresnel coefficients governing reflection, and the guided waves inside waveguides and optical fibers.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Waves in vacuum, media, and conductors</li>\n  <li>Dispersion</li>\n  <li>Waveguides</li>\n  <li>Reflection &amp; transmission (Fresnel)</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"potentials-and-radiation",title:"Potentials & Radiation",subtitle:"Retarded potentials and how accelerating charges shed light",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Causality enters through retarded potentials — fields today reflect charges as they were. Accelerating charges radiate: dipole radiation explains antennas and the blue sky, Larmor\'s formula counts the power, and synchrotron light powers modern materials science.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Retarded potentials</li>\n  <li>Dipole radiation</li>\n  <li>Antennas</li>\n  <li>The Larmor formula</li>\n  <li>Synchrotron &amp; bremsstrahlung glimpse</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"relativistic-electrodynamics",title:"Relativistic Electrodynamics",subtitle:"E and B unified in the field tensor",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The punchline of classical physics: electricity and magnetism are one field seen from different frames. The field tensor F^μν makes Maxwell\'s equations manifestly covariant — two tensor equations containing everything — and the fields of fast-moving charges follow by transformation.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The field tensor</li>\n  <li>Covariant Maxwell equations</li>\n  <li>Fields of moving charges</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]},{id:"quantum-mechanics-1",number:26,title:"Quantum Mechanics I",description:"The Griffiths-level first course: wavefunctions and the Schr\xf6dinger equation, the classic 1D problems, the Dirac formalism, the hydrogen atom, spin, and identical particles.",phase:5,chapters:[{id:"why-quantum",title:"Why Quantum",subtitle:"The experimental failures that forced a new physics",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Before the formalism, the evidence: blackbody radiation, the photoelectric effect, atomic spectra, and electron diffraction each broke classical physics in a specific way. Understanding exactly what failed makes the strange postulates ahead feel inevitable rather than arbitrary.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The failures of classical physics</li>\n  <li>The experiments that forced the theory</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"wavefunction-schrodinger",title:"The Wavefunction & Schr\xf6dinger Equation",subtitle:"ψ, probability, and the equation that runs the microworld",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The state of a particle is a complex-valued wavefunction whose square is a probability density — Born\'s rule. The Schr\xf6dinger equation (a PDE your Subject 23 methods handle) evolves it deterministically. Operators, expectation values, and normalization set up the machinery.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Probability interpretation</li>\n  <li>Normalization</li>\n  <li>Expectation values</li>\n  <li>Operators intro</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"one-dimensional-problems",title:"One-Dimensional Problems",subtitle:"Wells, barriers, tunnelling, and the harmonic oscillator",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The exactly-solvable classics: infinite and finite wells (energy quantization appears!), tunnelling through barriers (how the sun fuses and flash memory writes), the harmonic oscillator solved twice — analytically and with the elegant ladder operators — and wave packets for free particles.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Infinite &amp; finite wells</li>\n  <li>Tunnelling</li>\n  <li>Scattering off steps &amp; barriers</li>\n  <li>The harmonic oscillator (analytic + ladder operators)</li>\n  <li>Free particles &amp; wave packets</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"the-formalism",title:"The Formalism",subtitle:"Hilbert space, Dirac notation, and measurement — quantum mechanics as linear algebra",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The conceptual core: states are vectors in Hilbert space, observables are Hermitian operators, measurement yields eigenvalues — your Subject 22 linear algebra was all preparation for this chapter. The uncertainty principle stops being folklore and becomes a theorem.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Hilbert space</li>\n  <li>Dirac notation</li>\n  <li>Hermitian operators &amp; observables</li>\n  <li>Eigenvalues &amp; eigenstates</li>\n  <li>The uncertainty principle derived</li>\n  <li>Time evolution</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"qm-in-three-dimensions",title:"QM in Three Dimensions",subtitle:"The hydrogen atom — quantum mechanics's greatest exact triumph",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Separation of variables in spherical coordinates (spherical harmonics from Subject 23 return) cracks the hydrogen atom exactly: the quantum numbers n, l, m emerge naturally and the spectrum Bohr guessed is derived. This is the calculation that convinced physics quantum mechanics was true.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Separation in spherical coordinates</li>\n  <li>The hydrogen atom</li>\n  <li>Quantum numbers</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"angular-momentum-and-spin",title:"Angular Momentum & Spin",subtitle:"Ladder algebra and the two-valued mystery of spin-\xbd",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Angular momentum in quantum mechanics comes quantized, and the ladder-operator algebra derives it all from commutators alone. Then spin: an intrinsic angular momentum with no classical analog, revealed by Stern–Gerlach, described by two-component spinors — the qubit of quantum computing.</p>\n<h3>Topics</h3>\n<ul>\n  <li>L operators &amp; ladder algebra</li>\n  <li>Spin-\xbd</li>\n  <li>Stern–Gerlach</li>\n  <li>Addition of angular momenta intro</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"identical-particles",title:"Identical Particles",subtitle:"Bosons, fermions, and why chemistry exists",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Identical quantum particles are radically identical — swapping them changes nothing observable, which splits the world into bosons and fermions. The Pauli exclusion principle follows, and with it the shell structure of atoms: the periodic table, and hence chemistry, explained from symmetry.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Bosons &amp; fermions</li>\n  <li>The Pauli principle</li>\n  <li>The periodic table explained</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]},{id:"quantum-mechanics-2",number:27,title:"Quantum Mechanics II",description:"The Shankar/Sakurai-level second pass: symmetries, perturbation theory, scattering, entanglement and Bell's theorem, and Feynman's path integrals.",phase:5,chapters:[{id:"formalism-deepened",title:"Formalism Deepened",subtitle:"Pictures, symmetries, and the generators of transformations",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The formalism matures: Schr\xf6dinger and Heisenberg pictures as two views of the same physics, and the profound identification of momentum as the generator of translations and angular momentum of rotations — Noether\'s theorem reborn in quantum form.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Schr\xf6dinger vs Heisenberg pictures</li>\n  <li>Symmetries &amp; unitary operators</li>\n  <li>Translation &amp; rotation generators</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"time-independent-perturbation",title:"Time-Independent Perturbation Theory",subtitle:"Systematic approximation — fine structure, Zeeman, and Stark",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Almost nothing is exactly solvable; perturbation theory is how quantum mechanics earns its living. Nondegenerate and degenerate machinery, then the payoff: hydrogen\'s fine structure and the Zeeman and Stark effects that split spectral lines in fields.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Nondegenerate &amp; degenerate cases</li>\n  <li>Fine structure</li>\n  <li>Zeeman &amp; Stark effects</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"variational-wkb",title:"Variational & WKB Methods",subtitle:"Bounding ground states and estimating tunnelling",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Two more tools for the intractable: the variational principle (guess a wavefunction, get a rigorous upper bound on the ground-state energy — the workhorse of quantum chemistry) and the WKB approximation for barrier penetration and tunnelling rates.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The approximation toolkit</li>\n  <li>Tunnelling rates</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"time-dependent-perturbations",title:"Time-Dependent Perturbations",subtitle:"Fermi's golden rule — transitions, selection rules, and lasers",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Turn on a time-varying field and states transition: Fermi's golden rule gives the rates, selection rules say which jumps are allowed, and stimulated emission — Einstein's 1917 insight — becomes the working principle of every laser.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Fermi's golden rule</li>\n  <li>Radiative transitions</li>\n  <li>Selection rules</li>\n  <li>How lasers work</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"scattering-theory",title:"Scattering Theory",subtitle:"Partial waves and the Born approximation — how we probe matter",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Nearly everything we know about the subatomic world comes from throwing particles at things. Partial-wave analysis and the Born approximation turn detector counts into structure — the theory behind Rutherford\'s nucleus and the LHC alike.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Partial waves</li>\n  <li>The Born approximation</li>\n  <li>Cross sections</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"entanglement-interpretation",title:"Entanglement & Interpretation",subtitle:"EPR, Bell's theorem, decoherence — and quantum information",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>The chapter Einstein started: entangled states, the EPR argument, and Bell's inequalities — which experiment has decisively settled against local realism. Decoherence explains the classical world's emergence, and qubits turn the weirdness into a technology.</p>\n<h3>Topics</h3>\n<ul>\n  <li>EPR</li>\n  <li>Bell inequalities</li>\n  <li>Decoherence</li>\n  <li>The measurement problem</li>\n  <li>Qubits &amp; quantum information taste</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"path-integrals-glimpses",title:"Path Integrals & Advanced Glimpses",subtitle:"Feynman's sum over histories, Aharonov–Bohm, and Berry phase",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Feynman's third formulation: the particle takes every path, each weighted by its action — reconnecting quantum mechanics to Subject 24's least-action principle and opening the road to QFT. The Aharonov–Bohm effect and Berry phase reveal geometry hiding in quantum phases.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Feynman's sum over histories</li>\n  <li>Aharonov–Bohm</li>\n  <li>Berry phase glimpse</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]}]},{id:"statistical-mechanics",number:28,title:"Thermodynamics & Statistical Mechanics",description:"The Schroeder-level statistical theory of heat: entropy as counting, partition functions, quantum statistics from electron gases to Bose–Einstein condensates, and phase transitions.",phase:5,chapters:[{id:"first-law-revisited",title:"Energy & the First Law Revisited",subtitle:"Equilibrium, equipartition, and the microscopic ideal gas",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The thermal physics of Phase 3 returns with statistical foundations: what equilibrium really is, the ideal gas from molecular degrees of freedom, and the equipartition theorem that assigns \xbdkT to each — along with its famous failures that only quantum mechanics explains.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Equilibrium</li>\n  <li>The ideal gas microscopically</li>\n  <li>Equipartition</li>\n  <li>Heat &amp; work</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"entropy-second-law",title:"Entropy & the Second Law",subtitle:"S = k log W — entropy as counting, temperature as a definition",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The most profound idea in the subject: entropy simply counts microstates, and the second law is just probability at astronomical odds. Your combinatorics and Stirling\'s formula from Subject 23 derive it, and temperature itself gets defined statistically — 1/T = ∂S/∂E.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Multiplicity &amp; combinatorics</li>\n  <li>Boltzmann entropy</li>\n  <li>Temperature defined statistically</li>\n  <li>The third law</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"engines-free-energy",title:"Engines & Free Energy",subtitle:"Carnot's limit, thermodynamic potentials, and Maxwell relations",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Classical thermodynamics at full power: Carnot\'s absolute efficiency limit, the free energies that determine what happens at constant temperature and pressure, the Maxwell relations (partial-derivative identities doing real work), and the chemical potential that governs phase equilibria.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Carnot properly</li>\n  <li>Thermodynamic potentials</li>\n  <li>Maxwell relations</li>\n  <li>Phase equilibria</li>\n  <li>Chemical potential</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"boltzmann-statistics",title:"Boltzmann Statistics",subtitle:"The partition function — the machine that computes everything",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The canonical ensemble\'s Boltzmann factor e^(−E/kT) and its partition function Z form the central machine of statistical mechanics: differentiate Z correctly and any thermodynamic quantity drops out. Paramagnets, oscillators, and molecular gases put the machine to work.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The canonical ensemble</li>\n  <li>Partition-function machinery</li>\n  <li>Applications (paramagnets, oscillators, molecules)</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"quantum-statistics",title:"Quantum Statistics",subtitle:"Fermi–Dirac, Bose–Einstein, and blackbody radiation derived",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>When particles are identical (Subject 26), statistics change: Fermi–Dirac for fermions explains metals and white-dwarf stability; Bose–Einstein for bosons yields the Planck blackbody law — the formula that started quantum theory — plus Debye\'s solids and Bose–Einstein condensation.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The Gibbs factor</li>\n  <li>Fermi–Dirac &amp; Bose–Einstein</li>\n  <li>The electron gas</li>\n  <li>Blackbody radiation derived</li>\n  <li>Bose–Einstein condensation</li>\n  <li>Debye solids</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"phase-transitions",title:"Phase Transitions & Critical Phenomena",subtitle:"The Ising model, universality, and the renormalization idea",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>How does short-range order produce sudden global change — boiling, magnetization, superconductivity? The Ising model and mean-field theory give the classic answers; universality and the renormalization group reveal why wildly different systems share identical critical behavior.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The Ising model</li>\n  <li>Mean-field theory</li>\n  <li>Universality</li>\n  <li>The renormalization idea</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"transport-fluctuations",title:"Transport & Fluctuations",subtitle:"Random walks, Brownian motion, and fluctuation–dissipation",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Statistical mechanics away from equilibrium: random walks becoming diffusion, Einstein\'s Brownian-motion analysis (which finally proved atoms exist), and the fluctuation–dissipation idea linking spontaneous jiggling to friction.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Random walks &amp; diffusion</li>\n  <li>Brownian motion</li>\n  <li>Fluctuation–dissipation glimpse</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]},{id:"computational-physics",number:29,title:"Computational Physics",description:"Physics's third pillar alongside theory and experiment: simulate motion, chaos, quantum wavefunctions, and the Ising model in Python — and analyze data like an experimentalist.",phase:5,chapters:[{id:"tools",title:"Tools",subtitle:"Python, NumPy, and plotting — the working physicist's stack",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The modern physicist\'s laboratory is often a laptop. Set up Python with NumPy for fast arrays, Matplotlib for publication-quality plots, and notebooks for reproducible explorations — the stack used from undergraduate labs to LIGO.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Python &amp; NumPy for physics</li>\n  <li>Plotting</li>\n  <li>Notebooks</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"solving-motion-numerically",title:"Solving Motion Numerically",subtitle:"From Euler to RK4 — drag, chaos, and N-body orbits",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Most differential equations have no closed-form solution; numerics doesn't care. Build up from Euler's method to RK4, then simulate what analytic methods can't touch: projectiles with realistic drag, the chaotic double pendulum, and gravitational N-body systems.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Euler → RK4</li>\n  <li>Projectile with drag</li>\n  <li>The double pendulum (chaos)</li>\n  <li>N-body orbits</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"monte-carlo-methods",title:"Monte Carlo Methods",subtitle:"Random numbers as a computational superpower",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Randomness computes: Monte Carlo integration beats deterministic methods in high dimensions, and the Metropolis algorithm brings Subject 28\'s Ising model to life on screen — watching magnetization emerge and critical fluctuations diverge.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Random numbers</li>\n  <li>Monte Carlo integration</li>\n  <li>Simulating the Ising model</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"pdes-waves-numerically",title:"PDEs & Waves Numerically",subtitle:"Heat, waves, Laplace, and the Schr\xf6dinger equation on a grid",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Discretize space and time and the great PDEs of physics become loops: the heat and wave equations, relaxation methods for Laplace boundary-value problems, and the time-dependent Schr\xf6dinger equation — watch a wave packet actually tunnel.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Heat &amp; wave equations</li>\n  <li>Relaxation for Laplace</li>\n  <li>The time-dependent Schr\xf6dinger equation</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"data-and-fitting",title:"Data & Fitting",subtitle:"Least squares, uncertainty, and honest model comparison",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The experimentalist\'s essential skill set: least-squares fitting, propagating uncertainties, judging goodness of fit, and comparing models honestly — the difference between a measurement and a number.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Least squares</li>\n  <li>Uncertainty</li>\n  <li>Model comparison — real lab-analysis skills</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]},{id:"solid-state-physics",number:30,title:"Solid State Physics",description:"Why solids are the way they are, at the level of Simon's Oxford Solid State Basics: crystals, phonons, band theory, semiconductors, magnetism, and superconductivity.",phase:6,chapters:[{id:"bonding-crystal-structure",title:"Bonding & Crystal Structure",subtitle:"Lattices, the reciprocal lattice, and X-ray diffraction",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Crystals are nature\'s periodic tables in space. Learn the lattice language, then the reciprocal lattice — the Fourier transform of a crystal (Subject 23 pays off again) — and how X-ray diffraction reads atomic arrangements, the technique that later revealed DNA.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Lattices</li>\n  <li>The reciprocal lattice</li>\n  <li>X-ray diffraction</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"vibrations-phonons",title:"Vibrations & Phonons",subtitle:"Quantized lattice waves and the heat capacity of solids",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Atoms in a crystal vibrate collectively, and quantum mechanics quantizes those waves into phonons — particles of sound. Dispersion relations from 1D chains, then the Einstein and Debye models that finally explained solid heat capacities where classical physics failed.</p>\n<h3>Topics</h3>\n<ul>\n  <li>1D chains</li>\n  <li>Dispersion relations</li>\n  <li>Heat capacity (Einstein &amp; Debye models)</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"electrons-in-solids",title:"Electrons in Solids",subtitle:"Bloch's theorem and band structure — why metals conduct and glass doesn't",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Free electrons in a periodic potential organize into bands separated by gaps — Bloch's theorem is the key. Band filling then dictates everything: metals, insulators, and the semiconductors in between. This is Subject 26's quantum mechanics scaled to 10\xb2\xb3 particles.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The free-electron gas</li>\n  <li>Bloch's theorem</li>\n  <li>Band structure</li>\n  <li>Nearly-free &amp; tight-binding models</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"semiconductors",title:"Semiconductors",subtitle:"Doping, junctions, transistors — band theory becomes civilization",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The payoff chapter: doping engineers carriers, pn junctions rectify, transistors switch, LEDs glow, and solar cells harvest. If you\'ve taken the LearnSemi course, this is where its physics gets first-principles foundations.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Bands</li>\n  <li>Doping</li>\n  <li>pn junctions</li>\n  <li>Transistors</li>\n  <li>LEDs &amp; solar cells</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"magnetism-superconductivity",title:"Magnetism & Superconductivity",subtitle:"Collective quantum order — from ferromagnets to zero resistance",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Matter's collective quantum phases: dia-, para-, and ferromagnetism from electron spins, then superconductivity — zero resistance and expelled fields — via London theory and a glimpse of BCS pairing, ending at today's quantum materials frontier.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Dia-, para-, ferromagnetism</li>\n  <li>London theory</li>\n  <li>BCS glimpse</li>\n  <li>Quantum materials outlook</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]}]},{id:"nuclear-particle-physics",number:31,title:"Nuclear & Particle Physics",description:"From the nucleus to the Standard Model at the Griffiths/Krane level: binding energy, decay and fusion, detectors, quarks and leptons, broken symmetries, and the open questions beyond.",phase:6,chapters:[{id:"nuclear-structure",title:"Nuclear Structure",subtitle:"Binding energy, the shell model, and the valley of stability",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Inside the nucleus: the semi-empirical binding-energy curve that explains which nuclei exist, the shell model with its magic numbers (Subject 26\'s quantum mechanics in a new potential), and the systematics of nuclear stability.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Binding energy</li>\n  <li>The shell model</li>\n  <li>Stability</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"nuclear-processes",title:"Nuclear Processes",subtitle:"Decay theory, fission reactors, and fusion in stars and on Earth",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Nuclear transformation quantified: decay theory (Fermi\'s golden rule from Subject 27 in action), the controlled chain reactions inside power reactors, and fusion — the process powering every star and the goal of ITER.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Decay theory</li>\n  <li>Fission &amp; reactors</li>\n  <li>Fusion in stars and on Earth</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"particle-zoo-detectors",title:"The Particle Zoo & Detectors",subtitle:"Accelerators, detectors, and the discovery century",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>How particle physics actually happens: the accelerators that concentrate energy, the layered detectors that reconstruct collisions, and the discovery history from the positron through the muon puzzle to the quark hypothesis.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Accelerators</li>\n  <li>Detectors</li>\n  <li>The discovery history</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"standard-model",title:"The Standard Model",subtitle:"Quarks, leptons, force carriers — and how to read a Feynman diagram",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The most precisely tested theory in science: six quarks, six leptons, and the gauge bosons carrying three forces. You\'ll learn to read Feynman diagrams as physical processes and survey QED, QCD, and the weak interaction — the frontier Subject 34 formalizes.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Quarks &amp; leptons</li>\n  <li>Forces &amp; bosons</li>\n  <li>Reading Feynman diagrams</li>\n  <li>QED, QCD, weak-interaction overview</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"symmetries-conservation",title:"Symmetries & Conservation",subtitle:"Isospin, parity violation, CP, and oscillating neutrinos",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Symmetry organizes particle physics — and its violations write history: parity falls in weak decays, CP violation hints at why matter exists at all, and neutrino oscillations (a quantum interference effect light-years long) prove neutrinos have mass.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Isospin</li>\n  <li>Parity violation</li>\n  <li>CP</li>\n  <li>Neutrino oscillations</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"beyond-standard-model",title:"Beyond the Standard Model",subtitle:"The Higgs, dark matter, and the great open problems",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The 2012 Higgs discovery completed the Standard Model — and sharpened its mysteries: what is dark matter, why is the Higgs so light (the hierarchy problem), and why did matter beat antimatter? The honest state of the frontier.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The Higgs discovery</li>\n  <li>Dark matter</li>\n  <li>The hierarchy problem</li>\n  <li>Baryogenesis — the open questions</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]},{id:"astrophysics-cosmology",number:32,title:"Astrophysics & Cosmology",description:"The universe as a physics laboratory, at the Carroll & Ostlie/Ryden level: telescopes and distances, stellar structure and death, galaxies and dark matter, and the Big Bang's evidence.",phase:6,chapters:[{id:"observing-the-universe",title:"Observing the Universe",subtitle:"Telescopes, the distance ladder, and magnitudes",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Astronomy\'s first problem is knowing how far away anything is. Climb the distance ladder from parallax to standard candles, learn the magnitude system, and survey how telescopes across the electromagnetic spectrum (and now gravitational waves) observe the cosmos.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Telescopes across the spectrum</li>\n  <li>The distance ladder</li>\n  <li>Magnitudes</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"stars",title:"Stars",subtitle:"Stellar structure, nuclear burning, and the HR diagram",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>A star is a self-gravitating fusion reactor in equilibrium — four coupled differential equations describe it entirely. Nuclear burning chains, the Hertzsprung–Russell diagram as a stellar family portrait, and the evolutionary tracks stars follow across it.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Stellar-structure equations</li>\n  <li>Nuclear burning</li>\n  <li>The HR diagram</li>\n  <li>Stellar evolution</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"stellar-endpoints",title:"Stellar Endpoints",subtitle:"White dwarfs, neutron stars, black holes, and supernovae",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>How stars die depends on mass: white dwarfs held up by electron degeneracy (Subject 28\'s Fermi gas in the sky), neutron stars spinning as pulsars, supernovae that forge the heavy elements — and black holes, where Subject 33 takes over.</p>\n<h3>Topics</h3>\n<ul>\n  <li>White dwarfs</li>\n  <li>Neutron stars &amp; pulsars</li>\n  <li>Astrophysical black holes</li>\n  <li>Supernovae</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"galaxies-large-scale-structure",title:"Galaxies & Large-Scale Structure",subtitle:"The Milky Way, galaxy types, and the case for dark matter",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Zoom out to galaxies: our Milky Way's anatomy, Hubble's classification, and the flat rotation curves plus cluster dynamics and lensing that make dark matter the most parsimonious explanation — evidence you can now weigh critically.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The Milky Way</li>\n  <li>Galaxy types</li>\n  <li>The dark-matter evidence</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"cosmology",title:"Cosmology",subtitle:"The expanding universe — Big Bang nucleosynthesis, the CMB, and dark energy",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The universe has a history: Hubble expansion, the primordial furnace that fixed the light-element abundances, the cosmic microwave background\'s baby picture, and the accelerating expansion attributed to dark energy — assembled into the remarkably precise ΛCDM timeline.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Hubble expansion</li>\n  <li>The FRW universe</li>\n  <li>Big Bang nucleosynthesis</li>\n  <li>The CMB</li>\n  <li>Dark energy</li>\n  <li>Inflation</li>\n  <li>The timeline of the universe</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]},{id:"general-relativity",number:33,title:"General Relativity",description:"Einstein's theory of gravity at the Hartle/Schutz 'physics-first' level: curved spacetime, the field equations, black holes, gravitational waves, and relativistic cosmology.",phase:6,chapters:[{id:"mathematics-of-curved-spacetime",title:"The Mathematics of Curved Spacetime",subtitle:"Metrics, tensors, geodesics, and curvature",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The language first: metrics measure spacetime, tensors (Subject 23\'s index gymnastics, now essential) keep equations frame-independent, geodesics are the straightest possible paths, and the covariant derivative quantifies curvature.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Manifolds &amp; metrics</li>\n  <li>Tensors properly</li>\n  <li>Geodesics</li>\n  <li>Covariant derivative &amp; curvature</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"equivalence-to-field-equations",title:"From Equivalence Principle to Field Equations",subtitle:"Einstein's 'happiest thought' becomes G = 8πT",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Free fall feels like no gravity at all — from that equivalence principle, Einstein reasoned his way to the field equations: matter tells spacetime how to curve, spacetime tells matter how to move. The weak-field limit recovers Newton, as it must.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Newton → Einstein</li>\n  <li>The Einstein equations</li>\n  <li>The weak-field limit</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"schwarzschild-solution",title:"The Schwarzschild Solution",subtitle:"The classic tests — precession, light bending, redshift, GPS",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The first exact solution describes spacetime outside any spherical mass. From it: Mercury\'s anomalous perihelion precession explained, starlight bending measured in 1919, gravitational redshift — and the GPS corrections without which navigation would drift kilometers per day.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Orbits</li>\n  <li>Perihelion precession</li>\n  <li>Light bending</li>\n  <li>Gravitational redshift</li>\n  <li>GPS revisited</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"black-holes",title:"Black Holes",subtitle:"Event horizons, rotating Kerr holes, and Hawking's thermodynamics",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Where Schwarzschild's solution turns extreme: event horizons as one-way membranes, the rotating Kerr geometry that real astrophysical black holes follow, and black-hole thermodynamics — Hawking radiation's still-unresolved challenge to quantum theory.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Event horizons</li>\n  <li>The Kerr glimpse</li>\n  <li>Black-hole thermodynamics (Hawking glimpse)</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"gravitational-waves",title:"Gravitational Waves",subtitle:"Ripples in spacetime — the physics of LIGO",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Linearize Einstein\'s equations and spacetime waves: stretching space by parts in 10\xb2\xb9, detected at last in 2015. The interferometry of LIGO, the chirp of merging black holes, and the multimessenger astronomy the discovery unlocked.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Linearized theory</li>\n  <li>The physics of LIGO</li>\n  <li>Multimessenger astronomy</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"relativistic-cosmology",title:"Relativistic Cosmology",subtitle:"The Friedmann equations — the universe as a GR solution",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Apply Einstein's equations to the universe itself: the FRW metric from symmetry, the Friedmann equations governing expansion, and the cosmological constant Einstein regretted — now resurrected as dark energy. Subject 32's observational cosmology gets its theoretical engine.</p>\n<h3>Topics</h3>\n<ul>\n  <li>FRW derived</li>\n  <li>The Friedmann equations</li>\n  <li>The cosmological constant</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]}]},{id:"quantum-fields-frontier",number:34,title:"Quantum Fields & the Frontier",description:"The gateway course (Lancaster & Blundell level): why fields replace particles, quantization and Feynman diagrams, gauge symmetry and the Higgs, and an honest map of what physics doesn't know.",phase:6,chapters:[{id:"why-fields",title:"Why Fields",subtitle:"Relativity + quantum mechanics forces field theory",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Marry special relativity to quantum mechanics and single-particle theories break — particle number won't stay fixed. The resolution: fields are fundamental, particles are their excitations. Creation and annihilation operators (Subject 26's ladder algebra promoted) make it precise.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The problems of relativistic QM</li>\n  <li>Creation &amp; annihilation</li>\n  <li>The second-quantization idea</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"canonical-quantization-taste",title:"A Taste of Canonical Quantization",subtitle:"The Klein–Gordon field as infinitely many oscillators",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>Quantize the simplest relativistic field: the Klein–Gordon field decomposes into harmonic oscillators (one per momentum), and quantizing each yields particles as quanta. The harmonic oscillator you\'ve now solved four ways turns out to be the foundation of reality.</p>\n<h3>Topics</h3>\n<ul>\n  <li>Klein–Gordon</li>\n  <li>The quantum field as a set of oscillators</li>\n  <li>Particles as excitations</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]},{id:"interactions-feynman-diagrams",title:"Interactions & Feynman Diagrams",subtitle:"What the diagrams really mean",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>Add interactions and exact solutions vanish; perturbation theory returns with Feynman's diagrams as its bookkeeping — each line and vertex a factor in an amplitude, 'virtual particles' revealed as terms in an expansion rather than magic.</p>\n<h3>Topics</h3>\n<ul>\n  <li>What the perturbation expansion means</li>\n  <li>Virtual particles</li>\n  <li>Reading simple amplitudes</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"gauge-symmetry-standard-model",title:"Gauge Symmetry & the Standard Model",subtitle:"Demanding local symmetry creates the forces",sections:[{id:"overview",title:"What you'll learn in this chapter",content:"\n<p>The Standard Model's deepest idea: demand that quantum phases can be chosen independently at every point in spacetime, and forces must exist — U(1) gauge symmetry generates electromagnetism. The Higgs mechanism then explains mass without breaking the symmetry's benefits.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The U(1) gauge idea → QED</li>\n  <li>The Higgs mechanism conceptually</li>\n</ul>\n<div class=\"key-concept\"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>"}],quiz:[]},{id:"open-frontier",title:"The Open Frontier",subtitle:"Renormalization, quantum gravity, and your graduate roadmap",sections:[{id:"overview",title:"What you'll learn in this chapter",content:'\n<p>The course — and this curriculum — ends honestly: renormalization\'s modern meaning, why gravity resists quantization, the contenders (strings, loops), and what nobody knows. Plus the graduate roadmap: Jackson, Sakurai, Peskin, Carroll — you now have the foundations to attempt them all.</p>\n<h3>Topics</h3>\n<ul>\n  <li>The renormalization idea</li>\n  <li>The quantum-gravity problem</li>\n  <li>Strings &amp; loops glimpse</li>\n  <li>The graduate roadmap (Jackson, Sakurai, Peskin, Carroll)</li>\n</ul>\n<div class="key-concept"><h4>Status</h4><p>Full interactive content for this chapter is in development. This outline is your map — the chapter list and ordering are final, based on the research in <strong>docs/CURRICULUM.md</strong>.</p></div>'}],quiz:[]}]}].map((e,t)=>({...e,...a[t]}));function o(e){let t=s.find(t=>t.id===e);return t?t.chapters.reduce((e,t)=>e+t.sections.length,0):0}function r(e){return s.find(t=>t.id===e)}function l(e,t){let n=r(e);return null==n?void 0:n.chapters.find(e=>e.id===t)}function h(e){return i[e.phase-1]}function c(e,t){let n=r(e);if(!n)return null;let i=n.chapters.findIndex(e=>e.id===t);if(i<n.chapters.length-1)return{subjectId:e,chapterId:n.chapters[i+1].id};let a=s.findIndex(t=>t.id===e);if(a<s.length-1){let e=s[a+1];return{subjectId:e.id,chapterId:e.chapters[0].id}}return null}function d(e,t){let n=r(e);if(!n)return null;let i=n.chapters.findIndex(e=>e.id===t);if(i>0)return{subjectId:e,chapterId:n.chapters[i-1].id};let a=s.findIndex(t=>t.id===e);if(a>0){let e=s[a-1];return{subjectId:e.id,chapterId:e.chapters[e.chapters.length-1].id}}return null}}}]);